(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-034"]={"sura":34,"name_ar":"سبإ","name_en":"Saba","verses":54,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":54,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=2\" class=\"link\">34:2</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:2 ஐ பார்க்கவும்"},"2":{"html":"<strong>ஸூரத்து ஸபா</strong><br />\r\n<strong>மக்காவில் அருளப்பட்டது</strong><br />\r\n<h3>வசனங்கள்: 1-2</h3><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>எல்லாப் புகழும் மறைவானவற்றின் அறிவும் அல்லாஹ்வுக்கே உரியது</strong><br />\r\n<br />\r\nஇவ்வுலகிலும் மறுமையிலும் எல்லாப் புகழும் தனக்கே உரியது என்று அல்லாஹ் கூறுகிறான். ஏனெனில், அவனே இவ்வுலகம் மற்றும் மறுவுலக மக்களுக்கு அள்ளி வழங்குபவனும் அருள்புரிபவனும் ஆவான்; மேலும், அவனே அனைத்தையும் ஆள்பவனும் கட்டுப்படுத்துபவனும் ஆவான். அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَهُوَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لا</span> <span class=\"quran-arabic-font text-success\">إِلَـهَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الْحَمْدُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّولَى</span> <span class=\"quran-arabic-font text-success\">وَالاٌّخِرَةِ</span> <span class=\"quran-arabic-font text-success\">وَلَهُ</span> <span class=\"quran-arabic-font text-success\">الْحُكْمُ</span> <span class=\"quran-arabic-font text-success\">وَإِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">تُرْجَعُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவனே அல்லாஹ்; அவனைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை. இம்மையிலும் (முதலாவதாக) மறுமையிலும் (இறுதியாகவும்) புகழனைத்தும் அவனுக்கே உரியது. தீர்ப்பு வழங்கும் அதிகாரம் அவனுக்கே உரியது; மேலும், அவனிடமே நீங்கள் (அனைவரும்) திரும்பக் கொண்டு வரப்படுவீர்கள்.) (<a href=\"qurandisp.php?sura=28&ayah=70\" class=\"link\">28:70</a>). அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾الْحَمْدُ</span> <span class=\"quran-arabic-font text-success\">للَّهِ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ﴿</span><br />\r\n<br />\r\n(எல்லாப் புகழும் அல்லாஹ்வுக்கே உரியது; வானங்களில் உள்ளவை மற்றும் பூமியில் உள்ளவை அனைத்தும் அவனுக்கே உரியவை.) அதாவது, இவை அனைத்தும் அவனது ஆட்சிக்கு உட்பட்டவை, அவனுக்கே அடிபணிந்தவை மற்றும் அவனது கட்டுப்பாட்டின் கீழ் இருப்பவை. அல்லாஹ் கூறுவது போல்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">لَلاٌّخِرَةَ</span> <span class=\"quran-arabic-font text-success\">وَالاٍّولَى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, மறுமையும் இம்மையும் நமக்கே உரியன.) (<a href=\"qurandisp.php?sura=92&ayah=13\" class=\"link\">92:13</a>). பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَهُ</span> <span class=\"quran-arabic-font text-success\">الْحَمْدُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّخِرَةِ﴿</span><br />\r\n<br />\r\n(மறுமையிலும் புகழனைத்தும் அவனுக்கே உரியது.) ஏனெனில், அவனே என்றென்றும் வணங்கப்பட வேண்டியவனும், நித்தியமாகப் புகழப்பட வேண்டியவனும் ஆவான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْحَكِيمُ﴿</span><br />\r\n<br />\r\nமேலும் அவன் ஞானமிக்கவன்; அதாவது, அவன் கூறுவதிலும் செய்வதிலும், சட்டமியற்றுவதிலும் விதியமைப்பதிலும் ஞானமிக்கவன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾الْخَبِيرُ﴿</span><br />\r\n<br />\r\n(அவன் அனைத்தையும்) நன்கு அறிந்தவன். அவனிடமிருந்து எதுவும் மறைக்கப்படுவதோ அல்லது ஒளிக்கப்படுவதோ இல்லை. அஸ்-ஸுஹ்ரீ (ரஹ்) அவர்கள், \"அவன் தனது படைப்புகளைப் பற்றி நன்கு அறிந்தவன், தனது கட்டளைகளில் ஞானமிக்கவன்\" என்று கூறியதாக மாலிக் (ரஹ்) அவர்கள் அறிவித்துள்ளார்கள். அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَلْجُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يَخْرُجُ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا﴿</span><br />\r\n<br />\r\n(பூமிக்குள் நுழைவதையும், அதிலிருந்து வெளிவருவதையும் அவன் அறிகிறான்.) அதாவது, பூமியின் ஆழத்திற்குள் செல்லும் மழைத்துளிகளின் எண்ணிக்கையையும், விதைக்கப்பட்ட விதைகளையும், அதில் மறைந்துள்ளவற்றையும் அவன் அறிகிறான். மேலும், அதிலிருந்து வெளிவருபவை எத்தனை, அவை எவ்வாறு வளர்கின்றன, அவற்றின் தோற்றம் என்ன என்பதையும் அவன் அறிகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">يَنزِلُ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يَعْرُجُ</span> <span class=\"quran-arabic-font text-success\">فِيهَا﴿</span><br />\r\n<br />\r\n(வானத்திலிருந்து இறங்குவதையும், அதிலே ஏறிச் செல்வதையும்) அதாவது, மழைத்துளிகள் மற்றும் வாழ்வாதாரத்தையும், (வானத்திற்கு) ஏறிச் செல்பவற்றையும் - அதாவது மலக்குகள், நற்செயல்கள் ஆகியவற்றையும் - அவன் அறிகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمُ</span> <span class=\"quran-arabic-font text-success\">الْغَفُورُ﴿</span><br />\r\n<br />\r\n(மேலும் அவன் மகா கருணையாளன், மிக மன்னிப்பவன்.) அதாவது, அவன் தனது அடியார்கள் மீது பெரும் கருணை கொண்டவன்; அவர்களைத் தண்டிப்பதற்கு அவன் அவசரப்படுவதில்லை. மேலும், அவனிடம் பாவமன்னிப்பு கோரி, அவனைச் சார்ந்திருப்பவர்களின் பாவங்களை அவன் மன்னிக்கிறான்.<br />\r\n<br />","text":"ஸூரத்து ஸபா\n\r\nமக்காவில் அருளப்பட்டது\n\r\nவசனங்கள்: 1-2\n\r\n\n\r\n﴾بِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ ﴿\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nஎல்லாப் புகழும் மறைவானவற்றின் அறிவும் அல்லாஹ்வுக்கே உரியது\n\r\n\n\r\nஇவ்வுலகிலும் மறுமையிலும் எல்லாப் புகழும் தனக்கே உரியது என்று அல்லாஹ் கூறுகிறான். ஏனெனில், அவனே இவ்வுலகம் மற்றும் மறுவுலக மக்களுக்கு அள்ளி வழங்குபவனும் அருள்புரிபவனும் ஆவான்; மேலும், அவனே அனைத்தையும் ஆள்பவனும் கட்டுப்படுத்துபவனும் ஆவான். அல்லாஹ் கூறுகிறான்:\n\r\n﴾وَهُوَ اللَّهُ لا إِلَـهَ إِلاَّ هُوَ لَهُ الْحَمْدُ فِى الاٌّولَى وَالاٌّخِرَةِ وَلَهُ الْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ ﴿\n\r\n\n\r\n(அவனே அல்லாஹ்; அவனைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை. இம்மையிலும் (முதலாவதாக) மறுமையிலும் (இறுதியாகவும்) புகழனைத்தும் அவனுக்கே உரியது. தீர்ப்பு வழங்கும் அதிகாரம் அவனுக்கே உரியது; மேலும், அவனிடமே நீங்கள் (அனைவரும்) திரும்பக் கொண்டு வரப்படுவீர்கள்.) (28:70). அல்லாஹ் கூறுகிறான்:\n\r\n﴾الْحَمْدُ للَّهِ الَّذِى لَهُ مَا فِى السَّمَـوَتِ وَمَا فِى الاٌّرْضِ﴿\n\r\n\n\r\n(எல்லாப் புகழும் அல்லாஹ்வுக்கே உரியது; வானங்களில் உள்ளவை மற்றும் பூமியில் உள்ளவை அனைத்தும் அவனுக்கே உரியவை.) அதாவது, இவை அனைத்தும் அவனது ஆட்சிக்கு உட்பட்டவை, அவனுக்கே அடிபணிந்தவை மற்றும் அவனது கட்டுப்பாட்டின் கீழ் இருப்பவை. அல்லாஹ் கூறுவது போல்:\n\r\n﴾وَإِنَّ لَنَا لَلاٌّخِرَةَ وَالاٍّولَى ﴿\n\r\n\n\r\n(நிச்சயமாக, மறுமையும் இம்மையும் நமக்கே உரியன.) (92:13). பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n﴾وَلَهُ الْحَمْدُ فِى الاٌّخِرَةِ﴿\n\r\n\n\r\n(மறுமையிலும் புகழனைத்தும் அவனுக்கே உரியது.) ஏனெனில், அவனே என்றென்றும் வணங்கப்பட வேண்டியவனும், நித்தியமாகப் புகழப்பட வேண்டியவனும் ஆவான்.\n\r\n\n\r\n﴾وَهُوَ الْحَكِيمُ﴿\n\r\n\n\r\nமேலும் அவன் ஞானமிக்கவன்; அதாவது, அவன் கூறுவதிலும் செய்வதிலும், சட்டமியற்றுவதிலும் விதியமைப்பதிலும் ஞானமிக்கவன்.\n\r\n\n\r\n﴾الْخَبِيرُ﴿\n\r\n\n\r\n(அவன் அனைத்தையும்) நன்கு அறிந்தவன். அவனிடமிருந்து எதுவும் மறைக்கப்படுவதோ அல்லது ஒளிக்கப்படுவதோ இல்லை. அஸ்-ஸுஹ்ரீ (ரஹ்) அவர்கள், \"அவன் தனது படைப்புகளைப் பற்றி நன்கு அறிந்தவன், தனது கட்டளைகளில் ஞானமிக்கவன்\" என்று கூறியதாக மாலிக் (ரஹ்) அவர்கள் அறிவித்துள்ளார்கள். அல்லாஹ் கூறுகிறான்:\n\r\n﴾يَعْلَمُ مَا يَلْجُ فِى الاٌّرْضِ وَمَا يَخْرُجُ مِنْهَا﴿\n\r\n\n\r\n(பூமிக்குள் நுழைவதையும், அதிலிருந்து வெளிவருவதையும் அவன் அறிகிறான்.) அதாவது, பூமியின் ஆழத்திற்குள் செல்லும் மழைத்துளிகளின் எண்ணிக்கையையும், விதைக்கப்பட்ட விதைகளையும், அதில் மறைந்துள்ளவற்றையும் அவன் அறிகிறான். மேலும், அதிலிருந்து வெளிவருபவை எத்தனை, அவை எவ்வாறு வளர்கின்றன, அவற்றின் தோற்றம் என்ன என்பதையும் அவன் அறிகிறான்.\n\r\n\n\r\n﴾وَمَا يَنزِلُ مِنَ السَّمَآءِ وَمَا يَعْرُجُ فِيهَا﴿\n\r\n\n\r\n(வானத்திலிருந்து இறங்குவதையும், அதிலே ஏறிச் செல்வதையும்) அதாவது, மழைத்துளிகள் மற்றும் வாழ்வாதாரத்தையும், (வானத்திற்கு) ஏறிச் செல்பவற்றையும் - அதாவது மலக்குகள், நற்செயல்கள் ஆகியவற்றையும் - அவன் அறிகிறான்.\n\r\n\n\r\n﴾وَهُوَ الرَّحِيمُ الْغَفُورُ﴿\n\r\n\n\r\n(மேலும் அவன் மகா கருணையாளன், மிக மன்னிப்பவன்.) அதாவது, அவன் தனது அடியார்கள் மீது பெரும் கருணை கொண்டவன்; அவர்களைத் தண்டிப்பதற்கு அவன் அவசரப்படுவதில்லை. மேலும், அவனிடம் பாவமன்னிப்பு கோரி, அவனைச் சார்ந்திருப்பவர்களின் பாவங்களை அவன் மன்னிக்கிறான்."},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=6\" class=\"link\">34:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:6 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=6\" class=\"link\">34:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:6 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=6\" class=\"link\">34:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:6 ஐ பார்க்கவும்"},"6":{"html":"<strong>ஒவ்வொருவருக்கும் அவரவர் செயல்களுக்கு ஏற்ப கூலியோ தண்டனையோ வழங்கப்படுவதற்காக மறுமை நாள் வந்தே தீரும்</strong><br />\r\n<br />\r\nஇது மூன்று வசனங்களில் (ஆயத்களில்) ஒன்றாகும் - நான்காவதாக வேறெதுவும் இல்லை - இவற்றில், மறுமை நாள் நிச்சயமாக நிகழும் என்று சர்வ வல்லமையுள்ள தன் இறைவன் மீது சத்தியம் செய்யுமாறு அல்லாஹ் தன் தூதருக்கு (ஸல்) கட்டளையிடுகிறான். ஏனெனில், பிடிவாதமான நிராகரிப்பாளர்கள் அது நிகழும் என்பதை மறுத்தனர். இந்த வசனங்களில் ஒன்று சூரா யூனுஸில் உள்ளது, அதில் அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَيَسْتَنْبِئُونَكَ</span> <span class=\"quran-arabic-font text-success\">أَحَقٌّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">إِى</span> <span class=\"quran-arabic-font text-success\">وَرَبِّى</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَحَقٌّ</span> <span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">بِمُعْجِزِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(மேலும் அவர்கள் உம்மிடம், \"(இது) உண்மையா?\" என்று வினவுகிறார்கள். நீர் கூறுவீராக: \"ஆம்! என் இறைவன் மீது சத்தியமாக! அது முற்றிலும் உண்மையே! நீங்கள் (அவனை) தோற்கடிக்க முடியாது!\") (<a href=\"qurandisp.php?sura=10&ayah=53\" class=\"link\">10:53</a>).<br />\r\n<br />\r\nஇரண்டாவது வசனம் இதுவாகும்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَالَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَأْتِينَا</span> <span class=\"quran-arabic-font text-success\">السَّاعَةُ</span> <span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">بَلَى</span> <span class=\"quran-arabic-font text-success\">وَرَبِّى</span> <span class=\"quran-arabic-font text-success\">لَتَأْتِيَنَّكُمْ﴿</span><br />\r\n(நிராகரிப்பாளர்கள், \"அந்த (மறுமை) நேரம் எங்களுக்கு வராது\" என்று கூறுகின்றனர். நீர் கூறுவீராக: \"அப்படியல்ல, என் இறைவன் மீது சத்தியமாக, அது நிச்சயமாக உங்களிடம் வரும்...\")<br />\r\n<br />\r\nமூன்றாவது வசனம் சூரா அத்-தகாபுனில் வருகிறது, அதில் அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾زَعَمَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">لَّن</span> <span class=\"quran-arabic-font text-success\">يُبْعَثُواْ</span> <span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">بَلَى</span> <span class=\"quran-arabic-font text-success\">وَرَبِّى</span> <span class=\"quran-arabic-font text-success\">لَتُبْعَثُنَّ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لَتُنَبَّؤُنَّ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">عَمِلْتُمْ</span> <span class=\"quran-arabic-font text-success\">وَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">يَسِيرٌ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(தாங்கள் ஒருபோதும் உயிர் கொடுத்து எழுப்பப்பட மாட்டோம் என்று நிராகரிப்பாளர்கள் எண்ணிக் கொள்கின்றனர். நீர் கூறுவீராக: \"அப்படியல்ல! என் இறைவன் மீது சத்தியமாக, நீங்கள் நிச்சயமாக எழுப்பப்படுவீர்கள்; பிறகு நீங்கள் செய்தவை பற்றி உங்களுக்கு அறிவிக்கப்படும். இது அல்லாஹ்வுக்கு மிகவும் எளிதானது\") (<a href=\"qurandisp.php?sura=64&ayah=7\" class=\"link\">64:7</a>).<br />\r\n<br />\r\nஇங்கே அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قُلْ</span> <span class=\"quran-arabic-font text-success\">بَلَى</span> <span class=\"quran-arabic-font text-success\">وَرَبِّى</span> <span class=\"quran-arabic-font text-success\">لَتَأْتِيَنَّكُمْ﴿</span><br />\r\n(கூறுவீராக: \"ஆம், என் இறைவன் மீது சத்தியமாக, அது உங்களிடம் வந்தே தீரும்...\")<br />\r\n<br />\r\nபிறகு, அதை உறுதிப்படுத்தும் வகையில் அல்லாஹ் பின்வருமாறு விவரிக்கப்படுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾عَالِمِ</span> <span class=\"quran-arabic-font text-success\">الْغَيْبِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَعْزُبُ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">مِثْقَالُ</span> <span class=\"quran-arabic-font text-success\">ذَرَّةٍ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَصْغَرُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَكْبَرُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">كِتَابٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ﴿</span><br />\r\n(அவன் மறைவானவற்றை அறிந்தவன்; வானங்களிலோ பூமியிலோ ஓர் அணுவளவு கூட அவனது அறிவிலிருந்து தப்புவதில்லை. அதைவிடச் சிறியதோ அல்லது பெரியதோ, தெளிவான ஒரு பதிவேட்டில் இல்லாமல் இல்லை.)<br />\r\n<br />\r\nமுஜாஹித் (ரழி) அவர்களும் கத்தாதா (ரழி) அவர்களும், \"அவனிடமிருந்து எதுவும் மறைக்கப்படுவதோ அல்லது மறைந்திருப்பதோ இல்லை\" என்று கூறினார்கள். அதாவது, அனைத்தும் அவனது அறிவுக்கு உட்பட்டவை, அவனிடமிருந்து எதுவும் மறையாது. எலும்புகள் சிதறி மக்கிப்போனாலும், அவை எங்கு சென்றன, எங்கு பரவின என்பதை அவன் அறிவான். அவன் அனைத்தையும் அறிந்தவன் என்பதால், அவற்றை முதலில் எவ்வாறு படைத்தானோ, அவ்வாறே மீண்டும் உயிர்ப்பித்துக் கொண்டு வருவான். பிறகு, உடல்களை மீண்டும் படைப்பதிலும் மறுமை நாளைக் கொண்டு வருவதிலும் உள்ள தனது ஞானத்தைப் பற்றி அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لِّيَجْزِىَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">وَعَمِلُواْ</span> <span class=\"quran-arabic-font text-success\">الصَّالِحَاتِ</span> <span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">مَّغْفِرَةٌ</span> <span class=\"quran-arabic-font text-success\">وَرِزْقٌ</span> <span class=\"quran-arabic-font text-success\">كَرِيمٌ</span> <span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">سَعَوْا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">آيَاتِنَا</span> <span class=\"quran-arabic-font text-success\">مُعَاجِزِينَ﴿</span><br />\r\n(ஈமான் கொண்டு நற்செயல்கள் புரிந்தவர்களுக்கு அவன் கூலி வழங்குவதற்காக (இது நிகழும்). அவர்களுக்கு மன்னிப்பும், கண்ணியமான வாழ்வாதாரமும் உண்டு. ஆனால், நம்முடைய வசனங்களைத் தோற்கடிக்க முயற்சிப்பவர்கள்...)<br />\r\n<br />\r\nஅதாவது, பிறரை அல்லாஹ்வின் பாதையிலிருந்து திசைதிருப்ப முயல்பவர்கள் மற்றும் அவனது தூதர்களை நிராகரிப்பவர்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رِّجْزٍ</span> <span class=\"quran-arabic-font text-success\">أَلِيمٌ﴿</span><br />\r\n(...அத்தகையோருக்கு மிகவும் நோவினை செய்யும் கடுமையான வேதனை உண்டு.)<br />\r\n<br />\r\nஇதன் பொருள், நம்பிக்கையாளர்களான நற்பேறு பெற்றவர்கள் மீது அவன் தனது அருளைப் பொழிவான், மேலும் நிராகரிப்பாளர்களான துரதிஷ்டசாலிகளைத் தண்டிப்பான் என்பதாகும். இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لاَ</span> <span class=\"quran-arabic-font text-success\">يَسْتَوِى</span> <span class=\"quran-arabic-font text-success\">أَصْحَابُ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">وَأَصْحَـبُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">أَصْحَـبُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْفَآئِزُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(நரகவாசிகளும் சொர்க்கவாசிகளும் சமமாக மாட்டார்கள். சொர்க்கவாசிகளே வெற்றியாளர்கள்.) (<a href=\"qurandisp.php?sura=59&ayah=20\" class=\"link\">59:20</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَمْ</span> <span class=\"quran-arabic-font text-success\">نَجْعَلُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">وَعَمِلُواْ</span> <span class=\"quran-arabic-font text-success\">الصَّالِحَاتِ</span> <span class=\"quran-arabic-font text-success\">كَالْمُفْسِدِينَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الأَرْضِ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">نَجْعَلُ</span> <span class=\"quran-arabic-font text-success\">الْمُتَّقِينَ</span> <span class=\"quran-arabic-font text-success\">كَالْفُجَّارِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(நம்பிக்கை கொண்டு நற்செயல்கள் புரிந்தவர்களை, பூமியில் குழப்பம் விளைவிப்பவர்களைப் போல நாம் நடத்துவோமா? அல்லது இறையச்சம் உடையவர்களை தீயவர்களைப் போல நடத்துவோமா?) (<a href=\"qurandisp.php?sura=38&ayah=28\" class=\"link\">38:28</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَيَرَى</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أُوتُواْ</span> <span class=\"quran-arabic-font text-success\">الْعِلْمَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">أُنزِلَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكَ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الْحَقَّ﴿</span><br />\r\n(மேலும், கல்வி வழங்கப்பட்டவர்கள், உமது இறைவனிடமிருந்து உமக்கு அருளப்பட்ட வஹீ (இறைச்செய்தி) தான் சத்தியமானது என்பதைக் காண்பார்கள்.)<br />\r\n<br />\r\nஇது, முந்தைய ஞானத்தைத் தொடர்ந்து வரும் மற்றுமொரு ஞானமாகும். அதாவது, தூதர்களுக்கு அருளப்பட்ட வஹீயை (இறைச்செய்தியை) நம்பியவர்கள், மறுமை நாள் வருவதையும், நல்லவர்களுக்கும் தீயவர்களுக்கும் அவரவர் செயல்களுக்கு ஏற்பக் கூலியும் தண்டனையும் வழங்கப்படுவதையும் காணும்போது - இதை அவர்கள் ஏற்கனவே இவ்வுலகில் அல்லாஹ்வின் வேதங்கள் மூலம் அறிந்திருந்தனர், இப்போது நேரில் காணும்போது - அவர்கள் கூறுவார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لَقَدْ</span> <span class=\"quran-arabic-font text-success\">جَآءَتْ</span> <span class=\"quran-arabic-font text-success\">رُسُلُ</span> <span class=\"quran-arabic-font text-success\">رَبِّنَا</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ﴿</span><br />\r\n(\"நிச்சயமாக, எமது இறைவனின் தூதர்கள் சத்தியத்தையே கொண்டு வந்தார்கள்\") (<a href=\"qurandisp.php?sura=7&ayah=43\" class=\"link\">7:43</a>).<br />\r\n<br />\r\nமேலும் இவ்வாறு கூறப்படும்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾هَذَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">وَعَدَ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَنُ</span> <span class=\"quran-arabic-font text-success\">وَصَدَقَ</span> <span class=\"quran-arabic-font text-success\">الْمُرْسَلُونَ﴿</span><br />\r\n(\"இதுவே அளவற்ற அருளாளன் வாக்களித்ததாகும், தூதர்கள் உண்மையே பேசினார்கள்!\") (<a href=\"qurandisp.php?sura=36&ayah=52\" class=\"link\">36:52</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لَقَدْ</span> <span class=\"quran-arabic-font text-success\">لَبِثْتُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">كِتَابِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">الْبَعْثِ</span> <span class=\"quran-arabic-font text-success\">فَهَـذَا</span> <span class=\"quran-arabic-font text-success\">يَوْمُ</span> <span class=\"quran-arabic-font text-success\">الْبَعْثِ﴿</span><br />\r\n(\"நிச்சயமாக நீங்கள் அல்லாஹ்வின் விதிப்படி, உயிர்த்தெழுப்பப்படும் நாள் வரை தங்கியிருந்தீர்கள்; இதுவே அந்த உயிர்த்தெழுப்பப்படும் நாளாகும்\") (<a href=\"qurandisp.php?sura=30&ayah=56\" class=\"link\">30:56</a>),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَيَرَى</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أُوتُواْ</span> <span class=\"quran-arabic-font text-success\">الْعِلْمَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">أُنزِلَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكَ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الْحَقَّ</span> <span class=\"quran-arabic-font text-success\">وَيَهْدِى</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">صِرَاطِ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزِ</span> <span class=\"quran-arabic-font text-success\">الْحَمِيدِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(மேலும் கல்வி வழங்கப்பட்டவர்கள், உமது இறைவனிடமிருந்து உமக்கு அருளப்பட்ட வஹீ (இறைச்செய்தி) தான் சத்தியமானது என்பதையும், அது யாவற்றையும் மிகைத்தவனும், புகழுக்குரியவனுமாகிய அல்லாஹ்வின் நேர்வழியில் செலுத்துகிறது என்பதையும் காண்பார்கள்.)<br />\r\n<br />\r\n'யாவற்றையும் மிகைத்தவன்' (அல்-அஸீஸ்) என்பவன் சர்வ வல்லமையுள்ளவன், அவனை எவராலும் வெல்லவோ எதிர்க்கவோ முடியாது, மாறாக அவன் அனைத்தையும் அடக்கி ஆள்பவன். 'புகழுக்குரியவன்' (அல்-ஹமீது) என்பவன் தனது அனைத்து வார்த்தைகளிலும், செயல்களிலும், சட்டங்களிலும், விதிகளிலும் புகழுக்குத் தகுதியானவன்; அவன் தூய்மையானவனும் மிக உயர்ந்தவனுமாவான்.<br />\r\n<br />","text":"ஒவ்வொருவருக்கும் அவரவர் செயல்களுக்கு ஏற்ப கூலியோ தண்டனையோ வழங்கப்படுவதற்காக மறுமை நாள் வந்தே தீரும்\n\r\n\n\r\nஇது மூன்று வசனங்களில் (ஆயத்களில்) ஒன்றாகும் - நான்காவதாக வேறெதுவும் இல்லை - இவற்றில், மறுமை நாள் நிச்சயமாக நிகழும் என்று சர்வ வல்லமையுள்ள தன் இறைவன் மீது சத்தியம் செய்யுமாறு அல்லாஹ் தன் தூதருக்கு (ஸல்) கட்டளையிடுகிறான். ஏனெனில், பிடிவாதமான நிராகரிப்பாளர்கள் அது நிகழும் என்பதை மறுத்தனர். இந்த வசனங்களில் ஒன்று சூரா யூனுஸில் உள்ளது, அதில் அல்லாஹ் கூறுகிறான்:\n\r\n﴾وَيَسْتَنْبِئُونَكَ أَحَقٌّ هُوَ قُلْ إِى وَرَبِّى إِنَّهُ لَحَقٌّ وَمَآ أَنتُمْ بِمُعْجِزِينَ ﴿\n\r\n(மேலும் அவர்கள் உம்மிடம், \"(இது) உண்மையா?\" என்று வினவுகிறார்கள். நீர் கூறுவீராக: \"ஆம்! என் இறைவன் மீது சத்தியமாக! அது முற்றிலும் உண்மையே! நீங்கள் (அவனை) தோற்கடிக்க முடியாது!\") (10:53).\n\r\n\n\r\nஇரண்டாவது வசனம் இதுவாகும்:\n\r\n﴾وَقَالَ الَّذِينَ كَفَرُواْ لاَ تَأْتِينَا السَّاعَةُ قُلْ بَلَى وَرَبِّى لَتَأْتِيَنَّكُمْ﴿\n\r\n(நிராகரிப்பாளர்கள், \"அந்த (மறுமை) நேரம் எங்களுக்கு வராது\" என்று கூறுகின்றனர். நீர் கூறுவீராக: \"அப்படியல்ல, என் இறைவன் மீது சத்தியமாக, அது நிச்சயமாக உங்களிடம் வரும்...\")\n\r\n\n\r\nமூன்றாவது வசனம் சூரா அத்-தகாபுனில் வருகிறது, அதில் அல்லாஹ் கூறுகிறான்:\n\r\n﴾زَعَمَ الَّذِينَ كَفَرُواْ أَن لَّن يُبْعَثُواْ قُلْ بَلَى وَرَبِّى لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْ وَذَلِكَ عَلَى اللَّهِ يَسِيرٌ ﴿\n\r\n(தாங்கள் ஒருபோதும் உயிர் கொடுத்து எழுப்பப்பட மாட்டோம் என்று நிராகரிப்பாளர்கள் எண்ணிக் கொள்கின்றனர். நீர் கூறுவீராக: \"அப்படியல்ல! என் இறைவன் மீது சத்தியமாக, நீங்கள் நிச்சயமாக எழுப்பப்படுவீர்கள்; பிறகு நீங்கள் செய்தவை பற்றி உங்களுக்கு அறிவிக்கப்படும். இது அல்லாஹ்வுக்கு மிகவும் எளிதானது\") (64:7).\n\r\n\n\r\nஇங்கே அல்லாஹ் கூறுகிறான்:\n\r\n﴾قُلْ بَلَى وَرَبِّى لَتَأْتِيَنَّكُمْ﴿\n\r\n(கூறுவீராக: \"ஆம், என் இறைவன் மீது சத்தியமாக, அது உங்களிடம் வந்தே தீரும்...\")\n\r\n\n\r\nபிறகு, அதை உறுதிப்படுத்தும் வகையில் அல்லாஹ் பின்வருமாறு விவரிக்கப்படுகிறான்:\n\r\n﴾عَالِمِ الْغَيْبِ لاَ يَعْزُبُ عَنْهُ مِثْقَالُ ذَرَّةٍ فِي السَّمَاوَاتِ وَلاَ فِي الأَرْضِ وَلاَ أَصْغَرُ مِن ذَلِكَ وَلاَ أَكْبَرُ إِلاَّ فِي كِتَابٍ مُّبِينٍ﴿\n\r\n(அவன் மறைவானவற்றை அறிந்தவன்; வானங்களிலோ பூமியிலோ ஓர் அணுவளவு கூட அவனது அறிவிலிருந்து தப்புவதில்லை. அதைவிடச் சிறியதோ அல்லது பெரியதோ, தெளிவான ஒரு பதிவேட்டில் இல்லாமல் இல்லை.)\n\r\n\n\r\nமுஜாஹித் (ரழி) அவர்களும் கத்தாதா (ரழி) அவர்களும், \"அவனிடமிருந்து எதுவும் மறைக்கப்படுவதோ அல்லது மறைந்திருப்பதோ இல்லை\" என்று கூறினார்கள். அதாவது, அனைத்தும் அவனது அறிவுக்கு உட்பட்டவை, அவனிடமிருந்து எதுவும் மறையாது. எலும்புகள் சிதறி மக்கிப்போனாலும், அவை எங்கு சென்றன, எங்கு பரவின என்பதை அவன் அறிவான். அவன் அனைத்தையும் அறிந்தவன் என்பதால், அவற்றை முதலில் எவ்வாறு படைத்தானோ, அவ்வாறே மீண்டும் உயிர்ப்பித்துக் கொண்டு வருவான். பிறகு, உடல்களை மீண்டும் படைப்பதிலும் மறுமை நாளைக் கொண்டு வருவதிலும் உள்ள தனது ஞானத்தைப் பற்றி அல்லாஹ் கூறுகிறான்:\n\r\n﴾لِّيَجْزِىَ الَّذِينَ ءَامَنُواْ وَعَمِلُواْ الصَّالِحَاتِ أُوْلَـئِكَ لَهُمْ مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ وَالَّذِينَ سَعَوْا فِي آيَاتِنَا مُعَاجِزِينَ﴿\n\r\n(ஈமான் கொண்டு நற்செயல்கள் புரிந்தவர்களுக்கு அவன் கூலி வழங்குவதற்காக (இது நிகழும்). அவர்களுக்கு மன்னிப்பும், கண்ணியமான வாழ்வாதாரமும் உண்டு. ஆனால், நம்முடைய வசனங்களைத் தோற்கடிக்க முயற்சிப்பவர்கள்...)\n\r\n\n\r\nஅதாவது, பிறரை அல்லாஹ்வின் பாதையிலிருந்து திசைதிருப்ப முயல்பவர்கள் மற்றும் அவனது தூதர்களை நிராகரிப்பவர்கள்:\n\r\n﴾أُوْلَـئِكَ لَهُمْ عَذَابٌ مِّن رِّجْزٍ أَلِيمٌ﴿\n\r\n(...அத்தகையோருக்கு மிகவும் நோவினை செய்யும் கடுமையான வேதனை உண்டு.)\n\r\n\n\r\nஇதன் பொருள், நம்பிக்கையாளர்களான நற்பேறு பெற்றவர்கள் மீது அவன் தனது அருளைப் பொழிவான், மேலும் நிராகரிப்பாளர்களான துரதிஷ்டசாலிகளைத் தண்டிப்பான் என்பதாகும். இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n﴾لاَ يَسْتَوِى أَصْحَابُ النَّارِ وَأَصْحَـبُ الْجَنَّةِ أَصْحَـبُ الْجَنَّةِ هُمُ الْفَآئِزُونَ ﴿\n\r\n(நரகவாசிகளும் சொர்க்கவாசிகளும் சமமாக மாட்டார்கள். சொர்க்கவாசிகளே வெற்றியாளர்கள்.) (59:20)\n\r\n\n\r\n﴾أَمْ نَجْعَلُ الَّذِينَ ءَامَنُواْ وَعَمِلُواْ الصَّالِحَاتِ كَالْمُفْسِدِينَ فِي الأَرْضِ أَمْ نَجْعَلُ الْمُتَّقِينَ كَالْفُجَّارِ ﴿\n\r\n(நம்பிக்கை கொண்டு நற்செயல்கள் புரிந்தவர்களை, பூமியில் குழப்பம் விளைவிப்பவர்களைப் போல நாம் நடத்துவோமா? அல்லது இறையச்சம் உடையவர்களை தீயவர்களைப் போல நடத்துவோமா?) (38:28)\n\r\n\n\r\n﴾وَيَرَى الَّذِينَ أُوتُواْ الْعِلْمَ الَّذِى أُنزِلَ إِلَيْكَ مِن رَّبِّكَ هُوَ الْحَقَّ﴿\n\r\n(மேலும், கல்வி வழங்கப்பட்டவர்கள், உமது இறைவனிடமிருந்து உமக்கு அருளப்பட்ட வஹீ (இறைச்செய்தி) தான் சத்தியமானது என்பதைக் காண்பார்கள்.)\n\r\n\n\r\nஇது, முந்தைய ஞானத்தைத் தொடர்ந்து வரும் மற்றுமொரு ஞானமாகும். அதாவது, தூதர்களுக்கு அருளப்பட்ட வஹீயை (இறைச்செய்தியை) நம்பியவர்கள், மறுமை நாள் வருவதையும், நல்லவர்களுக்கும் தீயவர்களுக்கும் அவரவர் செயல்களுக்கு ஏற்பக் கூலியும் தண்டனையும் வழங்கப்படுவதையும் காணும்போது - இதை அவர்கள் ஏற்கனவே இவ்வுலகில் அல்லாஹ்வின் வேதங்கள் மூலம் அறிந்திருந்தனர், இப்போது நேரில் காணும்போது - அவர்கள் கூறுவார்கள்:\n\r\n﴾لَقَدْ جَآءَتْ رُسُلُ رَبِّنَا بِالْحَقِّ﴿\n\r\n(\"நிச்சயமாக, எமது இறைவனின் தூதர்கள் சத்தியத்தையே கொண்டு வந்தார்கள்\") (7:43).\n\r\n\n\r\nமேலும் இவ்வாறு கூறப்படும்:\n\r\n﴾هَذَا مَا وَعَدَ الرَّحْمَنُ وَصَدَقَ الْمُرْسَلُونَ﴿\n\r\n(\"இதுவே அளவற்ற அருளாளன் வாக்களித்ததாகும், தூதர்கள் உண்மையே பேசினார்கள்!\") (36:52)\n\r\n\n\r\n﴾لَقَدْ لَبِثْتُمْ فِي كِتَابِ اللَّهِ إِلَى يَوْمِ الْبَعْثِ فَهَـذَا يَوْمُ الْبَعْثِ﴿\n\r\n(\"நிச்சயமாக நீங்கள் அல்லாஹ்வின் விதிப்படி, உயிர்த்தெழுப்பப்படும் நாள் வரை தங்கியிருந்தீர்கள்; இதுவே அந்த உயிர்த்தெழுப்பப்படும் நாளாகும்\") (30:56),\n\r\n\n\r\n﴾وَيَرَى الَّذِينَ أُوتُواْ الْعِلْمَ الَّذِى أُنزِلَ إِلَيْكَ مِن رَّبِّكَ هُوَ الْحَقَّ وَيَهْدِى إِلَى صِرَاطِ الْعَزِيزِ الْحَمِيدِ ﴿\n\r\n(மேலும் கல்வி வழங்கப்பட்டவர்கள், உமது இறைவனிடமிருந்து உமக்கு அருளப்பட்ட வஹீ (இறைச்செய்தி) தான் சத்தியமானது என்பதையும், அது யாவற்றையும் மிகைத்தவனும், புகழுக்குரியவனுமாகிய அல்லாஹ்வின் நேர்வழியில் செலுத்துகிறது என்பதையும் காண்பார்கள்.)\n\r\n\n\r\n'யாவற்றையும் மிகைத்தவன்' (அல்-அஸீஸ்) என்பவன் சர்வ வல்லமையுள்ளவன், அவனை எவராலும் வெல்லவோ எதிர்க்கவோ முடியாது, மாறாக அவன் அனைத்தையும் அடக்கி ஆள்பவன். 'புகழுக்குரியவன்' (அல்-ஹமீது) என்பவன் தனது அனைத்து வார்த்தைகளிலும், செயல்களிலும், சட்டங்களிலும், விதிகளிலும் புகழுக்குத் தகுதியானவன்; அவன் தூய்மையானவனும் மிக உயர்ந்தவனுமாவான்."},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=9\" class=\"link\">34:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:9 ஐ பார்க்கவும்"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=9\" class=\"link\">34:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:9 ஐ பார்க்கவும்"},"9":{"html":"<strong>மரணத்திற்குப் பிந்தைய வாழ்வை நிராகரிப்பவர்களும், அவர்களின் கருத்திற்குப் பதிலடியும்</strong><br />\r\n<br />\r\nஇறுதித் தீர்ப்பு நாள் வருவதை நிராகரிப்பாளர்களும் நாத்திகர்களும் எவ்வாறு மறுத்தார்கள் என்பதையும், அதைப் பற்றிப் பேசியதற்காக அல்லாஹ்வின் தூதர் (ஸல்) அவர்களை அவர்கள் எப்படிக் கேலி செய்தார்கள் என்பதையும் அல்லாஹ் இங்கே நமக்குக் கூறுகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">نَدُلُّكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رَجُلٍ</span> <span class=\"quran-arabic-font text-success\">يُنَبِّئُكُمْ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">مُزِّقْتُمْ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">مُمَزَّقٍ</span><br />\r\n<br />\r\n(நிராகரிப்பவர்கள் கூறுகிறார்கள்: \"நீங்கள் (மரணத்திற்குப் பின்) முழுவதுமாகச் சிதைக்கப்பட்டு, துகள் துகளாகச் சிதறிப் போன பிறகு...\" என்று உங்களுக்குக் கூறும் ஒரு மனிதரை நாங்கள் உங்களுக்குக் காட்டட்டுமா?) அதாவது, உங்கள் உடல்கள் பூமியில் மட்கிப் போய், எந்த அடையாளமும் இன்றிச் சிதைந்து போகும்போது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّكُمْ</span><br />\r\n<br />\r\n(நிச்சயமாக நீங்கள்) அதாவது, இது நிகழ்ந்த பிறகு,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَفِى</span> <span class=\"quran-arabic-font text-success\">خَلْقٍ</span> <span class=\"quran-arabic-font text-success\">جَدِيدٍ</span><br />\r\n<br />\r\n(புதியதொரு படைப்பாக ஆக்கப்படுவீர்கள்) அதாவது, நீங்கள் மீண்டும் உயிர்ப்பிக்கப்பட்டு, புதிதாக வாழ்வாதாரம் பெறுவீர்கள். \"இதை எங்களிடம் கூறுவதன் மூலம் அவர் இரண்டு காரியங்களில் ஒன்றைச் செய்கிறார்: ஒன்று, அவர் வேண்டுமென்றே எதையாவது இட்டுக்கட்டி, அல்லாஹ் தனக்கு வஹீ (இறைச்செய்தி) அருளியதாகக் கூறுகிறார்; அல்லது அவர் வேண்டுமென்றே அவ்வாறு செய்யவில்லை, மாறாக அவர் பைத்தியக்காரர்களைப் போலவும் மனநலம் பாதிக்கப்பட்டவர்களைப் போலவும் பிரமையில் இருக்கிறார்\" என்று அவர்கள் கூறினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفْتَرَى</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">كَذِباً</span> <span class=\"quran-arabic-font text-success\">أَم</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">جِنَّةٌ</span><br />\r\n<br />\r\n(அவர் அல்லாஹ்வின் மீது பொய்யை இட்டுக்கட்டினாரா அல்லது அவருக்குப் பைத்தியம் பிடித்துள்ளதா?) இவர்களின் கூற்றை மறுத்து அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">بِالآخِرَةِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">وَالضَّلَالِ</span> <span class=\"quran-arabic-font text-success\">الْبَعِيدِ</span><br />\r\n<br />\r\n(அப்படியல்ல! மறுமையை நம்பாதவர்கள்தாம் வேதனையிலும், நீண்ட வழிகேட்டிலும் இருக்கிறார்கள்.) அதாவது, அவர்கள் கூறுவது போன்றோ அல்லது நினைப்பது போன்றோ இது இல்லை. மாறாக, முஹம்மது (ஸல்) அவர்களே உண்மையை உரைப்பவராகவும், நேர்மையாளராகவும், ஞானமுள்ளவராகவும் இருக்கிறார்கள். அவர்களே சத்தியத்தைக் கொண்டு வந்தவர்கள்; நிராகரிப்பாளர்களோ அறிவற்ற முட்டாள்களும் பொய்யர்களும் ஆவார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span><br />\r\n<br />\r\n(வேதனையில் இருக்கிறார்கள்) என்பது அவர்களின் நிராகரிப்பைக் குறிக்கிறது; இதுவே அவர்களை அல்லாஹ்வின் வேதனைக்கு இட்டுச் செல்லும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالضَّلَالِ</span> <span class=\"quran-arabic-font text-success\">الْبَعِيدِ</span><br />\r\n<br />\r\n(மற்றும் நீண்ட வழிகேட்டில்) அதாவது, இவ்வுலகில் உண்மையிலிருந்து வெகு தொலைவில் இருக்கிறார்கள். பின்னர் அல்லாஹ் வானங்கள் மற்றும் பூமியின் படைப்பில் உள்ள தனது ஆற்றலைக் குறித்து அவர்களை எச்சரிக்கிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَرَوْاْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيهِمْ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">خَلْفَهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span> <span class=\"quran-arabic-font text-success\">وَالأَرْضِ</span><br />\r\n<br />\r\n(அவர்கள் தங்களுக்கு முன்னாலும் பின்னாலும் உள்ள வானத்தையும் பூமியையும் பார்க்கவில்லையா?) அதாவது, அவர்கள் எங்கு சென்றாலும், எந்தத் திசையில் சென்றாலும், வானம் அவர்களுக்கு மேலேயும் பூமி அவர்களுக்குக் கீழேயும் இருக்கிறது. இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالسَّمَاءَ</span> <span class=\"quran-arabic-font text-success\">بَنَيْنَاهَا</span> <span class=\"quran-arabic-font text-success\">بِأَيْدٍ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّا</span> <span class=\"quran-arabic-font text-success\">لَمُوسِعُونَ</span> - <span class=\"quran-arabic-font text-success\">وَالأَرْضَ</span> <span class=\"quran-arabic-font text-success\">فَرَشْنَاهَا</span> <span class=\"quran-arabic-font text-success\">فَنِعْمَ</span> <span class=\"quran-arabic-font text-success\">الْمَاهِدُونَ</span><br />\r\n<br />\r\n(நாம் வானத்தை (நம்) கரங்களால் (ஆற்றலால்) அமைத்தோம். நிச்சயமாக நாம் அதனை விரிவுபடுத்துபவர்கள் ஆவோம். மேலும் நாம் பூமியை விரித்தோம்; விரிப்பவர்களில் நாம் எவ்வளவு சிறந்தவர்!) (<a href=\"qurandisp.php?sura=51&ayah=47\" class=\"link\">51:47</a>-48)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">نَّشَأْ</span> <span class=\"quran-arabic-font text-success\">نَخْسِفْ</span> <span class=\"quran-arabic-font text-success\">بِهِمُ</span> <span class=\"quran-arabic-font text-success\">الأَرْضَ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">نُسْقِطْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">كِسَفاً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span><br />\r\n<br />\r\n(நாம் நாடினால் அவர்களைப் பூமியில் புதையச் செய்வோம் அல்லது வானத்திலிருந்து ஒரு துண்டை அவர்கள் மீது விழச் செய்வோம்.) அதாவது, அவர்களின் அநியாயத்தின் காரணமாகவும், அவர்கள் மீது நமக்குள்ள ஆற்றலினாலும் நாம் விரும்பினால் அவர்களுக்கு அவ்வாறு செய்ய முடியும். இருப்பினும், நாம் பொறுமையுள்ளவனாகவும் மன்னிப்பவனாகவும் இருப்பதால் அதனைத் தாமதப்படுத்துகிறோம். பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لآيَةً</span> <span class=\"quran-arabic-font text-success\">لِّكُلِّ</span> <span class=\"quran-arabic-font text-success\">عَبْدٍ</span> <span class=\"quran-arabic-font text-success\">مُّنِيبٍ</span><br />\r\n<br />\r\n(நிச்சயமாக இதில் (அல்லாஹ்வையே) முன்னோக்கும் ஒவ்வொரு அடியாருக்கும் ஓர் அத்தாட்சி இருக்கிறது.) கதாதா (ரஹ்) அவர்களிடமிருந்து மஃமர் (ரஹ்) அவர்கள் அறிவிக்கிறார்கள்: 'அல்-முனீப்' என்பது (தன் பாவங்களை எண்ணி) வருந்தித் திரும்புபவர் என்று பொருள்படும். சுஃப்யான் (ரஹ்) அவர்கள் கதாதா (ரஹ்) அவர்களிடமிருந்து அறிவிப்பதாவது: 'அல்-முனீப்' என்பது அல்லாஹ்வை நோக்கித் திரும்புபவர் என்பதாகும். இதன் பொருள், வானங்கள் மற்றும் பூமியின் படைப்பைக் கவனிப்பதில், புத்திசாலியாகவும் ஞானமுள்ளவராகவும் அல்லாஹ்வை நோக்கித் திரும்புபவராகவும் இருக்கும் ஒவ்வொரு அடியாருக்கும் ஓர் அத்தாட்சி இருக்கிறது என்பதாகும். உடல்களை மீண்டும் படைப்பதற்கும் உயிர்த்தெழுதலைக் கொண்டு வருவதற்கும் அல்லாஹ்வின் ஆற்றலுக்கு இதில் ஓர் அத்தாட்சி உள்ளது. ஏனெனில், இவ்வளவு பரந்த வெளியைக் கொண்ட வானங்களையும், இவ்வளவு ஆழமும் அகலமும் கொண்ட பூமியையும் படைக்க ஆற்றல் பெற்றவன், உடல்களை மீண்டும் படைக்கவும் சிதைந்த எலும்புகளை உயிர்ப்பிக்கவும் ஆற்றல் பெற்றவன் ஆவான். இது பின்வரும் வசனங்களைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالأَرْضَ</span> <span class=\"quran-arabic-font text-success\">بِقَادِرٍ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَخْلُقَ</span> <span class=\"quran-arabic-font text-success\">مِثْلَهُم</span> <span class=\"quran-arabic-font text-success\">بَلَى</span><br />\r\n<br />\r\n(வானங்களையும் பூமியையும் படைத்தவன் அவர்களைப் போன்றவர்களைப் படைக்க ஆற்றல் பெற்றவன் அல்லவா? ஆம், நிச்சயமாக!) (<a href=\"qurandisp.php?sura=36&ayah=81\" class=\"link\">36:81</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَخَلْقُ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالأَرْضِ</span> <span class=\"quran-arabic-font text-success\">أَكْبَرُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">خَلْقِ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">وَلَكِنَّ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக வானங்களையும் பூமியையும் படைப்பது மனிதர்களைப் படைப்பதை விடப் பெரிய காரியமாகும்; ஆயினும் மனிதர்களில் பெரும்பாலோர் (இதனை) அறியமாட்டார்கள்.) (<a href=\"qurandisp.php?sura=40&ayah=57\" class=\"link\">40:57</a>)<br />\r\n<br />","text":"மரணத்திற்குப் பிந்தைய வாழ்வை நிராகரிப்பவர்களும், அவர்களின் கருத்திற்குப் பதிலடியும்\n\r\n\n\r\nஇறுதித் தீர்ப்பு நாள் வருவதை நிராகரிப்பாளர்களும் நாத்திகர்களும் எவ்வாறு மறுத்தார்கள் என்பதையும், அதைப் பற்றிப் பேசியதற்காக அல்லாஹ்வின் தூதர் (ஸல்) அவர்களை அவர்கள் எப்படிக் கேலி செய்தார்கள் என்பதையும் அல்லாஹ் இங்கே நமக்குக் கூறுகிறான்.\n\r\n\n\r\nوَقَالَ الَّذِينَ كَفَرُواْ هَلْ نَدُلُّكُمْ عَلَى رَجُلٍ يُنَبِّئُكُمْ إِذَا مُزِّقْتُمْ كُلَّ مُمَزَّقٍ\n\r\n\n\r\n(நிராகரிப்பவர்கள் கூறுகிறார்கள்: \"நீங்கள் (மரணத்திற்குப் பின்) முழுவதுமாகச் சிதைக்கப்பட்டு, துகள் துகளாகச் சிதறிப் போன பிறகு...\" என்று உங்களுக்குக் கூறும் ஒரு மனிதரை நாங்கள் உங்களுக்குக் காட்டட்டுமா?) அதாவது, உங்கள் உடல்கள் பூமியில் மட்கிப் போய், எந்த அடையாளமும் இன்றிச் சிதைந்து போகும்போது,\n\r\n\n\r\nإِنَّكُمْ\n\r\n\n\r\n(நிச்சயமாக நீங்கள்) அதாவது, இது நிகழ்ந்த பிறகு,\n\r\n\n\r\nلَفِى خَلْقٍ جَدِيدٍ\n\r\n\n\r\n(புதியதொரு படைப்பாக ஆக்கப்படுவீர்கள்) அதாவது, நீங்கள் மீண்டும் உயிர்ப்பிக்கப்பட்டு, புதிதாக வாழ்வாதாரம் பெறுவீர்கள். \"இதை எங்களிடம் கூறுவதன் மூலம் அவர் இரண்டு காரியங்களில் ஒன்றைச் செய்கிறார்: ஒன்று, அவர் வேண்டுமென்றே எதையாவது இட்டுக்கட்டி, அல்லாஹ் தனக்கு வஹீ (இறைச்செய்தி) அருளியதாகக் கூறுகிறார்; அல்லது அவர் வேண்டுமென்றே அவ்வாறு செய்யவில்லை, மாறாக அவர் பைத்தியக்காரர்களைப் போலவும் மனநலம் பாதிக்கப்பட்டவர்களைப் போலவும் பிரமையில் இருக்கிறார்\" என்று அவர்கள் கூறினார்கள்.\n\r\n\n\r\nأَفْتَرَى عَلَى اللَّهِ كَذِباً أَم بِهِ جِنَّةٌ\n\r\n\n\r\n(அவர் அல்லாஹ்வின் மீது பொய்யை இட்டுக்கட்டினாரா அல்லது அவருக்குப் பைத்தியம் பிடித்துள்ளதா?) இவர்களின் கூற்றை மறுத்து அல்லாஹ் கூறினான்:\n\r\n\n\r\nبَلِ الَّذِينَ لاَ يُؤْمِنُونَ بِالآخِرَةِ فِي الْعَذَابِ وَالضَّلَالِ الْبَعِيدِ\n\r\n\n\r\n(அப்படியல்ல! மறுமையை நம்பாதவர்கள்தாம் வேதனையிலும், நீண்ட வழிகேட்டிலும் இருக்கிறார்கள்.) அதாவது, அவர்கள் கூறுவது போன்றோ அல்லது நினைப்பது போன்றோ இது இல்லை. மாறாக, முஹம்மது (ஸல்) அவர்களே உண்மையை உரைப்பவராகவும், நேர்மையாளராகவும், ஞானமுள்ளவராகவும் இருக்கிறார்கள். அவர்களே சத்தியத்தைக் கொண்டு வந்தவர்கள்; நிராகரிப்பாளர்களோ அறிவற்ற முட்டாள்களும் பொய்யர்களும் ஆவார்கள்.\n\r\n\n\r\nفِي الْعَذَابِ\n\r\n\n\r\n(வேதனையில் இருக்கிறார்கள்) என்பது அவர்களின் நிராகரிப்பைக் குறிக்கிறது; இதுவே அவர்களை அல்லாஹ்வின் வேதனைக்கு இட்டுச் செல்லும்.\n\r\n\n\r\nوَالضَّلَالِ الْبَعِيدِ\n\r\n\n\r\n(மற்றும் நீண்ட வழிகேட்டில்) அதாவது, இவ்வுலகில் உண்மையிலிருந்து வெகு தொலைவில் இருக்கிறார்கள். பின்னர் அல்லாஹ் வானங்கள் மற்றும் பூமியின் படைப்பில் உள்ள தனது ஆற்றலைக் குறித்து அவர்களை எச்சரிக்கிறான்:\n\r\n\n\r\nأَفَلَمْ يَرَوْاْ إِلَى مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ مِّنَ السَّمَاءِ وَالأَرْضِ\n\r\n\n\r\n(அவர்கள் தங்களுக்கு முன்னாலும் பின்னாலும் உள்ள வானத்தையும் பூமியையும் பார்க்கவில்லையா?) அதாவது, அவர்கள் எங்கு சென்றாலும், எந்தத் திசையில் சென்றாலும், வானம் அவர்களுக்கு மேலேயும் பூமி அவர்களுக்குக் கீழேயும் இருக்கிறது. இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nوَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ وَإِنَّا لَمُوسِعُونَ - وَالأَرْضَ فَرَشْنَاهَا فَنِعْمَ الْمَاهِدُونَ\n\r\n\n\r\n(நாம் வானத்தை (நம்) கரங்களால் (ஆற்றலால்) அமைத்தோம். நிச்சயமாக நாம் அதனை விரிவுபடுத்துபவர்கள் ஆவோம். மேலும் நாம் பூமியை விரித்தோம்; விரிப்பவர்களில் நாம் எவ்வளவு சிறந்தவர்!) (51:47-48)\n\r\n\n\r\nإِن نَّشَأْ نَخْسِفْ بِهِمُ الأَرْضَ أَوْ نُسْقِطْ عَلَيْهِمْ كِسَفاً مِّنَ السَّمَاءِ\n\r\n\n\r\n(நாம் நாடினால் அவர்களைப் பூமியில் புதையச் செய்வோம் அல்லது வானத்திலிருந்து ஒரு துண்டை அவர்கள் மீது விழச் செய்வோம்.) அதாவது, அவர்களின் அநியாயத்தின் காரணமாகவும், அவர்கள் மீது நமக்குள்ள ஆற்றலினாலும் நாம் விரும்பினால் அவர்களுக்கு அவ்வாறு செய்ய முடியும். இருப்பினும், நாம் பொறுமையுள்ளவனாகவும் மன்னிப்பவனாகவும் இருப்பதால் அதனைத் தாமதப்படுத்துகிறோம். பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nإِنَّ فِي ذَلِكَ لآيَةً لِّكُلِّ عَبْدٍ مُّنِيبٍ\n\r\n\n\r\n(நிச்சயமாக இதில் (அல்லாஹ்வையே) முன்னோக்கும் ஒவ்வொரு அடியாருக்கும் ஓர் அத்தாட்சி இருக்கிறது.) கதாதா (ரஹ்) அவர்களிடமிருந்து மஃமர் (ரஹ்) அவர்கள் அறிவிக்கிறார்கள்: 'அல்-முனீப்' என்பது (தன் பாவங்களை எண்ணி) வருந்தித் திரும்புபவர் என்று பொருள்படும். சுஃப்யான் (ரஹ்) அவர்கள் கதாதா (ரஹ்) அவர்களிடமிருந்து அறிவிப்பதாவது: 'அல்-முனீப்' என்பது அல்லாஹ்வை நோக்கித் திரும்புபவர் என்பதாகும். இதன் பொருள், வானங்கள் மற்றும் பூமியின் படைப்பைக் கவனிப்பதில், புத்திசாலியாகவும் ஞானமுள்ளவராகவும் அல்லாஹ்வை நோக்கித் திரும்புபவராகவும் இருக்கும் ஒவ்வொரு அடியாருக்கும் ஓர் அத்தாட்சி இருக்கிறது என்பதாகும். உடல்களை மீண்டும் படைப்பதற்கும் உயிர்த்தெழுதலைக் கொண்டு வருவதற்கும் அல்லாஹ்வின் ஆற்றலுக்கு இதில் ஓர் அத்தாட்சி உள்ளது. ஏனெனில், இவ்வளவு பரந்த வெளியைக் கொண்ட வானங்களையும், இவ்வளவு ஆழமும் அகலமும் கொண்ட பூமியையும் படைக்க ஆற்றல் பெற்றவன், உடல்களை மீண்டும் படைக்கவும் சிதைந்த எலும்புகளை உயிர்ப்பிக்கவும் ஆற்றல் பெற்றவன் ஆவான். இது பின்வரும் வசனங்களைப் போன்றது:\n\r\n\n\r\nأَوَلَيْسَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالأَرْضَ بِقَادِرٍ عَلَى أَن يَخْلُقَ مِثْلَهُم بَلَى\n\r\n\n\r\n(வானங்களையும் பூமியையும் படைத்தவன் அவர்களைப் போன்றவர்களைப் படைக்க ஆற்றல் பெற்றவன் அல்லவா? ஆம், நிச்சயமாக!) (36:81)\n\r\n\n\r\nلَخَلْقُ السَّمَاوَاتِ وَالأَرْضِ أَكْبَرُ مِنْ خَلْقِ النَّاسِ وَلَكِنَّ أَكْثَرَ النَّاسِ لاَ يَعْلَمُونَ\n\r\n\n\r\n(நிச்சயமாக வானங்களையும் பூமியையும் படைப்பது மனிதர்களைப் படைப்பதை விடப் பெரிய காரியமாகும்; ஆயினும் மனிதர்களில் பெரும்பாலோர் (இதனை) அறியமாட்டார்கள்.) (40:57)"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=11\" class=\"link\">34:11</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:11 ஐ பார்க்கவும்"},"11":{"html":"<strong>தாவூத் (அலை) அவர்களுக்கு அல்லாஹ் வழங்கிய அருட்கொடைகள்</strong><br />\r\n<br />\r\nதன் அடியாரும் தூதருமான தாவூத் (அலை) அவர்களுக்குத் தான் புரிந்த அருட்கொடைகளைப் பற்றியும், தனது பெரும் கிருபையிலிருந்து அவருக்கு வழங்கிய நபித்துவம், ஆட்சி மற்றும் பெரும் படைகளைப் பற்றியும் அல்லாஹ் இங்கு கூறுகிறான். மேலும், அவருக்கு ஒரு கம்பீரமான குரலை வழங்கி அருளினான். அவர் அல்லாஹ்வைப் போற்றித் துதிக்கும் (தஸ்பீஹ் செய்யும்) போது, உறுதியான, உயர்ந்த மலைகளும் அவருடன் சேர்ந்து துதித்தன. மேலும் பறவைகள் அந்தரத்தில் நின்று அவருடன் சேர்ந்து துதித்தன. ஸஹீஹ் ஹதீஸில் பின்வருமாறு பதிவாகியுள்ளது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள், அபூ மூஸா அல்-அஷ்அரீ (ரழி) அவர்கள் இரவில் குர்ஆன் ஓதுவதைக் கேட்டு, நின்று கவனித்தார்கள். பிறகு, <br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَقَدْ</span> <span class=\"quran-arabic-font text-success\">أُوتِيَ</span> <span class=\"quran-arabic-font text-success\">هذَا</span> <span class=\"quran-arabic-font text-success\">مِزْمَارًا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">مَزَامِيرِ</span> <span class=\"quran-arabic-font text-success\">آلِ</span> <span class=\"quran-arabic-font text-success\">دَاوُد</span>»<br />\r\n<br />\r\n(தாவூத் (அலை) அவர்களின் குடும்பத்தினருக்கு வழங்கப்பட்ட இனிமையான குரல்களில் ஒன்று இவருக்கும் வழங்கப்பட்டுள்ளது) என்று கூறினார்கள். அபூ உத்மான் அன்-நஹ்தீ கூறினார்கள்: \"அபூ மூஸா அல்-அஷ்அரீ (ரழி) அவர்களின் குரலை விட இனிமையான எந்தவொரு தாள வாத்தியத்தையோ, நரம்பிசையையோ அல்லது இசைக்கருவியையோ நான் கேட்டதில்லை.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوِّبِي</span><br />\r\n<br />\r\n(துதிப்பீராக) என்பது அல்லாஹ்வைப் போற்றித் துதிப்பதைக் குறிக்கும். இது இப்னு அப்பாஸ் (ரழி), முஜாஹித் மற்றும் பலரின் கருத்தாகும். 'தஃவீப்' என்ற சொல்லின் வேர்ச் சொல்லுக்கு 'திரும்பத் திரும்பக் கூறுவது' அல்லது 'பதிலளிப்பது' என்று பொருள். எனவே, மலைகளும் பறவைகளும் அவருக்குப் பின்னால் அந்தத் துதியைத் திரும்பத் திரும்பச் சொல்லுமாறு கட்டளையிடப்பட்டன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَلَنَّا</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الْحَدِيدَ</span><br />\r\n<br />\r\nமேலும் நாம் அவருக்கு இரும்பை மென்மையாக்கினோம். அல்-ஹஸன் அல்-பஸரீ, கதாதா, அல்-அஃமஷ் மற்றும் பலர் கூறினார்கள்: அவர் இரும்பை நெருப்பில் வாட்டவோ அல்லது சுத்தியலால் அடிக்கவோ தேவையில்லை; ஒரு நூலைப் போல அதைத் தன் கைகளாலேயே வளைக்கும் அளவுக்கு (அல்லாஹ் அதை மென்மையாக்கினான்). அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَنِ</span> <span class=\"quran-arabic-font text-success\">اعْمَلْ</span> <span class=\"quran-arabic-font text-success\">سَابِغَاتٍ</span><br />\r\n<br />\r\nஅதாவது \"முழுமையான கவச அங்கிகளைச் செய்வீராக...\", இதன் பொருள் சங்கிலிக் கவசம் என்பதாகும். கதாதா கூறினார்கள்: \"சங்கிலிக் கவசத்தை முதன்முதலில் உருவாக்கியவர் தாவூத் (அலை) அவர்களே; அதற்கு முன்பு மக்கள் இரும்புத் தகடுகளையே கவசமாக அணிந்து வந்தனர்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَدِّرْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">السَّرْدِ</span><br />\r\n<br />\r\n(மேலும் சங்கிலிக் கவசத்தின் வளையங்களை (ஸர்த்) முறையாக ஒழுங்குபடுத்துவீராக). இவ்வாறு அல்லாஹ் தனது தூதர் தாவூத் (அலை) அவர்களுக்குக் கவச அங்கிகளைத் தயாரிக்கும் முறையைக் கற்றுக் கொடுத்தான். இந்த வசனத்தைப் பற்றி முஜாஹித் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَدِّرْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">السَّرْدِ</span><br />\r\n<br />\r\n(மேலும் சங்கிலிக் கவசத்தின் வளையங்களை (ஸர்த்) முறையாக ஒழுங்குபடுத்துவீராக), \"அதன் ஆணிகளை (rivets) மிகவும் தளர்வாகப் போடாதீர்கள், அப்படிச் செய்தால் வளையங்கள் ஆடிவிடும்; அல்லது நகரவே முடியாத அளவுக்கு மிக நெருக்கமாகவும் போடாதீர்கள், மாறாக அதைச் சரியான அளவில் அமையுங்கள்.\" இப்னு அப்பாஸ் (ரழி) அவர்கள், \"ஸர்த் என்பது இரும்பு வளையத்தைக் குறிக்கும்\" எனக் கூறியதாக அலீ பின் அபீ தல்ஹா அறிவிக்கிறார்கள். சங்கிலிக் கவச ஆணிகளால் பிணைக்கப்பட்டிருந்தால் அதற்கு 'மஸ்ரூத்' என்று பெயர் என்று சிலர் கூறியுள்ளனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاعْمَلُوا</span> <span class=\"quran-arabic-font text-success\">صَالِحًا</span><br />\r\n<br />\r\nமேலும் நீங்கள் (மனிதர்களே) நற்செயல்களைச் செய்யுங்கள். அதாவது, அல்லாஹ் உங்களுக்கு வழங்கிய அருட்கொடைகளைக் கொண்டு நற்கருமங்களைச் செய்யுங்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">بَصِيرٌ</span><br />\r\n<br />\r\nநிச்சயமாக, நீங்கள் செய்வதை எல்லாம் நான் பார்ப்பவன். அதாவது, உங்களைக் கவனித்துக் கொண்டிருக்கிறேன், நீங்கள் செய்யும் மற்றும் சொல்லும் அனைத்தையும் பார்க்கிறேன்; அதில் எதுவும் எனக்கு மறைவானதல்ல.<br />\r\n<br />","text":"தாவூத் (அலை) அவர்களுக்கு அல்லாஹ் வழங்கிய அருட்கொடைகள்\n\r\n\n\r\nதன் அடியாரும் தூதருமான தாவூத் (அலை) அவர்களுக்குத் தான் புரிந்த அருட்கொடைகளைப் பற்றியும், தனது பெரும் கிருபையிலிருந்து அவருக்கு வழங்கிய நபித்துவம், ஆட்சி மற்றும் பெரும் படைகளைப் பற்றியும் அல்லாஹ் இங்கு கூறுகிறான். மேலும், அவருக்கு ஒரு கம்பீரமான குரலை வழங்கி அருளினான். அவர் அல்லாஹ்வைப் போற்றித் துதிக்கும் (தஸ்பீஹ் செய்யும்) போது, உறுதியான, உயர்ந்த மலைகளும் அவருடன் சேர்ந்து துதித்தன. மேலும் பறவைகள் அந்தரத்தில் நின்று அவருடன் சேர்ந்து துதித்தன. ஸஹீஹ் ஹதீஸில் பின்வருமாறு பதிவாகியுள்ளது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள், அபூ மூஸா அல்-அஷ்அரீ (ரழி) அவர்கள் இரவில் குர்ஆன் ஓதுவதைக் கேட்டு, நின்று கவனித்தார்கள். பிறகு,\n\r\n\n\r\n«لَقَدْ أُوتِيَ هذَا مِزْمَارًا مِنْ مَزَامِيرِ آلِ دَاوُد»\n\r\n\n\r\n(தாவூத் (அலை) அவர்களின் குடும்பத்தினருக்கு வழங்கப்பட்ட இனிமையான குரல்களில் ஒன்று இவருக்கும் வழங்கப்பட்டுள்ளது) என்று கூறினார்கள். அபூ உத்மான் அன்-நஹ்தீ கூறினார்கள்: \"அபூ மூஸா அல்-அஷ்அரீ (ரழி) அவர்களின் குரலை விட இனிமையான எந்தவொரு தாள வாத்தியத்தையோ, நரம்பிசையையோ அல்லது இசைக்கருவியையோ நான் கேட்டதில்லை.\"\n\r\n\n\r\nأَوِّبِي\n\r\n\n\r\n(துதிப்பீராக) என்பது அல்லாஹ்வைப் போற்றித் துதிப்பதைக் குறிக்கும். இது இப்னு அப்பாஸ் (ரழி), முஜாஹித் மற்றும் பலரின் கருத்தாகும். 'தஃவீப்' என்ற சொல்லின் வேர்ச் சொல்லுக்கு 'திரும்பத் திரும்பக் கூறுவது' அல்லது 'பதிலளிப்பது' என்று பொருள். எனவே, மலைகளும் பறவைகளும் அவருக்குப் பின்னால் அந்தத் துதியைத் திரும்பத் திரும்பச் சொல்லுமாறு கட்டளையிடப்பட்டன.\n\r\n\n\r\nوَأَلَنَّا لَهُ الْحَدِيدَ\n\r\n\n\r\nமேலும் நாம் அவருக்கு இரும்பை மென்மையாக்கினோம். அல்-ஹஸன் அல்-பஸரீ, கதாதா, அல்-அஃமஷ் மற்றும் பலர் கூறினார்கள்: அவர் இரும்பை நெருப்பில் வாட்டவோ அல்லது சுத்தியலால் அடிக்கவோ தேவையில்லை; ஒரு நூலைப் போல அதைத் தன் கைகளாலேயே வளைக்கும் அளவுக்கு (அல்லாஹ் அதை மென்மையாக்கினான்). அல்லாஹ் கூறினான்:\n\r\n\n\r\nأَنِ اعْمَلْ سَابِغَاتٍ\n\r\n\n\r\nஅதாவது \"முழுமையான கவச அங்கிகளைச் செய்வீராக...\", இதன் பொருள் சங்கிலிக் கவசம் என்பதாகும். கதாதா கூறினார்கள்: \"சங்கிலிக் கவசத்தை முதன்முதலில் உருவாக்கியவர் தாவூத் (அலை) அவர்களே; அதற்கு முன்பு மக்கள் இரும்புத் தகடுகளையே கவசமாக அணிந்து வந்தனர்.\"\n\r\n\n\r\nوَقَدِّرْ فِي السَّرْدِ\n\r\n\n\r\n(மேலும் சங்கிலிக் கவசத்தின் வளையங்களை (ஸர்த்) முறையாக ஒழுங்குபடுத்துவீராக). இவ்வாறு அல்லாஹ் தனது தூதர் தாவூத் (அலை) அவர்களுக்குக் கவச அங்கிகளைத் தயாரிக்கும் முறையைக் கற்றுக் கொடுத்தான். இந்த வசனத்தைப் பற்றி முஜாஹித் கூறினார்கள்:\n\r\n\n\r\nوَقَدِّرْ فِي السَّرْدِ\n\r\n\n\r\n(மேலும் சங்கிலிக் கவசத்தின் வளையங்களை (ஸர்த்) முறையாக ஒழுங்குபடுத்துவீராக), \"அதன் ஆணிகளை (rivets) மிகவும் தளர்வாகப் போடாதீர்கள், அப்படிச் செய்தால் வளையங்கள் ஆடிவிடும்; அல்லது நகரவே முடியாத அளவுக்கு மிக நெருக்கமாகவும் போடாதீர்கள், மாறாக அதைச் சரியான அளவில் அமையுங்கள்.\" இப்னு அப்பாஸ் (ரழி) அவர்கள், \"ஸர்த் என்பது இரும்பு வளையத்தைக் குறிக்கும்\" எனக் கூறியதாக அலீ பின் அபீ தல்ஹா அறிவிக்கிறார்கள். சங்கிலிக் கவச ஆணிகளால் பிணைக்கப்பட்டிருந்தால் அதற்கு 'மஸ்ரூத்' என்று பெயர் என்று சிலர் கூறியுள்ளனர்.\n\r\n\n\r\nوَاعْمَلُوا صَالِحًا\n\r\n\n\r\nமேலும் நீங்கள் (மனிதர்களே) நற்செயல்களைச் செய்யுங்கள். அதாவது, அல்லாஹ் உங்களுக்கு வழங்கிய அருட்கொடைகளைக் கொண்டு நற்கருமங்களைச் செய்யுங்கள்.\n\r\n\n\r\nإِنِّي بِمَا تَعْمَلُونَ بَصِيرٌ\n\r\n\n\r\nநிச்சயமாக, நீங்கள் செய்வதை எல்லாம் நான் பார்ப்பவன். அதாவது, உங்களைக் கவனித்துக் கொண்டிருக்கிறேன், நீங்கள் செய்யும் மற்றும் சொல்லும் அனைத்தையும் பார்க்கிறேன்; அதில் எதுவும் எனக்கு மறைவானதல்ல."},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=13\" class=\"link\">34:13</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:13 ஐ பார்க்கவும்"},"13":{"html":"<strong>அல்லாஹ் ஸுலைமான் (அலை) அவர்களுக்கு வழங்கிய அருட்கொடைகள்</strong><br />\r\n<br />\r\nதாவூத் (அலை) அவர்களுக்கு வழங்கிய அருட்கொடைகளைக் குறிப்பிட்ட பிறகு, அல்லாஹ் அவரது மகனான ஸுலைமான் (அலை) அவர்களுக்கு வழங்கியவற்றைக் குறிப்பிடுகிறான். அவர்கள் இருவர் மீதும் ஸலாம் (சாந்தி) உண்டாவதாக.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلِسُلَيْمَانَ</span> <span class=\"quran-arabic-font text-success\">الرِّيحَ</span> <span class=\"quran-arabic-font text-success\">غُدُوُّهَا</span> <span class=\"quran-arabic-font text-success\">شَهْرٌ</span> <span class=\"quran-arabic-font text-success\">وَرَوَاحُهَا</span> <span class=\"quran-arabic-font text-success\">شَهْرٌ</span><br />\r\n<br />\r\nஅல்லாஹ் அவருக்கு காற்றை வசப்படுத்திக் கொடுத்தான்; அது அவரது விரிப்பை ஒரு திசையில் ஒரு மாத கால பயண தூரத்திற்கும், மீண்டும் திரும்புவதற்கு ஒரு மாத கால பயண தூரத்திற்கும் சுமந்து செல்லும். ஹஸன் அல்-பஸரி அவர்கள் கூறினார்கள்: \"அவர்கள் காலையில் டமாஸ்கஸிலிருந்து புறப்பட்டு, இஸ்தகாரில் இறங்கி அங்கே மதிய உணவு உண்டார்கள்; பின்னர் இஸ்தகாரிலிருந்து பறந்து சென்று காபுலில் இரவைக் கழித்தார்கள்.\" டமாஸ்கஸிற்கும் இஸ்தகாருக்கும் இடையில் ஒரு வேகமான பயணிக்கு ஒரு மாதப் பயண தூரமும், இஸ்தகாருக்கும் காபுலுக்கும் இடையில் ஒரு வேகமான பயணிக்கு ஒரு மாதப் பயண தூரமும் உள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَسَلْنَا</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">عَيْنَ</span> <span class=\"quran-arabic-font text-success\">الْقِطْرِ</span><br />\r\n<br />\r\n(மேலும், நாம் அவருக்காக ‘கித்ர்’ ஊற்றை ஓடச் செய்தோம்.) இப்னு அப்பாஸ் (ரழி), முஜாஹித், இக்ரிமா, அதா அல்-குராஸானி, கதாதா, அஸ்-ஸுத்தி, ஸைத் பின் அஸ்லமிடமிருந்து மாலிக், அப்துர்-ரஹ்மான் பின் ஸைத் பின் அஸ்லம் மற்றும் பலர், \"கித்ர் என்பது செம்பைக் குறிக்கும்\" என்று கூறினார்கள். கதாதா அவர்கள், \"அது யமனில் இருந்தது\" என்று கூறினார்கள். ஸுலைமான் (அலை) அவர்களுக்காக மக்கள் உருவாக்கும் அனைத்துப் பொருட்களையும் அல்லாஹ் வெளிப்படுத்தினான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمِنَ</span> <span class=\"quran-arabic-font text-success\">الْجِنِّ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">يَدَيْهِ</span> <span class=\"quran-arabic-font text-success\">بِإِذْنِ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِ</span><br />\r\n<br />\r\n(மேலும், அவரது இறைவனின் அனுமதியுடன் அவருக்கு முன்னால் வேலை செய்யும் ஜின்களும் இருந்தனர்.) அதாவது, 'ஜின்களை அவருக்கு முன்னால் பணிபுரிய நாம் வசப்படுத்தினோம்.' அவரது இறைவனின் அனுமதியுடன், அதாவது அல்லாஹ்வின் கட்டளை மற்றும் கட்டுப்பாட்டின் கீழ், ஸுலைமான் (அலை) அவர்கள் விரும்பிய கட்டுமானங்களை அவர்கள் கட்டினார்கள், இன்னும் பிற வேலைகளையும் செய்தார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَزِغْ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">أَمْرِنَا</span><br />\r\n<br />\r\n(மேலும், அவர்களில் எவரேனும் நமது கட்டளையை விட்டு விலகினால்,) அதாவது, அவர்களில் எவரேனும் மாறுசெய்து கீழ்ப்படிய மறுத்தால்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">نُذِقْهُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عَذَابِ</span> <span class=\"quran-arabic-font text-success\">السَّعِيرِ</span><br />\r\n<br />\r\n(அவனை நாம் கொழுந்துவிட்டெரியும் நரக நெருப்பின் வேதனையைச் சுவைக்கச் செய்வோம்.) இதற்கு எரிக்கப்படுதல் என்று பொருள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مَّحَارِيبَ</span> <span class=\"quran-arabic-font text-success\">وَتَمَاثِيلَ</span><br />\r\n<br />\r\n(அவர் விரும்பியபடி ‘மஹாரிப்’களையும், ‘தமாஸீல்’களையும் அவர்கள் அவருக்காகச் செய்தார்கள்.) 'மஹாரிப்' என்பது அழகான கட்டிடங்களையும், ஒரு குடியிருப்பின் மிகச் சிறந்த உட்பகுதியையும் குறிக்கும். இப்னு ஸைத் அவர்கள், \"இதன் பொருள் வசிப்பிடங்கள்\" என்று கூறினார்கள். 'தமாஸீல்' என்பதைப் பொறுத்தவரை, அதிய்யா அல்-அவ்ஃபீ, அத்-தஹ்ஹாக் மற்றும் அஸ்-ஸுத்தி ஆகியோர் 'தமாஸீல்' என்றால் உருவப்படங்கள் என்று கூறினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجِفَانٍ</span> <span class=\"quran-arabic-font text-success\">كَالْجَوَابِ</span> <span class=\"quran-arabic-font text-success\">وَقُدُورٍ</span> <span class=\"quran-arabic-font text-success\">رَاسِيَاتٍ</span><br />\r\n<br />\r\n(நீர்நிலைகளைப் போன்ற பெரிய தொட்டிகளையும், நகர்த்த முடியாத பெரிய கொப்பரைகளையும் அவர்கள் செய்தார்கள்.) 'ஜவாப்' என்பது 'ஜாபியா' என்பதன் பன்மை வடிவமாகும், இது தண்ணீர் தேக்கி வைக்கப்படும் தடாகங்கள் அல்லது தொட்டிகளைக் குறிக்கும். 'குதூர் ராஸியாத்' என்பது அவற்றின் பிரம்மாண்டமான அளவு காரணமாக ஒரே இடத்தில் நிலைபெற்றுள்ள, நகர்த்த முடியாத பெரிய சமையல் பாத்திரங்கள் ஆகும். இது முஜாஹித், அத்-தஹ்ஹாக் மற்றும் பிறரின் கருத்தாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اعْمَلُواْ</span> <span class=\"quran-arabic-font text-success\">ءَالَ</span> <span class=\"quran-arabic-font text-success\">دَاوُودَ</span> <span class=\"quran-arabic-font text-success\">شُكْراً</span><br />\r\n<br />\r\n(‘தாவூத் (அலை) அவர்களின் குடும்பத்தாரே! நன்றியுடன் செயல்படுங்கள்!’) அதாவது, 'இவ்வுலகிலும் மறுமையிலும் நாம் உங்களுக்கு வழங்கிய அருட்கொடைகளுக்காக நன்றியுடன் நற்செயல்கள் புரியுங்கள் என்று நாம் அவர்களிடம் கூறினோம்.' நன்றியுணர்வு என்பது சொற்கள் மற்றும் எண்ணங்களால் மட்டுமல்லாது, செயல்களாலும் வெளிப்படுத்தப்பட வேண்டும் என்பதை இது உணர்த்துகிறது. அபூ அப்துர்-ரஹ்மான் அல்-ஹுபுலீ அவர்கள் கூறினார்கள்: \"தொழுகை ஒரு நன்றி, நோன்பு ஒரு நன்றி, அல்லாஹ்வின் திருப்திக்காக நீங்கள் செய்யும் ஒவ்வொரு நற்செயலும் ஒரு நன்றியாகும். நன்றிகளில் மிகச் சிறந்தது அவனைப் புகழ்வதே ஆகும்.\" இதனை இப்னு ஜரீர் அவர்கள் பதிவு செய்துள்ளார்கள். ஸஹீஹைன் (புகாரி, முஸ்லிம்) நூல்களில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறியதாக அறிவிக்கப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">أَحَبَّ</span> <span class=\"quran-arabic-font text-success\">الصَّلَاةِ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">صَلَاةُ</span> <span class=\"quran-arabic-font text-success\">دَاوُدَ،</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">يَنَامُ</span> <span class=\"quran-arabic-font text-success\">نِصْفَ</span> <span class=\"quran-arabic-font text-success\">اللَّيْلِ،</span> <span class=\"quran-arabic-font text-success\">وَيَقُومُ</span> <span class=\"quran-arabic-font text-success\">ثُلُثَهُ،</span> <span class=\"quran-arabic-font text-success\">وَيَنَامُ</span> <span class=\"quran-arabic-font text-success\">سُدُسَهُ،</span> <span class=\"quran-arabic-font text-success\">وَأَحَبَّ</span> <span class=\"quran-arabic-font text-success\">الصِّيَامِ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">صِيَامُ</span> <span class=\"quran-arabic-font text-success\">دَاوُدَ،</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">يَصُومُ</span> <span class=\"quran-arabic-font text-success\">يَوْمًا</span> <span class=\"quran-arabic-font text-success\">وَيُفْطِرُ</span> <span class=\"quran-arabic-font text-success\">يَوْمًا،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَفِرُّ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">لَاقَى</span>»<br />\r\n<br />\r\n(\"அல்லாஹ்வுக்கு மிகவும் விருப்பமான தொழுகை தாவூத் (அலை) அவர்களின் தொழுகையாகும். அவர்கள் இரவின் பாதி வரை உறங்குவார்கள், பின்னர் அதன் மூன்றில் ஒரு பகுதி நின்றும் வணங்குவார்கள், பிறகு எஞ்சிய ஆறில் ஒரு பகுதி உறங்குவார்கள். அல்லாஹ்வுக்கு மிகவும் விருப்பமான நோன்பு தாவூத் (அலை) அவர்களின் நோன்பாகும். அவர்கள் ஒரு நாள் நோன்பு நோற்பார்கள், ஒரு நாள் நோன்பை விட்டுவிடுவார்கள். அவர்கள் போர்க்களத்தில் எதிரியைச் சந்திக்கும்போது ஒருபோதும் புறங்காட்டி ஓடமாட்டார்கள்.\")<br />\r\n<br />\r\nஇப்னு அபீ ஹாதிம் அவர்கள் ஃபுளைல் அவர்கள் இந்த வசனத்தைப் பற்றிக் கூறியதாக அறிவிக்கிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اعْمَلُواْ</span> <span class=\"quran-arabic-font text-success\">ءَالَ</span> <span class=\"quran-arabic-font text-success\">دَاوُودَ</span> <span class=\"quran-arabic-font text-success\">شُكْراً</span><br />\r\n<br />\r\n(‘தாவூத் (அலை) அவர்களின் குடும்பத்தாரே! நன்றியுடன் செயல்படுங்கள்!’) தாவூத் (அலை) அவர்கள் கூறினார்கள்: \"இறைவா! நான் உனக்கு எப்படி நன்றி செலுத்த முடியும்? ஏனெனில், நான் உனக்கு நன்றி செலுத்துவதே உன்னிடமிருந்து எனக்குக் கிடைத்த ஒரு அருட்கொடைதானே!\" அதற்கு அல்லாஹ் கூறினான்: \"இப்போது நீ எனக்கு உண்மையாக நன்றி செலுத்திவிட்டாய்; ஏனெனில் அது என்னிடமிருந்து கிடைத்த அருட்கொடை என்பதை நீ உணர்ந்து கொண்டாய்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَلِيلٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عِبَادِىَ</span> <span class=\"quran-arabic-font text-success\">الشَّكُورُ</span><br />\r\n<br />\r\nஆனால், என் அடியார்களில் நன்றி செலுத்துவோர் மிகக் குறைவே. இது யதார்த்த நிலையின் பிரதிபலிப்பாகும்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"அல்லாஹ் ஸுலைமான் (அலை) அவர்களுக்கு வழங்கிய அருட்கொடைகள்\n\r\n\n\r\nதாவூத் (அலை) அவர்களுக்கு வழங்கிய அருட்கொடைகளைக் குறிப்பிட்ட பிறகு, அல்லாஹ் அவரது மகனான ஸுலைமான் (அலை) அவர்களுக்கு வழங்கியவற்றைக் குறிப்பிடுகிறான். அவர்கள் இருவர் மீதும் ஸலாம் (சாந்தி) உண்டாவதாக.\n\r\n\n\r\nوَلِسُلَيْمَانَ الرِّيحَ غُدُوُّهَا شَهْرٌ وَرَوَاحُهَا شَهْرٌ\n\r\n\n\r\nஅல்லாஹ் அவருக்கு காற்றை வசப்படுத்திக் கொடுத்தான்; அது அவரது விரிப்பை ஒரு திசையில் ஒரு மாத கால பயண தூரத்திற்கும், மீண்டும் திரும்புவதற்கு ஒரு மாத கால பயண தூரத்திற்கும் சுமந்து செல்லும். ஹஸன் அல்-பஸரி அவர்கள் கூறினார்கள்: \"அவர்கள் காலையில் டமாஸ்கஸிலிருந்து புறப்பட்டு, இஸ்தகாரில் இறங்கி அங்கே மதிய உணவு உண்டார்கள்; பின்னர் இஸ்தகாரிலிருந்து பறந்து சென்று காபுலில் இரவைக் கழித்தார்கள்.\" டமாஸ்கஸிற்கும் இஸ்தகாருக்கும் இடையில் ஒரு வேகமான பயணிக்கு ஒரு மாதப் பயண தூரமும், இஸ்தகாருக்கும் காபுலுக்கும் இடையில் ஒரு வேகமான பயணிக்கு ஒரு மாதப் பயண தூரமும் உள்ளது.\n\r\n\n\r\nوَأَسَلْنَا لَهُ عَيْنَ الْقِطْرِ\n\r\n\n\r\n(மேலும், நாம் அவருக்காக ‘கித்ர்’ ஊற்றை ஓடச் செய்தோம்.) இப்னு அப்பாஸ் (ரழி), முஜாஹித், இக்ரிமா, அதா அல்-குராஸானி, கதாதா, அஸ்-ஸுத்தி, ஸைத் பின் அஸ்லமிடமிருந்து மாலிக், அப்துர்-ரஹ்மான் பின் ஸைத் பின் அஸ்லம் மற்றும் பலர், \"கித்ர் என்பது செம்பைக் குறிக்கும்\" என்று கூறினார்கள். கதாதா அவர்கள், \"அது யமனில் இருந்தது\" என்று கூறினார்கள். ஸுலைமான் (அலை) அவர்களுக்காக மக்கள் உருவாக்கும் அனைத்துப் பொருட்களையும் அல்லாஹ் வெளிப்படுத்தினான்.\n\r\n\n\r\nوَمِنَ الْجِنِّ مَن يَعْمَلُ بَيْنَ يَدَيْهِ بِإِذْنِ رَبِّهِ\n\r\n\n\r\n(மேலும், அவரது இறைவனின் அனுமதியுடன் அவருக்கு முன்னால் வேலை செய்யும் ஜின்களும் இருந்தனர்.) அதாவது, 'ஜின்களை அவருக்கு முன்னால் பணிபுரிய நாம் வசப்படுத்தினோம்.' அவரது இறைவனின் அனுமதியுடன், அதாவது அல்லாஹ்வின் கட்டளை மற்றும் கட்டுப்பாட்டின் கீழ், ஸுலைமான் (அலை) அவர்கள் விரும்பிய கட்டுமானங்களை அவர்கள் கட்டினார்கள், இன்னும் பிற வேலைகளையும் செய்தார்கள்.\n\r\n\n\r\nوَمَن يَزِغْ مِنْهُمْ عَنْ أَمْرِنَا\n\r\n\n\r\n(மேலும், அவர்களில் எவரேனும் நமது கட்டளையை விட்டு விலகினால்,) அதாவது, அவர்களில் எவரேனும் மாறுசெய்து கீழ்ப்படிய மறுத்தால்,\n\r\n\n\r\nنُذِقْهُ مِنْ عَذَابِ السَّعِيرِ\n\r\n\n\r\n(அவனை நாம் கொழுந்துவிட்டெரியும் நரக நெருப்பின் வேதனையைச் சுவைக்கச் செய்வோம்.) இதற்கு எரிக்கப்படுதல் என்று பொருள்.\n\r\n\n\r\nيَعْمَلُونَ لَهُ مَا يَشَآءُ مِن مَّحَارِيبَ وَتَمَاثِيلَ\n\r\n\n\r\n(அவர் விரும்பியபடி ‘மஹாரிப்’களையும், ‘தமாஸீல்’களையும் அவர்கள் அவருக்காகச் செய்தார்கள்.) 'மஹாரிப்' என்பது அழகான கட்டிடங்களையும், ஒரு குடியிருப்பின் மிகச் சிறந்த உட்பகுதியையும் குறிக்கும். இப்னு ஸைத் அவர்கள், \"இதன் பொருள் வசிப்பிடங்கள்\" என்று கூறினார்கள். 'தமாஸீல்' என்பதைப் பொறுத்தவரை, அதிய்யா அல்-அவ்ஃபீ, அத்-தஹ்ஹாக் மற்றும் அஸ்-ஸுத்தி ஆகியோர் 'தமாஸீல்' என்றால் உருவப்படங்கள் என்று கூறினார்கள்.\n\r\n\n\r\nوَجِفَانٍ كَالْجَوَابِ وَقُدُورٍ رَاسِيَاتٍ\n\r\n\n\r\n(நீர்நிலைகளைப் போன்ற பெரிய தொட்டிகளையும், நகர்த்த முடியாத பெரிய கொப்பரைகளையும் அவர்கள் செய்தார்கள்.) 'ஜவாப்' என்பது 'ஜாபியா' என்பதன் பன்மை வடிவமாகும், இது தண்ணீர் தேக்கி வைக்கப்படும் தடாகங்கள் அல்லது தொட்டிகளைக் குறிக்கும். 'குதூர் ராஸியாத்' என்பது அவற்றின் பிரம்மாண்டமான அளவு காரணமாக ஒரே இடத்தில் நிலைபெற்றுள்ள, நகர்த்த முடியாத பெரிய சமையல் பாத்திரங்கள் ஆகும். இது முஜாஹித், அத்-தஹ்ஹாக் மற்றும் பிறரின் கருத்தாகும்.\n\r\n\n\r\nاعْمَلُواْ ءَالَ دَاوُودَ شُكْراً\n\r\n\n\r\n(‘தாவூத் (அலை) அவர்களின் குடும்பத்தாரே! நன்றியுடன் செயல்படுங்கள்!’) அதாவது, 'இவ்வுலகிலும் மறுமையிலும் நாம் உங்களுக்கு வழங்கிய அருட்கொடைகளுக்காக நன்றியுடன் நற்செயல்கள் புரியுங்கள் என்று நாம் அவர்களிடம் கூறினோம்.' நன்றியுணர்வு என்பது சொற்கள் மற்றும் எண்ணங்களால் மட்டுமல்லாது, செயல்களாலும் வெளிப்படுத்தப்பட வேண்டும் என்பதை இது உணர்த்துகிறது. அபூ அப்துர்-ரஹ்மான் அல்-ஹுபுலீ அவர்கள் கூறினார்கள்: \"தொழுகை ஒரு நன்றி, நோன்பு ஒரு நன்றி, அல்லாஹ்வின் திருப்திக்காக நீங்கள் செய்யும் ஒவ்வொரு நற்செயலும் ஒரு நன்றியாகும். நன்றிகளில் மிகச் சிறந்தது அவனைப் புகழ்வதே ஆகும்.\" இதனை இப்னு ஜரீர் அவர்கள் பதிவு செய்துள்ளார்கள். ஸஹீஹைன் (புகாரி, முஸ்லிம்) நூல்களில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறியதாக அறிவிக்கப்பட்டுள்ளது:\n\r\n\n\r\n«إِنَّ أَحَبَّ الصَّلَاةِ إِلَى اللهِ تَعَالَى صَلَاةُ دَاوُدَ، كَانَ يَنَامُ نِصْفَ اللَّيْلِ، وَيَقُومُ ثُلُثَهُ، وَيَنَامُ سُدُسَهُ، وَأَحَبَّ الصِّيَامِ إِلَى اللهِ تَعَالَى صِيَامُ دَاوُدَ، كَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا، وَلَا يَفِرُّ إِذَا لَاقَى»\n\r\n\n\r\n(\"அல்லாஹ்வுக்கு மிகவும் விருப்பமான தொழுகை தாவூத் (அலை) அவர்களின் தொழுகையாகும். அவர்கள் இரவின் பாதி வரை உறங்குவார்கள், பின்னர் அதன் மூன்றில் ஒரு பகுதி நின்றும் வணங்குவார்கள், பிறகு எஞ்சிய ஆறில் ஒரு பகுதி உறங்குவார்கள். அல்லாஹ்வுக்கு மிகவும் விருப்பமான நோன்பு தாவூத் (அலை) அவர்களின் நோன்பாகும். அவர்கள் ஒரு நாள் நோன்பு நோற்பார்கள், ஒரு நாள் நோன்பை விட்டுவிடுவார்கள். அவர்கள் போர்க்களத்தில் எதிரியைச் சந்திக்கும்போது ஒருபோதும் புறங்காட்டி ஓடமாட்டார்கள்.\")\n\r\n\n\r\nஇப்னு அபீ ஹாதிம் அவர்கள் ஃபுளைல் அவர்கள் இந்த வசனத்தைப் பற்றிக் கூறியதாக அறிவிக்கிறார்கள்:\n\r\n\n\r\nاعْمَلُواْ ءَالَ دَاوُودَ شُكْراً\n\r\n\n\r\n(‘தாவூத் (அலை) அவர்களின் குடும்பத்தாரே! நன்றியுடன் செயல்படுங்கள்!’) தாவூத் (அலை) அவர்கள் கூறினார்கள்: \"இறைவா! நான் உனக்கு எப்படி நன்றி செலுத்த முடியும்? ஏனெனில், நான் உனக்கு நன்றி செலுத்துவதே உன்னிடமிருந்து எனக்குக் கிடைத்த ஒரு அருட்கொடைதானே!\" அதற்கு அல்லாஹ் கூறினான்: \"இப்போது நீ எனக்கு உண்மையாக நன்றி செலுத்திவிட்டாய்; ஏனெனில் அது என்னிடமிருந்து கிடைத்த அருட்கொடை என்பதை நீ உணர்ந்து கொண்டாய்.\"\n\r\n\n\r\nوَقَلِيلٌ مِّنْ عِبَادِىَ الشَّكُورُ\n\r\n\n\r\nஆனால், என் அடியார்களில் நன்றி செலுத்துவோர் மிகக் குறைவே. இது யதார்த்த நிலையின் பிரதிபலிப்பாகும்."},"14":{"html":"<strong>சுலைமானின் மரணம்</strong><br />\r\n<br />\r\nசுலைமான் (அலை) அவர்கள் எவ்வாறு மரணித்தார்கள் என்பதையும், கடினமான பணிகளைச் செய்வதற்காக அவருக்குக் கீழ்ப்படுத்தப்பட்டிருந்த ஜின்களிடமிருந்து அல்லாஹ் அவருடைய மரணத்தை எவ்வாறு மறைத்தான் என்பதையும் அல்லாஹ் கூறுகிறான். இப்னு அப்பாஸ் (ரழி), முஜாஹித், அல்-ஹசன், கதாதா மற்றும் பலர் கூறியது போல, அவர்கள் தமது கைத்தடியின் மீது சாய்ந்தபடி இருந்தார்கள். கிட்டத்தட்ட ஓராண்டு காலம் வரை நீண்ட நேரமாக அவர்கள் அவ்வாறே இருந்தார்கள். கறையான் எனும் நிலத்தின் உயிரினம் ஒன்று அந்த ஊன்றுகோலை அரித்தபோது, அது பலவீனமடைந்து அவர்கள் தரையில் விழுந்தார்கள். அப்போதுதான், அவர்கள் நீண்ட காலத்திற்கு முன்பே மரணித்துவிட்டார்கள் என்பது வெளிப்பட்டது. மேலும், ஜின்கள் தாங்கள் கற்பனை செய்துகொண்டு மக்களை ஏமாற்ற முயன்றது போல, தங்களால் மறைவானவற்றை அறிய முடியாது என்பது ஜின்களுக்கும் மனிதர்களுக்கும் தெளிவாகியது. இதனையே அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾مَا</span> <span class=\"quran-arabic-font text-success\">دَلَّهُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَوْتِهِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">دَابَّةُ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">تَأْكُلُ</span> <span class=\"quran-arabic-font text-success\">مِنسَأَتَهُ</span> <span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">خَرَّ</span> <span class=\"quran-arabic-font text-success\">تَبَيَّنَتِ</span> <span class=\"quran-arabic-font text-success\">الْجِنُّ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">لَّوْ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ</span> <span class=\"quran-arabic-font text-success\">الْغَيْبَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لَبِثُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">الْمُهِينِ﴿</span><br />\r\n<br />\r\n(அவருடைய கைத்தடியை மெதுவாக அரித்துத் தின்றுகொண்டிருந்த நிலத்தின் ஒரு கறையானைத் தவிர வேறெதுவும் ஜின்களுக்கு அவருடைய மரணத்தை அறிவிக்கவில்லை. அவர் கீழே விழுந்தபோது, ஜின்கள் மறைவானவற்றை அறிந்திருந்தால் இழிவுபடுத்தும் இந்த வேதனையில் தாங்கள் தங்கியிருந்திருக்க மாட்டோம் என்பதைத் தெளிவாகக் கண்டுகொண்டன.) அதாவது, ஜின்கள் பொய் சொல்லிக் கொண்டிருந்தார்கள் என்பது மக்களுக்குத் தெளிவாகியது.<br />\r\n<br />\r\n<br />\r\n<br />","text":"சுலைமானின் மரணம்\n\r\n\n\r\nசுலைமான் (அலை) அவர்கள் எவ்வாறு மரணித்தார்கள் என்பதையும், கடினமான பணிகளைச் செய்வதற்காக அவருக்குக் கீழ்ப்படுத்தப்பட்டிருந்த ஜின்களிடமிருந்து அல்லாஹ் அவருடைய மரணத்தை எவ்வாறு மறைத்தான் என்பதையும் அல்லாஹ் கூறுகிறான். இப்னு அப்பாஸ் (ரழி), முஜாஹித், அல்-ஹசன், கதாதா மற்றும் பலர் கூறியது போல, அவர்கள் தமது கைத்தடியின் மீது சாய்ந்தபடி இருந்தார்கள். கிட்டத்தட்ட ஓராண்டு காலம் வரை நீண்ட நேரமாக அவர்கள் அவ்வாறே இருந்தார்கள். கறையான் எனும் நிலத்தின் உயிரினம் ஒன்று அந்த ஊன்றுகோலை அரித்தபோது, அது பலவீனமடைந்து அவர்கள் தரையில் விழுந்தார்கள். அப்போதுதான், அவர்கள் நீண்ட காலத்திற்கு முன்பே மரணித்துவிட்டார்கள் என்பது வெளிப்பட்டது. மேலும், ஜின்கள் தாங்கள் கற்பனை செய்துகொண்டு மக்களை ஏமாற்ற முயன்றது போல, தங்களால் மறைவானவற்றை அறிய முடியாது என்பது ஜின்களுக்கும் மனிதர்களுக்கும் தெளிவாகியது. இதனையே அல்லாஹ் கூறுகிறான்: ﴾مَا دَلَّهُمْ عَلَى مَوْتِهِ إِلاَّ دَابَّةُ الْأَرْضِ تَأْكُلُ مِنسَأَتَهُ فَلَمَّا خَرَّ تَبَيَّنَتِ الْجِنُّ أَن لَّوْ كَانُواْ يَعْلَمُونَ الْغَيْبَ مَا لَبِثُواْ فِى الْعَذَابِ الْمُهِينِ﴿\n\r\n\n\r\n(அவருடைய கைத்தடியை மெதுவாக அரித்துத் தின்றுகொண்டிருந்த நிலத்தின் ஒரு கறையானைத் தவிர வேறெதுவும் ஜின்களுக்கு அவருடைய மரணத்தை அறிவிக்கவில்லை. அவர் கீழே விழுந்தபோது, ஜின்கள் மறைவானவற்றை அறிந்திருந்தால் இழிவுபடுத்தும் இந்த வேதனையில் தாங்கள் தங்கியிருந்திருக்க மாட்டோம் என்பதைத் தெளிவாகக் கண்டுகொண்டன.) அதாவது, ஜின்கள் பொய் சொல்லிக் கொண்டிருந்தார்கள் என்பது மக்களுக்குத் தெளிவாகியது."},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=17\" class=\"link\">34:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:17 ஐ பார்க்கவும்"},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=17\" class=\"link\">34:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:17 ஐ பார்க்கவும்"},"17":{"html":"<strong>ஸபா மக்களின் நிராகரிப்பும் அவர்களின் தண்டனையும்</strong><br />\r\n<br />\r\nஸபா என்பது யமன் தேசத்து மன்னர்களையும் மக்களையும் குறிக்கும். யமனின் பண்டைய மன்னர்களின் பட்டப் பெயரான 'அத்தபாபிஆ' (துப்பா) என்பவர்கள் அவர்களில் ஒரு பகுதியினரே. சுலைமான் (அலை) அவர்களைச் சந்தித்த அரசியான பல்கீஸும் அவர்களில் ஒருவராவார். அவர்கள் அந்தத் தேசத்தில் வளமான வாழ்வாதாரங்கள், பயிர்கள் மற்றும் பழங்களுடன் பொறாமைப்படத்தக்க ஆடம்பர வாழ்க்கை வாழ்ந்து வந்தார்கள். அல்லாஹ் அவர்களுக்குத் தூதர்களை அனுப்பி, அவனுடைய வாழ்வாதாரங்களிலிருந்து உண்ணுமாறும், அவனை மட்டுமே வணங்கி அவனுக்கு நன்றி செலுத்துமாறும் கூறினான். அல்லாஹ் நாடிய காலம் வரை அவர்கள் அதைப் பின்பற்றினார்கள்; பின்னர் தங்களுக்குக் கட்டளையிடப்பட்ட நேர்வழியிலிருந்து அவர்கள் விலகிச் சென்றார்கள். எனவே, அவர்கள் ஒரு பெரும் வெள்ளத்தால் தண்டிக்கப்பட்டார்கள். அந்த வெள்ளம் அவர்களை ஸபாவுக்கு அருகிலுள்ள பல திசைகளிலும் சிதறடித்தது. இதன் விவரங்களை அல்லாஹ் நாடினால் (இன்ஷா அல்லாஹ்) கீழே விரிவாகக் காண்போம். அவனிடமே நாம் முழுமையாகப் பொறுப்பேற்படுத்துகிறோம். இப்னு ஜரீர் அவர்கள் பதிவு செய்துள்ளார்கள்: ஃபர்வா பின் முஸைக் அல்-குதைஃபீ (ரழி) அவர்கள் கூறியதாவது: \"ஒரு மனிதர், 'அல்லாஹ்வின் தூதரே! ஸபாவைப் பற்றி எனக்குச் சொல்லுங்கள் - அது ஒரு நிலமா அல்லது ஒரு பெண்ணா?' என்று கேட்டார். அதற்கு அவர்கள் (ஸல்) கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">بِأَرْضٍ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">امْرَأَةٍ،</span> <span class=\"quran-arabic-font text-success\">وَلَكِنَّهُ</span> <span class=\"quran-arabic-font text-success\">رَجُلٌ</span> <span class=\"quran-arabic-font text-success\">وُلِدَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">عَشَرَةٌ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْوَلَدِ،</span> <span class=\"quran-arabic-font text-success\">فَتَيَامَنَ</span> <span class=\"quran-arabic-font text-success\">سِتَّةٌ</span> <span class=\"quran-arabic-font text-success\">وَتَشَاءَمَ</span> <span class=\"quran-arabic-font text-success\">أَرْبَعَةٌ،</span> <span class=\"quran-arabic-font text-success\">فَأَمَّا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">تَشَاءَمُوا</span>: <span class=\"quran-arabic-font text-success\">فَلَخْمٌ</span> <span class=\"quran-arabic-font text-success\">وَجُذَامٌ</span> <span class=\"quran-arabic-font text-success\">وَعَامِلَةُ</span> <span class=\"quran-arabic-font text-success\">وَغَسَّانُ،</span> <span class=\"quran-arabic-font text-success\">وَأَمَّا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">تَيَامَنُوا</span>: <span class=\"quran-arabic-font text-success\">فَكِنْدَةُ</span> <span class=\"quran-arabic-font text-success\">وَالْأَشْعَرِيُّونَ</span> <span class=\"quran-arabic-font text-success\">وَالْأَزْدُ</span> <span class=\"quran-arabic-font text-success\">وَمَذْحِجٌ</span> <span class=\"quran-arabic-font text-success\">وَحِمْيَرُ</span> <span class=\"quran-arabic-font text-success\">وَأَنْمَار</span>»<br />\r\n<br />\r\n(அது ஒரு நிலமும் அல்ல, ஒரு பெண்ணும் அல்ல. அவர் ஒரு மனிதர், அவருக்குப் பத்து குழந்தைகள் இருந்தன. அவர்களில் ஆறு பேர் யமன் நோக்கியும், நான்கு பேர் ஷாம் நோக்கியும் சென்றனர். ஷாம் நோக்கிச் சென்றவர்கள் லக்ம், ஜுதாம், ஆமிலா மற்றும் கஸ்ஸான் ஆவர். தெற்கு நோக்கி (யமன்) சென்றவர்கள் கிந்தா, அல்-அஷ்அரிய்யூன், அல்-அஸ்து, மத்ஹிஜ், ஹிம்யர் மற்றும் அன்மார் ஆவர்.) ஒரு மனிதர், 'அன்மார் என்பவர் யார்?' என்று கேட்டார். அதற்கு அவர்கள் (ஸல்) கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">خَثْعَمُ</span> <span class=\"quran-arabic-font text-success\">وَبَجِيلَة</span>»<br />\r\n<br />\r\n(அவர்களில் கத்அம் மற்றும் பஜீலா ஆகிய கிளையினரும் உள்ளனர்.)\" இதை அத்-திர்மிதீ தனது 'ஜாமிஉ சுனன்' நூலில் இன்னும் விரிவாகப் பதிவு செய்துள்ளார். மேலும், \"இது ஒரு ஹஸன் கரீப் ஹதீஸ்\" என்றும் அவர் குறிப்பிட்டுள்ளார். முஹம்மது பின் இஸ்ஹாக் உள்ளிட்ட வம்சாவளி ஆய்வாளர்கள் கூறுகிறார்கள்: \"ஸபாவின் பெயர் அப்த் ஷம்ஸ் பின் யஷ்ஜுப் பின் யஃருப் பின் கஹ்தான் என்பதாகும். அரபுப் பழங்குடியினரில் முதன்முதலில் (எதிரிகளைச்) சிறைபிடித்தவர் என்பதால் 'ஸபா' என்று அழைக்கப்பட்டார். மேலும் இவர் 'அர்-ராஇஷ்' என்றும் அறியப்பட்டார். ஏனெனில், போரில் கிடைத்த வெற்றிப் பொருட்களை (கனீமத்) முதன்முதலில் கைப்பற்றித் தன் மக்களுக்குப் பங்கிட்டுக் கொடுத்தவர் இவரே. அரபியில் செல்வத்தை 'ரீஷ்' அல்லது 'ரியாஷ்' என்று அழைப்பதால் இவர் அர்-ராஇஷ் எனப்பட்டார்.\" கஹ்தான் என்பவர் யார் என்பது குறித்து மூன்று கருத்துக்கள் உள்ளன. (முதலாவது) அவர் இரம் பின் ஸாம் பின் நூஹ் (அலை) அவர்களின் வழித்தோன்றல். இதில் அவர் அவரிடமிருந்து எவ்வாறு தோன்றினார் என்பது குறித்து மூன்று உட்பிரிவு கருத்துக்கள் உள்ளன. (இரண்டாவது) அவர் ஹூத் (அலை) அவர்களின் மற்றொரு பெயரான ஆபிர் என்பவரின் வழித்தோன்றல். இதிலும் அவர் அவரிடமிருந்து எவ்வாறு தோன்றினார் என்பது குறித்து மூன்று உட்பிரிவு கருத்துக்கள் உள்ளன. (மூன்றாவது) அவர் இப்ராஹீம் அல்-கலீல் (அலை) அவர்களின் மகன் இஸ்மாயீல் (அலை) அவர்களின் வழித்தோன்றல். இதிலும் அவர் அவரிடமிருந்து எவ்வாறு தோன்றினார் என்பது குறித்து மூன்று உட்பிரிவு கருத்துக்கள் உள்ளன. இமாம் அல்-ஹாஃபிழ் அபூ உமர் பின் அப்துல் பர் அன்-நமரீ (ரஹிமஹுல்லாஹ்) அவர்கள் தனது 'அல்-இன்பாஹ் அலா திக்ர் உசூல் அல்-கபாயில் அர்-ருவாத்' எனும் நூலில் இதைப் பற்றி விரிவாக விளக்கியுள்ளார். நபிகளாரின் வார்த்தைகளின் பொருள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">رَجُلًا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْعَرَب</span>»<br />\r\n<br />\r\n(அவர் அரபுகளில் ஒரு மனிதராக இருந்தார்.) என்பது, அவர் இப்ராஹீம் (அலை) அவர்களுக்கு முந்தைய அசல் அரபிகளில் ஒருவராக இருந்தார் என்பதாகும். அவர் ஸாம் பின் நூஹ் (அலை) அவர்களின் வம்சாவழியில் வந்தவர். மேலே கூறப்பட்ட மூன்றாவது கருத்தின்படி அவர் இப்ராஹீம் (அலை) அவர்களின் வழித்தோன்றலாகக் கருதப்பட்டாலும், அது மக்களிடையே அதிகம் அறியப்பட்ட கருத்தாக இல்லை. அல்லாஹ்வே மிக அறிந்தவன். ஆனால் ஸஹீஹ் அல்-புஹாரியில், அஸ்லம் கோத்திரத்தைச் சேர்ந்த ஒரு குழுவினர் வில்வித்தை பயிற்சி செய்து கொண்டிருந்ததைக் கடந்து சென்றபோது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">ارْمُوا</span> <span class=\"quran-arabic-font text-success\">بَنِي</span> <span class=\"quran-arabic-font text-success\">إِسْمَاعِيلَ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">أَبَاكُمْ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">رَامِيًا</span>»<br />\r\n<br />\r\n(இஸ்மாயீலின் சந்ததியினரே! அம்பு எய்யுங்கள். ஏனெனில், உங்கள் தந்தை ஒரு வில்லாளியாக இருந்தார்.) அஸ்லம் என்பது அன்சாரிகளின் ஒரு கிளையாகும். அன்சாரிகளான அவ்ஸ் மற்றும் கஸ்ரஜ் ஆகிய இரு பிரிவினரும் கஸ்ஸான் கிளையைச் சேர்ந்தவர்கள். இவர்கள் யமனின் ஸபா பகுதியைச் சேர்ந்த அரபிகளாவர். அல்லாஹ் அந்த அணையிலிருந்து வெள்ளத்தை அனுப்பி ஸபா மக்கள் நாலாபுறமும் சிதறியபோது, இவர்கள் யத்ரிப்பில் குடியேறினார்கள். இவர்களில் ஒரு குழுவினர் சிரியாவிலும் குடியேறினர். அவர்கள் தங்கியிருந்த ஒரு நீர்நிலையின் பெயரால் 'கஸ்ஸான்' என்று அழைக்கப்பட்டனர். அது யமனில் இருந்ததாகவோ அல்லது அல்-முஷல்லல் அருகே இருந்ததாகவோ கூறப்படுகிறது. இதையே ஹஸ்ஸான் பின் ஸாபித் (ரழி) அவர்கள் தனது கவிதை ஒன்றில் பின்வருமாறு குறிப்பிடுகிறார்கள்: \"நீங்கள் கேட்டால், நாங்கள் கண்ணியமிக்க வழித்தோன்றல்களின் கூட்டத்தினர்; எங்களது வம்சாவளி அல்-அஸ்து, எங்களது நீர்நிலை கஸ்ஸான்.\"<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وُلِدَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">عَشَرَةٌ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْعَرَب</span>»<br />\r\n<br />\r\n(அவருக்கு அரபிகளில் பத்து மகன்கள் இருந்தனர்.) என்பதன் பொருள், அந்தப் பத்து பேரும் அவரது வம்சாவளியைச் சேர்ந்தவர்கள் என்பதாகும். யமனின் அரபுப் பழங்குடியினரின் ஆதிமூலம் அவரிடமே முடிகிறது. அவர்கள் அனைவரும் அவரது நேரடிப் புதல்வர்கள் என்று பொருளல்ல. வம்சாவளி நூல்களில் விளக்கப்பட்டுள்ளபடி, அவருக்கும் அவர்களுக்குமிடையே இரண்டு அல்லது மூன்று அல்லது அதற்கும் மேற்பட்ட தலைமுறைகள் இருந்திருக்கலாம். இந்த வார்த்தைகளின் பொருள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فَتَيَامَنَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">سِتَّةٌ</span> <span class=\"quran-arabic-font text-success\">وَتَشَاءَمَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">أَرْبَعَة</span>»<br />\r\n<br />\r\n(அவர்களில் ஆறு பேர் தெற்கு நோக்கியும், நான்கு பேர் வடக்கு நோக்கியும் சென்றனர்.) என்பது, அல்லாஹ் அணையிலிருந்து வெள்ளத்தை அவர்கள் மீது அனுப்பிய பிறகு, அவர்களில் சிலர் தங்கள் தாயகத்திலேயே தங்கிவிட்டனர், மற்றவர்கள் வேறு இடங்களுக்குப் புலம் பெயர்ந்தனர் என்பதாகும்.<br />\r\n<br />\r\n<strong>மஃரிப் அணையும் வெள்ளப்பெருக்கும்</strong><br />\r\n<br />\r\nஅணை பற்றிய வரலாறானது, இரு மலைகளுக்கு இடையிலிருந்து மழை மற்றும் பள்ளத்தாக்குகளின் வழியாக அவர்களுக்குக் கிடைத்த தண்ணீரைப் பற்றியதாகும். அவர்களின் பண்டைய மன்னர்கள் ஒரு பிரம்மாண்டமான, வலுவான அணையைக் கட்டினார்கள். இதனால் அந்த இரு மலைகளுக்கு இடையே நீர் மட்டம் உயர்ந்தது. அதன் பின் அவர்கள் அங்கு மரங்களை நட்டனர். மிகச்சிறந்த, ஏராளமான, அழகான பழங்களை அவர்கள் அறுவடை செய்தார்கள். கத்தாதா உள்ளிட்ட முன்னோர்கள் (ஸலஃபுகள்) சிலர் குறிப்பிடுகையில்: \"ஒரு பெண் தனது தலையில் ஒரு கூடையைச் சுமந்து கொண்டு அந்த மரங்களுக்கு அடியே நடந்து சென்றால், அவள் கைகளால் பறிக்காமலேயே மரங்களிலிருந்து விழும் பழுத்த பழங்களால் அந்தக் கூடை தானாகவே நிறைந்துவிடும். அந்தளவுக்கு அங்கு பழங்கள் செழித்துக் காணப்பட்டன\" என்று கூறியுள்ளனர். இது ஸன்ஆவிலிருந்து மூன்று நாள் பயண தூரத்தில் இருந்த மஃரிப் அணைப் பகுதியாகும். அந்தப் பகுதியில் ஈக்கள், கொசுக்கள் அல்லது வேறு எந்த விஷப்பூச்சிகளும் இல்லை என்று வேறு சிலர் கூறியுள்ளனர். வானிலை இதமாகவும், மக்கள் ஆரோக்கியமாகவும் இருந்ததே இதற்குக் காரணம். அவர்கள் தன்னை மட்டுமே வணங்க வேண்டும் என்பதற்காக அல்லாஹ் அவர்களுக்கு இத்தகைய வசதிகளைச் செய்திருந்தான். இதையே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَقَدْ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">لِسَبَإٍ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">مَسْكَنِهِمْ</span> <span class=\"quran-arabic-font text-success\">ءَايَةٌ</span><br />\r\n<br />\r\n(நிச்சயமாக ஸபா (ஷீபா) மக்களுக்கு அவர்கள் வசித்த இடத்தில் ஓர் அத்தாட்சி இருந்தது.) பின்னர் அல்லாஹ் அதை இவ்வாறு விளக்குகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">جَنَّتَانِ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">يَمِينٍ</span> <span class=\"quran-arabic-font text-success\">وَشِمَالٍ</span><br />\r\n<br />\r\n(வலப்புறத்திலும் இடப்புறத்திலும் இரு தோட்டங்கள்;) அதாவது, மலைகள் இருந்த இரு பக்கங்களிலும் தோட்டங்கள் இருந்தன, அவற்றின் நிலம் அவற்றுக்கு இடையில் அமைந்திருந்தது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كُلُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رِّزْقِ</span> <span class=\"quran-arabic-font text-success\">رَبِّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَاشْكُرُواْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">بَلْدَةٌ</span> <span class=\"quran-arabic-font text-success\">طَيِّبَةٌ</span> <span class=\"quran-arabic-font text-success\">وَرَبٌّ</span> <span class=\"quran-arabic-font text-success\">غَفُورٌ</span><br />\r\n<br />\r\n((மேலும் அவர்களிடம் கூறப்பட்டது:) \"உங்கள் இறைவனின் வாழ்வாதாரத்திலிருந்து உண்ணுங்கள், அவனுக்கு நன்றி செலுத்துங்கள். அது ஒரு வளமான தேசம்; அவன் மிகவும் மன்னிப்பவன்!\") இதன் பொருள்: 'நீங்கள் அவனை மட்டுமே தொடர்ந்து வணங்கி வந்தால் அவன் உங்களை மன்னிப்பான்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَعْرِضُواْ</span><br />\r\n<br />\r\n(ஆனால் அவர்கள் புறக்கணித்தார்கள்,) அதாவது, அல்லாஹ்வை மட்டும் வணங்குவதிலிருந்தும், அவன் அவர்களுக்கு அருளிய அருட்கொடைகளுக்கு நன்றி செலுத்துவதிலிருந்தும் அவர்கள் விலகிச் சென்றார்கள். அவர்கள் அல்லாஹ்வுக்குப் பதிலாகச் சூரியனை வணங்கத் தொடங்கினார்கள். இதையே சுலைமான் (அலை) அவர்களிடம் ஹுத்ஹுத் பறவை கூறியது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَمَكَثَ</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">بَعِيدٍ</span> <span class=\"quran-arabic-font text-success\">فَقَالَ</span> <span class=\"quran-arabic-font text-success\">أَحَطتُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">تُحِطْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">وَجِئْتُكَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">سَبَإٍ</span> <span class=\"quran-arabic-font text-success\">بِنَبَإٍ</span> <span class=\"quran-arabic-font text-success\">يَقِينٍ</span> - <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">وَجَدتُّ</span> <span class=\"quran-arabic-font text-success\">امْرَأَةً</span> <span class=\"quran-arabic-font text-success\">تَمْلِكُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَأُوتِيَتْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">وَلَهَا</span> <span class=\"quran-arabic-font text-success\">عَرْشٌ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٌ</span> - <span class=\"quran-arabic-font text-success\">وَجَدتُّهَا</span> <span class=\"quran-arabic-font text-success\">وَقَوْمَهَا</span> <span class=\"quran-arabic-font text-success\">يَسْجُدُونَ</span> <span class=\"quran-arabic-font text-success\">لِلشَّمْسِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَزَيَّنَ</span> <span class=\"quran-arabic-font text-success\">لَهُمُ</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَـنُ</span> <span class=\"quran-arabic-font text-success\">أَعْمَـلَهُمْ</span> <span class=\"quran-arabic-font text-success\">فَصَدَّهُمْ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">السَّبِيلِ</span> <span class=\"quran-arabic-font text-success\">فَهُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَهْتَدُونَ</span><br />\r\n<br />\r\n(\"நான் ஸபாவிலிருந்து (ஷீபா) ஒரு உறுதியான செய்தியுடன் உங்களிடம் வந்துள்ளேன். ஒரு பெண் அவர்களை ஆட்சி செய்வதை நான் கண்டேன். அவளுக்கு எல்லா வசதிகளும் வழங்கப்பட்டுள்ளன; அவளுக்கு ஒரு பிரம்மாண்டமான அரியணையும் உள்ளது. அவளும் அவளது மக்களும் அல்லாஹ்வையன்றிச் சூரியனை வணங்குவதை நான் கண்டேன். ஷைத்தான் அவர்களின் செயல்களை அவர்களுக்கு அழகானதாகக் காட்டி, அவர்களை நல்வழியிலிருந்து தடுத்துவிட்டான். எனவே அவர்கள் நேர்வழி பெறமாட்டார்கள்.\") (<a href=\"qurandisp.php?sura=27&ayah=22\" class=\"link\">27:22</a>-24)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">سَيْلَ</span> <span class=\"quran-arabic-font text-success\">الْعَرِمِ</span><br />\r\n<br />\r\n(ஆகவே, அந்த அணையிலிருந்து கட்டவிழ்த்து விடப்பட்ட வெள்ளத்தை நாம் அவர்கள் மீது அனுப்பினோம்,) இப்னு அப்பாஸ், வஹ்ப் பின் முனப்பிஹ், கத்தாதா மற்றும் அத்-தஹ்ஹாக் உள்ளிட்டோர் கூறுகிறார்கள்: அல்லாஹ் அவர்கள் மீது வெள்ளத்தை அனுப்பித் தண்டிக்க நாடியபோது, பூமியிலிருந்து பெரிய வகை எலிகளை அந்த அணைக்கு அனுப்பினான். அவை அணையில் துளைகளை இட்டன. வஹ்ப் பின் முனப்பிஹ் அவர்கள் கூறுகையில்: \"பெரிய எலிகளால் இந்த அணை அழியும் என்று அவர்கள் தங்கள் வேதங்களில் கண்டனர். எனவே அவர்கள் அணையைப் பாதுகாக்கப் பூனைகளை வளர்த்தார்கள். ஆனால் அல்லாஹ்வின் கட்டளை வந்தபோது, எலிகள் பூனைகளை மீறி அணைக்குள் புகுந்து துளைகளை இட்டன; அணை சரிந்தது\" என்றார். கத்தாதா உள்ளிட்டோர் கூறுகையில்: \"அது ஒரு வகை பாலைவன எலியாகும். அவை அணையின் அடிப்பகுதியை அரித்து வலுவிழக்கச் செய்தன. வெள்ளம் வந்தபோது நீர் அந்த அமைப்பைத் தாக்கியது, அணை உடைந்தது. அந்தப் பெருவெள்ளம் பள்ளத்தாக்கின் வழியே சீறிப் பாய்ந்து, அங்குள்ள கட்டடங்கள், மரங்கள் என அனைத்தையும் அழித்தது\" என்றனர். மலைகளின் வலது மற்றும் இடதுபுறம் இருந்த மரங்களுக்கு நீர் கிடைக்காமல் அவை காய்ந்து அழிந்தன. அந்த அழகான, கனி தரும் மரங்களுக்குப் பதிலாக முற்றிலும் வேறான மரங்கள் முளைத்தன. இதையே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَبَدَّلْنَاهُم</span> <span class=\"quran-arabic-font text-success\">بِجَنَّتَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">جَنَّتَيْنِ</span> <span class=\"quran-arabic-font text-success\">ذَوَاتَيْ</span> <span class=\"quran-arabic-font text-success\">أُكُلٍ</span> <span class=\"quran-arabic-font text-success\">خَمْطٍ</span><br />\r\n<br />\r\n(மேலும், அவர்களுடைய அந்த இரு தோட்டங்களையும் கசப்பான கனிகளைத் தரும் இரு தோட்டங்களாக நாம் மாற்றினோம்,) இப்னு அப்பாஸ், முஜாஹித், இக்ரிமா, அதா அல்-குராசானீ, கத்தாதா மற்றும் அஸ்-ஸுத்தீ ஆகியோர் கூறுகையில்: \"இது அராக் மற்றும் கசப்பான கனிகளைக் குறிக்கும்\" என்றனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَثْلٍ</span><br />\r\n<br />\r\nமற்றும் 'அத்ல்'. அல்-அவ்ஃபீ மற்றும் இப்னு அப்பாஸ் ஆகியோர் இதற்குத் 'தாமரிக்ஸ்' (சவுக்கு போன்ற மரம்) என்று பொருள் கூறினர். சிலர் இது சவுக்கு போன்ற மரம் என்றும், வேறு சிலர் இது 'காட்டு வேல மரம்' அல்லது 'மிமோசா' என்றும் கூறியுள்ளனர். அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَشَىْءٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">سِدْرٍ</span> <span class=\"quran-arabic-font text-success\">قَلِيلٍ</span><br />\r\n<br />\r\nமேலும் சில இலந்தை மரங்கள். அந்தத் தோட்டங்கள் மாற்றப்பட்டபோது அவற்றில் எஞ்சியவற்றில் இலந்தை மரங்கள் சிறந்தவையாக இருந்ததால், அவை மிகக் குறைவாகவே இருந்தன.<br />\r\n<br />\r\n  அடர்ந்த நிழலும், ஓடும் ஆறுகளும், அழகான காட்சிகளும், செழிப்பான கனிகளும் நிறைந்திருந்த அந்த இரு தோட்டங்களுக்கும் ஏற்பட்ட கதி இதுதான்: அவை முள் மரங்களாகவும், சவுக்கு மரங்களாகவும், பெரிய முட்களும் சிறு கனிகளும் கொண்ட இலந்தை மரங்களாகவும் மாறின. இதற்குக் காரணம் அவர்கள் கொண்ட இறைநிராகரிப்பும், அல்லாஹ்வுக்கு இணைவைத்த பாவமும், சத்தியத்தைப் புறக்கணித்துப் பொய்யைப் பின்பற்றியதுமே ஆகும். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَٰلِكَ</span> <span class=\"quran-arabic-font text-success\">جَزَيْنَاهُم</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَفَرُوا</span> <span class=\"quran-arabic-font text-success\">وَهَلْ</span> <span class=\"quran-arabic-font text-success\">نُجَازِي</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">الْكَفُورَ</span><br />\r\n<br />\r\n(அவர்கள் நன்றி கெட்டவர்களாக இருந்த காரணத்தால், இவ்வாறு நாம் அவர்களுக்குக் கூலி கொடுத்தோம். நன்றி கெட்டவர்களைத் தவிர வேறு யாருக்கும் நாம் இவ்வாறு கூலி கொடுப்பதில்லை.) அதாவது, அவர்களின் நிராகரிப்புக்காக நாம் அவர்களைத் தண்டித்தோம். முஜாஹித் அவர்கள் கூறுகையில்: \"நிராகரிப்பவர்களைத் தவிர வேறு யாரையும் அல்லாஹ் இவ்வாறு தண்டிப்பதில்லை\" என்றார். ஹஸன் அல்-பஸரீ அவர்கள் கூறுகையில்: \"மகத்துவமிக்க அல்லாஹ் உண்மையையே கூறியுள்ளான். நன்றி கெட்ட நிராகரிப்பாளர்களைத் தவிர வேறு எவரும் அவர்கள் செய்த பாவத்திற்குப் பொருத்தமான முறையில் இவ்வாறு தண்டிக்கப்பட மாட்டார்கள்\" என்றார்.<br />\r\n<br />","text":"ஸபா மக்களின் நிராகரிப்பும் அவர்களின் தண்டனையும்\n\r\n\n\r\nஸபா என்பது யமன் தேசத்து மன்னர்களையும் மக்களையும் குறிக்கும். யமனின் பண்டைய மன்னர்களின் பட்டப் பெயரான 'அத்தபாபிஆ' (துப்பா) என்பவர்கள் அவர்களில் ஒரு பகுதியினரே. சுலைமான் (அலை) அவர்களைச் சந்தித்த அரசியான பல்கீஸும் அவர்களில் ஒருவராவார். அவர்கள் அந்தத் தேசத்தில் வளமான வாழ்வாதாரங்கள், பயிர்கள் மற்றும் பழங்களுடன் பொறாமைப்படத்தக்க ஆடம்பர வாழ்க்கை வாழ்ந்து வந்தார்கள். அல்லாஹ் அவர்களுக்குத் தூதர்களை அனுப்பி, அவனுடைய வாழ்வாதாரங்களிலிருந்து உண்ணுமாறும், அவனை மட்டுமே வணங்கி அவனுக்கு நன்றி செலுத்துமாறும் கூறினான். அல்லாஹ் நாடிய காலம் வரை அவர்கள் அதைப் பின்பற்றினார்கள்; பின்னர் தங்களுக்குக் கட்டளையிடப்பட்ட நேர்வழியிலிருந்து அவர்கள் விலகிச் சென்றார்கள். எனவே, அவர்கள் ஒரு பெரும் வெள்ளத்தால் தண்டிக்கப்பட்டார்கள். அந்த வெள்ளம் அவர்களை ஸபாவுக்கு அருகிலுள்ள பல திசைகளிலும் சிதறடித்தது. இதன் விவரங்களை அல்லாஹ் நாடினால் (இன்ஷா அல்லாஹ்) கீழே விரிவாகக் காண்போம். அவனிடமே நாம் முழுமையாகப் பொறுப்பேற்படுத்துகிறோம். இப்னு ஜரீர் அவர்கள் பதிவு செய்துள்ளார்கள்: ஃபர்வா பின் முஸைக் அல்-குதைஃபீ (ரழி) அவர்கள் கூறியதாவது: \"ஒரு மனிதர், 'அல்லாஹ்வின் தூதரே! ஸபாவைப் பற்றி எனக்குச் சொல்லுங்கள் - அது ஒரு நிலமா அல்லது ஒரு பெண்ணா?' என்று கேட்டார். அதற்கு அவர்கள் (ஸல்) கூறினார்கள்:\n\r\n\n\r\n«لَيْسَ بِأَرْضٍ وَلَا امْرَأَةٍ، وَلَكِنَّهُ رَجُلٌ وُلِدَ لَهُ عَشَرَةٌ مِنَ الْوَلَدِ، فَتَيَامَنَ سِتَّةٌ وَتَشَاءَمَ أَرْبَعَةٌ، فَأَمَّا الَّذِينَ تَشَاءَمُوا: فَلَخْمٌ وَجُذَامٌ وَعَامِلَةُ وَغَسَّانُ، وَأَمَّا الَّذِينَ تَيَامَنُوا: فَكِنْدَةُ وَالْأَشْعَرِيُّونَ وَالْأَزْدُ وَمَذْحِجٌ وَحِمْيَرُ وَأَنْمَار»\n\r\n\n\r\n(அது ஒரு நிலமும் அல்ல, ஒரு பெண்ணும் அல்ல. அவர் ஒரு மனிதர், அவருக்குப் பத்து குழந்தைகள் இருந்தன. அவர்களில் ஆறு பேர் யமன் நோக்கியும், நான்கு பேர் ஷாம் நோக்கியும் சென்றனர். ஷாம் நோக்கிச் சென்றவர்கள் லக்ம், ஜுதாம், ஆமிலா மற்றும் கஸ்ஸான் ஆவர். தெற்கு நோக்கி (யமன்) சென்றவர்கள் கிந்தா, அல்-அஷ்அரிய்யூன், அல்-அஸ்து, மத்ஹிஜ், ஹிம்யர் மற்றும் அன்மார் ஆவர்.) ஒரு மனிதர், 'அன்மார் என்பவர் யார்?' என்று கேட்டார். அதற்கு அவர்கள் (ஸல்) கூறினார்கள்:\n\r\n\n\r\n«الَّذِينَ مِنْهُمْ خَثْعَمُ وَبَجِيلَة»\n\r\n\n\r\n(அவர்களில் கத்அம் மற்றும் பஜீலா ஆகிய கிளையினரும் உள்ளனர்.)\" இதை அத்-திர்மிதீ தனது 'ஜாமிஉ சுனன்' நூலில் இன்னும் விரிவாகப் பதிவு செய்துள்ளார். மேலும், \"இது ஒரு ஹஸன் கரீப் ஹதீஸ்\" என்றும் அவர் குறிப்பிட்டுள்ளார். முஹம்மது பின் இஸ்ஹாக் உள்ளிட்ட வம்சாவளி ஆய்வாளர்கள் கூறுகிறார்கள்: \"ஸபாவின் பெயர் அப்த் ஷம்ஸ் பின் யஷ்ஜுப் பின் யஃருப் பின் கஹ்தான் என்பதாகும். அரபுப் பழங்குடியினரில் முதன்முதலில் (எதிரிகளைச்) சிறைபிடித்தவர் என்பதால் 'ஸபா' என்று அழைக்கப்பட்டார். மேலும் இவர் 'அர்-ராஇஷ்' என்றும் அறியப்பட்டார். ஏனெனில், போரில் கிடைத்த வெற்றிப் பொருட்களை (கனீமத்) முதன்முதலில் கைப்பற்றித் தன் மக்களுக்குப் பங்கிட்டுக் கொடுத்தவர் இவரே. அரபியில் செல்வத்தை 'ரீஷ்' அல்லது 'ரியாஷ்' என்று அழைப்பதால் இவர் அர்-ராஇஷ் எனப்பட்டார்.\" கஹ்தான் என்பவர் யார் என்பது குறித்து மூன்று கருத்துக்கள் உள்ளன. (முதலாவது) அவர் இரம் பின் ஸாம் பின் நூஹ் (அலை) அவர்களின் வழித்தோன்றல். இதில் அவர் அவரிடமிருந்து எவ்வாறு தோன்றினார் என்பது குறித்து மூன்று உட்பிரிவு கருத்துக்கள் உள்ளன. (இரண்டாவது) அவர் ஹூத் (அலை) அவர்களின் மற்றொரு பெயரான ஆபிர் என்பவரின் வழித்தோன்றல். இதிலும் அவர் அவரிடமிருந்து எவ்வாறு தோன்றினார் என்பது குறித்து மூன்று உட்பிரிவு கருத்துக்கள் உள்ளன. (மூன்றாவது) அவர் இப்ராஹீம் அல்-கலீல் (அலை) அவர்களின் மகன் இஸ்மாயீல் (அலை) அவர்களின் வழித்தோன்றல். இதிலும் அவர் அவரிடமிருந்து எவ்வாறு தோன்றினார் என்பது குறித்து மூன்று உட்பிரிவு கருத்துக்கள் உள்ளன. இமாம் அல்-ஹாஃபிழ் அபூ உமர் பின் அப்துல் பர் அன்-நமரீ (ரஹிமஹுல்லாஹ்) அவர்கள் தனது 'அல்-இன்பாஹ் அலா திக்ர் உசூல் அல்-கபாயில் அர்-ருவாத்' எனும் நூலில் இதைப் பற்றி விரிவாக விளக்கியுள்ளார். நபிகளாரின் வார்த்தைகளின் பொருள்,\n\r\n\n\r\n«كَانَ رَجُلًا مِنَ الْعَرَب»\n\r\n\n\r\n(அவர் அரபுகளில் ஒரு மனிதராக இருந்தார்.) என்பது, அவர் இப்ராஹீம் (அலை) அவர்களுக்கு முந்தைய அசல் அரபிகளில் ஒருவராக இருந்தார் என்பதாகும். அவர் ஸாம் பின் நூஹ் (அலை) அவர்களின் வம்சாவழியில் வந்தவர். மேலே கூறப்பட்ட மூன்றாவது கருத்தின்படி அவர் இப்ராஹீம் (அலை) அவர்களின் வழித்தோன்றலாகக் கருதப்பட்டாலும், அது மக்களிடையே அதிகம் அறியப்பட்ட கருத்தாக இல்லை. அல்லாஹ்வே மிக அறிந்தவன். ஆனால் ஸஹீஹ் அல்-புஹாரியில், அஸ்லம் கோத்திரத்தைச் சேர்ந்த ஒரு குழுவினர் வில்வித்தை பயிற்சி செய்து கொண்டிருந்ததைக் கடந்து சென்றபோது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«ارْمُوا بَنِي إِسْمَاعِيلَ فَإِنَّ أَبَاكُمْ كَانَ رَامِيًا»\n\r\n\n\r\n(இஸ்மாயீலின் சந்ததியினரே! அம்பு எய்யுங்கள். ஏனெனில், உங்கள் தந்தை ஒரு வில்லாளியாக இருந்தார்.) அஸ்லம் என்பது அன்சாரிகளின் ஒரு கிளையாகும். அன்சாரிகளான அவ்ஸ் மற்றும் கஸ்ரஜ் ஆகிய இரு பிரிவினரும் கஸ்ஸான் கிளையைச் சேர்ந்தவர்கள். இவர்கள் யமனின் ஸபா பகுதியைச் சேர்ந்த அரபிகளாவர். அல்லாஹ் அந்த அணையிலிருந்து வெள்ளத்தை அனுப்பி ஸபா மக்கள் நாலாபுறமும் சிதறியபோது, இவர்கள் யத்ரிப்பில் குடியேறினார்கள். இவர்களில் ஒரு குழுவினர் சிரியாவிலும் குடியேறினர். அவர்கள் தங்கியிருந்த ஒரு நீர்நிலையின் பெயரால் 'கஸ்ஸான்' என்று அழைக்கப்பட்டனர். அது யமனில் இருந்ததாகவோ அல்லது அல்-முஷல்லல் அருகே இருந்ததாகவோ கூறப்படுகிறது. இதையே ஹஸ்ஸான் பின் ஸாபித் (ரழி) அவர்கள் தனது கவிதை ஒன்றில் பின்வருமாறு குறிப்பிடுகிறார்கள்: \"நீங்கள் கேட்டால், நாங்கள் கண்ணியமிக்க வழித்தோன்றல்களின் கூட்டத்தினர்; எங்களது வம்சாவளி அல்-அஸ்து, எங்களது நீர்நிலை கஸ்ஸான்.\"\n\r\n\n\r\n«وُلِدَ لَهُ عَشَرَةٌ مِنَ الْعَرَب»\n\r\n\n\r\n(அவருக்கு அரபிகளில் பத்து மகன்கள் இருந்தனர்.) என்பதன் பொருள், அந்தப் பத்து பேரும் அவரது வம்சாவளியைச் சேர்ந்தவர்கள் என்பதாகும். யமனின் அரபுப் பழங்குடியினரின் ஆதிமூலம் அவரிடமே முடிகிறது. அவர்கள் அனைவரும் அவரது நேரடிப் புதல்வர்கள் என்று பொருளல்ல. வம்சாவளி நூல்களில் விளக்கப்பட்டுள்ளபடி, அவருக்கும் அவர்களுக்குமிடையே இரண்டு அல்லது மூன்று அல்லது அதற்கும் மேற்பட்ட தலைமுறைகள் இருந்திருக்கலாம். இந்த வார்த்தைகளின் பொருள்,\n\r\n\n\r\n«فَتَيَامَنَ مِنْهُمْ سِتَّةٌ وَتَشَاءَمَ مِنْهُمْ أَرْبَعَة»\n\r\n\n\r\n(அவர்களில் ஆறு பேர் தெற்கு நோக்கியும், நான்கு பேர் வடக்கு நோக்கியும் சென்றனர்.) என்பது, அல்லாஹ் அணையிலிருந்து வெள்ளத்தை அவர்கள் மீது அனுப்பிய பிறகு, அவர்களில் சிலர் தங்கள் தாயகத்திலேயே தங்கிவிட்டனர், மற்றவர்கள் வேறு இடங்களுக்குப் புலம் பெயர்ந்தனர் என்பதாகும்.\n\r\n\n\r\nமஃரிப் அணையும் வெள்ளப்பெருக்கும்\n\r\n\n\r\nஅணை பற்றிய வரலாறானது, இரு மலைகளுக்கு இடையிலிருந்து மழை மற்றும் பள்ளத்தாக்குகளின் வழியாக அவர்களுக்குக் கிடைத்த தண்ணீரைப் பற்றியதாகும். அவர்களின் பண்டைய மன்னர்கள் ஒரு பிரம்மாண்டமான, வலுவான அணையைக் கட்டினார்கள். இதனால் அந்த இரு மலைகளுக்கு இடையே நீர் மட்டம் உயர்ந்தது. அதன் பின் அவர்கள் அங்கு மரங்களை நட்டனர். மிகச்சிறந்த, ஏராளமான, அழகான பழங்களை அவர்கள் அறுவடை செய்தார்கள். கத்தாதா உள்ளிட்ட முன்னோர்கள் (ஸலஃபுகள்) சிலர் குறிப்பிடுகையில்: \"ஒரு பெண் தனது தலையில் ஒரு கூடையைச் சுமந்து கொண்டு அந்த மரங்களுக்கு அடியே நடந்து சென்றால், அவள் கைகளால் பறிக்காமலேயே மரங்களிலிருந்து விழும் பழுத்த பழங்களால் அந்தக் கூடை தானாகவே நிறைந்துவிடும். அந்தளவுக்கு அங்கு பழங்கள் செழித்துக் காணப்பட்டன\" என்று கூறியுள்ளனர். இது ஸன்ஆவிலிருந்து மூன்று நாள் பயண தூரத்தில் இருந்த மஃரிப் அணைப் பகுதியாகும். அந்தப் பகுதியில் ஈக்கள், கொசுக்கள் அல்லது வேறு எந்த விஷப்பூச்சிகளும் இல்லை என்று வேறு சிலர் கூறியுள்ளனர். வானிலை இதமாகவும், மக்கள் ஆரோக்கியமாகவும் இருந்ததே இதற்குக் காரணம். அவர்கள் தன்னை மட்டுமே வணங்க வேண்டும் என்பதற்காக அல்லாஹ் அவர்களுக்கு இத்தகைய வசதிகளைச் செய்திருந்தான். இதையே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nلَقَدْ كَانَ لِسَبَإٍ فِى مَسْكَنِهِمْ ءَايَةٌ\n\r\n\n\r\n(நிச்சயமாக ஸபா (ஷீபா) மக்களுக்கு அவர்கள் வசித்த இடத்தில் ஓர் அத்தாட்சி இருந்தது.) பின்னர் அல்லாஹ் அதை இவ்வாறு விளக்குகிறான்:\n\r\n\n\r\nجَنَّتَانِ عَن يَمِينٍ وَشِمَالٍ\n\r\n\n\r\n(வலப்புறத்திலும் இடப்புறத்திலும் இரு தோட்டங்கள்;) அதாவது, மலைகள் இருந்த இரு பக்கங்களிலும் தோட்டங்கள் இருந்தன, அவற்றின் நிலம் அவற்றுக்கு இடையில் அமைந்திருந்தது.\n\r\n\n\r\nكُلُواْ مِن رِّزْقِ رَبِّكُمْ وَاشْكُرُواْ لَهُ بَلْدَةٌ طَيِّبَةٌ وَرَبٌّ غَفُورٌ\n\r\n\n\r\n((மேலும் அவர்களிடம் கூறப்பட்டது:) \"உங்கள் இறைவனின் வாழ்வாதாரத்திலிருந்து உண்ணுங்கள், அவனுக்கு நன்றி செலுத்துங்கள். அது ஒரு வளமான தேசம்; அவன் மிகவும் மன்னிப்பவன்!\") இதன் பொருள்: 'நீங்கள் அவனை மட்டுமே தொடர்ந்து வணங்கி வந்தால் அவன் உங்களை மன்னிப்பான்.'\n\r\n\n\r\nفَأَعْرِضُواْ\n\r\n\n\r\n(ஆனால் அவர்கள் புறக்கணித்தார்கள்,) அதாவது, அல்லாஹ்வை மட்டும் வணங்குவதிலிருந்தும், அவன் அவர்களுக்கு அருளிய அருட்கொடைகளுக்கு நன்றி செலுத்துவதிலிருந்தும் அவர்கள் விலகிச் சென்றார்கள். அவர்கள் அல்லாஹ்வுக்குப் பதிலாகச் சூரியனை வணங்கத் தொடங்கினார்கள். இதையே சுலைமான் (அலை) அவர்களிடம் ஹுத்ஹுத் பறவை கூறியது:\n\r\n\n\r\nفَمَكَثَ غَيْرَ بَعِيدٍ فَقَالَ أَحَطتُ بِمَا لَمْ تُحِطْ بِهِ وَجِئْتُكَ مِن سَبَإٍ بِنَبَإٍ يَقِينٍ - إِنِّى وَجَدتُّ امْرَأَةً تَمْلِكُهُمْ وَأُوتِيَتْ مِن كُلِّ شَىْءٍ وَلَهَا عَرْشٌ عَظِيمٌ - وَجَدتُّهَا وَقَوْمَهَا يَسْجُدُونَ لِلشَّمْسِ مِن دُونِ اللَّهِ وَزَيَّنَ لَهُمُ الشَّيْطَـنُ أَعْمَـلَهُمْ فَصَدَّهُمْ عَنِ السَّبِيلِ فَهُمْ لاَ يَهْتَدُونَ\n\r\n\n\r\n(\"நான் ஸபாவிலிருந்து (ஷீபா) ஒரு உறுதியான செய்தியுடன் உங்களிடம் வந்துள்ளேன். ஒரு பெண் அவர்களை ஆட்சி செய்வதை நான் கண்டேன். அவளுக்கு எல்லா வசதிகளும் வழங்கப்பட்டுள்ளன; அவளுக்கு ஒரு பிரம்மாண்டமான அரியணையும் உள்ளது. அவளும் அவளது மக்களும் அல்லாஹ்வையன்றிச் சூரியனை வணங்குவதை நான் கண்டேன். ஷைத்தான் அவர்களின் செயல்களை அவர்களுக்கு அழகானதாகக் காட்டி, அவர்களை நல்வழியிலிருந்து தடுத்துவிட்டான். எனவே அவர்கள் நேர்வழி பெறமாட்டார்கள்.\") (27:22-24)\n\r\n\n\r\nفَأَرْسَلْنَا عَلَيْهِمْ سَيْلَ الْعَرِمِ\n\r\n\n\r\n(ஆகவே, அந்த அணையிலிருந்து கட்டவிழ்த்து விடப்பட்ட வெள்ளத்தை நாம் அவர்கள் மீது அனுப்பினோம்,) இப்னு அப்பாஸ், வஹ்ப் பின் முனப்பிஹ், கத்தாதா மற்றும் அத்-தஹ்ஹாக் உள்ளிட்டோர் கூறுகிறார்கள்: அல்லாஹ் அவர்கள் மீது வெள்ளத்தை அனுப்பித் தண்டிக்க நாடியபோது, பூமியிலிருந்து பெரிய வகை எலிகளை அந்த அணைக்கு அனுப்பினான். அவை அணையில் துளைகளை இட்டன. வஹ்ப் பின் முனப்பிஹ் அவர்கள் கூறுகையில்: \"பெரிய எலிகளால் இந்த அணை அழியும் என்று அவர்கள் தங்கள் வேதங்களில் கண்டனர். எனவே அவர்கள் அணையைப் பாதுகாக்கப் பூனைகளை வளர்த்தார்கள். ஆனால் அல்லாஹ்வின் கட்டளை வந்தபோது, எலிகள் பூனைகளை மீறி அணைக்குள் புகுந்து துளைகளை இட்டன; அணை சரிந்தது\" என்றார். கத்தாதா உள்ளிட்டோர் கூறுகையில்: \"அது ஒரு வகை பாலைவன எலியாகும். அவை அணையின் அடிப்பகுதியை அரித்து வலுவிழக்கச் செய்தன. வெள்ளம் வந்தபோது நீர் அந்த அமைப்பைத் தாக்கியது, அணை உடைந்தது. அந்தப் பெருவெள்ளம் பள்ளத்தாக்கின் வழியே சீறிப் பாய்ந்து, அங்குள்ள கட்டடங்கள், மரங்கள் என அனைத்தையும் அழித்தது\" என்றனர். மலைகளின் வலது மற்றும் இடதுபுறம் இருந்த மரங்களுக்கு நீர் கிடைக்காமல் அவை காய்ந்து அழிந்தன. அந்த அழகான, கனி தரும் மரங்களுக்குப் பதிலாக முற்றிலும் வேறான மரங்கள் முளைத்தன. இதையே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَبَدَّلْنَاهُم بِجَنَّتَيْهِمْ جَنَّتَيْنِ ذَوَاتَيْ أُكُلٍ خَمْطٍ\n\r\n\n\r\n(மேலும், அவர்களுடைய அந்த இரு தோட்டங்களையும் கசப்பான கனிகளைத் தரும் இரு தோட்டங்களாக நாம் மாற்றினோம்,) இப்னு அப்பாஸ், முஜாஹித், இக்ரிமா, அதா அல்-குராசானீ, கத்தாதா மற்றும் அஸ்-ஸுத்தீ ஆகியோர் கூறுகையில்: \"இது அராக் மற்றும் கசப்பான கனிகளைக் குறிக்கும்\" என்றனர்.\n\r\n\n\r\nوَأَثْلٍ\n\r\n\n\r\nமற்றும் 'அத்ல்'. அல்-அவ்ஃபீ மற்றும் இப்னு அப்பாஸ் ஆகியோர் இதற்குத் 'தாமரிக்ஸ்' (சவுக்கு போன்ற மரம்) என்று பொருள் கூறினர். சிலர் இது சவுக்கு போன்ற மரம் என்றும், வேறு சிலர் இது 'காட்டு வேல மரம்' அல்லது 'மிமோசா' என்றும் கூறியுள்ளனர். அல்லாஹ்வே மிக அறிந்தவன்.\n\r\n\n\r\nوَشَىْءٍ مِّن سِدْرٍ قَلِيلٍ\n\r\n\n\r\nமேலும் சில இலந்தை மரங்கள். அந்தத் தோட்டங்கள் மாற்றப்பட்டபோது அவற்றில் எஞ்சியவற்றில் இலந்தை மரங்கள் சிறந்தவையாக இருந்ததால், அவை மிகக் குறைவாகவே இருந்தன.\n\r\n\n\r\n  அடர்ந்த நிழலும், ஓடும் ஆறுகளும், அழகான காட்சிகளும், செழிப்பான கனிகளும் நிறைந்திருந்த அந்த இரு தோட்டங்களுக்கும் ஏற்பட்ட கதி இதுதான்: அவை முள் மரங்களாகவும், சவுக்கு மரங்களாகவும், பெரிய முட்களும் சிறு கனிகளும் கொண்ட இலந்தை மரங்களாகவும் மாறின. இதற்குக் காரணம் அவர்கள் கொண்ட இறைநிராகரிப்பும், அல்லாஹ்வுக்கு இணைவைத்த பாவமும், சத்தியத்தைப் புறக்கணித்துப் பொய்யைப் பின்பற்றியதுமே ஆகும். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nذَٰلِكَ جَزَيْنَاهُم بِمَا كَفَرُوا وَهَلْ نُجَازِي إِلَّا الْكَفُورَ\n\r\n\n\r\n(அவர்கள் நன்றி கெட்டவர்களாக இருந்த காரணத்தால், இவ்வாறு நாம் அவர்களுக்குக் கூலி கொடுத்தோம். நன்றி கெட்டவர்களைத் தவிர வேறு யாருக்கும் நாம் இவ்வாறு கூலி கொடுப்பதில்லை.) அதாவது, அவர்களின் நிராகரிப்புக்காக நாம் அவர்களைத் தண்டித்தோம். முஜாஹித் அவர்கள் கூறுகையில்: \"நிராகரிப்பவர்களைத் தவிர வேறு யாரையும் அல்லாஹ் இவ்வாறு தண்டிப்பதில்லை\" என்றார். ஹஸன் அல்-பஸரீ அவர்கள் கூறுகையில்: \"மகத்துவமிக்க அல்லாஹ் உண்மையையே கூறியுள்ளான். நன்றி கெட்ட நிராகரிப்பாளர்களைத் தவிர வேறு எவரும் அவர்கள் செய்த பாவத்திற்குப் பொருத்தமான முறையில் இவ்வாறு தண்டிக்கப்பட மாட்டார்கள்\" என்றார்."},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=19\" class=\"link\">34:19</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:19 ஐ பார்க்கவும்"},"19":{"html":"<strong>ஸபா மக்களின் வர்த்தகமும் அவர்களின் அழிவும்</strong><br />\r\n<br />\r\nஸபா மக்கள் அனுபவித்த அருட்கொடைகள் குறித்தும், அவர்களுக்கு அவர்களது தேசத்தில் வழங்கப்பட்டிருந்த ஆடம்பர வசதிகள் மற்றும் தாராளமான வாழ்வாதாரங்கள் குறித்தும் அல்லாஹ் நமக்குக் கூறுகிறான். அங்கே பாதுகாப்பான குடியிருப்புகளும், ஏராளமான மரங்கள், பயிர்கள் மற்றும் கனிகளுடன் ஒன்றோடொன்று இணைக்கப்பட்ட ஊர்களும் இருந்தன. அவர்கள் பயணம் செய்யும்போது, தங்களுடன் உணவுப் பொருட்களையோ அல்லது தண்ணீரையோ சுமந்து செல்ல வேண்டிய அவசியம் இருக்கவில்லை. அவர்கள் எங்கு தங்கினாலும் அவர்களுக்குத் தண்ணீரும் பழங்களும் கிடைத்தன. இதனால் அவர்கள் தங்கள் பயணத் தேவைகளுக்கேற்ப, ஒரு ஊரில் மதிய ஓய்வெடுத்துவிட்டு, மற்றொரு ஊரில் இரவு தங்க முடிந்தது. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَ</span> <span class=\"quran-arabic-font text-success\">الْقُرَى</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">بَارَكْنَا</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span><br />\r\n<br />\r\n(\"நாம் அவர்களுக்கும், நாம் அருள் புரிந்திருந்த ஊர்களுக்கும் இடையே (வேறு பல) ஊர்களை அமைத்தோம்.\") இது சிரியாவின் ஊர்களைக் குறிக்கிறது என்று முஜாஹித், அல்-ஹஸன், ஸயீத் பின் ஜுபைர், ஸைத் பின் அஸ்லமிடமிருந்து அறிவிக்கும் மாலிக், கத்தாதா, அத்-தஹ்ஹாக், அஸ்-ஸுத்தி, இப்னு ஸைத் மற்றும் பலர் கூறியுள்ளனர். அதாவது, அவர்கள் யமனிலிருந்து சிரியாவிற்கு, ஒன்றோடொன்று இணைக்கப்பட்ட மற்றும் எளிதில் தென்படக்கூடிய ஊர்கள் வழியாகப் பயணம் செய்து வந்தனர். \"நாம் எவற்றில் பைத்துல் முகத்தஸை (ஜெருசலேம்) அமைத்தோமோ, அந்த அருள்வளம் மிக்க ஊர்களையே இது குறிக்கிறது\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அல்-அவ்ஃபி அறிவிக்கிறார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُرًى</span> <span class=\"quran-arabic-font text-success\">ظَاهِرَةً</span><br />\r\n<br />\r\nஎளிதில் தென்படக்கூடிய ஊர்கள்; அதாவது, பயணிகளுக்குத் தெளிவாகத் தெரியக்கூடிய மற்றும் நன்கு அறியப்பட்ட ஊர்கள். இதன் மூலம் அவர்கள் ஒரு ஊரில் மதிய ஓய்வையும், மற்றோர் ஊரில் இரவுத் தங்கலையும் மேற்கொள்ள முடிந்தது. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَدَّرْنَا</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">السَّيْرَ</span><br />\r\n<br />\r\n(\"அவற்றுக்கிடையே பயண தூரங்களை நாம் நிர்ணயித்தோம்.\") அதாவது, \"பயணிகளின் தேவைகளைப் பூர்த்தி செய்யும் வகையில் நாம் அதனை அமைத்தோம்\" என்று பொருள்படும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سِيرُواْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">لَيَالِىَ</span> <span class=\"quran-arabic-font text-success\">وَأَيَّاماً</span> <span class=\"quran-arabic-font text-success\">ءَامِنِينَ</span><br />\r\n<br />\r\n(\"அவற்றில் இரவிலும் பகலிலும் அச்சமற்றவர்களாகப் பிரயாணம் செய்யுங்கள்.\") அதாவது, அவற்றில் பயணம் செய்பவர்கள் இரவிலும் பகலிலும் பாதுகாப்பாக இருப்பார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">بَاعِدْ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">أَسْفَارِنَا</span> <span class=\"quran-arabic-font text-success\">وَظَلَمُواْ</span> <span class=\"quran-arabic-font text-success\">أَنفُسَهُمْ</span><br />\r\n<br />\r\n(ஆனால் அவர்கள், \"எங்கள் இறைவா! எங்கள் பயணங்களுக்கு இடையேயான தூரத்தை அதிகமாக்குவாயாக\" எனக் கூறி, தங்களுக்குத் தாங்களே அநீதி இழைத்துக் கொண்டார்கள்.) இப்னு அப்பாஸ் (ரழி), முஜாஹித், அல்-ஹஸன் மற்றும் பலர் கூறியது போல், அவர்கள் தங்களுக்கு வழங்கப்பட்ட இந்த அருட்கொடையை மதிக்கத் தவறினார்கள்; பனூ இஸ்ராயீல்கள் (மன்னையும் ஸல்வாவையும் விடுத்து) பூண்டு, வெங்காயம் போன்றவற்றை எப்படிக் கேட்டார்களோ அதுபோல, \"தங்களுடன் உணவுப் பொருட்களைச் சுமந்து கொண்டு, கடும் வெப்பத்திலும் அச்சத்திலும் ஆளில்லாத பாலைவனங்கள் வழியாக நீண்ட தூரம் பயணம் செய்ய அவர்கள் விரும்பினார்கள்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَجَعَلْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">أَحَادِيثَ</span> <span class=\"quran-arabic-font text-success\">وَمَزَّقْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">مُمَزَّقٍ</span><br />\r\n<br />\r\n(\"எனவே, நாம் அவர்களைப் (பிற்காலத்தவர் பேசிக்கொள்ளும்) பழங்கதைகளாக ஆக்கினோம்; மேலும் அவர்களை முற்றிலும் சிதறடித்தோம்.\") அதாவது, \"மக்கள் மாலை நேரங்களில் கூடிப் பேசும் கதைகளாக அவர்களை நாம் ஆக்கினோம். அவர்கள் ஆடம்பர வாழ்வு வாழ்ந்து ஒன்றுபட்டிருந்த பிறகு, அல்லாஹ் அவர்களுக்கு எதிராகச் சூழ்ச்சி செய்து அவர்களை எவ்வாறு சிதறடித்தான் என்பது பேசுபொருளானது. அவர்கள் தேசம் முழுவதும் அங்கொன்றும் இங்கொன்றுமாகச் சிதறடிக்கப்பட்டனர்.\" எனவே, ஒரு மக்கள் சிதறடிக்கப்படுவதைக் குறிக்க, \"அவர்கள் ஸபா மக்களைப் போல் எல்லாத் திசைகளிலும் சிதறடிக்கப்பட்டனர்\" என்று அரபுகள் கூறுவார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لَآيَاتٍ</span> <span class=\"quran-arabic-font text-success\">لِكُلِّ</span> <span class=\"quran-arabic-font text-success\">صَبَّارٍ</span> <span class=\"quran-arabic-font text-success\">شَكُورٍ</span><br />\r\n<br />\r\n(\"நிச்சயமாக, இதில் பொறுமையுடையோர், நன்றியுடையோர் ஒவ்வொருவருக்கும் அத்தாட்சிகள் உள்ளன.\") இந்த மக்கள் அனுபவித்த தண்டனையிலும், அவர்களின் அருட்கொடைகளும் ஆரோக்கியமும் அவர்களின் இறைநிராகரிப்பு மற்றும் பாவங்களுக்காகப் பழிவாங்கலாக மாற்றப்பட்ட விதத்திலும், சோதனைகளின் போது பொறுமையுடனும் அருட்கொடைகளுக்கு நன்றியுடனும் இருக்கும் ஒவ்வொருவருக்கும் படிப்பினையும் சான்றும் உள்ளது. இமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: ஸஃத் பின் அபி வக்காஸ் (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">عَجِبْتُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">قَضَاءِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">لِلْمُؤْمِنِ</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">أَصَابَهُ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">حَمِدَ</span> <span class=\"quran-arabic-font text-success\">رَبَّهُ</span> <span class=\"quran-arabic-font text-success\">وَشَكَرَ،</span> <span class=\"quran-arabic-font text-success\">وَإِنْ</span> <span class=\"quran-arabic-font text-success\">أَصَابَتْهُ</span> <span class=\"quran-arabic-font text-success\">مُصِيبَةٌ</span> <span class=\"quran-arabic-font text-success\">حَمِدَ</span> <span class=\"quran-arabic-font text-success\">رَبَّهُ</span> <span class=\"quran-arabic-font text-success\">وَصَبَرَ،</span> <span class=\"quran-arabic-font text-success\">يُؤْجَرُ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">حَتْى</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">اللُّقْمَةِ</span> <span class=\"quran-arabic-font text-success\">يَرْفَعُهَا</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">امْرَأَتِه</span>»<br />\r\n<br />\r\n(\"முஃமினுக்காக (விசுவாசிக்காக) அல்லாஹ் விதிக்கும் தீர்ப்பைக் கண்டு நான் வியப்படைகிறேன்; அவருக்கு ஒரு நன்மை கிடைத்தால், அவர் தனது இறைவனைப் புகழ்ந்து நன்றி செலுத்துகிறார். அவருக்கு ஏதேனும் துன்பம் ஏற்பட்டால், அவர் தனது இறைவனைப் புகழ்ந்து பொறுமை காக்கிறார். ஒரு முஃமின், தனது மனைவியின் வாயில் ஊட்டும் ஒரு கவளம் உணவு உட்பட ஒவ்வொன்றிற்கும் நற்கூலி வழங்கப்படுகிறார்.\") இது அன்-நஸாயீ அவர்களால் 'அல்-யவ்ம் வல்-லைலா'வில் பதிவு செய்யப்பட்டுள்ளது. மேலும் முஸ்லிம் நூலில் ஸுஹைப் (ரழி) அவர்கள் அறிவிக்கும் ஒரு ஹதீஸ் இதனை உறுதிப்படுத்துகிறது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">عَجَبًا</span> <span class=\"quran-arabic-font text-success\">لِلْمُؤْمِنِ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَقْضِي</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">قَضَاءً</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">خَيْرًا</span> <span class=\"quran-arabic-font text-success\">لَهُ،</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">أَصَابَتْهُ</span> <span class=\"quran-arabic-font text-success\">سَرَّاءُ</span> <span class=\"quran-arabic-font text-success\">شَكَرَ</span> <span class=\"quran-arabic-font text-success\">فَكَانَ</span> <span class=\"quran-arabic-font text-success\">خَيْرًا</span> <span class=\"quran-arabic-font text-success\">لَهُ،</span> <span class=\"quran-arabic-font text-success\">وَإِنْ</span> <span class=\"quran-arabic-font text-success\">أَصَابَتْهُ</span> <span class=\"quran-arabic-font text-success\">ضَرَّاءُ</span> <span class=\"quran-arabic-font text-success\">صَبَرَ</span> <span class=\"quran-arabic-font text-success\">فَكَانَ</span> <span class=\"quran-arabic-font text-success\">خَيْرًا</span> <span class=\"quran-arabic-font text-success\">لَهُ،</span> <span class=\"quran-arabic-font text-success\">وَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لِأَحَدٍ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">لِلْمُؤْمِن</span>»<br />\r\n<br />\r\n(\"முஃமினின் விஷயம் வியப்பிற்குரியது! அல்லாஹ் அவருக்காக எதை விதித்தாலும் அது அவருக்கு நன்மையாகவே முடிகிறது. அவருக்கு ஒரு மகிழ்ச்சியான நிலை ஏற்பட்டால், அவர் நன்றி செலுத்துகிறார், அது அவருக்கு நன்மையாகிறது; அவருக்கு ஒரு துன்பம் ஏற்பட்டால், அவர் பொறுமை காக்கிறார், அதுவும் அவருக்கு நன்மையாகிறது. இது முஃமினைத் தவிர வேறு யாருக்கும் கிடைப்பதில்லை.\") கத்தாதா அவர்கள் (இந்த வசனம் குறித்து) கூறியதாக அறிவிக்கப்பட்டுள்ளது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لَآيَاتٍ</span> <span class=\"quran-arabic-font text-success\">لِكُلِّ</span> <span class=\"quran-arabic-font text-success\">صَبَّارٍ</span> <span class=\"quran-arabic-font text-success\">شَكُورٍ</span><br />\r\n<br />\r\n(\"நிச்சயமாக, இதில் பொறுமையுடையோர், நன்றியுடையோர் ஒவ்வொருவருக்கும் அத்தாட்சிகள் உள்ளன.\") முத்தர்ரிஃப் அவர்கள் இவ்வாறு கூறுவது வழக்கம்: \"நன்றி செலுத்துபவராகவும் பொறுமை காப்பவராகவும் இருக்கும் அடியார் எவ்வளவு பாக்கியசாலி! அவருக்கு ஏதேனும் வழங்கப்பட்டால் அவர் நன்றி செலுத்துகிறார், அவர் சோதிக்கப்பட்டால் பொறுமை காக்கிறார்.\"<br />\r\n<br />","text":"ஸபா மக்களின் வர்த்தகமும் அவர்களின் அழிவும்\n\r\n\n\r\nஸபா மக்கள் அனுபவித்த அருட்கொடைகள் குறித்தும், அவர்களுக்கு அவர்களது தேசத்தில் வழங்கப்பட்டிருந்த ஆடம்பர வசதிகள் மற்றும் தாராளமான வாழ்வாதாரங்கள் குறித்தும் அல்லாஹ் நமக்குக் கூறுகிறான். அங்கே பாதுகாப்பான குடியிருப்புகளும், ஏராளமான மரங்கள், பயிர்கள் மற்றும் கனிகளுடன் ஒன்றோடொன்று இணைக்கப்பட்ட ஊர்களும் இருந்தன. அவர்கள் பயணம் செய்யும்போது, தங்களுடன் உணவுப் பொருட்களையோ அல்லது தண்ணீரையோ சுமந்து செல்ல வேண்டிய அவசியம் இருக்கவில்லை. அவர்கள் எங்கு தங்கினாலும் அவர்களுக்குத் தண்ணீரும் பழங்களும் கிடைத்தன. இதனால் அவர்கள் தங்கள் பயணத் தேவைகளுக்கேற்ப, ஒரு ஊரில் மதிய ஓய்வெடுத்துவிட்டு, மற்றொரு ஊரில் இரவு தங்க முடிந்தது. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَجَعَلْنَا بَيْنَهُمْ وَبَيْنَ الْقُرَى الَّتِى بَارَكْنَا فِيهَا\n\r\n\n\r\n(\"நாம் அவர்களுக்கும், நாம் அருள் புரிந்திருந்த ஊர்களுக்கும் இடையே (வேறு பல) ஊர்களை அமைத்தோம்.\") இது சிரியாவின் ஊர்களைக் குறிக்கிறது என்று முஜாஹித், அல்-ஹஸன், ஸயீத் பின் ஜுபைர், ஸைத் பின் அஸ்லமிடமிருந்து அறிவிக்கும் மாலிக், கத்தாதா, அத்-தஹ்ஹாக், அஸ்-ஸுத்தி, இப்னு ஸைத் மற்றும் பலர் கூறியுள்ளனர். அதாவது, அவர்கள் யமனிலிருந்து சிரியாவிற்கு, ஒன்றோடொன்று இணைக்கப்பட்ட மற்றும் எளிதில் தென்படக்கூடிய ஊர்கள் வழியாகப் பயணம் செய்து வந்தனர். \"நாம் எவற்றில் பைத்துல் முகத்தஸை (ஜெருசலேம்) அமைத்தோமோ, அந்த அருள்வளம் மிக்க ஊர்களையே இது குறிக்கிறது\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அல்-அவ்ஃபி அறிவிக்கிறார்கள்.\n\r\n\n\r\nقُرًى ظَاهِرَةً\n\r\n\n\r\nஎளிதில் தென்படக்கூடிய ஊர்கள்; அதாவது, பயணிகளுக்குத் தெளிவாகத் தெரியக்கூடிய மற்றும் நன்கு அறியப்பட்ட ஊர்கள். இதன் மூலம் அவர்கள் ஒரு ஊரில் மதிய ஓய்வையும், மற்றோர் ஊரில் இரவுத் தங்கலையும் மேற்கொள்ள முடிந்தது. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَقَدَّرْنَا فِيهَا السَّيْرَ\n\r\n\n\r\n(\"அவற்றுக்கிடையே பயண தூரங்களை நாம் நிர்ணயித்தோம்.\") அதாவது, \"பயணிகளின் தேவைகளைப் பூர்த்தி செய்யும் வகையில் நாம் அதனை அமைத்தோம்\" என்று பொருள்படும்.\n\r\n\n\r\nسِيرُواْ فِيهَا لَيَالِىَ وَأَيَّاماً ءَامِنِينَ\n\r\n\n\r\n(\"அவற்றில் இரவிலும் பகலிலும் அச்சமற்றவர்களாகப் பிரயாணம் செய்யுங்கள்.\") அதாவது, அவற்றில் பயணம் செய்பவர்கள் இரவிலும் பகலிலும் பாதுகாப்பாக இருப்பார்கள்.\n\r\n\n\r\nفَقَالُواْ رَبَّنَا بَاعِدْ بَيْنَ أَسْفَارِنَا وَظَلَمُواْ أَنفُسَهُمْ\n\r\n\n\r\n(ஆனால் அவர்கள், \"எங்கள் இறைவா! எங்கள் பயணங்களுக்கு இடையேயான தூரத்தை அதிகமாக்குவாயாக\" எனக் கூறி, தங்களுக்குத் தாங்களே அநீதி இழைத்துக் கொண்டார்கள்.) இப்னு அப்பாஸ் (ரழி), முஜாஹித், அல்-ஹஸன் மற்றும் பலர் கூறியது போல், அவர்கள் தங்களுக்கு வழங்கப்பட்ட இந்த அருட்கொடையை மதிக்கத் தவறினார்கள்; பனூ இஸ்ராயீல்கள் (மன்னையும் ஸல்வாவையும் விடுத்து) பூண்டு, வெங்காயம் போன்றவற்றை எப்படிக் கேட்டார்களோ அதுபோல, \"தங்களுடன் உணவுப் பொருட்களைச் சுமந்து கொண்டு, கடும் வெப்பத்திலும் அச்சத்திலும் ஆளில்லாத பாலைவனங்கள் வழியாக நீண்ட தூரம் பயணம் செய்ய அவர்கள் விரும்பினார்கள்.\"\n\r\n\n\r\nفَجَعَلْنَاهُمْ أَحَادِيثَ وَمَزَّقْنَاهُمْ كُلَّ مُمَزَّقٍ\n\r\n\n\r\n(\"எனவே, நாம் அவர்களைப் (பிற்காலத்தவர் பேசிக்கொள்ளும்) பழங்கதைகளாக ஆக்கினோம்; மேலும் அவர்களை முற்றிலும் சிதறடித்தோம்.\") அதாவது, \"மக்கள் மாலை நேரங்களில் கூடிப் பேசும் கதைகளாக அவர்களை நாம் ஆக்கினோம். அவர்கள் ஆடம்பர வாழ்வு வாழ்ந்து ஒன்றுபட்டிருந்த பிறகு, அல்லாஹ் அவர்களுக்கு எதிராகச் சூழ்ச்சி செய்து அவர்களை எவ்வாறு சிதறடித்தான் என்பது பேசுபொருளானது. அவர்கள் தேசம் முழுவதும் அங்கொன்றும் இங்கொன்றுமாகச் சிதறடிக்கப்பட்டனர்.\" எனவே, ஒரு மக்கள் சிதறடிக்கப்படுவதைக் குறிக்க, \"அவர்கள் ஸபா மக்களைப் போல் எல்லாத் திசைகளிலும் சிதறடிக்கப்பட்டனர்\" என்று அரபுகள் கூறுவார்கள்.\n\r\n\n\r\nإِنَّ فِي ذَلِكَ لَآيَاتٍ لِكُلِّ صَبَّارٍ شَكُورٍ\n\r\n\n\r\n(\"நிச்சயமாக, இதில் பொறுமையுடையோர், நன்றியுடையோர் ஒவ்வொருவருக்கும் அத்தாட்சிகள் உள்ளன.\") இந்த மக்கள் அனுபவித்த தண்டனையிலும், அவர்களின் அருட்கொடைகளும் ஆரோக்கியமும் அவர்களின் இறைநிராகரிப்பு மற்றும் பாவங்களுக்காகப் பழிவாங்கலாக மாற்றப்பட்ட விதத்திலும், சோதனைகளின் போது பொறுமையுடனும் அருட்கொடைகளுக்கு நன்றியுடனும் இருக்கும் ஒவ்வொருவருக்கும் படிப்பினையும் சான்றும் உள்ளது. இமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: ஸஃத் பின் அபி வக்காஸ் (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«عَجِبْتُ مِنْ قَضَاءِ اللهِ تَعَالَى لِلْمُؤْمِنِ إِنْ أَصَابَهُ خَيْرٌ حَمِدَ رَبَّهُ وَشَكَرَ، وَإِنْ أَصَابَتْهُ مُصِيبَةٌ حَمِدَ رَبَّهُ وَصَبَرَ، يُؤْجَرُ الْمُؤْمِنُ فِي كُلِّ شَيْءٍ حَتْى فِي اللُّقْمَةِ يَرْفَعُهَا إِلَى فِي امْرَأَتِه»\n\r\n\n\r\n(\"முஃமினுக்காக (விசுவாசிக்காக) அல்லாஹ் விதிக்கும் தீர்ப்பைக் கண்டு நான் வியப்படைகிறேன்; அவருக்கு ஒரு நன்மை கிடைத்தால், அவர் தனது இறைவனைப் புகழ்ந்து நன்றி செலுத்துகிறார். அவருக்கு ஏதேனும் துன்பம் ஏற்பட்டால், அவர் தனது இறைவனைப் புகழ்ந்து பொறுமை காக்கிறார். ஒரு முஃமின், தனது மனைவியின் வாயில் ஊட்டும் ஒரு கவளம் உணவு உட்பட ஒவ்வொன்றிற்கும் நற்கூலி வழங்கப்படுகிறார்.\") இது அன்-நஸாயீ அவர்களால் 'அல்-யவ்ம் வல்-லைலா'வில் பதிவு செய்யப்பட்டுள்ளது. மேலும் முஸ்லிம் நூலில் ஸுஹைப் (ரழி) அவர்கள் அறிவிக்கும் ஒரு ஹதீஸ் இதனை உறுதிப்படுத்துகிறது:\n\r\n\n\r\n«عَجَبًا لِلْمُؤْمِنِ لَا يَقْضِي اللهُ تَعَالَى لَهُ قَضَاءً إِلَّا كَانَ خَيْرًا لَهُ، إِنْ أَصَابَتْهُ سَرَّاءُ شَكَرَ فَكَانَ خَيْرًا لَهُ، وَإِنْ أَصَابَتْهُ ضَرَّاءُ صَبَرَ فَكَانَ خَيْرًا لَهُ، وَلَيْسَ ذَلِكَ لِأَحَدٍ إِلَّا لِلْمُؤْمِن»\n\r\n\n\r\n(\"முஃமினின் விஷயம் வியப்பிற்குரியது! அல்லாஹ் அவருக்காக எதை விதித்தாலும் அது அவருக்கு நன்மையாகவே முடிகிறது. அவருக்கு ஒரு மகிழ்ச்சியான நிலை ஏற்பட்டால், அவர் நன்றி செலுத்துகிறார், அது அவருக்கு நன்மையாகிறது; அவருக்கு ஒரு துன்பம் ஏற்பட்டால், அவர் பொறுமை காக்கிறார், அதுவும் அவருக்கு நன்மையாகிறது. இது முஃமினைத் தவிர வேறு யாருக்கும் கிடைப்பதில்லை.\") கத்தாதா அவர்கள் (இந்த வசனம் குறித்து) கூறியதாக அறிவிக்கப்பட்டுள்ளது:\n\r\n\n\r\nإِنَّ فِي ذَلِكَ لَآيَاتٍ لِكُلِّ صَبَّارٍ شَكُورٍ\n\r\n\n\r\n(\"நிச்சயமாக, இதில் பொறுமையுடையோர், நன்றியுடையோர் ஒவ்வொருவருக்கும் அத்தாட்சிகள் உள்ளன.\") முத்தர்ரிஃப் அவர்கள் இவ்வாறு கூறுவது வழக்கம்: \"நன்றி செலுத்துபவராகவும் பொறுமை காப்பவராகவும் இருக்கும் அடியார் எவ்வளவு பாக்கியசாலி! அவருக்கு ஏதேனும் வழங்கப்பட்டால் அவர் நன்றி செலுத்துகிறார், அவர் சோதிக்கப்பட்டால் பொறுமை காக்கிறார்.\""},"20":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=21\" class=\"link\">34:21</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:21 ஐ பார்க்கவும்"},"21":{"html":"<strong>நிராகரிப்பவர்களைப் பற்றிய இப்லீஸின் எண்ணம் எவ்வாறு உண்மையானது</strong><br />\r\n<br />\r\nஸபா மக்களைப் பற்றியும், அவர்கள் தங்களின் மன இச்சைகளையும் ஷைத்தானையும் எவ்வாறு பின்பற்றினார்கள் என்பதைப் பற்றியும் குறிப்பிட்ட பிறகு, இப்லீஸையும் தங்களின் சொந்த மன இச்சைகளையும் பின்பற்றி, ஞானத்திற்கும் நேர்வழிக்கும் எதிராகச் செயல்படும் அவர்களைப் போன்ற பிறரைப் பற்றி அல்லாஹ் கூறுகிறான். அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">صَدَّقَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">إِبْلِيسُ</span> <span class=\"quran-arabic-font text-success\">ظَنَّهُ</span> <span class=\"quran-arabic-font text-success\">فَاتَّبَعُوهُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">فَرِيقاً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ﴿</span><br />\r\n(நிச்சயமாக இப்லீஸ் அவர்களைப் பற்றிய தனது எண்ணத்தை உண்மையாக்கினான், ஆகவே, முஃமின்களிலுள்ள ஒரு பிரிவினரைத் தவிர, மற்றவர்கள் அவனையே பின்பற்றினார்கள்.)<br />\r\n<br />\r\nஇப்னு அப்பாஸ் (ரழி) அவர்களும் மற்றவர்களும், இந்த வசனமானது ஆதம் (அலை) அவர்களுக்கு ஸஜ்தா செய்ய இப்லீஸ் மறுத்தது குறித்தும், பின்னர் அவன் கூறியது குறித்தும் அல்லாஹ் தெரிவிக்கும் பின்வரும் வசனத்தைப் போன்றது எனக் கூறுகிறார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَرَءَيْتَكَ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">كَرَّمْتَ</span> <span class=\"quran-arabic-font text-success\">عَلَىَّ</span> <span class=\"quran-arabic-font text-success\">لَئِنْ</span> <span class=\"quran-arabic-font text-success\">أَخَّرْتَنِ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">الْقِيَـمَةِ</span> <span class=\"quran-arabic-font text-success\">لأَحْتَنِكَنَّ</span> <span class=\"quran-arabic-font text-success\">ذُرِّيَّتَهُ</span> <span class=\"quran-arabic-font text-success\">إَلاَّ</span> <span class=\"quran-arabic-font text-success\">قَلِيلاً﴿</span><br />\r\n('என்னைவிட நீ கண்ணியப்படுத்திய இவரைப் பார்த்தாயா? மறுமை நாள் வரை எனக்கு நீ அவகாசம் அளித்தால், ஒரு சிலரைத் தவிர இவருடைய சந்ததியினரை நான் நிச்சயமாக என் வசப்படுத்தி (வழிகெடுத்து) விடுவேன்!' என்று அவன் கூறினான்.) (<a href=\"qurandisp.php?sura=17&ayah=62\" class=\"link\">17:62</a>)<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لآتِيَنَّهُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">بَيْنِ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيهِمْ</span> <span class=\"quran-arabic-font text-success\">وَمِنْ</span> <span class=\"quran-arabic-font text-success\">خَلْفِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَعَنْ</span> <span class=\"quran-arabic-font text-success\">أَيْمَـنِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَعَن</span> <span class=\"quran-arabic-font text-success\">شَمَآئِلِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَجِدُ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَهُمْ</span> <span class=\"quran-arabic-font text-success\">شَـكِرِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n('பின்னர் நான் அவர்களின் முன்னாலும், பின்னாலும், அவர்களின் வலப்பக்கத்திலிருந்தும், இடப்பக்கத்திலிருந்தும் அவர்களிடம் வருவேன்; அவர்களில் பெரும்பாலோரை நன்றியுள்ளவர்களாக நீ காண மாட்டாய்' என்றும் அவன் கூறினான்.) (<a href=\"qurandisp.php?sura=7&ayah=17\" class=\"link\">7:17</a>) இது போன்ற பல வசனங்கள் இக்கருத்தைக் குறிப்பிடுகின்றன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">سُلْطَـنٍ﴿</span><br />\r\n(மேலும் அவர்களுக்கு மேல் அவனுக்கு (இப்லீஸுக்கு) எந்த அதிகாரமும் இருக்கவில்லை.) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகையில், \"இதன் பொருள், அவனிடம் எந்த ஆதாரமும் (சான்றும்) இருக்கவில்லை என்பதாகும்.\" ஹஸன் அல்பஸ்ரீ (ரஹ்) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் மீது ஆணையாக! அவர்களை அடிப்பதற்கு அவனிடம் சாட்டையோ, அல்லது அவர்களைக் கட்டாயப்படுத்த அவனிடம் எந்த அதிகாரமோ இருக்கவில்லை. மாறாக, அவன் (தன் வழிக்கு) அழைத்தான்; அவர்கள் அவனுக்குப் பதிலளித்தார்கள்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِلاَّ</span> <span class=\"quran-arabic-font text-success\">لِنَعْلَمَ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُ</span> <span class=\"quran-arabic-font text-success\">بِالاٌّخِرَةِ</span> <span class=\"quran-arabic-font text-success\">مِمَّنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">شَكٍّ﴿</span><br />\r\n(மறுமையை நம்புபவர் யார், அதைப் பற்றிச் சந்தேகத்தில் இருப்பவர் யார் என்பதை நாம் அறிவதற்காகவே தவிர (அவனுக்கு நாம் இடமளித்தோம்).) இதன் பொருள், \"மறுமையையும் அது நிச்சயமாக நிகழும் என்பதையும் நம்புபவர் யார் என்பதை வெளிப்படுத்துவதற்காகவே நாம் அவர்களுக்கு மேல் அவனுக்கு அதிகாரத்தை வழங்கினோம்.\" மக்கள் விசாரணைக்கு உட்படுத்தப்பட்டு, அதற்கேற்ப அவர்களுக்கு நற்கூலியோ அல்லது தண்டனையோ வழங்கப்படும். இதன் மூலம் ஒரு முஃமின் (நம்பிக்கையாளர்) இவ்வுலகில் தனது இறைவனை முறையாக வணங்குவார். மேலும், மறுமையைப் பற்றிச் சந்தேகத்தில் இருப்பவர்களிடமிருந்து இத்தகைய நம்பிக்கையாளர்களைப் பிரித்தறிவதற்காகவும் இவ்வாறு செய்யப்பட்டது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَرَبُّكَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">حَفُيظٌ﴿</span><br />\r\n(மேலும் உமது இறைவன் அனைத்துப் பொருட்களையும் கண்காணிப்பவனாக இருக்கிறான்.) அதாவது, அவன் அனைத்தையும் கண்காணித்துக் கொண்டிருந்த போதிலும், இப்லீஸைப் பின்பற்றுபவர்கள் வழிதவறிச் செல்கின்றனர். எனினும், அவனது கண்காணிப்பினாலும் பராமரிப்பினாலும், தூதர்களைப் பின்பற்றும் நம்பிக்கையாளர்கள் காப்பாற்றப்படுகின்றனர்.<br />\r\n<br />","text":"நிராகரிப்பவர்களைப் பற்றிய இப்லீஸின் எண்ணம் எவ்வாறு உண்மையானது\n\r\n\n\r\nஸபா மக்களைப் பற்றியும், அவர்கள் தங்களின் மன இச்சைகளையும் ஷைத்தானையும் எவ்வாறு பின்பற்றினார்கள் என்பதைப் பற்றியும் குறிப்பிட்ட பிறகு, இப்லீஸையும் தங்களின் சொந்த மன இச்சைகளையும் பின்பற்றி, ஞானத்திற்கும் நேர்வழிக்கும் எதிராகச் செயல்படும் அவர்களைப் போன்ற பிறரைப் பற்றி அல்லாஹ் கூறுகிறான். அல்லாஹ் கூறுகிறான்:\n\r\n﴾وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُ فَاتَّبَعُوهُ إِلاَّ فَرِيقاً مِّنَ الْمُؤْمِنِينَ﴿\n\r\n(நிச்சயமாக இப்லீஸ் அவர்களைப் பற்றிய தனது எண்ணத்தை உண்மையாக்கினான், ஆகவே, முஃமின்களிலுள்ள ஒரு பிரிவினரைத் தவிர, மற்றவர்கள் அவனையே பின்பற்றினார்கள்.)\n\r\n\n\r\nஇப்னு அப்பாஸ் (ரழி) அவர்களும் மற்றவர்களும், இந்த வசனமானது ஆதம் (அலை) அவர்களுக்கு ஸஜ்தா செய்ய இப்லீஸ் மறுத்தது குறித்தும், பின்னர் அவன் கூறியது குறித்தும் அல்லாஹ் தெரிவிக்கும் பின்வரும் வசனத்தைப் போன்றது எனக் கூறுகிறார்கள்:\n\r\n﴾أَرَءَيْتَكَ هَـذَا الَّذِى كَرَّمْتَ عَلَىَّ لَئِنْ أَخَّرْتَنِ إِلَى يَوْمِ الْقِيَـمَةِ لأَحْتَنِكَنَّ ذُرِّيَّتَهُ إَلاَّ قَلِيلاً﴿\n\r\n('என்னைவிட நீ கண்ணியப்படுத்திய இவரைப் பார்த்தாயா? மறுமை நாள் வரை எனக்கு நீ அவகாசம் அளித்தால், ஒரு சிலரைத் தவிர இவருடைய சந்ததியினரை நான் நிச்சயமாக என் வசப்படுத்தி (வழிகெடுத்து) விடுவேன்!' என்று அவன் கூறினான்.) (17:62)\n\r\n﴾ثُمَّ لآتِيَنَّهُم مِّن بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ وَعَنْ أَيْمَـنِهِمْ وَعَن شَمَآئِلِهِمْ وَلاَ تَجِدُ أَكْثَرَهُمْ شَـكِرِينَ ﴿\n\r\n('பின்னர் நான் அவர்களின் முன்னாலும், பின்னாலும், அவர்களின் வலப்பக்கத்திலிருந்தும், இடப்பக்கத்திலிருந்தும் அவர்களிடம் வருவேன்; அவர்களில் பெரும்பாலோரை நன்றியுள்ளவர்களாக நீ காண மாட்டாய்' என்றும் அவன் கூறினான்.) (7:17) இது போன்ற பல வசனங்கள் இக்கருத்தைக் குறிப்பிடுகின்றன.\n\r\n\n\r\n﴾وَمَا كَانَ لَهُ عَلَيْهِمْ مِّن سُلْطَـنٍ﴿\n\r\n(மேலும் அவர்களுக்கு மேல் அவனுக்கு (இப்லீஸுக்கு) எந்த அதிகாரமும் இருக்கவில்லை.) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகையில், \"இதன் பொருள், அவனிடம் எந்த ஆதாரமும் (சான்றும்) இருக்கவில்லை என்பதாகும்.\" ஹஸன் அல்பஸ்ரீ (ரஹ்) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் மீது ஆணையாக! அவர்களை அடிப்பதற்கு அவனிடம் சாட்டையோ, அல்லது அவர்களைக் கட்டாயப்படுத்த அவனிடம் எந்த அதிகாரமோ இருக்கவில்லை. மாறாக, அவன் (தன் வழிக்கு) அழைத்தான்; அவர்கள் அவனுக்குப் பதிலளித்தார்கள்.\"\n\r\n\n\r\n﴾إِلاَّ لِنَعْلَمَ مَن يُؤْمِنُ بِالاٌّخِرَةِ مِمَّنْ هُوَ مِنْهَا فِى شَكٍّ﴿\n\r\n(மறுமையை நம்புபவர் யார், அதைப் பற்றிச் சந்தேகத்தில் இருப்பவர் யார் என்பதை நாம் அறிவதற்காகவே தவிர (அவனுக்கு நாம் இடமளித்தோம்).) இதன் பொருள், \"மறுமையையும் அது நிச்சயமாக நிகழும் என்பதையும் நம்புபவர் யார் என்பதை வெளிப்படுத்துவதற்காகவே நாம் அவர்களுக்கு மேல் அவனுக்கு அதிகாரத்தை வழங்கினோம்.\" மக்கள் விசாரணைக்கு உட்படுத்தப்பட்டு, அதற்கேற்ப அவர்களுக்கு நற்கூலியோ அல்லது தண்டனையோ வழங்கப்படும். இதன் மூலம் ஒரு முஃமின் (நம்பிக்கையாளர்) இவ்வுலகில் தனது இறைவனை முறையாக வணங்குவார். மேலும், மறுமையைப் பற்றிச் சந்தேகத்தில் இருப்பவர்களிடமிருந்து இத்தகைய நம்பிக்கையாளர்களைப் பிரித்தறிவதற்காகவும் இவ்வாறு செய்யப்பட்டது.\n\r\n\n\r\n﴾وَرَبُّكَ عَلَى كُلِّ شَىْءٍ حَفُيظٌ﴿\n\r\n(மேலும் உமது இறைவன் அனைத்துப் பொருட்களையும் கண்காணிப்பவனாக இருக்கிறான்.) அதாவது, அவன் அனைத்தையும் கண்காணித்துக் கொண்டிருந்த போதிலும், இப்லீஸைப் பின்பற்றுபவர்கள் வழிதவறிச் செல்கின்றனர். எனினும், அவனது கண்காணிப்பினாலும் பராமரிப்பினாலும், தூதர்களைப் பின்பற்றும் நம்பிக்கையாளர்கள் காப்பாற்றப்படுகின்றனர்."},"22":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=23\" class=\"link\">34:23</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:23 ஐ பார்க்கவும்"},"23":{"html":"<strong>இங்கு இணைவைப்பாளர்களின் தெய்வங்களின் இயலாமை</strong><br />\r\n<br />\r\nஅல்லாஹ் தான் ஒருவன் மட்டுமே இறைவன் என்றும், அனைத்திலிருந்தும் தேவையற்ற அதிபதி (அஸ்-ஸமது) என்றும், அவனுக்கு நிகரோ அல்லது கூட்டாளியோ எவருமில்லை என்றும் தெளிவாகக் கூறுகிறான். அவன் தனது அதிகாரத்தில் தனித்தவன். அவனது அதிகாரத்தில் அவனுடன் பங்குகொள்ளவோ, தர்க்கம் செய்யவோ அல்லது அவனது கட்டளையை மாற்றவோ எவருக்கும் எவ்வித உரிமையும் இல்லை. எனவே, அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلِ</span> <span class=\"quran-arabic-font text-success\">ادْعُواْ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">زَعَمْتُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(கூறுவீராக: \"அல்லாஹ்வையன்றி நீங்கள் எவர்களை (தெய்வங்கள் என்று) எண்ணிக் கொண்டிருக்கின்றீர்களோ, அவர்களை அழையுங்கள்...\") அதாவது, அல்லாஹ்வையன்றி வணங்கப்படும் தெய்வங்களை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَمْلِكُونَ</span> <span class=\"quran-arabic-font text-success\">مِثْقَالَ</span> <span class=\"quran-arabic-font text-success\">ذَرَّةٍ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span><br />\r\n<br />\r\n(வானங்களிலோ அல்லது பூமியிலோ அவர்கள் ஓர் அணுவளவும் அதிகாரம் பெற்றிருக்கவில்லை.) இது பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">تَدْعُونَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَمْلِكُونَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قِطْمِيرٍ</span><br />\r\n<br />\r\n(அவனையன்றி நீங்கள் எவர்களை அழைக்கின்றீர்களோ, அவர்கள் ஒரு 'கித்மீர்' (பேரீச்சம் பழக் கொட்டையின் மெல்லிய தோல்) அளவு கூட அதிகாரம் பெற்றிருக்கவில்லை.) (<a href=\"qurandisp.php?sura=35&ayah=13\" class=\"link\">35:13</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهِمَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">شِرْكٍ</span><br />\r\n<br />\r\nஅன்றி, அவ்விரண்டிலும் அவர்களுக்கு எந்தப் பங்கும் இல்லை. அதாவது, அவர்கள் தனித்தோ அல்லது கூட்டாகவோ எதற்கும் உரிமையாளர்கள் அல்லர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">ظَهِيرٍ</span><br />\r\n<br />\r\n(அன்றி, அவர்களிலிருந்து அவனுக்கு உதவியாளர் எவரும் இல்லை.) அதாவது, இந்த இணையானவர்களிடமிருந்து எந்த விஷயத்திலும் அல்லாஹ் உதவி தேடுவதில்லை; மாறாக, படைப்புகள் அனைத்தும் அவனிடமே தேவையுள்ளவையாகவும் அவனுக்கே அடிபணிந்தவையாகவும் இருக்கின்றன. பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَنفَعُ</span> <span class=\"quran-arabic-font text-success\">الشَّفَـعَةُ</span> <span class=\"quran-arabic-font text-success\">عِندَهُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">لِمَنْ</span> <span class=\"quran-arabic-font text-success\">أَذِنَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span><br />\r\n<br />\r\n(அவன் அனுமதி அளித்தவருக்கே தவிர, அவனிடம் பரிந்துரை (ஷஃபாஅத்) பயனளிக்காது.) அதாவது, அவனது வல்லமை, மகத்துவம் மற்றும் பெருமை காரணமாக, பரிந்துரை செய்ய அவனது அனுமதியைப் பெற்ற பின்னரே தவிர, எந்தவொரு விஷயத்திலும் அவனிடம் பரிந்துரை செய்ய எவரும் துணிய மாட்டார்கள். அல்லாஹ் கூறுவது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">ذَا</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">يَشْفَعُ</span> <span class=\"quran-arabic-font text-success\">عِندَهُ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">بِإِذْنِهِ</span><br />\r\n<br />\r\n(அவனது அனுமதியின்றி அவனிடம் பரிந்துரை செய்பவர் யார்?) (<a href=\"qurandisp.php?sura=2&ayah=255\" class=\"link\">2:255</a>),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">مَّلَكٍ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تُغْنِي</span> <span class=\"quran-arabic-font text-success\">شَفَاعَتُهُمْ</span> <span class=\"quran-arabic-font text-success\">شَيْئًا</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَأْذَنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لِمَن</span> <span class=\"quran-arabic-font text-success\">يَشَاءُ</span> <span class=\"quran-arabic-font text-success\">وَيَرْضَى</span><br />\r\n<br />\r\n(மேலும் வானங்களில் எத்தனையோ வானவர்கள் இருக்கின்றனர். அல்லாஹ் நாடி, பொருந்திக்கொண்டவருக்காக அவன் அனுமதி அளித்த பின்னரே தவிர, அவர்களுடைய பரிந்துரை எவ்விதப் பயனும் அளிக்காது.) (<a href=\"qurandisp.php?sura=53&ayah=26\" class=\"link\">53:26</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَشْفَعُونَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">لِمَنِ</span> <span class=\"quran-arabic-font text-success\">ارْتَضَى</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">خَشْيَتِهِ</span> <span class=\"quran-arabic-font text-success\">مُشْفِقُونَ</span><br />\r\n<br />\r\n(அவன் பொருந்திக்கொண்டவருக்காகவே தவிர அவர்கள் பரிந்துரை செய்ய மாட்டார்கள். மேலும், அவர்கள் அவனது அச்சத்தால் நடுங்குபவர்களாக இருக்கிறார்கள்.) (<a href=\"qurandisp.php?sura=21&ayah=28\" class=\"link\">21:28</a>). ஆதமுடைய மக்களின் தலைவரும், அல்லாஹ்விடம் மிகச்சிறந்த பரிந்துரையாளருமான அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள், மனிதர்களுக்கு அவர்களுடைய இறைவன் தீர்ப்பளிக்க வரும்போது, அனைத்து மனிதர்களுக்காகவும் பரிந்துரை செய்வதற்காக 'அல்-மகாமுல் மஹ்மூத்' (புகழப்பட்ட இடம்) எனும் இடத்தில் நிற்பார்கள் என்று ஸஹீஹைனில் ஒன்றுக்கும் மேற்பட்ட அறிவிப்பாளர் தொடர்கள் வழியாக அறிவிக்கப்பட்டுள்ளது. அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فَأَسْجُدُ</span> <span class=\"quran-arabic-font text-success\">للهِ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">فَيَدَعُنِي</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">شَاءَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَدَعَنِي،</span> <span class=\"quran-arabic-font text-success\">وَيَفْتَحُ</span> <span class=\"quran-arabic-font text-success\">عَلَيَّ</span> <span class=\"quran-arabic-font text-success\">بِمَحَامِدَ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">أُحْصِيهَا</span> <span class=\"quran-arabic-font text-success\">الْآنَ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُقَالُ</span>: <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُحَمَّدُ</span> <span class=\"quran-arabic-font text-success\">ارْفَعْ</span> <span class=\"quran-arabic-font text-success\">رَأْسَكَ</span> <span class=\"quran-arabic-font text-success\">وَقُلْ</span> <span class=\"quran-arabic-font text-success\">تُسْمَعْ،</span> <span class=\"quran-arabic-font text-success\">وَسَلْ</span> <span class=\"quran-arabic-font text-success\">تُعْطَهُ،</span> <span class=\"quran-arabic-font text-success\">وَاشْفَعْ</span> <span class=\"quran-arabic-font text-success\">تُشَفَّع</span>»<br />\r\n<br />\r\n(\"அப்போது நான் அல்லாஹ் தஆலாவுக்கு ஸஜ்தா செய்வேன். அல்லாஹ் நாடிய காலம் வரை அவன் என்னை (அந்த நிலையில்) விட்டுவிடுவான். பிறகு, இப்போது என்னால் விவரிக்க முடியாத அளவுக்கான புகழுரைகளை அவன் எனக்குப் போதிப்பான். பின்னர், 'முஹம்மதே! உமது தலையை உயர்த்தும். பேசுவீராக, அது கேட்கப்படும்; கேளும், உமக்குக் கொடுக்கப்படும்; பரிந்துரை செய்வீராக, உமது பரிந்துரை ஏற்கப்படும்' என்று கூறப்படும்.\")<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">فُزِّعَ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِمْ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">مَاذَا</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمْ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">الْحَقَّ</span><br />\r\n<br />\r\n(அவர்களுடைய உள்ளங்களிலிருந்து அச்சம் நீக்கப்படும்போது, \"உங்கள் இறைவன் என்ன கூறினான்?\" என்று கேட்பார்கள். \"அவன் உண்மையையே கூறினான்\" என்று அவர்கள் கூறுவார்கள்.) இதுவும் அவனது வல்லமை மற்றும் பேராற்றலின் மகத்துவத்தைக் குறிக்கிறது. அவன் வஹீ (இறைச்செய்தி) வார்த்தைகளைப் பேசும்போது, வானவாசிகள் அவன் கூறுவதைக் கேட்கிறார்கள்; மேலும் அவர்கள் (அல்லாஹ்வின் மீதான) அச்சத்தால் மயக்கமடையும் அளவுக்கு நடுங்குகிறார்கள். இது இப்னு மஸ்ஊத் (ரழி), மஸ்ரூக் மற்றும் பலரது கருத்தாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">فُزِّعَ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِمْ</span><br />\r\n<br />\r\n(அவர்களுடைய உள்ளங்களிலிருந்து அச்சம் நீக்கப்படும்போது,) அதாவது, அச்சம் அவர்களுடைய உள்ளங்களை விட்டு நீங்கும்போது. இப்னு அப்பாஸ் (ரழி), இப்னு உமர் (ரழி), அபூ அப்துர்-ரஹ்மான் அஸ்-ஸுலமி, அஷ்-ஷஃபீ, இப்ராஹீம் அன்-நகஈ, அத்-தஹ்ஹாக், அல்-ஹஸன் மற்றும் கத்தாதா ஆகியோர் இந்த வசனத்தைப் பற்றிக் கூறுகையில்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">فُزِّعَ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِمْ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">مَاذَا</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمْ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">الْحَقَّ</span><br />\r\n<br />\r\n(அவர்களுடைய உள்ளங்களிலிருந்து அச்சம் நீக்கப்படும்போது, \"உங்கள் இறைவன் என்ன கூறினான்?\" என்று கேட்பார்கள். \"அவன் உண்மையையே கூறினான்\" என்று அவர்கள் கூறுவார்கள்.) \"அவர்களுடைய உள்ளங்களிலிருந்து அச்சம் நீக்கப்படும்போது\" என்று விளக்கமளித்தனர். இது நிகழும்போது, அவர்களில் சிலர் மற்றவர்களிடம், \"உங்கள் இறைவன் என்ன கூறினான்?\" என்று கேட்பார்கள். அர்ஷைச் சுமக்கும் (வானவர்கள்) தங்களுக்கு அடுத்துள்ளவர்களிடம் கூறுவார்கள், பிறகு அவர்கள் தங்களுக்கு அடுத்துள்ளவர்களிடம் அதைக் கடத்துவார்கள். இப்படியே அந்தச் செய்தி கீழ் வானத்தில் வசிப்பவர்களை அடையும் வரை தொடரும். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">الْحَقَّ</span><br />\r\n<br />\r\nஅவர்கள் உண்மையையே கூறுகிறார்கள். அதாவது, அல்லாஹ் கூறியதை எதையும் கூட்டாமலோ குறைக்காமலோ அவர்கள் தெரிவிக்கிறார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْعَلِىُّ</span> <span class=\"quran-arabic-font text-success\">الْكَبِيرُ</span><br />\r\n<br />\r\n(மேலும் அவன் மிக்க உயர்ந்தவன், மிகப் பெரியவன்.) இந்த வசனத்திற்கான விளக்கத்தில் இமாம் புகாரி அவர்கள் தமது ஸஹீஹில், அபூ ஹுரைரா (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">قَضَى</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">الْأَمْرَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span> <span class=\"quran-arabic-font text-success\">ضَرَبَتِ</span> <span class=\"quran-arabic-font text-success\">الْمَلَائِكَةُ</span> <span class=\"quran-arabic-font text-success\">بِأَجْنِحَتِهَا</span> <span class=\"quran-arabic-font text-success\">خُضْعَانًا</span> <span class=\"quran-arabic-font text-success\">لِقَوْلِهِ،كَأَنَّهُ</span> <span class=\"quran-arabic-font text-success\">سِلْسِلَةٌ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">صَفْوَانٍ،</span> <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">فُزِّعَ</span> <span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِمْ</span> <span class=\"quran-arabic-font text-success\">قَالُوا</span>: <span class=\"quran-arabic-font text-success\">مَاذَا</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمْ؟</span> <span class=\"quran-arabic-font text-success\">قَالُوا</span> <span class=\"quran-arabic-font text-success\">لِلَّذِي</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">الْحَقَّ،</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْعَلِيُّ</span> <span class=\"quran-arabic-font text-success\">الْكَبِيرُ،</span> <span class=\"quran-arabic-font text-success\">فَيَسْمَعُهَا</span> <span class=\"quran-arabic-font text-success\">مُسْتَرِقُ</span> <span class=\"quran-arabic-font text-success\">السَّمْعِ،</span> <span class=\"quran-arabic-font text-success\">وَمُسْتَرِقُ</span> <span class=\"quran-arabic-font text-success\">السَّمْعِ</span> <span class=\"quran-arabic-font text-success\">هَكَذَا</span> <span class=\"quran-arabic-font text-success\">بَعْضُهُ</span> <span class=\"quran-arabic-font text-success\">فَوْقَ</span> <span class=\"quran-arabic-font text-success\">بَعْضٍ</span> <span class=\"quran-arabic-font text-success\">وَوَصَفَ</span> <span class=\"quran-arabic-font text-success\">سُفْيَانُ</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ</span> <span class=\"quran-arabic-font text-success\">فَحَرَّفَهَا،</span> <span class=\"quran-arabic-font text-success\">وَنَشَرَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">أَصَابِعِهِ</span> <span class=\"quran-arabic-font text-success\">فَيَسْمَعُ</span> <span class=\"quran-arabic-font text-success\">الْكَلِمَةَ</span> <span class=\"quran-arabic-font text-success\">فَيُلْقِيهَا</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">تَحْتَهُ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُلْقِيهَا</span> <span class=\"quran-arabic-font text-success\">الْآخَرُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">تَحْتَهُ،</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يُلْقِيَهَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">لِسَانِ</span> <span class=\"quran-arabic-font text-success\">السَّاحِرِ</span> <span class=\"quran-arabic-font text-success\">أَوِ</span> <span class=\"quran-arabic-font text-success\">الْكَاهِنِ،</span> <span class=\"quran-arabic-font text-success\">فَرُبَّمَا</span> <span class=\"quran-arabic-font text-success\">أَدْرَكَهُ</span> <span class=\"quran-arabic-font text-success\">الشِّهَابُ</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يُلْقِيَهَا،</span> <span class=\"quran-arabic-font text-success\">وَرُبَّمَا</span> <span class=\"quran-arabic-font text-success\">أَلْقَاهَا</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يُدْرِكَهُ،</span> <span class=\"quran-arabic-font text-success\">فَيَكْذِبُ</span> <span class=\"quran-arabic-font text-success\">مَعَهَا</span> <span class=\"quran-arabic-font text-success\">مِائَةَ</span> <span class=\"quran-arabic-font text-success\">كَذْبَةٍ</span> <span class=\"quran-arabic-font text-success\">فَيُقَالُ</span>: <span class=\"quran-arabic-font text-success\">أَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">كَذَا</span> <span class=\"quran-arabic-font text-success\">وَكَذَا،</span> <span class=\"quran-arabic-font text-success\">كَذَا</span> <span class=\"quran-arabic-font text-success\">وَكَذَا؟</span> <span class=\"quran-arabic-font text-success\">فَيُصَدَّقُ</span> <span class=\"quran-arabic-font text-success\">بِتِلْكَ</span> <span class=\"quran-arabic-font text-success\">الْكَلِمَةِ</span> <span class=\"quran-arabic-font text-success\">الَّتِي</span> <span class=\"quran-arabic-font text-success\">سُمِعَتْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاء</span>»<br />\r\n<br />\r\n(அல்லாஹ் வானத்தில் ஒரு விவகாரத்தைத் தீர்மானிக்கும்போது, வானவர்கள் அவனது வார்த்தைகளுக்குப் பணிந்து தங்கள் சிறகுகளை அடிப்பார்கள். அது ஒரு வழுவழுப்பான பாறையின் மீது சங்கிலி மோதும் சத்தத்தைப் போல் இருக்கும். அவர்களுடைய உள்ளங்களிலிருந்து அச்சம் நீக்கப்பட்டதும் அவர்கள், \"உங்கள் இறைவன் என்ன கூறினான்?\" என்று கேட்பார்கள். அதற்கு அவர்கள், \"உண்மையையே கூறினான்; மேலும் அவன் மிக்க உயர்ந்தவன், மிகப் பெரியவன்\" என்று பதிலளிப்பார்கள். அப்போது ஒட்டுக் கேட்பவர்கள் அதைக் கேட்பார்கள். ஒட்டுக் கேட்பவர்கள் ஒருவர் மீது ஒருவராக இருப்பார்கள்.) - இதை அறிவிப்பவர்களில் ஒருவரான சுஃப்யான் அவர்கள் தனது கையைச் சாய்வாக வைத்து விரல்களை விரித்து விளக்கிக் காட்டினார்கள். (ஒட்டுக் கேட்பவன் ஒரு வார்த்தையைக் கேட்டு, தனக்குக் கீழே இருப்பவனுக்கு அதைக் கடத்துவான். அவன் தனக்குக் கீழே இருப்பவனுக்கு அதைக் கடத்துவான். இப்படியே அது ஒரு சூனியக்காரன் அல்லது குறிசொல்பவனின் நாக்கை அடையும். சில நேரங்களில் அந்த வார்த்தையைக் கடத்துவதற்கு முன்பே எரிநட்சத்திரம் அவனைத் தாக்கிவிடும்; சில நேரங்களில் அவன் அதைக் கடத்திய பிறகு அது அவனைத் தாக்கும். அவன் அந்த ஒரு வார்த்தையுடன் நூறு பொய்களைச் சேர்த்துச் சொல்வான். \"இன்ன நாளில் இன்னின்ன நடக்கும் என்று அவர் நமக்குச் சொல்லவில்லையா?\" என்று மக்களால் பேசப்படும். வானத்திலிருந்து கேட்கப்பட்ட அந்த ஒரு உண்மையின் காரணமாக மக்கள் அவனை நம்பிவிடுவார்கள்.)\" இச்செய்தி புகாரியில் இடம்பெற்றுள்ளது, முஸ்லிமில் இல்லை. அபூ தாவூத், திர்மிதி மற்றும் இப்னு மாஜா ஆகியோரும் இதனைப் பதிவு செய்துள்ளனர். அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />","text":"இங்கு இணைவைப்பாளர்களின் தெய்வங்களின் இயலாமை\n\r\n\n\r\nஅல்லாஹ் தான் ஒருவன் மட்டுமே இறைவன் என்றும், அனைத்திலிருந்தும் தேவையற்ற அதிபதி (அஸ்-ஸமது) என்றும், அவனுக்கு நிகரோ அல்லது கூட்டாளியோ எவருமில்லை என்றும் தெளிவாகக் கூறுகிறான். அவன் தனது அதிகாரத்தில் தனித்தவன். அவனது அதிகாரத்தில் அவனுடன் பங்குகொள்ளவோ, தர்க்கம் செய்யவோ அல்லது அவனது கட்டளையை மாற்றவோ எவருக்கும் எவ்வித உரிமையும் இல்லை. எனவே, அவன் கூறுகிறான்:\n\r\n\n\r\nقُلِ ادْعُواْ الَّذِينَ زَعَمْتُمْ مِّن دُونِ اللَّهِ\n\r\n\n\r\n(கூறுவீராக: \"அல்லாஹ்வையன்றி நீங்கள் எவர்களை (தெய்வங்கள் என்று) எண்ணிக் கொண்டிருக்கின்றீர்களோ, அவர்களை அழையுங்கள்...\") அதாவது, அல்லாஹ்வையன்றி வணங்கப்படும் தெய்வங்களை.\n\r\n\n\r\nلَا يَمْلِكُونَ مِثْقَالَ ذَرَّةٍ فِي السَّمَاوَاتِ وَلَا فِي الْأَرْضِ\n\r\n\n\r\n(வானங்களிலோ அல்லது பூமியிலோ அவர்கள் ஓர் அணுவளவும் அதிகாரம் பெற்றிருக்கவில்லை.) இது பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\nوَالَّذِينَ تَدْعُونَ مِن دُونِهِ مَا يَمْلِكُونَ مِن قِطْمِيرٍ\n\r\n\n\r\n(அவனையன்றி நீங்கள் எவர்களை அழைக்கின்றீர்களோ, அவர்கள் ஒரு 'கித்மீர்' (பேரீச்சம் பழக் கொட்டையின் மெல்லிய தோல்) அளவு கூட அதிகாரம் பெற்றிருக்கவில்லை.) (35:13).\n\r\n\n\r\nوَمَا لَهُمْ فِيهِمَا مِن شِرْكٍ\n\r\n\n\r\nஅன்றி, அவ்விரண்டிலும் அவர்களுக்கு எந்தப் பங்கும் இல்லை. அதாவது, அவர்கள் தனித்தோ அல்லது கூட்டாகவோ எதற்கும் உரிமையாளர்கள் அல்லர்.\n\r\n\n\r\nوَمَا لَهُ مِنْهُمْ مِّن ظَهِيرٍ\n\r\n\n\r\n(அன்றி, அவர்களிலிருந்து அவனுக்கு உதவியாளர் எவரும் இல்லை.) அதாவது, இந்த இணையானவர்களிடமிருந்து எந்த விஷயத்திலும் அல்லாஹ் உதவி தேடுவதில்லை; மாறாக, படைப்புகள் அனைத்தும் அவனிடமே தேவையுள்ளவையாகவும் அவனுக்கே அடிபணிந்தவையாகவும் இருக்கின்றன. பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَلاَ تَنفَعُ الشَّفَـعَةُ عِندَهُ إِلاَّ لِمَنْ أَذِنَ لَهُ\n\r\n\n\r\n(அவன் அனுமதி அளித்தவருக்கே தவிர, அவனிடம் பரிந்துரை (ஷஃபாஅத்) பயனளிக்காது.) அதாவது, அவனது வல்லமை, மகத்துவம் மற்றும் பெருமை காரணமாக, பரிந்துரை செய்ய அவனது அனுமதியைப் பெற்ற பின்னரே தவிர, எந்தவொரு விஷயத்திலும் அவனிடம் பரிந்துரை செய்ய எவரும் துணிய மாட்டார்கள். அல்லாஹ் கூறுவது போல்:\n\r\n\n\r\nمَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ\n\r\n\n\r\n(அவனது அனுமதியின்றி அவனிடம் பரிந்துரை செய்பவர் யார்?) (2:255),\n\r\n\n\r\nوَكَمْ مِّن مَّلَكٍ فِي السَّمَاوَاتِ لَا تُغْنِي شَفَاعَتُهُمْ شَيْئًا إِلَّا مِن بَعْدِ أَن يَأْذَنَ اللَّهُ لِمَن يَشَاءُ وَيَرْضَى\n\r\n\n\r\n(மேலும் வானங்களில் எத்தனையோ வானவர்கள் இருக்கின்றனர். அல்லாஹ் நாடி, பொருந்திக்கொண்டவருக்காக அவன் அனுமதி அளித்த பின்னரே தவிர, அவர்களுடைய பரிந்துரை எவ்விதப் பயனும் அளிக்காது.) (53:26)\n\r\n\n\r\nوَلاَ يَشْفَعُونَ إِلاَّ لِمَنِ ارْتَضَى وَهُمْ مِّنْ خَشْيَتِهِ مُشْفِقُونَ\n\r\n\n\r\n(அவன் பொருந்திக்கொண்டவருக்காகவே தவிர அவர்கள் பரிந்துரை செய்ய மாட்டார்கள். மேலும், அவர்கள் அவனது அச்சத்தால் நடுங்குபவர்களாக இருக்கிறார்கள்.) (21:28). ஆதமுடைய மக்களின் தலைவரும், அல்லாஹ்விடம் மிகச்சிறந்த பரிந்துரையாளருமான அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள், மனிதர்களுக்கு அவர்களுடைய இறைவன் தீர்ப்பளிக்க வரும்போது, அனைத்து மனிதர்களுக்காகவும் பரிந்துரை செய்வதற்காக 'அல்-மகாமுல் மஹ்மூத்' (புகழப்பட்ட இடம்) எனும் இடத்தில் நிற்பார்கள் என்று ஸஹீஹைனில் ஒன்றுக்கும் மேற்பட்ட அறிவிப்பாளர் தொடர்கள் வழியாக அறிவிக்கப்பட்டுள்ளது. அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«فَأَسْجُدُ للهِ تَعَالَى فَيَدَعُنِي مَا شَاءَ اللهُ أَنْ يَدَعَنِي، وَيَفْتَحُ عَلَيَّ بِمَحَامِدَ لَا أُحْصِيهَا الْآنَ، ثُمَّ يُقَالُ: يَا مُحَمَّدُ ارْفَعْ رَأْسَكَ وَقُلْ تُسْمَعْ، وَسَلْ تُعْطَهُ، وَاشْفَعْ تُشَفَّع»\n\r\n\n\r\n(\"அப்போது நான் அல்லாஹ் தஆலாவுக்கு ஸஜ்தா செய்வேன். அல்லாஹ் நாடிய காலம் வரை அவன் என்னை (அந்த நிலையில்) விட்டுவிடுவான். பிறகு, இப்போது என்னால் விவரிக்க முடியாத அளவுக்கான புகழுரைகளை அவன் எனக்குப் போதிப்பான். பின்னர், 'முஹம்மதே! உமது தலையை உயர்த்தும். பேசுவீராக, அது கேட்கப்படும்; கேளும், உமக்குக் கொடுக்கப்படும்; பரிந்துரை செய்வீராக, உமது பரிந்துரை ஏற்கப்படும்' என்று கூறப்படும்.\")\n\r\n\n\r\nحَتَّى إِذَا فُزِّعَ عَن قُلُوبِهِمْ قَالُواْ مَاذَا قَالَ رَبُّكُمْ قَالُواْ الْحَقَّ\n\r\n\n\r\n(அவர்களுடைய உள்ளங்களிலிருந்து அச்சம் நீக்கப்படும்போது, \"உங்கள் இறைவன் என்ன கூறினான்?\" என்று கேட்பார்கள். \"அவன் உண்மையையே கூறினான்\" என்று அவர்கள் கூறுவார்கள்.) இதுவும் அவனது வல்லமை மற்றும் பேராற்றலின் மகத்துவத்தைக் குறிக்கிறது. அவன் வஹீ (இறைச்செய்தி) வார்த்தைகளைப் பேசும்போது, வானவாசிகள் அவன் கூறுவதைக் கேட்கிறார்கள்; மேலும் அவர்கள் (அல்லாஹ்வின் மீதான) அச்சத்தால் மயக்கமடையும் அளவுக்கு நடுங்குகிறார்கள். இது இப்னு மஸ்ஊத் (ரழி), மஸ்ரூக் மற்றும் பலரது கருத்தாகும்.\n\r\n\n\r\nحَتَّى إِذَا فُزِّعَ عَن قُلُوبِهِمْ\n\r\n\n\r\n(அவர்களுடைய உள்ளங்களிலிருந்து அச்சம் நீக்கப்படும்போது,) அதாவது, அச்சம் அவர்களுடைய உள்ளங்களை விட்டு நீங்கும்போது. இப்னு அப்பாஸ் (ரழி), இப்னு உமர் (ரழி), அபூ அப்துர்-ரஹ்மான் அஸ்-ஸுலமி, அஷ்-ஷஃபீ, இப்ராஹீம் அன்-நகஈ, அத்-தஹ்ஹாக், அல்-ஹஸன் மற்றும் கத்தாதா ஆகியோர் இந்த வசனத்தைப் பற்றிக் கூறுகையில்:\n\r\n\n\r\nحَتَّى إِذَا فُزِّعَ عَن قُلُوبِهِمْ قَالُواْ مَاذَا قَالَ رَبُّكُمْ قَالُواْ الْحَقَّ\n\r\n\n\r\n(அவர்களுடைய உள்ளங்களிலிருந்து அச்சம் நீக்கப்படும்போது, \"உங்கள் இறைவன் என்ன கூறினான்?\" என்று கேட்பார்கள். \"அவன் உண்மையையே கூறினான்\" என்று அவர்கள் கூறுவார்கள்.) \"அவர்களுடைய உள்ளங்களிலிருந்து அச்சம் நீக்கப்படும்போது\" என்று விளக்கமளித்தனர். இது நிகழும்போது, அவர்களில் சிலர் மற்றவர்களிடம், \"உங்கள் இறைவன் என்ன கூறினான்?\" என்று கேட்பார்கள். அர்ஷைச் சுமக்கும் (வானவர்கள்) தங்களுக்கு அடுத்துள்ளவர்களிடம் கூறுவார்கள், பிறகு அவர்கள் தங்களுக்கு அடுத்துள்ளவர்களிடம் அதைக் கடத்துவார்கள். இப்படியே அந்தச் செய்தி கீழ் வானத்தில் வசிப்பவர்களை அடையும் வரை தொடரும். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nقَالُواْ الْحَقَّ\n\r\n\n\r\nஅவர்கள் உண்மையையே கூறுகிறார்கள். அதாவது, அல்லாஹ் கூறியதை எதையும் கூட்டாமலோ குறைக்காமலோ அவர்கள் தெரிவிக்கிறார்கள்.\n\r\n\n\r\nوَهُوَ الْعَلِىُّ الْكَبِيرُ\n\r\n\n\r\n(மேலும் அவன் மிக்க உயர்ந்தவன், மிகப் பெரியவன்.) இந்த வசனத்திற்கான விளக்கத்தில் இமாம் புகாரி அவர்கள் தமது ஸஹீஹில், அபூ ஹுரைரா (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِذَا قَضَى اللهُ تَعَالَى الْأَمْرَ فِي السَّمَاءِ ضَرَبَتِ الْمَلَائِكَةُ بِأَجْنِحَتِهَا خُضْعَانًا لِقَوْلِهِ،كَأَنَّهُ سِلْسِلَةٌ عَلَى صَفْوَانٍ، فَإِذَا فُزِّعَ عَنْ قُلُوبِهِمْ قَالُوا: مَاذَا قَالَ رَبُّكُمْ؟ قَالُوا لِلَّذِي قَالَ: الْحَقَّ، وَهُوَ الْعَلِيُّ الْكَبِيرُ، فَيَسْمَعُهَا مُسْتَرِقُ السَّمْعِ، وَمُسْتَرِقُ السَّمْعِ هَكَذَا بَعْضُهُ فَوْقَ بَعْضٍ وَوَصَفَ سُفْيَانُ بِيَدِهِ فَحَرَّفَهَا، وَنَشَرَ بَيْنَ أَصَابِعِهِ فَيَسْمَعُ الْكَلِمَةَ فَيُلْقِيهَا إِلَى مَنْ تَحْتَهُ، ثُمَّ يُلْقِيهَا الْآخَرُ إِلَى مَنْ تَحْتَهُ، حَتَّى يُلْقِيَهَا عَلَى لِسَانِ السَّاحِرِ أَوِ الْكَاهِنِ، فَرُبَّمَا أَدْرَكَهُ الشِّهَابُ قَبْلَ أَنْ يُلْقِيَهَا، وَرُبَّمَا أَلْقَاهَا قَبْلَ أَنْ يُدْرِكَهُ، فَيَكْذِبُ مَعَهَا مِائَةَ كَذْبَةٍ فَيُقَالُ: أَلَيْسَ قَدْ قَالَ لَنَا يَوْمَ كَذَا وَكَذَا، كَذَا وَكَذَا؟ فَيُصَدَّقُ بِتِلْكَ الْكَلِمَةِ الَّتِي سُمِعَتْ مِنَ السَّمَاء»\n\r\n\n\r\n(அல்லாஹ் வானத்தில் ஒரு விவகாரத்தைத் தீர்மானிக்கும்போது, வானவர்கள் அவனது வார்த்தைகளுக்குப் பணிந்து தங்கள் சிறகுகளை அடிப்பார்கள். அது ஒரு வழுவழுப்பான பாறையின் மீது சங்கிலி மோதும் சத்தத்தைப் போல் இருக்கும். அவர்களுடைய உள்ளங்களிலிருந்து அச்சம் நீக்கப்பட்டதும் அவர்கள், \"உங்கள் இறைவன் என்ன கூறினான்?\" என்று கேட்பார்கள். அதற்கு அவர்கள், \"உண்மையையே கூறினான்; மேலும் அவன் மிக்க உயர்ந்தவன், மிகப் பெரியவன்\" என்று பதிலளிப்பார்கள். அப்போது ஒட்டுக் கேட்பவர்கள் அதைக் கேட்பார்கள். ஒட்டுக் கேட்பவர்கள் ஒருவர் மீது ஒருவராக இருப்பார்கள்.) - இதை அறிவிப்பவர்களில் ஒருவரான சுஃப்யான் அவர்கள் தனது கையைச் சாய்வாக வைத்து விரல்களை விரித்து விளக்கிக் காட்டினார்கள். (ஒட்டுக் கேட்பவன் ஒரு வார்த்தையைக் கேட்டு, தனக்குக் கீழே இருப்பவனுக்கு அதைக் கடத்துவான். அவன் தனக்குக் கீழே இருப்பவனுக்கு அதைக் கடத்துவான். இப்படியே அது ஒரு சூனியக்காரன் அல்லது குறிசொல்பவனின் நாக்கை அடையும். சில நேரங்களில் அந்த வார்த்தையைக் கடத்துவதற்கு முன்பே எரிநட்சத்திரம் அவனைத் தாக்கிவிடும்; சில நேரங்களில் அவன் அதைக் கடத்திய பிறகு அது அவனைத் தாக்கும். அவன் அந்த ஒரு வார்த்தையுடன் நூறு பொய்களைச் சேர்த்துச் சொல்வான். \"இன்ன நாளில் இன்னின்ன நடக்கும் என்று அவர் நமக்குச் சொல்லவில்லையா?\" என்று மக்களால் பேசப்படும். வானத்திலிருந்து கேட்கப்பட்ட அந்த ஒரு உண்மையின் காரணமாக மக்கள் அவனை நம்பிவிடுவார்கள்.)\" இச்செய்தி புகாரியில் இடம்பெற்றுள்ளது, முஸ்லிமில் இல்லை. அபூ தாவூத், திர்மிதி மற்றும் இப்னு மாஜா ஆகியோரும் இதனைப் பதிவு செய்துள்ளனர். அல்லாஹ்வே மிக அறிந்தவன்."},"24":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=27\" class=\"link\">34:27</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:27 ஐ பார்க்கவும்"},"25":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=27\" class=\"link\">34:27</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:27 ஐ பார்க்கவும்"},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=27\" class=\"link\">34:27</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:27 ஐ பார்க்கவும்"},"27":{"html":"<strong>எந்தவொரு விஷயத்திலும் அல்லாஹ்வுக்கு எவ்விதப் பங்காளியும் இல்லை</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَرْزُقُكُم</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">ۖ</span> <span class=\"quran-arabic-font text-success\">قُلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span><br />\r\n<br />\r\n(கூறுவீராக: \"வானங்களிலிருந்தும், பூமியிலிருந்தும் உங்களுக்கு உணவளிப்பவன் யார்?\" என்று கேட்பீராக. \"அல்லாஹ்\" என்று கூறுவீராக.)<br />\r\n<br />\r\nபடைப்பாற்றலிலும், வாழ்வாதாரம் வழங்குவதிலும் அல்லாஹ் தனித்துவமானவன் என்றும், தனது தெய்வீகத்திலும் அவன் தனித்துவமானவன் என்றும் அல்லாஹ் நமக்குக் கூறுகிறான். வானத்திலிருந்தும் பூமியிலிருந்தும் அல்லாஹ்வைத் தவிர வேறெவரும் தங்களுக்கு வாழ்வாதாரம் வழங்கவில்லை என்பதை (அதாவது மழையை இறக்கி, பயிர்களை முளைக்கச் செய்வது போன்றவற்றை) அவர்கள் ஏற்றுக்கொண்டிருந்ததைப் போலவே, அவனைத் தவிர வணக்கத்திற்குரிய வேறு இறைவன் எவருமில்லை என்பதையும் அவர்கள் உணர வேண்டும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّا</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">إِيَّاكُمْ</span> <span class=\"quran-arabic-font text-success\">لَعَلَىٰ</span> <span class=\"quran-arabic-font text-success\">هُدًى</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ضَلَالٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span><br />\r\n<br />\r\n(நிச்சயமாக நாங்களோ அல்லது நீங்களோ நேர்வழியில் இருக்கிறோம் அல்லது தெளிவான வழிகேட்டில் இருக்கிறோம்.) 'இரு தரப்பினரில் ஒருவர் பொய்யராகவும் மற்றவர் உண்மையாளராகவும் இருக்க வேண்டும். நீங்களும் நாங்களும் இருவரும் நேர்வழியைப் பின்பற்றுவதற்கோ அல்லது இருவருமே வழிகேட்டில் இருப்பதற்கோ வழியே இல்லை. நம்மில் ஒருவர் மட்டுமே சரியானவராக இருக்க முடியும்; உங்களது ஷிர்க் (இணைவைத்தல்) தவறானது என்பதைக் காட்டும் தவ்ஹீதின் (ஏகத்துவத்தின்) ஆதாரத்தை நாங்கள் சமர்ப்பித்துவிட்டோம்.' அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّا</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">إِيَّاكُمْ</span> <span class=\"quran-arabic-font text-success\">لَعَلَىٰ</span> <span class=\"quran-arabic-font text-success\">هُدًى</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ضَلَالٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span><br />\r\n<br />\r\n(நிச்சயமாக நாங்களோ அல்லது நீங்களோ நேர்வழியில் இருக்கிறோம் அல்லது தெளிவான வழிகேட்டில் இருக்கிறோம்.) கத்தாதா (ரழி) கூறினார்கள், \"முஹம்மது (ஸல்) அவர்களின் தோழர்கள் (ரழி) இணைவைப்பாளர்களிடம் இவ்வாறு கூறினார்கள்: 'அல்லாஹ்வின் மீது சத்தியமாக, நாங்களும் நீங்களும் ஒரே பாதையில் இருக்க முடியாது; நம்மில் ஒருவர் மட்டுமே உண்மையான நேர்வழியில் இருக்க முடியும்.'\" இக்ரிமா (ரழி) மற்றும் ஸியாத் பின் அபீ மர்யம் (ரழி) ஆகியோர், \"இதன் பொருள்: நாங்கள் நேர்வழியில் இருக்கிறோம், நீங்கள் தெளிவான வழிகேட்டில் இருக்கிறீர்கள் என்பதாகும்\" என்று கூறினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُل</span> <span class=\"quran-arabic-font text-success\">لَّا</span> <span class=\"quran-arabic-font text-success\">تُسْأَلُونَ</span> <span class=\"quran-arabic-font text-success\">عَمَّا</span> <span class=\"quran-arabic-font text-success\">أَجْرَمْنَا</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">نُسْأَلُ</span> <span class=\"quran-arabic-font text-success\">عَمَّا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span><br />\r\n<br />\r\n(கூறுவீராக: \"நாங்கள் செய்த குற்றங்களைப் பற்றி நீங்கள் கேட்கப்பட மாட்டீர்கள்; நீங்கள் செய்பவை பற்றி நாங்களும் கேட்கப்பட மாட்டோம்.\") இது அவர்களைத் துண்டித்துக் கொள்வதைக் குறிக்கிறது. அதாவது, 'நீங்கள் எங்களைச் சார்ந்தவர்கள் அல்ல, நாங்கள் உங்களைச் சார்ந்தவர்கள் அல்ல. ஏனெனில், அல்லாஹ் ஒருவனே இறைவன் என்று நம்பவும், அவனை மட்டுமே வணங்கவும் நாங்கள் மக்களை அழைக்கிறோம். நீங்கள் அதற்குப் பதிலளித்தால், நீங்கள் எங்களைச் சார்ந்தவர்கள், நாங்கள் உங்களைச் சார்ந்தவர்கள். ஆனால் நீங்கள் எமது அழைப்பை நிராகரித்தால், எங்களுக்கும் உங்களுக்கும் எவ்விதத் தொடர்பும் இல்லை' என்று கூறுவதாகும். இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">كَذَّبُوكَ</span> <span class=\"quran-arabic-font text-success\">فَقُل</span> <span class=\"quran-arabic-font text-success\">لِّي</span> <span class=\"quran-arabic-font text-success\">عَمَلِي</span> <span class=\"quran-arabic-font text-success\">وَلَكُمْ</span> <span class=\"quran-arabic-font text-success\">عَمَلُكُمْ</span> <span class=\"quran-arabic-font text-success\">ۖ</span> <span class=\"quran-arabic-font text-success\">أَنتُم</span> <span class=\"quran-arabic-font text-success\">بَرِيئُونَ</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">أَعْمَلُ</span> <span class=\"quran-arabic-font text-success\">وَأَنَا</span> <span class=\"quran-arabic-font text-success\">بَرِيءٌ</span> <span class=\"quran-arabic-font text-success\">مِّمَّا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span><br />\r\n<br />\r\n(அவர்கள் உம்மைப் பொய்யாக்கினால், கூறுவீராக: \"எனக்கு எனது செயல், உங்களுக்கு உங்களது செயல்கள்! நான் செய்வதிலிருந்து நீங்கள் விலகியவர்கள், நீங்கள் செய்வதிலிருந்து நான் விலகியவன்!\") (<a href=\"qurandisp.php?sura=10&ayah=41\" class=\"link\">10:41</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الْكَافِرُونَ</span> - <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">أَعْبُدُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَعْبُدُونَ</span> - <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">عَابِدُونَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَعْبُدُ</span> - <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">عَابِدٌ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">عَبَدتُّمْ</span> - <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">عَابِدُونَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَعْبُدُ</span> - <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">دِينُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلِيَ</span> <span class=\"quran-arabic-font text-success\">دِينِ</span><br />\r\n<br />\r\n(கூறுவீராக: \"ஓ நிராகரிப்பாளர்களே! நீங்கள் வணங்குபவற்றை நான் வணங்க மாட்டேன். நான் வணங்குபவனை நீங்கள் வணங்குபவர்கள் அல்லர். நீங்கள் வணங்குபவற்றை நான் வணங்குபவன் அல்லன். நான் வணங்குபவனை நீங்கள் வணங்குபவர்கள் அல்லர். உங்களுக்கு உங்கள் மார்க்கம், எனக்கு என் மார்க்கம்.\") (<a href=\"qurandisp.php?sura=109&ayah=1\" class=\"link\">109:1</a>-6).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">يَجْمَعُ</span> <span class=\"quran-arabic-font text-success\">بَيْنَنَا</span> <span class=\"quran-arabic-font text-success\">رَبُّنَا</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يَفْتَحُ</span> <span class=\"quran-arabic-font text-success\">بَيْنَنَا</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span><br />\r\n<br />\r\n(கூறுவீராக: \"நம் இறைவன் நம் அனைவரையும் ஒன்று சேர்ப்பான்; பின்னர் நமக்கிடையே சத்தியத்தைக் கொண்டு தீர்ப்பளிப்பான்.\") இதன் பொருள், 'மறுமை நாளில், அவன் அனைத்துப் படைப்புகளையும் ஒரே மைதானத்தில் ஒன்று திரட்டுவான். பின்னர் நமக்கிடையே சத்தியத்தைக் கொண்டு, அதாவது நீதியுடன் தீர்ப்பளிப்பான்.' ஒவ்வொரு மனிதனும் அவனது செயல்களுக்கு ஏற்பப் பிரதிபலன் அளிக்கப்படுவான் அல்லது தண்டிக்கப்படுவான். செயல்கள் நன்மையாக இருந்தால் அவனது முடிவு நன்மையாக அமையும்; அவை தீமையாக இருந்தால் முடிவு தீமையாக அமையும். வெற்றி, கண்ணியம் மற்றும் நிலையான மகிழ்ச்சியை அடைந்தவர் யார் என்பதை அந்த நாளில் அவர்கள் அறிந்து கொள்வார்கள். அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">تَقُومُ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">يَتَفَرَّقُونَ</span> - <span class=\"quran-arabic-font text-success\">فَأَمَّا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">وَعَمِلُوا</span> <span class=\"quran-arabic-font text-success\">الصَّالِحَاتِ</span> <span class=\"quran-arabic-font text-success\">فَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">رَوْضَةٍ</span> <span class=\"quran-arabic-font text-success\">يُحْبَرُونَ</span> - <span class=\"quran-arabic-font text-success\">وَأَمَّا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُوا</span> <span class=\"quran-arabic-font text-success\">وَكَذَّبُوا</span> <span class=\"quran-arabic-font text-success\">بِآيَاتِنَا</span> <span class=\"quran-arabic-font text-success\">وَلِقَاءِ</span> <span class=\"quran-arabic-font text-success\">الْآخِرَةِ</span> <span class=\"quran-arabic-font text-success\">فَأُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">مُحْضَرُونَ</span><br />\r\n<br />\r\n(மறுமை நாள் நிலைநாட்டப்படும் அந்த நாளில் (மக்கள்) பிரிந்துவிடுவார்கள். நம்பிக்கை கொண்டு நற்செயல்கள் புரிந்தவர்கள், ஒரு சொர்க்கப் பூங்காவில் மகிழ்ச்சியூட்டப்படுவார்கள். ஆனால் எவர்கள் நிராகரித்து, நமது வசனங்களையும் மறுமையின் சந்திப்பையும் பொய்யாக்கினார்களோ, அவர்கள் வேதனையில் ஆஜர்படுத்தப்படுவார்கள்.) (<a href=\"qurandisp.php?sura=30&ayah=14\" class=\"link\">30:14</a>-16). அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْفَتَّاحُ</span> <span class=\"quran-arabic-font text-success\">الْعَلِيمُ</span><br />\r\n<br />\r\n(மேலும் அவனே உண்மையான தீர்ப்பளிப்பவன், யாவற்றையும் நன்கறிந்தவன்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">أَرُونِيَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أَلْحَقْتُم</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">شُرَكَاءَ</span><br />\r\n<br />\r\n(கூறுவீராக: \"அவனுக்குப் பங்காளிகளாக நீங்கள் இணைத்தவர்களை எனக்குக் காட்டுங்கள்...\") இதன் பொருள், 'அல்லாஹ்வுக்கு இணையாகவும் நிகராகவும் நீங்கள் ஆக்கிக்கொண்ட அந்தத் தெய்வங்களை எனக்குக் காட்டுங்கள்' என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَلاَّ</span><br />\r\n<br />\r\n(இல்லை!) அதாவது, அவனுக்கு நிகரானவரோ, போட்டியாளரோ, பங்காளியோ அல்லது சமமானவரோ எவருமில்லை. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span><br />\r\n<br />\r\nமாறாக, அவனே அல்லாஹ்; அதாவது எவ்விதப் பங்காளியும் இல்லாத தனித்த ஒரே இறைவன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span> <span class=\"quran-arabic-font text-success\">الْحَكِيمُ</span><br />\r\n<br />\r\nயாவற்றையும் மிகைத்தவன், மகா ஞானமுடையவன். அதாவது, அனைத்துப் பொருட்களையும் அடக்கி ஆளக்கூடிய வல்லமையின் அதிபதி அவன். தனது அனைத்து வார்த்தைகளிலும், செயல்களிலும், சட்டங்களிலும், விதிகளிலும் அவன் ஞானமிக்கவன். அவர்கள் கூறுவதை விட அவன் மிகவும் தூய்மையானவன், உயர்ந்தவன் மற்றும் கண்ணியமானவன். அல்லாஹ்வே நன்கறிந்தவன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَاكَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">كَافَّةً</span> <span class=\"quran-arabic-font text-success\">لِّلنَّاسِ</span> <span class=\"quran-arabic-font text-success\">بَشِيرًا</span> <span class=\"quran-arabic-font text-success\">وَنَذِيرًا</span> <span class=\"quran-arabic-font text-success\">وَلَكِنَّ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ</span><br />\r\n<br />\r\n(மேலும், (நபியே!) நாம் உம்மை மனிதகுலம் முழுமைக்கும் நற்செய்தி கூறுபவராகவும், எச்சரிப்பவராகவுமே அன்றி அனுப்பவில்லை; ஆனால், மனிதர்களில் பெரும்பாலோர் (இதை) அறியமாட்டார்கள்.)<br />\r\n<br />","text":"எந்தவொரு விஷயத்திலும் அல்லாஹ்வுக்கு எவ்விதப் பங்காளியும் இல்லை\n\r\n\n\r\nقُلْ مَن يَرْزُقُكُم مِّنَ السَّمَاوَاتِ وَالْأَرْضِ ۖ قُلِ اللَّهُ\n\r\n\n\r\n(கூறுவீராக: \"வானங்களிலிருந்தும், பூமியிலிருந்தும் உங்களுக்கு உணவளிப்பவன் யார்?\" என்று கேட்பீராக. \"அல்லாஹ்\" என்று கூறுவீராக.)\n\r\n\n\r\nபடைப்பாற்றலிலும், வாழ்வாதாரம் வழங்குவதிலும் அல்லாஹ் தனித்துவமானவன் என்றும், தனது தெய்வீகத்திலும் அவன் தனித்துவமானவன் என்றும் அல்லாஹ் நமக்குக் கூறுகிறான். வானத்திலிருந்தும் பூமியிலிருந்தும் அல்லாஹ்வைத் தவிர வேறெவரும் தங்களுக்கு வாழ்வாதாரம் வழங்கவில்லை என்பதை (அதாவது மழையை இறக்கி, பயிர்களை முளைக்கச் செய்வது போன்றவற்றை) அவர்கள் ஏற்றுக்கொண்டிருந்ததைப் போலவே, அவனைத் தவிர வணக்கத்திற்குரிய வேறு இறைவன் எவருமில்லை என்பதையும் அவர்கள் உணர வேண்டும்.\n\r\n\n\r\nوَإِنَّا أَوْ إِيَّاكُمْ لَعَلَىٰ هُدًى أَوْ فِي ضَلَالٍ مُّبِينٍ\n\r\n\n\r\n(நிச்சயமாக நாங்களோ அல்லது நீங்களோ நேர்வழியில் இருக்கிறோம் அல்லது தெளிவான வழிகேட்டில் இருக்கிறோம்.) 'இரு தரப்பினரில் ஒருவர் பொய்யராகவும் மற்றவர் உண்மையாளராகவும் இருக்க வேண்டும். நீங்களும் நாங்களும் இருவரும் நேர்வழியைப் பின்பற்றுவதற்கோ அல்லது இருவருமே வழிகேட்டில் இருப்பதற்கோ வழியே இல்லை. நம்மில் ஒருவர் மட்டுமே சரியானவராக இருக்க முடியும்; உங்களது ஷிர்க் (இணைவைத்தல்) தவறானது என்பதைக் காட்டும் தவ்ஹீதின் (ஏகத்துவத்தின்) ஆதாரத்தை நாங்கள் சமர்ப்பித்துவிட்டோம்.' அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَإِنَّا أَوْ إِيَّاكُمْ لَعَلَىٰ هُدًى أَوْ فِي ضَلَالٍ مُّبِينٍ\n\r\n\n\r\n(நிச்சயமாக நாங்களோ அல்லது நீங்களோ நேர்வழியில் இருக்கிறோம் அல்லது தெளிவான வழிகேட்டில் இருக்கிறோம்.) கத்தாதா (ரழி) கூறினார்கள், \"முஹம்மது (ஸல்) அவர்களின் தோழர்கள் (ரழி) இணைவைப்பாளர்களிடம் இவ்வாறு கூறினார்கள்: 'அல்லாஹ்வின் மீது சத்தியமாக, நாங்களும் நீங்களும் ஒரே பாதையில் இருக்க முடியாது; நம்மில் ஒருவர் மட்டுமே உண்மையான நேர்வழியில் இருக்க முடியும்.'\" இக்ரிமா (ரழி) மற்றும் ஸியாத் பின் அபீ மர்யம் (ரழி) ஆகியோர், \"இதன் பொருள்: நாங்கள் நேர்வழியில் இருக்கிறோம், நீங்கள் தெளிவான வழிகேட்டில் இருக்கிறீர்கள் என்பதாகும்\" என்று கூறினார்கள்.\n\r\n\n\r\nقُل لَّا تُسْأَلُونَ عَمَّا أَجْرَمْنَا وَلَا نُسْأَلُ عَمَّا تَعْمَلُونَ\n\r\n\n\r\n(கூறுவீராக: \"நாங்கள் செய்த குற்றங்களைப் பற்றி நீங்கள் கேட்கப்பட மாட்டீர்கள்; நீங்கள் செய்பவை பற்றி நாங்களும் கேட்கப்பட மாட்டோம்.\") இது அவர்களைத் துண்டித்துக் கொள்வதைக் குறிக்கிறது. அதாவது, 'நீங்கள் எங்களைச் சார்ந்தவர்கள் அல்ல, நாங்கள் உங்களைச் சார்ந்தவர்கள் அல்ல. ஏனெனில், அல்லாஹ் ஒருவனே இறைவன் என்று நம்பவும், அவனை மட்டுமே வணங்கவும் நாங்கள் மக்களை அழைக்கிறோம். நீங்கள் அதற்குப் பதிலளித்தால், நீங்கள் எங்களைச் சார்ந்தவர்கள், நாங்கள் உங்களைச் சார்ந்தவர்கள். ஆனால் நீங்கள் எமது அழைப்பை நிராகரித்தால், எங்களுக்கும் உங்களுக்கும் எவ்விதத் தொடர்பும் இல்லை' என்று கூறுவதாகும். இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nوَإِن كَذَّبُوكَ فَقُل لِّي عَمَلِي وَلَكُمْ عَمَلُكُمْ ۖ أَنتُم بَرِيئُونَ مِمَّا أَعْمَلُ وَأَنَا بَرِيءٌ مِّمَّا تَعْمَلُونَ\n\r\n\n\r\n(அவர்கள் உம்மைப் பொய்யாக்கினால், கூறுவீராக: \"எனக்கு எனது செயல், உங்களுக்கு உங்களது செயல்கள்! நான் செய்வதிலிருந்து நீங்கள் விலகியவர்கள், நீங்கள் செய்வதிலிருந்து நான் விலகியவன்!\") (10:41)\n\r\n\n\r\nقُلْ يَا أَيُّهَا الْكَافِرُونَ - لَا أَعْبُدُ مَا تَعْبُدُونَ - وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ - وَلَا أَنَا عَابِدٌ مَّا عَبَدتُّمْ - وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ - لَكُمْ دِينُكُمْ وَلِيَ دِينِ\n\r\n\n\r\n(கூறுவீராக: \"ஓ நிராகரிப்பாளர்களே! நீங்கள் வணங்குபவற்றை நான் வணங்க மாட்டேன். நான் வணங்குபவனை நீங்கள் வணங்குபவர்கள் அல்லர். நீங்கள் வணங்குபவற்றை நான் வணங்குபவன் அல்லன். நான் வணங்குபவனை நீங்கள் வணங்குபவர்கள் அல்லர். உங்களுக்கு உங்கள் மார்க்கம், எனக்கு என் மார்க்கம்.\") (109:1-6).\n\r\n\n\r\nقُلْ يَجْمَعُ بَيْنَنَا رَبُّنَا ثُمَّ يَفْتَحُ بَيْنَنَا بِالْحَقِّ\n\r\n\n\r\n(கூறுவீராக: \"நம் இறைவன் நம் அனைவரையும் ஒன்று சேர்ப்பான்; பின்னர் நமக்கிடையே சத்தியத்தைக் கொண்டு தீர்ப்பளிப்பான்.\") இதன் பொருள், 'மறுமை நாளில், அவன் அனைத்துப் படைப்புகளையும் ஒரே மைதானத்தில் ஒன்று திரட்டுவான். பின்னர் நமக்கிடையே சத்தியத்தைக் கொண்டு, அதாவது நீதியுடன் தீர்ப்பளிப்பான்.' ஒவ்வொரு மனிதனும் அவனது செயல்களுக்கு ஏற்பப் பிரதிபலன் அளிக்கப்படுவான் அல்லது தண்டிக்கப்படுவான். செயல்கள் நன்மையாக இருந்தால் அவனது முடிவு நன்மையாக அமையும்; அவை தீமையாக இருந்தால் முடிவு தீமையாக அமையும். வெற்றி, கண்ணியம் மற்றும் நிலையான மகிழ்ச்சியை அடைந்தவர் யார் என்பதை அந்த நாளில் அவர்கள் அறிந்து கொள்வார்கள். அல்லாஹ் கூறுவது போல:\n\r\n\n\r\nوَيَوْمَ تَقُومُ السَّاعَةُ يَوْمَئِذٍ يَتَفَرَّقُونَ - فَأَمَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَهُمْ فِي رَوْضَةٍ يُحْبَرُونَ - وَأَمَّا الَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا وَلِقَاءِ الْآخِرَةِ فَأُولَئِكَ فِي الْعَذَابِ مُحْضَرُونَ\n\r\n\n\r\n(மறுமை நாள் நிலைநாட்டப்படும் அந்த நாளில் (மக்கள்) பிரிந்துவிடுவார்கள். நம்பிக்கை கொண்டு நற்செயல்கள் புரிந்தவர்கள், ஒரு சொர்க்கப் பூங்காவில் மகிழ்ச்சியூட்டப்படுவார்கள். ஆனால் எவர்கள் நிராகரித்து, நமது வசனங்களையும் மறுமையின் சந்திப்பையும் பொய்யாக்கினார்களோ, அவர்கள் வேதனையில் ஆஜர்படுத்தப்படுவார்கள்.) (30:14-16). அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَهُوَ الْفَتَّاحُ الْعَلِيمُ\n\r\n\n\r\n(மேலும் அவனே உண்மையான தீர்ப்பளிப்பவன், யாவற்றையும் நன்கறிந்தவன்.)\n\r\n\n\r\nقُلْ أَرُونِيَ الَّذِينَ أَلْحَقْتُم بِهِ شُرَكَاءَ\n\r\n\n\r\n(கூறுவீராக: \"அவனுக்குப் பங்காளிகளாக நீங்கள் இணைத்தவர்களை எனக்குக் காட்டுங்கள்...\") இதன் பொருள், 'அல்லாஹ்வுக்கு இணையாகவும் நிகராகவும் நீங்கள் ஆக்கிக்கொண்ட அந்தத் தெய்வங்களை எனக்குக் காட்டுங்கள்' என்பதாகும்.\n\r\n\n\r\nكَلاَّ\n\r\n\n\r\n(இல்லை!) அதாவது, அவனுக்கு நிகரானவரோ, போட்டியாளரோ, பங்காளியோ அல்லது சமமானவரோ எவருமில்லை. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nبَلْ هُوَ اللَّهُ\n\r\n\n\r\nமாறாக, அவனே அல்லாஹ்; அதாவது எவ்விதப் பங்காளியும் இல்லாத தனித்த ஒரே இறைவன்.\n\r\n\n\r\nالْعَزِيزُ الْحَكِيمُ\n\r\n\n\r\nயாவற்றையும் மிகைத்தவன், மகா ஞானமுடையவன். அதாவது, அனைத்துப் பொருட்களையும் அடக்கி ஆளக்கூடிய வல்லமையின் அதிபதி அவன். தனது அனைத்து வார்த்தைகளிலும், செயல்களிலும், சட்டங்களிலும், விதிகளிலும் அவன் ஞானமிக்கவன். அவர்கள் கூறுவதை விட அவன் மிகவும் தூய்மையானவன், உயர்ந்தவன் மற்றும் கண்ணியமானவன். அல்லாஹ்வே நன்கறிந்தவன்.\n\r\n\n\r\nوَمَا أَرْسَلْنَاكَ إِلَّا كَافَّةً لِّلنَّاسِ بَشِيرًا وَنَذِيرًا وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ\n\r\n\n\r\n(மேலும், (நபியே!) நாம் உம்மை மனிதகுலம் முழுமைக்கும் நற்செய்தி கூறுபவராகவும், எச்சரிப்பவராகவுமே அன்றி அனுப்பவில்லை; ஆனால், மனிதர்களில் பெரும்பாலோர் (இதை) அறியமாட்டார்கள்.)"},"28":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=30\" class=\"link\">34:30</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:30 ஐ பார்க்கவும்"},"29":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=30\" class=\"link\">34:30</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:30 ஐ பார்க்கவும்"},"30":{"html":"<strong>நபி (ஸல்) அவர்கள் மனிதகுலம் முழுமைக்கும் அனுப்பப்பட்டார்கள். அல்லாஹ் தனது அடியாரும் தூதருமான முஹம்மது (ஸல்) அவர்களிடம் கூறுகிறான்:</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَاكَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">كَآفَّةً</span> <span class=\"quran-arabic-font text-success\">لِّلنَّاسِ</span> <span class=\"quran-arabic-font text-success\">بَشِيراً</span> <span class=\"quran-arabic-font text-success\">وَنَذِيراً</span><br />\r\n<br />\r\n(நாம் உம்மை மனிதகுலம் முழுமைக்கும் நற்செய்தி கூறுபவராகவும், எச்சரிக்கை செய்பவராகவுமே தவிர அனுப்பவில்லை.) அதாவது, தங்களது செயல்களுக்குப் பொறுப்புக் கூற வேண்டிய அனைத்துப் படைப்புகளுக்கும் (நீர் தூதராக அனுப்பப்பட்டுள்ளீர்). இது இந்த வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">يَأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">رَسُولُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">جَمِيعًا</span><br />\r\n<br />\r\n(கூறுவீராக: “மனிதர்களே! நிச்சயமாக நான் உங்கள் அனைவருக்கும் அனுப்பப்பட்ட அல்லாஹ்வின் தூதராவேன்.”) (<a href=\"qurandisp.php?sura=7&ayah=158\" class=\"link\">7:158</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تَبَارَكَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">نَزَّلَ</span> <span class=\"quran-arabic-font text-success\">الْفُرْقَانَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">عَبْدِهِ</span> <span class=\"quran-arabic-font text-success\">لِيَكُونَ</span> <span class=\"quran-arabic-font text-success\">لِلْعَالَمِينَ</span> <span class=\"quran-arabic-font text-success\">نَذِيراً</span><br />\r\n<br />\r\n(அகிலத்தாருக்கு எச்சரிக்கை செய்வதற்காக, தனது அடியார் மீது ஃபுர்கானை (சத்தியத்தையும் அசத்தியத்தையும் பிரித்தறியும் வேதத்தை) இறக்கியவன் பாக்கியமிக்கவன்.) (<a href=\"qurandisp.php?sura=25&ayah=1\" class=\"link\">25:1</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَشِيراً</span> <span class=\"quran-arabic-font text-success\">وَنَذِيراً</span><br />\r\n<br />\r\nநற்செய்தி கூறுபவர் மற்றும் எச்சரிக்கை செய்பவர் என்பதன் பொருள், உமக்குக் கீழ்ப்படிவோருக்குச் சொர்க்கத்தைப் பற்றிய நற்செய்தியை வழங்குவதும், உமக்கு மாறு செய்வோருக்கு நரக நெருப்பைப் பற்றி எச்சரிக்கை செய்வதுமாகும். இது பின்வரும் வசனங்களைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَكِنَّ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ</span><br />\r\n<br />\r\n(எனினும், மனிதர்களில் பெரும்பாலானோர் அறியமாட்டார்கள்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرُ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">حَرَصْتَ</span> <span class=\"quran-arabic-font text-success\">بِمُؤْمِنِينَ</span><br />\r\n<br />\r\n(நீர் எவ்வளவுதான் ஆசைப்பட்டாலும், மனிதர்களில் பெரும்பாலானோர் நம்பிக்கை கொள்ளமாட்டார்கள்.) (<a href=\"qurandisp.php?sura=12&ayah=103\" class=\"link\">12:103</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">تُطِعْ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">يُضِلُّوكَ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(பூமியில் உள்ளவர்களில் பெரும்பாலானோருக்கு நீர் கீழ்ப்படிந்தால், அவர்கள் உம்மை அல்லாஹ்வின் பாதையிலிருந்து வழிதவறச் செய்துவிடுவார்கள்.) (<a href=\"qurandisp.php?sura=6&ayah=116\" class=\"link\">6:116</a>). முஹம்மது பின் கஃப் அவர்கள் இந்த வசனத்தைப் பற்றிக் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَاكَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">كَآفَّةً</span> <span class=\"quran-arabic-font text-success\">لِّلنَّاسِ</span><br />\r\n<br />\r\n(நாம் உம்மை மனிதகுலம் முழுமைக்குமே தவிர அனுப்பவில்லை) என்பதன் பொருள், எல்லா மக்களுக்கும் என்பதாகும். கத்தாதா அவர்கள் இந்த வசனத்தைப் பற்றிக் கூறினார்கள்: \"அல்லாஹ், முஹம்மது (ஸல்) அவர்களை அரபிகளுக்கும் அரபியல்லாதவர்களுக்கும் தூதராக அனுப்பினான். எனவே, அவர்களில் அல்லாஹ்விடம் மிகவும் கண்ணியமானவர் எவரெனில், அல்லாஹ்வுக்கு மிகவும் கீழ்ப்படிந்து நடப்பவரே ஆவார்.\" புகாரி, முஸ்லிம் ஆகிய இரு ஸஹீஹ் நூல்களிலும் ஜாபிர் (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்யப்பட்டுள்ளது, \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أُعْطِيتُ</span> <span class=\"quran-arabic-font text-success\">خَمْسًا</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يُعْطَهُنَّ</span> <span class=\"quran-arabic-font text-success\">أَحَدٌ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْأَنْبِيَاءِ</span> <span class=\"quran-arabic-font text-success\">قَبْلِي</span>: <span class=\"quran-arabic-font text-success\">نُصِرْتُ</span> <span class=\"quran-arabic-font text-success\">بِالرُّعْبِ</span> <span class=\"quran-arabic-font text-success\">مَسِيرَةَ</span> <span class=\"quran-arabic-font text-success\">شَهْرٍ،</span> <span class=\"quran-arabic-font text-success\">وَجُعِلَتْ</span> <span class=\"quran-arabic-font text-success\">لِيَ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضُ</span> <span class=\"quran-arabic-font text-success\">مَسْجِدًا</span> <span class=\"quran-arabic-font text-success\">وَطَهُورًا،</span> <span class=\"quran-arabic-font text-success\">فَأَيُّمَا</span> <span class=\"quran-arabic-font text-success\">رَجُلٍ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أُمَّتِي</span> <span class=\"quran-arabic-font text-success\">أَدْرَكَتْهُ</span> <span class=\"quran-arabic-font text-success\">الصَّلَاةُ</span> <span class=\"quran-arabic-font text-success\">فَلْيُصَلِّ،</span> <span class=\"quran-arabic-font text-success\">وَأُحِلَّتْ</span> <span class=\"quran-arabic-font text-success\">لِيَ</span> <span class=\"quran-arabic-font text-success\">الْغَنَائِمُ</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَحِلَّ</span> <span class=\"quran-arabic-font text-success\">لِأَحَدٍ</span> <span class=\"quran-arabic-font text-success\">قَبْلِي،</span> <span class=\"quran-arabic-font text-success\">وَأُعْطِيتُ</span> <span class=\"quran-arabic-font text-success\">الشَّفَاعَةَ،</span> <span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">النَّبِيُّ</span> <span class=\"quran-arabic-font text-success\">يُبْعَثُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">قَوْمِهِ</span> <span class=\"quran-arabic-font text-success\">خَاصَّةً</span> <span class=\"quran-arabic-font text-success\">وَبُعِثْتُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">عَامَّة</span>»<br />\r\n<br />\r\n(எனக்கு முன்னிருந்த எந்தவொரு நபிக்கும் வழங்கப்படாத ஐந்து விஷயங்கள் எனக்கு வழங்கப்பட்டுள்ளன: ஒரு மாத கால பயணத் தொலைவிலிருந்தே எதிரிகளின் உள்ளங்களில் அச்சத்தை ஏற்படுத்துவதன் மூலம் எனக்கு உதவி செய்யப்பட்டுள்ளது. பூமி முழுவதும் எனக்குத் தொழுமிடமாகவும், தூய்மைப்படுத்தும் சாதனமாகவும் ஆக்கப்பட்டுள்ளது. எனவே, எனது உம்மத்தைச் சேர்ந்த எவருக்குத் தொழுகை நேரம் வந்துவிடுகிறதோ அவர் அங்கேயே தொழுதுகொள்ளட்டும். போர்ச் செல்வங்கள் (கனீமத்) எனக்கு ஆகுமாக்கப்பட்டுள்ளன; எனக்கு முன் இருந்த எவருக்கும் அவை ஆகுமாக்கப்பட்டிருக்கவில்லை. எனக்குப் பரிந்துரை செய்யும் அதிகாரம் (ஷஃபாஅத்) வழங்கப்பட்டுள்ளது. ஒவ்வொரு நபியும் தத்தமது சமூகத்தாருக்கு மட்டுமே பிரத்யேகமாக அனுப்பப்பட்டார்கள்; ஆனால் நான் ஒட்டுமொத்த மனிதகுலத்திற்கும் பொதுவானவராக அனுப்பப்பட்டுள்ளேன்.)\" ஸஹீஹ் முஸ்லிமில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூறியதாகவும் பதிவு செய்யப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">بُعِثْتُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الْأَسْوَدِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَحْمَر</span>»<br />\r\n<br />\r\n(நான் கறுப்பு மற்றும் சிவப்பு (நிறமுடைய) மக்களுக்கும் தூதராக அனுப்பப்பட்டுள்ளேன்.) முஜாஹித் அவர்கள், \"இதன் பொருள் ஜின்களுக்கும் மனிதர்களுக்கும் என்பதாகும்\" என்று கூறினார்கள். மற்றவர்கள் இதன் பொருள் அரபிகள் மற்றும் அரபியல்லாதவர்கள் என்று கூறினார்கள். இவ்விரு கருத்துகளுமே சரியானவை.<br />\r\n<br />\r\n<strong>மறுமை நாள் எப்போது நிகழும் என்று நிராகரிப்பாளர்கள் கேட்டதும், அதற்கான பதிலும். அந்த நேரம் ஒருபோதும் வராது என்று நிராகரிப்பாளர்கள் எவ்வாறு எண்ணினார்கள் என்பதை அல்லாஹ் நமக்குக் கூறுகிறான்:</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">مَتَى</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">الْوَعْدُ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">صَادِقِينَ</span><br />\r\n<br />\r\n(“நீங்கள் உண்மையாளர்களாக இருந்தால், இந்த வாக்குறுதி எப்போது நிறைவேறும்?” என்று அவர்கள் கேட்கிறார்கள்.) இது இந்த வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَسْتَعْجِلُ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">مُشْفِقُونَ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">وَيَعْلَمُونَ</span> <span class=\"quran-arabic-font text-success\">أَنَّهَا</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span><br />\r\n<br />\r\n(அதன் மீது நம்பிக்கை கொள்ளாதவர்களே அதை அவசரமாகத் தேடுகிறார்கள். ஆனால், நம்பிக்கை கொண்டவர்களோ அது குறித்து அஞ்சுகிறார்கள், மேலும் அது முற்றிலும் உண்மை என்பதையும் அவர்கள் அறிவார்கள்...) (<a href=\"qurandisp.php?sura=42&ayah=18\" class=\"link\">42:18</a>). பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُل</span> <span class=\"quran-arabic-font text-success\">لَّكُم</span> <span class=\"quran-arabic-font text-success\">مِّيعَادُ</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تَسْتَأْخِرُونَ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">سَاعَةً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَسْتَقْدِمُونَ</span><br />\r\n<br />\r\n(கூறுவீராக: “உங்களுக்கு ஒரு நாளின் வாக்குறுதி உள்ளது. அதை விட்டும் ஒரு நாழிகை கூட நீங்கள் பிந்தவும் மாட்டீர்கள், முந்தவும் மாட்டீர்கள்.”) இதன் பொருள், 'உங்களுக்கு ஒரு குறிப்பிட்ட நேரம் நிர்ணயிக்கப்பட்டுள்ளது, அதை மாற்றவோ திருத்தவோ முடியாது. அந்த நேரம் வரும்போது, உங்களால் அதைத் தள்ளிப் போடவோ அல்லது முன்கூட்டியே கொண்டு வரவோ முடியாது' என்பதாகும். அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">أَجَلَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُؤَخَّرُ</span><br />\r\n<br />\r\n(நிச்சயமாக, அல்லாஹ்வின் தவணை வரும்போது, அது தாமதப்படுத்தப்படாது.) (<a href=\"qurandisp.php?sura=71&ayah=4\" class=\"link\">71:4</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">نُؤَخِّرُهُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">لِأَجَلٍ</span> <span class=\"quran-arabic-font text-success\">مَّعْدُودٍ</span> - <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَأْتِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَكَلَّمُ</span> <span class=\"quran-arabic-font text-success\">نَفْسٌ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">بِإِذْنِهِ</span> <span class=\"quran-arabic-font text-success\">فَمِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">شَقِىٌّ</span> <span class=\"quran-arabic-font text-success\">وَسَعِيدٌ</span><br />\r\n<br />\r\n(குறிப்பிடப்பட்ட ஒரு தவணைக்காகவே தவிர நாம் அதைத் தாமதப்படுத்தவில்லை. அது வரும் நாளில், அவனது அனுமதியின்றி எந்த ஓர் ஆன்மாவும் பேசாது. அவர்களில் சிலர் துர்பாக்கியசாலிகளாகவும், (மற்றவர்கள்) பாக்கியசாலிகளாகவும் இருப்பார்கள்.) (<a href=\"qurandisp.php?sura=11&ayah=104\" class=\"link\">11:104</a>-105).<br />\r\n<br />\r\n<br />\r\n<br />","text":"நபி (ஸல்) அவர்கள் மனிதகுலம் முழுமைக்கும் அனுப்பப்பட்டார்கள். அல்லாஹ் தனது அடியாரும் தூதருமான முஹம்மது (ஸல்) அவர்களிடம் கூறுகிறான்:\n\r\n\n\r\nوَمَآ أَرْسَلْنَاكَ إِلاَّ كَآفَّةً لِّلنَّاسِ بَشِيراً وَنَذِيراً\n\r\n\n\r\n(நாம் உம்மை மனிதகுலம் முழுமைக்கும் நற்செய்தி கூறுபவராகவும், எச்சரிக்கை செய்பவராகவுமே தவிர அனுப்பவில்லை.) அதாவது, தங்களது செயல்களுக்குப் பொறுப்புக் கூற வேண்டிய அனைத்துப் படைப்புகளுக்கும் (நீர் தூதராக அனுப்பப்பட்டுள்ளீர்). இது இந்த வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\nقُلْ يَأَيُّهَا النَّاسُ إِنِّى رَسُولُ اللَّهِ إِلَيْكُمْ جَمِيعًا\n\r\n\n\r\n(கூறுவீராக: “மனிதர்களே! நிச்சயமாக நான் உங்கள் அனைவருக்கும் அனுப்பப்பட்ட அல்லாஹ்வின் தூதராவேன்.”) (7:158)\n\r\n\n\r\nتَبَارَكَ الَّذِى نَزَّلَ الْفُرْقَانَ عَلَى عَبْدِهِ لِيَكُونَ لِلْعَالَمِينَ نَذِيراً\n\r\n\n\r\n(அகிலத்தாருக்கு எச்சரிக்கை செய்வதற்காக, தனது அடியார் மீது ஃபுர்கானை (சத்தியத்தையும் அசத்தியத்தையும் பிரித்தறியும் வேதத்தை) இறக்கியவன் பாக்கியமிக்கவன்.) (25:1)\n\r\n\n\r\nبَشِيراً وَنَذِيراً\n\r\n\n\r\nநற்செய்தி கூறுபவர் மற்றும் எச்சரிக்கை செய்பவர் என்பதன் பொருள், உமக்குக் கீழ்ப்படிவோருக்குச் சொர்க்கத்தைப் பற்றிய நற்செய்தியை வழங்குவதும், உமக்கு மாறு செய்வோருக்கு நரக நெருப்பைப் பற்றி எச்சரிக்கை செய்வதுமாகும். இது பின்வரும் வசனங்களைப் போன்றதாகும்:\n\r\n\n\r\nوَلَكِنَّ أَكْثَرَ النَّاسِ لاَ يَعْلَمُونَ\n\r\n\n\r\n(எனினும், மனிதர்களில் பெரும்பாலானோர் அறியமாட்டார்கள்.)\n\r\n\n\r\nوَمَآ أَكْثَرُ النَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ\n\r\n\n\r\n(நீர் எவ்வளவுதான் ஆசைப்பட்டாலும், மனிதர்களில் பெரும்பாலானோர் நம்பிக்கை கொள்ளமாட்டார்கள்.) (12:103)\n\r\n\n\r\nوَإِن تُطِعْ أَكْثَرَ مَن فِى الْأَرْضِ يُضِلُّوكَ عَن سَبِيلِ اللَّهِ\n\r\n\n\r\n(பூமியில் உள்ளவர்களில் பெரும்பாலானோருக்கு நீர் கீழ்ப்படிந்தால், அவர்கள் உம்மை அல்லாஹ்வின் பாதையிலிருந்து வழிதவறச் செய்துவிடுவார்கள்.) (6:116). முஹம்மது பின் கஃப் அவர்கள் இந்த வசனத்தைப் பற்றிக் கூறினார்கள்:\n\r\n\n\r\nوَمَآ أَرْسَلْنَاكَ إِلاَّ كَآفَّةً لِّلنَّاسِ\n\r\n\n\r\n(நாம் உம்மை மனிதகுலம் முழுமைக்குமே தவிர அனுப்பவில்லை) என்பதன் பொருள், எல்லா மக்களுக்கும் என்பதாகும். கத்தாதா அவர்கள் இந்த வசனத்தைப் பற்றிக் கூறினார்கள்: \"அல்லாஹ், முஹம்மது (ஸல்) அவர்களை அரபிகளுக்கும் அரபியல்லாதவர்களுக்கும் தூதராக அனுப்பினான். எனவே, அவர்களில் அல்லாஹ்விடம் மிகவும் கண்ணியமானவர் எவரெனில், அல்லாஹ்வுக்கு மிகவும் கீழ்ப்படிந்து நடப்பவரே ஆவார்.\" புகாரி, முஸ்லிம் ஆகிய இரு ஸஹீஹ் நூல்களிலும் ஜாபிர் (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்யப்பட்டுள்ளது, \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«أُعْطِيتُ خَمْسًا لَمْ يُعْطَهُنَّ أَحَدٌ مِنَ الْأَنْبِيَاءِ قَبْلِي: نُصِرْتُ بِالرُّعْبِ مَسِيرَةَ شَهْرٍ، وَجُعِلَتْ لِيَ الْأَرْضُ مَسْجِدًا وَطَهُورًا، فَأَيُّمَا رَجُلٍ مِنْ أُمَّتِي أَدْرَكَتْهُ الصَّلَاةُ فَلْيُصَلِّ، وَأُحِلَّتْ لِيَ الْغَنَائِمُ وَلَمْ تَحِلَّ لِأَحَدٍ قَبْلِي، وَأُعْطِيتُ الشَّفَاعَةَ، وَكَانَ النَّبِيُّ يُبْعَثُ إِلَى قَوْمِهِ خَاصَّةً وَبُعِثْتُ إِلَى النَّاسِ عَامَّة»\n\r\n\n\r\n(எனக்கு முன்னிருந்த எந்தவொரு நபிக்கும் வழங்கப்படாத ஐந்து விஷயங்கள் எனக்கு வழங்கப்பட்டுள்ளன: ஒரு மாத கால பயணத் தொலைவிலிருந்தே எதிரிகளின் உள்ளங்களில் அச்சத்தை ஏற்படுத்துவதன் மூலம் எனக்கு உதவி செய்யப்பட்டுள்ளது. பூமி முழுவதும் எனக்குத் தொழுமிடமாகவும், தூய்மைப்படுத்தும் சாதனமாகவும் ஆக்கப்பட்டுள்ளது. எனவே, எனது உம்மத்தைச் சேர்ந்த எவருக்குத் தொழுகை நேரம் வந்துவிடுகிறதோ அவர் அங்கேயே தொழுதுகொள்ளட்டும். போர்ச் செல்வங்கள் (கனீமத்) எனக்கு ஆகுமாக்கப்பட்டுள்ளன; எனக்கு முன் இருந்த எவருக்கும் அவை ஆகுமாக்கப்பட்டிருக்கவில்லை. எனக்குப் பரிந்துரை செய்யும் அதிகாரம் (ஷஃபாஅத்) வழங்கப்பட்டுள்ளது. ஒவ்வொரு நபியும் தத்தமது சமூகத்தாருக்கு மட்டுமே பிரத்யேகமாக அனுப்பப்பட்டார்கள்; ஆனால் நான் ஒட்டுமொத்த மனிதகுலத்திற்கும் பொதுவானவராக அனுப்பப்பட்டுள்ளேன்.)\" ஸஹீஹ் முஸ்லிமில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூறியதாகவும் பதிவு செய்யப்பட்டுள்ளது:\n\r\n\n\r\n«بُعِثْتُ إِلَى الْأَسْوَدِ وَالْأَحْمَر»\n\r\n\n\r\n(நான் கறுப்பு மற்றும் சிவப்பு (நிறமுடைய) மக்களுக்கும் தூதராக அனுப்பப்பட்டுள்ளேன்.) முஜாஹித் அவர்கள், \"இதன் பொருள் ஜின்களுக்கும் மனிதர்களுக்கும் என்பதாகும்\" என்று கூறினார்கள். மற்றவர்கள் இதன் பொருள் அரபிகள் மற்றும் அரபியல்லாதவர்கள் என்று கூறினார்கள். இவ்விரு கருத்துகளுமே சரியானவை.\n\r\n\n\r\nமறுமை நாள் எப்போது நிகழும் என்று நிராகரிப்பாளர்கள் கேட்டதும், அதற்கான பதிலும். அந்த நேரம் ஒருபோதும் வராது என்று நிராகரிப்பாளர்கள் எவ்வாறு எண்ணினார்கள் என்பதை அல்லாஹ் நமக்குக் கூறுகிறான்:\n\r\n\n\r\nوَيَقُولُونَ مَتَى هَذَا الْوَعْدُ إِن كُنتُمْ صَادِقِينَ\n\r\n\n\r\n(“நீங்கள் உண்மையாளர்களாக இருந்தால், இந்த வாக்குறுதி எப்போது நிறைவேறும்?” என்று அவர்கள் கேட்கிறார்கள்.) இது இந்த வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\nيَسْتَعْجِلُ بِهَا الَّذِينَ لاَ يُؤْمِنُونَ بِهَا وَالَّذِينَ ءَامَنُواْ مُشْفِقُونَ مِنْهَا وَيَعْلَمُونَ أَنَّهَا الْحَقُّ\n\r\n\n\r\n(அதன் மீது நம்பிக்கை கொள்ளாதவர்களே அதை அவசரமாகத் தேடுகிறார்கள். ஆனால், நம்பிக்கை கொண்டவர்களோ அது குறித்து அஞ்சுகிறார்கள், மேலும் அது முற்றிலும் உண்மை என்பதையும் அவர்கள் அறிவார்கள்...) (42:18). பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nقُل لَّكُم مِّيعَادُ يَوْمٍ لاَّ تَسْتَأْخِرُونَ عَنْهُ سَاعَةً وَلاَ تَسْتَقْدِمُونَ\n\r\n\n\r\n(கூறுவீராக: “உங்களுக்கு ஒரு நாளின் வாக்குறுதி உள்ளது. அதை விட்டும் ஒரு நாழிகை கூட நீங்கள் பிந்தவும் மாட்டீர்கள், முந்தவும் மாட்டீர்கள்.”) இதன் பொருள், 'உங்களுக்கு ஒரு குறிப்பிட்ட நேரம் நிர்ணயிக்கப்பட்டுள்ளது, அதை மாற்றவோ திருத்தவோ முடியாது. அந்த நேரம் வரும்போது, உங்களால் அதைத் தள்ளிப் போடவோ அல்லது முன்கூட்டியே கொண்டு வரவோ முடியாது' என்பதாகும். அல்லாஹ் கூறுவது போல:\n\r\n\n\r\nإِنَّ أَجَلَ اللَّهِ إِذَا جَآءَ لاَ يُؤَخَّرُ\n\r\n\n\r\n(நிச்சயமாக, அல்லாஹ்வின் தவணை வரும்போது, அது தாமதப்படுத்தப்படாது.) (71:4)\n\r\n\n\r\nوَمَا نُؤَخِّرُهُ إِلاَّ لِأَجَلٍ مَّعْدُودٍ - يَوْمَ يَأْتِ لاَ تَكَلَّمُ نَفْسٌ إِلاَّ بِإِذْنِهِ فَمِنْهُمْ شَقِىٌّ وَسَعِيدٌ\n\r\n\n\r\n(குறிப்பிடப்பட்ட ஒரு தவணைக்காகவே தவிர நாம் அதைத் தாமதப்படுத்தவில்லை. அது வரும் நாளில், அவனது அனுமதியின்றி எந்த ஓர் ஆன்மாவும் பேசாது. அவர்களில் சிலர் துர்பாக்கியசாலிகளாகவும், (மற்றவர்கள்) பாக்கியசாலிகளாகவும் இருப்பார்கள்.) (11:104-105)."},"31":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=33\" class=\"link\">34:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:33 ஐ பார்க்கவும்"},"32":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=33\" class=\"link\">34:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:33 ஐ பார்க்கவும்"},"33":{"html":"<strong>உண்மையை மறுப்பதில் நிராகரிப்பாளர்கள் இவ்வுலகில் எவ்வாறு ஒன்றுபட்டிருந்தார்கள் என்பதும், மறுமை நாளில் அவர்கள் ஒருவருக்கொருவர் எவ்வாறு தர்க்கம் செய்துகொள்வார்கள் என்பதும்</strong><br />\r\n<br />\r\n <br />\r\n<br />\r\nநிராகரிப்பாளர்களின் எல்லைமீறிய அநியாயம், பிடிவாதம் மற்றும் திருக்குர்ஆனையும், அது மறுமை நாளைப் பற்றி அவர்களுக்குக் கூறுவதையும் நம்ப மறுக்கும் அவர்களின் பிடிவாதம் குறித்து அல்லாஹ் நமக்குக் கூறுகிறான். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">لَن</span> <span class=\"quran-arabic-font text-success\">نُّؤْمِنَ</span> <span class=\"quran-arabic-font text-success\">بِهَـذَا</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانِ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">بِالَّذِى</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">يَدَيْهِ</span><br />\r\n<br />\r\n(“இந்தக் குர்ஆனையும், இதற்கு முன்னிருந்தவற்றையும் நாங்கள் ஒருபோதும் நம்ப மாட்டோம்” என்று நிராகரிப்பாளர்கள் கூறுகின்றனர்.) அல்லாஹ் அவர்களை அச்சுறுத்துகிறான். மேலும், தனக்கு முன்பாக அவர்கள் ஒருவருக்கொருவர் தர்க்கம் செய்து விவாதித்துக் கொண்டு நிற்கும் இழிவான நிலையைப் பற்றி அவர்களை எச்சரிக்கிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">تَرَى</span> <span class=\"quran-arabic-font text-success\">إِذِ</span> <span class=\"quran-arabic-font text-success\">الظَّـلِمُونَ</span> <span class=\"quran-arabic-font text-success\">مَوْقُوفُونَ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَرْجِعُ</span> <span class=\"quran-arabic-font text-success\">بَعْضُهُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">بَعْضٍ</span> <span class=\"quran-arabic-font text-success\">الْقَوْلَ</span> <span class=\"quran-arabic-font text-success\">يَقُولُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">اسْتُضْعِفُواْ</span><br />\r\n<br />\r\n(அவர்கள் ஒருவருக்கொருவர் குற்றச்சாட்டுகளைத் திருப்பிக் கூறிக்கொள்வதை (நீர் காண்பீர்)! எவர்கள் பலவீனர்களாகக் கருதப்பட்டார்களோ அவர்கள்) - இது பின் தொடர்பவர்களைக் குறிக்கிறது --<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">اسْتَكْبَرُواْ</span><br />\r\n<br />\r\nபெருமையடித்துக் கொண்டிருந்தவர்களிடம் - இது தலைவர்களையும் எஜமானர்களையும் குறிக்கிறது --<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَوْلاَ</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">لَكُنَّا</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنِينَ</span><br />\r\n<br />\r\n(“நீங்கள் மட்டும் இல்லையென்றால், நாங்கள் நிச்சயமாக நம்பிக்கை கொண்டவர்களாக (முஃமின்களாக) இருந்திருப்போம்!” எனக் கூறுவார்கள்.) அதாவது, \"நீங்கள் எங்களைத் தடுத்திருக்காவிட்டால், நாங்கள் தூதர்களைப் பின்பற்றி அவர்கள் கொண்டு வந்ததை நம்பியிருப்போம்\" என்பதாகும். பெருமையடித்துக் கொண்டிருந்த அவர்களின் தலைவர்களும் எஜமானர்களும் அவர்களிடம் கூறுவார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَنَحْنُ</span> <span class=\"quran-arabic-font text-success\">صَدَدْنَاكُمْ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">الْهُدَى</span> <span class=\"quran-arabic-font text-success\">بَعْدَ</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">جَآءَكُمْ</span><br />\r\n<br />\r\n(“நேர்வழி உங்களிடம் வந்த பிறகு, அதிலிருந்து நாமா உங்களைத் தடுத்தோம்?”) அதாவது, “நாங்கள் உங்களை (வழிகேட்டின் பக்கம்) அழைத்ததைத் தவிர வேறெதுவும் செய்யவில்லை. நீங்களோ எந்த ஆதாரமும் சான்றும் இன்றி எங்களைப் பின்தொடர்ந்தீர்கள். உங்கள் சுய இச்சைகளின் காரணமாகவே, தூதர்கள் கொண்டு வந்த அத்தாட்சிகளுக்கும் ஆதாரங்களுக்கும் எதிராகச் சென்றீர்கள்; அது உங்கள் சொந்தத் தேர்வாகும்.” அவர்கள் கூறுவார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">مُّجْرِمِينَ</span><br />\r\n<br />\r\n(“...இல்லை, நீங்களே குற்றவாளிகளாக இருந்தீர்கள்.”)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">اسْتُضْعِفُواْ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">اسْتَكْبَرُواْ</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">مَكْرُ</span> <span class=\"quran-arabic-font text-success\">الَّيْلِ</span> <span class=\"quran-arabic-font text-success\">وَالنَّهَارِ</span><br />\r\n<br />\r\nபலவீனர்களாகக் கருதப்பட்டவர்கள் பெருமையடித்துக் கொண்டிருந்தவர்களிடம் கூறுவார்கள்: “அப்படியல்ல! இரவும் பகலும் நீங்கள் செய்த சூழ்ச்சிகளே (எங்களை வீழ்த்தின)...”) அதாவது, “நீங்கள் இரவும் பகலும் எங்களுக்கு எதிராகச் சதி செய்தீர்கள். போலியான வாக்குறுதிகள் மற்றும் ஆசைகளைக் காட்டி எங்களை மருட்டினீர்கள். நாங்கள் தான் உண்மையான நேர்வழியில் இருப்பதாகவும், ஏதோ ஒரு சரியான பாதையைப் பின்பற்றுவதாகவும் எங்களிடம் கூறினீர்கள். ஆனால் அவை அனைத்தும் வெறும் பொய்களும் அப்பட்டமான புரட்டுகளுமே ஆகும்.” கதாதா மற்றும் இப்னு ஸைத் ஆகியோர் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">مَكْرُ</span> <span class=\"quran-arabic-font text-success\">الَّيْلِ</span> <span class=\"quran-arabic-font text-success\">وَالنَّهَارِ</span><br />\r\n<br />\r\n(இல்லை, அது உங்களின் இரவும் பகலுமான சூழ்ச்சியாக இருந்தது) என்பதன் பொருள், “நீங்கள் இரவும் பகலும் சூழ்ச்சி செய்தீர்கள்” என்பதாகும். மாலிக் அவர்கள், ஸைத் பின் அஸ்லம் அவர்களிடமிருந்து இது போன்ற ஒரு கருத்தை அறிவித்துள்ளார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">تَأْمُرُونَنَآ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">نَّكْفُرَ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَنَجْعَلَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">أَندَاداً</span><br />\r\n<br />\r\n(அல்லாஹ்வை நாங்கள் நிராகரிக்க வேண்டும் என்றும், அவனுக்கு இணைகளை ஏற்படுத்த வேண்டும் என்றும் நீங்கள் எங்களுக்குக் கட்டளையிட்ட போது!) அதாவது, அல்லாஹ்வுக்கு நிகராகத் தெய்வங்களை ஏற்படுத்துமாறும், எங்கள் மனங்களில் சந்தேகங்களையும் குழப்பங்களையும் நீங்கள் உருவாக்கினீர்கள். எங்களை வழிதவறச் செய்வதற்காகத் தர்க்கத்திற்கு அப்பாற்பட்ட கற்பனையான கருத்துகளைப் புனைந்துரைத்தீர்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَسَرُّواْ</span> <span class=\"quran-arabic-font text-success\">النَّدَامَةَ</span> <span class=\"quran-arabic-font text-success\">لَمَّا</span> <span class=\"quran-arabic-font text-success\">رَأَوُاْ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابَ</span><br />\r\n<br />\r\n(அவர்கள் வேதனையைக் காணும்போது, தங்கள் வருத்தங்களை மறைத்துக் கொள்வார்கள்.) அதாவது, தலைவர்கள் மற்றும் அவர்களைப் பின்பற்றியவர்கள் என இரு சாராரும் தாங்கள் முன்னர் செய்த செயல்களுக்காகப் பெரிதும் வருந்துவார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">الاٌّغْلَـلَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">أَعْنَاقِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span><br />\r\n<br />\r\n(நிராகரிப்பவர்களின் கழுத்துகளில் நாம் இரும்பு விலங்குகளை மாட்டுவோம்.) இது அவர்களின் கைகளைக் கழுத்துடன் சேர்த்துப் பிணைக்கக்கூடிய சங்கிலியாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">يُجْزَوْنَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُونَ</span><br />\r\n<br />\r\n(அவர்கள் செய்துகொண்டிருந்ததைத் தவிர வேறு எதற்காவது அவர்கள் கூலி வழங்கப்படுவார்களா?) அதாவது, அவர்கள் தங்களின் செயல்களுக்கு ஏற்பவே தண்டிக்கப்படுவார்கள். தலைவர்கள் அவர்கள் செய்தவற்றுக்கு ஏற்பவும், அவர்களைப் பின்பற்றியவர்கள் அவர்கள் செய்தவற்றுக்கு ஏற்பவும் தண்டிக்கப்படுவார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">لِكُلٍّ</span> <span class=\"quran-arabic-font text-success\">ضِعْفٌ</span> <span class=\"quran-arabic-font text-success\">وَلَـكِن</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُونَ</span><br />\r\n<br />\r\n(அவன் கூறுவான்: “ஒவ்வொருவருக்கும் இரட்டிப்பு (வேதனை) உண்டு, ஆனால் நீங்கள் அதனை அறிய மாட்டீர்கள்.”) (<a href=\"qurandisp.php?sura=7&ayah=38\" class=\"link\">7:38</a>). இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ ஹுரைரா (ரழி) அவர்கள் கூறினார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">لَمَّا</span> <span class=\"quran-arabic-font text-success\">سِيقَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهَا</span> <span class=\"quran-arabic-font text-success\">أَهْلُهَا</span> <span class=\"quran-arabic-font text-success\">تَلَقَّاهُمْ</span> <span class=\"quran-arabic-font text-success\">لَهَبُهَا،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لَفَحَتْهُمْ</span> <span class=\"quran-arabic-font text-success\">لَفْحَةً</span> <span class=\"quran-arabic-font text-success\">فَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَبْقَ</span> <span class=\"quran-arabic-font text-success\">لَحْمٌ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">سَقَطَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْعُرْقُوب</span>»<br />\r\n<br />\r\n(நரகவாசிகள் நரகத்தை நோக்கி ஓட்டிச் செல்லப்படும்போது, அதன் ஜுவாலைகள் அவர்களை எதிர்கொள்ளும். பின்னர், அந்த நெருப்பு அவர்களின் முகங்களை ஒருமுறை பொசுக்கும்போது, உடலில் உள்ள சதை அனைத்தும் அவர்களின் குதிக்கால்கள் வரை உதிர்ந்து விழுந்துவிடும்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قَرْيَةٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">نَّذِيرٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">مُتْرَفُوهَآ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">بِمَآ</span> <span class=\"quran-arabic-font text-success\">أُرْسِلْتُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">كَـفِرُونَ</span> - <span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">أَكْثَـرُ</span> <span class=\"quran-arabic-font text-success\">أَمْوَلاً</span> <span class=\"quran-arabic-font text-success\">وَأَوْلَـداً</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">بِمُعَذَّبِينَ</span> - <span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">رَبِّى</span> <span class=\"quran-arabic-font text-success\">يَبْسُطُ</span> <span class=\"quran-arabic-font text-success\">الرِّزْقَ</span> <span class=\"quran-arabic-font text-success\">لِمَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span> <span class=\"quran-arabic-font text-success\">وَيَقْدِرُ</span> <span class=\"quran-arabic-font text-success\">وَلَـكِنَّ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ</span> - <span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَمْوَلُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَوْلَـدُكُمْ</span> <span class=\"quran-arabic-font text-success\">بِالَّتِى</span> <span class=\"quran-arabic-font text-success\">تُقَرِّبُكُمْ</span> <span class=\"quran-arabic-font text-success\">عِندَنَا</span> <span class=\"quran-arabic-font text-success\">زُلْفَى</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">ءَامَنَ</span> <span class=\"quran-arabic-font text-success\">وَعَمِلَ</span> <span class=\"quran-arabic-font text-success\">صَـلِحاً</span> <span class=\"quran-arabic-font text-success\">فَأُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">جَزَآءُ</span> <span class=\"quran-arabic-font text-success\">الضِّعْفِ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">عَمِلُواْ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْغُرُفَـتِ</span> <span class=\"quran-arabic-font text-success\">ءَامِنُونَ</span> - <span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَسْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ءَايَـتِنَا</span> <span class=\"quran-arabic-font text-success\">مُعَـجِزِينَ</span> <span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">مُحْضَرُونَ</span><br />\r\n<br />","text":"உண்மையை மறுப்பதில் நிராகரிப்பாளர்கள் இவ்வுலகில் எவ்வாறு ஒன்றுபட்டிருந்தார்கள் என்பதும், மறுமை நாளில் அவர்கள் ஒருவருக்கொருவர் எவ்வாறு தர்க்கம் செய்துகொள்வார்கள் என்பதும்\n\r\n\n\r\n\n\r\n\n\r\nநிராகரிப்பாளர்களின் எல்லைமீறிய அநியாயம், பிடிவாதம் மற்றும் திருக்குர்ஆனையும், அது மறுமை நாளைப் பற்றி அவர்களுக்குக் கூறுவதையும் நம்ப மறுக்கும் அவர்களின் பிடிவாதம் குறித்து அல்லாஹ் நமக்குக் கூறுகிறான். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَقَالَ الَّذِينَ كَفَرُواْ لَن نُّؤْمِنَ بِهَـذَا الْقُرْءَانِ وَلاَ بِالَّذِى بَيْنَ يَدَيْهِ\n\r\n\n\r\n(“இந்தக் குர்ஆனையும், இதற்கு முன்னிருந்தவற்றையும் நாங்கள் ஒருபோதும் நம்ப மாட்டோம்” என்று நிராகரிப்பாளர்கள் கூறுகின்றனர்.) அல்லாஹ் அவர்களை அச்சுறுத்துகிறான். மேலும், தனக்கு முன்பாக அவர்கள் ஒருவருக்கொருவர் தர்க்கம் செய்து விவாதித்துக் கொண்டு நிற்கும் இழிவான நிலையைப் பற்றி அவர்களை எச்சரிக்கிறான்:\n\r\n\n\r\nوَلَوْ تَرَى إِذِ الظَّـلِمُونَ مَوْقُوفُونَ عِندَ رَبِّهِمْ\n\r\n\n\r\nيَرْجِعُ بَعْضُهُمْ إِلَى بَعْضٍ الْقَوْلَ يَقُولُ الَّذِينَ اسْتُضْعِفُواْ\n\r\n\n\r\n(அவர்கள் ஒருவருக்கொருவர் குற்றச்சாட்டுகளைத் திருப்பிக் கூறிக்கொள்வதை (நீர் காண்பீர்)! எவர்கள் பலவீனர்களாகக் கருதப்பட்டார்களோ அவர்கள்) - இது பின் தொடர்பவர்களைக் குறிக்கிறது --\n\r\n\n\r\nلِلَّذِينَ اسْتَكْبَرُواْ\n\r\n\n\r\nபெருமையடித்துக் கொண்டிருந்தவர்களிடம் - இது தலைவர்களையும் எஜமானர்களையும் குறிக்கிறது --\n\r\n\n\r\nلَوْلاَ أَنتُمْ لَكُنَّا مُؤْمِنِينَ\n\r\n\n\r\n(“நீங்கள் மட்டும் இல்லையென்றால், நாங்கள் நிச்சயமாக நம்பிக்கை கொண்டவர்களாக (முஃமின்களாக) இருந்திருப்போம்!” எனக் கூறுவார்கள்.) அதாவது, \"நீங்கள் எங்களைத் தடுத்திருக்காவிட்டால், நாங்கள் தூதர்களைப் பின்பற்றி அவர்கள் கொண்டு வந்ததை நம்பியிருப்போம்\" என்பதாகும். பெருமையடித்துக் கொண்டிருந்த அவர்களின் தலைவர்களும் எஜமானர்களும் அவர்களிடம் கூறுவார்கள்:\n\r\n\n\r\nأَنَحْنُ صَدَدْنَاكُمْ عَنِ الْهُدَى بَعْدَ إِذْ جَآءَكُمْ\n\r\n\n\r\n(“நேர்வழி உங்களிடம் வந்த பிறகு, அதிலிருந்து நாமா உங்களைத் தடுத்தோம்?”) அதாவது, “நாங்கள் உங்களை (வழிகேட்டின் பக்கம்) அழைத்ததைத் தவிர வேறெதுவும் செய்யவில்லை. நீங்களோ எந்த ஆதாரமும் சான்றும் இன்றி எங்களைப் பின்தொடர்ந்தீர்கள். உங்கள் சுய இச்சைகளின் காரணமாகவே, தூதர்கள் கொண்டு வந்த அத்தாட்சிகளுக்கும் ஆதாரங்களுக்கும் எதிராகச் சென்றீர்கள்; அது உங்கள் சொந்தத் தேர்வாகும்.” அவர்கள் கூறுவார்கள்:\n\r\n\n\r\nبَلْ كُنتُمْ مُّجْرِمِينَ\n\r\n\n\r\n(“...இல்லை, நீங்களே குற்றவாளிகளாக இருந்தீர்கள்.”)\n\r\n\n\r\nوَقَالَ الَّذِينَ اسْتُضْعِفُواْ لِلَّذِينَ اسْتَكْبَرُواْ بَلْ مَكْرُ الَّيْلِ وَالنَّهَارِ\n\r\n\n\r\nபலவீனர்களாகக் கருதப்பட்டவர்கள் பெருமையடித்துக் கொண்டிருந்தவர்களிடம் கூறுவார்கள்: “அப்படியல்ல! இரவும் பகலும் நீங்கள் செய்த சூழ்ச்சிகளே (எங்களை வீழ்த்தின)...”) அதாவது, “நீங்கள் இரவும் பகலும் எங்களுக்கு எதிராகச் சதி செய்தீர்கள். போலியான வாக்குறுதிகள் மற்றும் ஆசைகளைக் காட்டி எங்களை மருட்டினீர்கள். நாங்கள் தான் உண்மையான நேர்வழியில் இருப்பதாகவும், ஏதோ ஒரு சரியான பாதையைப் பின்பற்றுவதாகவும் எங்களிடம் கூறினீர்கள். ஆனால் அவை அனைத்தும் வெறும் பொய்களும் அப்பட்டமான புரட்டுகளுமே ஆகும்.” கதாதா மற்றும் இப்னு ஸைத் ஆகியோர் கூறினார்கள்:\n\r\n\n\r\nبَلْ مَكْرُ الَّيْلِ وَالنَّهَارِ\n\r\n\n\r\n(இல்லை, அது உங்களின் இரவும் பகலுமான சூழ்ச்சியாக இருந்தது) என்பதன் பொருள், “நீங்கள் இரவும் பகலும் சூழ்ச்சி செய்தீர்கள்” என்பதாகும். மாலிக் அவர்கள், ஸைத் பின் அஸ்லம் அவர்களிடமிருந்து இது போன்ற ஒரு கருத்தை அறிவித்துள்ளார்கள்.\n\r\n\n\r\nإِذْ تَأْمُرُونَنَآ أَن نَّكْفُرَ بِاللَّهِ وَنَجْعَلَ لَهُ أَندَاداً\n\r\n\n\r\n(அல்லாஹ்வை நாங்கள் நிராகரிக்க வேண்டும் என்றும், அவனுக்கு இணைகளை ஏற்படுத்த வேண்டும் என்றும் நீங்கள் எங்களுக்குக் கட்டளையிட்ட போது!) அதாவது, அல்லாஹ்வுக்கு நிகராகத் தெய்வங்களை ஏற்படுத்துமாறும், எங்கள் மனங்களில் சந்தேகங்களையும் குழப்பங்களையும் நீங்கள் உருவாக்கினீர்கள். எங்களை வழிதவறச் செய்வதற்காகத் தர்க்கத்திற்கு அப்பாற்பட்ட கற்பனையான கருத்துகளைப் புனைந்துரைத்தீர்கள்.\n\r\n\n\r\nوَأَسَرُّواْ النَّدَامَةَ لَمَّا رَأَوُاْ الْعَذَابَ\n\r\n\n\r\n(அவர்கள் வேதனையைக் காணும்போது, தங்கள் வருத்தங்களை மறைத்துக் கொள்வார்கள்.) அதாவது, தலைவர்கள் மற்றும் அவர்களைப் பின்பற்றியவர்கள் என இரு சாராரும் தாங்கள் முன்னர் செய்த செயல்களுக்காகப் பெரிதும் வருந்துவார்கள்.\n\r\n\n\r\nوَجَعَلْنَا الاٌّغْلَـلَ فِى أَعْنَاقِ الَّذِينَ كَفَرُواْ\n\r\n\n\r\n(நிராகரிப்பவர்களின் கழுத்துகளில் நாம் இரும்பு விலங்குகளை மாட்டுவோம்.) இது அவர்களின் கைகளைக் கழுத்துடன் சேர்த்துப் பிணைக்கக்கூடிய சங்கிலியாகும்.\n\r\n\n\r\nهَلْ يُجْزَوْنَ إِلاَّ مَا كَانُواْ يَعْمَلُونَ\n\r\n\n\r\n(அவர்கள் செய்துகொண்டிருந்ததைத் தவிர வேறு எதற்காவது அவர்கள் கூலி வழங்கப்படுவார்களா?) அதாவது, அவர்கள் தங்களின் செயல்களுக்கு ஏற்பவே தண்டிக்கப்படுவார்கள். தலைவர்கள் அவர்கள் செய்தவற்றுக்கு ஏற்பவும், அவர்களைப் பின்பற்றியவர்கள் அவர்கள் செய்தவற்றுக்கு ஏற்பவும் தண்டிக்கப்படுவார்கள்.\n\r\n\n\r\nقَالَ لِكُلٍّ ضِعْفٌ وَلَـكِن لاَّ تَعْلَمُونَ\n\r\n\n\r\n(அவன் கூறுவான்: “ஒவ்வொருவருக்கும் இரட்டிப்பு (வேதனை) உண்டு, ஆனால் நீங்கள் அதனை அறிய மாட்டீர்கள்.”) (7:38). இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ ஹுரைரா (ரழி) அவர்கள் கூறினார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ جَهَنَّمَ لَمَّا سِيقَ إِلَيْهَا أَهْلُهَا تَلَقَّاهُمْ لَهَبُهَا، ثُمَّ لَفَحَتْهُمْ لَفْحَةً فَلَمْ يَبْقَ لَحْمٌ إِلَّا سَقَطَ عَلَى الْعُرْقُوب»\n\r\n\n\r\n(நரகவாசிகள் நரகத்தை நோக்கி ஓட்டிச் செல்லப்படும்போது, அதன் ஜுவாலைகள் அவர்களை எதிர்கொள்ளும். பின்னர், அந்த நெருப்பு அவர்களின் முகங்களை ஒருமுறை பொசுக்கும்போது, உடலில் உள்ள சதை அனைத்தும் அவர்களின் குதிக்கால்கள் வரை உதிர்ந்து விழுந்துவிடும்.)\n\r\n\n\r\nوَمَآ أَرْسَلْنَا فِى قَرْيَةٍ مِّن نَّذِيرٍ إِلاَّ قَالَ مُتْرَفُوهَآ إِنَّا بِمَآ أُرْسِلْتُمْ بِهِ كَـفِرُونَ - وَقَالُواْ نَحْنُ أَكْثَـرُ أَمْوَلاً وَأَوْلَـداً وَمَا نَحْنُ بِمُعَذَّبِينَ - قُلْ إِنَّ رَبِّى يَبْسُطُ الرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ وَلَـكِنَّ أَكْثَرَ النَّاسِ لاَ يَعْلَمُونَ - وَمَآ أَمْوَلُكُمْ وَلاَ أَوْلَـدُكُمْ بِالَّتِى تُقَرِّبُكُمْ عِندَنَا زُلْفَى إِلاَّ مَنْ ءَامَنَ وَعَمِلَ صَـلِحاً فَأُوْلَـئِكَ لَهُمْ جَزَآءُ الضِّعْفِ بِمَا عَمِلُواْ وَهُمْ فِى الْغُرُفَـتِ ءَامِنُونَ - وَالَّذِينَ يَسْعَوْنَ فِى ءَايَـتِنَا مُعَـجِزِينَ أُوْلَـئِكَ فِى الْعَذَابِ مُحْضَرُونَ"},"34":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=38\" class=\"link\">34:38</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:38 ஐ பார்க்கவும்"},"35":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=38\" class=\"link\">34:38</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:38 ஐ பார்க்கவும்"},"36":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=38\" class=\"link\">34:38</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:38 ஐ பார்க்கவும்"},"37":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=38\" class=\"link\">34:38</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:38 ஐ பார்க்கவும்"},"38":{"html":"<strong>ஆடம்பர வாழ்க்கை வாழ்ந்தவர்கள் எவ்வாறு தூதர்களை நிராகரித்தார்கள் மற்றும் செல்வம், பிள்ளைகள் மீதான மோகத்தால் எவ்வாறு வழிதவறினார்கள்</strong><br />\r\n<br />\r\nஅல்லாஹ் தனது தூதருக்கு (ஸல்) ஆறுதல் கூறுகிறான்; மேலும் அவருக்கு முன் வந்த தூதர்களின் முன்மாதிரியைப் பின்பற்றுமாறு கட்டளையிடுகிறான். எந்த ஓர் ஊருக்கு ஒரு நபி அனுப்பப்பட்டாலும், அங்கிருந்த ஆடம்பர வாழ்க்கை வாழ்ந்தவர்கள் அவரை நிராகரிக்காமல் இருந்ததில்லை; மாறாக, அந்த ஊரின் பலவீனமான மக்களே அவரைப் பின்பற்றினார்கள் என்று அவன் கூறுகிறான். நூஹ் (அலை) அவர்களின் சமூகத்தினர் அவர்களிடம் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَنُؤْمِنُ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">وَاتَّبَعَكَ</span> <span class=\"quran-arabic-font text-success\">الْأَرْذَلُونَ</span><br />\r\n<br />\r\n\"(மக்களில்) மிகவும் தாழ்ந்தவர்கள் உங்களைப் பின்பற்றும் நிலையில், நாங்கள் உங்களை ஈமான் கொள்வோமா?\" (<a href=\"qurandisp.php?sura=26&ayah=111\" class=\"link\">26:111</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">نَرَاكَ</span> <span class=\"quran-arabic-font text-success\">اتَّبَعَكَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">أَرَاذِلُنَا</span> <span class=\"quran-arabic-font text-success\">بَادِىَ</span> <span class=\"quran-arabic-font text-success\">الرَّأْى</span><br />\r\n<br />\r\n\"எங்களில் மிகவும் தாழ்ந்தவர்களைத் தவிர வேறு யாரும் உங்களைப் பின்பற்றுவதை நாங்கள் காணவில்லை; அவர்களும் கூட ஆழமாகச் சிந்திக்காமலே உங்களைப் பின்பற்றினார்கள்.\" (<a href=\"qurandisp.php?sura=11&ayah=27\" class=\"link\">11:27</a>). ஸாலிஹ் (அலை) அவர்களின் சமூகத்திலிருந்த தலைவர்கள், அவர்களில் ஈமான் கொண்ட பலவீனமான மக்களிடம் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">الْمَلأ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">اسْتَكْبَرُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَوْمِهِ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">اسْتُضْعِفُواْ</span> <span class=\"quran-arabic-font text-success\">لِمَنْ</span> <span class=\"quran-arabic-font text-success\">ءَامَنَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">أَتَعْلَمُونَ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">صَـلِحاً</span> <span class=\"quran-arabic-font text-success\">مُّرْسَلٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّبِّهِ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">بِمَآ</span> <span class=\"quran-arabic-font text-success\">أُرْسِلَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنُونَ</span> - <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">اسْتَكْبَرُواْ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">بِالَّذِى</span> <span class=\"quran-arabic-font text-success\">ءَامَنتُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">كَـفِرُونَ</span><br />\r\n<br />\r\n(பலவீனமானவர்களாகக் கருதப்பட்டவர்களில் ஈமான் கொண்டவர்களிடம்: \"நிச்சயமாக ஸாலிஹ் தம் இறைவனால் அனுப்பப்பட்ட தூதர் என்று நீங்கள் அறிகிறீர்களா?\" எனக் கேட்டனர். அதற்கு அவர்கள்: \"நிச்சயமாக அவர் எதைக் கொண்டு அனுப்பப்பட்டாரோ, அதையே நாங்கள் ஈமான் கொள்கிறோம்\" என்று கூறினர். அதற்குப் பெருமையடித்தவர்கள்: \"நிச்சயமாக நீங்கள் எதை ஈமான் கொள்கிறீர்களோ, அதை நாங்கள் நிராகரிக்கிறோம்\" என்று கூறினர்.) (<a href=\"qurandisp.php?sura=7&ayah=75\" class=\"link\">7:75</a>-76). மேலும் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَذلِكَ</span> <span class=\"quran-arabic-font text-success\">فَتَنَّا</span> <span class=\"quran-arabic-font text-success\">بَعْضَهُمْ</span> <span class=\"quran-arabic-font text-success\">بِبَعْضٍ</span> <span class=\"quran-arabic-font text-success\">لِّيَقُولواْ</span> <span class=\"quran-arabic-font text-success\">أَهَـؤُلاءِ</span> <span class=\"quran-arabic-font text-success\">مَنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">بَيْنِنَآ</span> <span class=\"quran-arabic-font text-success\">أَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">بِأَعْلَمَ</span> <span class=\"quran-arabic-font text-success\">بِالشَّـكِرِينَ</span><br />\r\n<br />\r\n(\"இவ்வாறே, அவர்களில் சிலரை மற்றவர்களைக் கொண்டு நாம் சோதித்தோம்; 'நமக்கு இடையில் அல்லாஹ் அருள் புரிந்தது இவர்களுக்கா (இந்த ஏழை முஃமின்களுக்கா)?' என்று அவர்கள் கேட்பதற்காக. நன்றியுள்ளவர்களை அல்லாஹ் மிக அறிந்தவன் அல்லவா?\") (<a href=\"qurandisp.php?sura=6&ayah=53\" class=\"link\">6:53</a>),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَذلِكَ</span> <span class=\"quran-arabic-font text-success\">جَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">قَرْيَةٍ</span> <span class=\"quran-arabic-font text-success\">أَكَابِرَ</span> <span class=\"quran-arabic-font text-success\">مُجْرِمِيهَا</span> <span class=\"quran-arabic-font text-success\">لِيَمْكُرُواْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span><br />\r\n<br />\r\n(\"இவ்வாறே ஒவ்வொரு ஊரிலும் சதி செய்வதற்காக, அதன் குற்றவாளிகளில் பெரியவர்களை நாம் ஏற்படுத்தினோம்.\") (<a href=\"qurandisp.php?sura=6&ayah=123\" class=\"link\">6:123</a>), மேலும்<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذَآ</span> <span class=\"quran-arabic-font text-success\">أَرَدْنَآ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">نُّهْلِكَ</span> <span class=\"quran-arabic-font text-success\">قَرْيَةً</span> <span class=\"quran-arabic-font text-success\">أَمَرْنَا</span> <span class=\"quran-arabic-font text-success\">مُتْرَفِيهَا</span> <span class=\"quran-arabic-font text-success\">فَفَسَقُواْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">فَحَقَّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَا</span> <span class=\"quran-arabic-font text-success\">الْقَوْلُ</span> <span class=\"quran-arabic-font text-success\">فَدَمَّرْنَاهَا</span> <span class=\"quran-arabic-font text-success\">تَدْمِيرًا</span><br />\r\n<br />\r\n(\"நாம் ஓர் ஊரை அழிக்க நாடினால், அங்கிருந்த ஆடம்பர வாழ்க்கை வாழ்ந்தவர்களுக்கு (கீழ்ப்படியுமாறு) கட்டளையிடுவோம். ஆனால் அவர்கள் அதில் வரம்பு மீறி நடப்பார்கள்; அப்போது அந்த ஊரின் மீது நமது தீர்ப்பு உறுதியாகிவிடும்; பின்னர் நாம் அதனை அடியோடு அழித்துவிடுவோம்.\") (<a href=\"qurandisp.php?sura=17&ayah=16\" class=\"link\">17:16</a>). இங்கு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قَرْيَةٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">نَّذِيرٍ</span><br />\r\n<br />\r\nநாம் எந்த ஓர் ஊருக்கும் ஓர் எச்சரிக்கையாளரை அனுப்பவில்லை - அதாவது ஒரு நபியையோ அல்லது ஒரு தூதரையோ -<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">مُتْرَفُوهَآ</span><br />\r\n<br />\r\n(அங்கிருந்த ஆடம்பர சுகபோகங்களை அனுபவித்தவர்கள் கூறாமல் இருந்ததில்லை) அதாவது, செல்வம், செல்வாக்கு மற்றும் தலைமைப் பதவிகளில் இருப்பவர்கள். கதாதா (ரஹ்) கூறினார்கள், \"அவர்கள் அந்த ஊரின் கொடுங்கோலர்களும், தலைவர்களும், தீய வழிகாட்டுதல்களை வழங்குபவர்களும் ஆவர்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">بِمَآ</span> <span class=\"quran-arabic-font text-success\">أُرْسِلْتُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">كَـفِرُونَ</span><br />\r\n<br />\r\n(\"நிச்சயமாக நீங்கள் எதைக் கொண்டு அனுப்பப்பட்டீர்களோ, அதனை நாங்கள் நிராகரிக்கிறோம்.\") அதாவது, 'நாங்கள் அதனை நம்பமாட்டோம், பின்பற்றவும் மாட்டோம்.' தூதர்களை நிராகரித்த அந்த ஆடம்பரவாதிகள் இவ்வாறு கூறியதாக அல்லாஹ் நமக்குத் தெரிவிக்கிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">أَكْثَـرُ</span> <span class=\"quran-arabic-font text-success\">أَمْوَلاً</span> <span class=\"quran-arabic-font text-success\">وَأَوْلَـداً</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">بِمُعَذَّبِينَ</span><br />\r\n<br />\r\n(\"மேலும் அவர்கள் கூறினார்கள்: 'நாங்கள் செல்வத்திலும் பிள்ளைகளிலும் அதிகமுடையவர்கள்; நாங்கள் தண்டிக்கப்பட மாட்டோம்.'\") அதாவது, அவர்கள் தங்களின் அதிகப்படியான செல்வத்தையும் பிள்ளைகளையும் கண்டு பெருமை கொண்டனர். இது அல்லாஹ் தங்களை நேசிப்பதற்கும் தங்கள் மீது அக்கறை கொள்வதற்குமான அடையாளம் என்று அவர்கள் நம்பினார்கள். 'இந்த உலகிலேயே அல்லாஹ் எங்களுக்கு இவற்றை வழங்கியிருக்கும்போது, அவன் எங்களை மறுமையில் தண்டிக்க மாட்டான்' என்று அவர்கள் எண்ணினர். இது மிகவும் தவறான கற்பனையாகும். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَيَحْسَبُونَ</span> <span class=\"quran-arabic-font text-success\">أَنَّمَا</span> <span class=\"quran-arabic-font text-success\">نُمِدُّهُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مَّالٍ</span> <span class=\"quran-arabic-font text-success\">وَبَنِينَ</span> - <span class=\"quran-arabic-font text-success\">نُسَارِعُ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْخَيْرَتِ</span> <span class=\"quran-arabic-font text-success\">بَل</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَشْعُرُونَ</span><br />\r\n<br />\r\n(\"நாம் அவர்களுக்கு வழங்கும் செல்வம் மற்றும் பிள்ளைகளால், அவர்களுக்கு நன்மைகளை விரைவுபடுத்துகிறோம் என்று அவர்கள் நினைக்கிறார்களா? இல்லை, அவர்கள் (உண்மையை) உணரவில்லை.\") (<a href=\"qurandisp.php?sura=23&ayah=55\" class=\"link\">23:55</a>-56)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">تُعْجِبْكَ</span> <span class=\"quran-arabic-font text-success\">أَمْوَلُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَوْلَـدُهُمْ</span> <span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">يُرِيدُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لِيُعَذِّبَهُمْ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَتَزْهَقَ</span> <span class=\"quran-arabic-font text-success\">أَنفُسُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">كَـفِرُونَ</span><br />\r\n<br />\r\n(\"ஆகவே, அவர்களுடைய செல்வமும் அவர்களுடைய பிள்ளைகளும் உம்மை ஆச்சரியப்படுத்த வேண்டாம். உண்மையில், இவ்வுலக வாழ்க்கையிலேயே அவற்றின் மூலம் அவர்களைத் தண்டிக்கவும், அவர்கள் காஃபிர்களாக இருக்கும் நிலையிலேயே அவர்களுடைய உயிர் பிரியவுமே அல்லாஹ் நாடுகிறான்.\") (<a href=\"qurandisp.php?sura=9&ayah=55\" class=\"link\">9:55</a>), மேலும்<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَرْنِى</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">خَلَقْتُ</span> <span class=\"quran-arabic-font text-success\">وَحِيداً</span> - <span class=\"quran-arabic-font text-success\">وَجَعَلْتُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مَالاً</span> <span class=\"quran-arabic-font text-success\">مَّمْدُوداً</span> - <span class=\"quran-arabic-font text-success\">وَبَنِينَ</span> <span class=\"quran-arabic-font text-success\">شُهُوداً</span> - <span class=\"quran-arabic-font text-success\">وَمَهَّدتُّ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">تَمْهِيداً</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يَطْمَعُ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">أَزِيدَ</span> - <span class=\"quran-arabic-font text-success\">كَلاَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">لِآيَاتِنَا</span> <span class=\"quran-arabic-font text-success\">عَنِيداً</span> - <span class=\"quran-arabic-font text-success\">سَأُرْهِقُهُ</span> <span class=\"quran-arabic-font text-success\">صَعُوداً</span><br />\r\n<br />\r\n(\"எவனை நான் தனியாகப் படைத்தேனோ, அவனுடன் என்னை விட்டுவிடுவீராக! அவனுக்கு நான் தாராளமான செல்வத்தை வழங்கினேன். எப்போதும் அவனுடன் இருக்கக்கூடிய பிள்ளைகளையும் வழங்கினேன். அவனுக்கு வாழ்க்கையை மிக வசதியாகவும் ஆக்கினேன். இவ்வளவு இருந்தும், நான் இன்னும் அதிகமாகக் கொடுக்க வேண்டும் என்று அவன் ஆசைப்படுகிறான். அவ்வாறல்ல! நிச்சயமாக அவன் நமது வசனங்களை (ஆயத்துக்களை) பிடிவாதமாக எதிர்ப்பவனாய் இருந்தான். விரைவில் அவனை நான் ஏறுவதற்கு மிகக் கடினமான ஒரு வேதனையில் ஆழ்த்துவேன்.\") (<a href=\"qurandisp.php?sura=74&ayah=11\" class=\"link\">74:11</a>-17) மேலும், அந்த இரண்டு தோட்டங்களின் உரிமையாளரைப் பற்றியும் அல்லாஹ் நமக்குக் கூறியிருக்கிறான். அவனிடம் செல்வம், பயிர்கள் மற்றும் பிள்ளைகள் இருந்தன. ஆனால், மறுமையை அடைவதற்கு முன்பே, இந்த உலகிலேயே அவனிடமிருந்து அவை அனைத்தும் பறிக்கப்பட்டபோது, அவற்றுள் எதுவும் அவனுக்குப் பலன் அளிக்கவில்லை. அல்லாஹ் இங்கு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">رَبِّى</span> <span class=\"quran-arabic-font text-success\">يَبْسُطُ</span> <span class=\"quran-arabic-font text-success\">الرِّزْقَ</span> <span class=\"quran-arabic-font text-success\">لِمَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span> <span class=\"quran-arabic-font text-success\">وَيَقْدِرُ</span><br />\r\n<br />\r\n(கூறுவீராக: \"நிச்சயமாக எனது இறைவன் தான் நாடியவருக்கு வாழ்வாதாரத்தை விரிவாக்குகிறான்; (தான் நாடியவருக்கு) அதனைச் சுருக்கியும் விடுகிறான்.\") அதாவது, தான் நேசிப்பவர்களுக்கும் நேசிக்காதவர்களுக்கும் அவன் செல்வத்தை வழங்குகிறான். தான் நாடியவரை ஏழையாக்குகிறான், தான் நாடியவரைச் செல்வந்தனாக்குகிறான். அவனிடம் இது தொடர்பாக முழுமையான ஞானமும் தெளிவான அத்தாட்சியும் உள்ளன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَـكِنَّ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ</span><br />\r\n<br />\r\n(\"ஆனாலும் மனிதர்களில் பெரும்பாலானோர் இதனை அறிவதில்லை.\") பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَمْوَلُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَوْلَـدُكُمْ</span> <span class=\"quran-arabic-font text-success\">بِالَّتِى</span> <span class=\"quran-arabic-font text-success\">تُقَرِّبُكُمْ</span> <span class=\"quran-arabic-font text-success\">عِندَنَا</span> <span class=\"quran-arabic-font text-success\">زُلْفَى</span><br />\r\n<br />\r\n(\"உங்களுடைய செல்வமோ அல்லது உங்களுடைய பிள்ளைகளோ எம்மிடம் உங்களை நெருக்கமாக்கிவிடக் கூடியவை அல்ல.\") அதாவது, 'இவை நாம் உங்களை நேசிக்கிறோம் அல்லது உங்கள் மீது அக்கறை கொள்கிறோம் என்பதற்கான அடையாளங்கள் அல்ல.' இமாம் அஹ்மத் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَنْظُرُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">صُوَرِكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَمْوَالِكُمْ،</span> <span class=\"quran-arabic-font text-success\">وَلَكِنْ</span> <span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">يَنْظُرُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَعْمَالِكُم</span>»<br />\r\n<br />\r\n(\"நிச்சயமாக அல்லாஹ் உங்கள் உருவங்களையோ அல்லது உங்கள் செல்வங்களையோ பார்ப்பதில்லை; மாறாக அவன் உங்கள் இதயங்களையும் உங்கள் செயல்களையுமே பார்க்கிறான்.\") முஸ்லிம் மற்றும் இப்னு மாஜா ஆகியோரும் இதனைப் பதிவு செய்துள்ளனர். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">ءَامَنَ</span> <span class=\"quran-arabic-font text-success\">وَعَمِلَ</span> <span class=\"quran-arabic-font text-success\">صَـلِحاً</span><br />\r\n<br />\r\n(\"ஈமான் கொண்டு நற்செயல்களைச் செய்தவர்களைத் தவிர.\") அதாவது, 'ஈமானும் நற்செயல்களும் மட்டுமே உங்களை எம்மிடம் நெருக்கமாக்கும்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">جَزَآءُ</span> <span class=\"quran-arabic-font text-success\">الضِّعْفِ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">عَمِلُواْ</span><br />\r\n<br />\r\n(\"அத்தகையவர்களுக்கு அவர்கள் செய்தவற்றிற்காகப் பலமடங்கு நற்கூலி உண்டு.\") அதாவது, அவர்களுடைய கூலியானது பத்து முதல் எழுநூறு மடங்கு வரை அதிகப்படுத்தப்படும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْغُرُفَـتِ</span> <span class=\"quran-arabic-font text-success\">ءَامِنُونَ</span><br />\r\n<br />\r\n(\"அவர்கள் (சுவனத்தின்) உன்னதமான அறைகளில் நிம்மதியாக வசிப்பார்கள்.\") அதாவது, சொர்க்கத்தின் உயர்ந்த மாளிகைகளில் எல்லாவிதமான துக்கங்கள், பயம், துன்பங்கள் மற்றும் தாங்கள் அஞ்சக்கூடிய அனைத்துத் தீமைகளிலிருந்தும் பாதுகாப்பாக இருப்பார்கள். இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்கள்: அலி (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">لَغُرَفًا</span> <span class=\"quran-arabic-font text-success\">تُرَى</span> <span class=\"quran-arabic-font text-success\">ظُهُورُهَا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">بُطُونِهَا،</span> <span class=\"quran-arabic-font text-success\">وَبُطُونُهَا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">ظُهُورِهَا</span>»<br />\r\n<br />\r\n(\"நிச்சயமாகச் சொர்க்கத்தில் உயர்ந்த அறைகள் உள்ளன; அவற்றின் வெளிப்புறத்தை உட்புறத்திலிருந்தும், உட்புறத்தை வெளிப்புறத்திலிருந்தும் பார்க்கலாம்.\") ஒரு கிராமவாசி, \"அல்லாஹ்வின் தூதரே! அவை யாருக்காக?\" எனக் கேட்டார். அதற்கு அவர்கள் (ஸல்) கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لِمَنْ</span> <span class=\"quran-arabic-font text-success\">طَيَّبَ</span> <span class=\"quran-arabic-font text-success\">الْكَلَامَ،</span> <span class=\"quran-arabic-font text-success\">وَأَطْعَمَ</span> <span class=\"quran-arabic-font text-success\">الطَّعَامَ،</span> <span class=\"quran-arabic-font text-success\">وَأَدَامَ</span> <span class=\"quran-arabic-font text-success\">الصِّيَامَ،</span> <span class=\"quran-arabic-font text-success\">وَصَلَّى</span> <span class=\"quran-arabic-font text-success\">بِاللَّيْلِ</span> <span class=\"quran-arabic-font text-success\">وَالنَّاسُ</span> <span class=\"quran-arabic-font text-success\">نِيَام</span>»<br />\r\n<br />\r\n(\"இனிய சொற்களைப் பேசுபவர்களுக்கும், உணவளிப்பவர்களுக்கும், தொடர்ந்து நோன்பு நோற்பவர்களுக்கும், மக்கள் உறங்கிக் கொண்டிருக்கும்போது இரவில் எழுந்து தொழுபவர்களுக்கும் (அவை உரியவை).\")<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَسْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ءَايَـتِنَا</span> <span class=\"quran-arabic-font text-success\">مُعَـجِزِينَ</span><br />\r\n<br />\r\n(\"எவர்கள் நமது வசனங்களை (ஆயத்துக்களை) முறியடிக்க முயற்சி செய்கிறார்களோ,\") அதாவது, அல்லாஹ்வின் பாதையிலிருந்தும், அவனது தூதர்களைப் பின்பற்றுவதிலிருந்தும், அவனது சான்றுகளை ஈமான் கொள்வதிலிருந்தும் மக்களைத் தடுக்க முயற்சிப்பவர்கள்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">مُحْضَرُونَ</span><br />\r\n<br />\r\n(அவர்கள் வேதனையில் ஆஜர்படுத்தப்படுவார்கள்.) அதாவது, அவர்கள் அனைவரும் அவரவர் செயல்களுக்கு ஏற்பத் தண்டிக்கப்படுவார்கள்.<br />\r\n<br />","text":"ஆடம்பர வாழ்க்கை வாழ்ந்தவர்கள் எவ்வாறு தூதர்களை நிராகரித்தார்கள் மற்றும் செல்வம், பிள்ளைகள் மீதான மோகத்தால் எவ்வாறு வழிதவறினார்கள்\n\r\n\n\r\nஅல்லாஹ் தனது தூதருக்கு (ஸல்) ஆறுதல் கூறுகிறான்; மேலும் அவருக்கு முன் வந்த தூதர்களின் முன்மாதிரியைப் பின்பற்றுமாறு கட்டளையிடுகிறான். எந்த ஓர் ஊருக்கு ஒரு நபி அனுப்பப்பட்டாலும், அங்கிருந்த ஆடம்பர வாழ்க்கை வாழ்ந்தவர்கள் அவரை நிராகரிக்காமல் இருந்ததில்லை; மாறாக, அந்த ஊரின் பலவீனமான மக்களே அவரைப் பின்பற்றினார்கள் என்று அவன் கூறுகிறான். நூஹ் (அலை) அவர்களின் சமூகத்தினர் அவர்களிடம் கூறினார்கள்:\n\r\n\n\r\nأَنُؤْمِنُ لَكَ وَاتَّبَعَكَ الْأَرْذَلُونَ\n\r\n\n\r\n\"(மக்களில்) மிகவும் தாழ்ந்தவர்கள் உங்களைப் பின்பற்றும் நிலையில், நாங்கள் உங்களை ஈமான் கொள்வோமா?\" (26:111)\n\r\n\n\r\nوَمَا نَرَاكَ اتَّبَعَكَ إِلاَّ الَّذِينَ هُمْ أَرَاذِلُنَا بَادِىَ الرَّأْى\n\r\n\n\r\n\"எங்களில் மிகவும் தாழ்ந்தவர்களைத் தவிர வேறு யாரும் உங்களைப் பின்பற்றுவதை நாங்கள் காணவில்லை; அவர்களும் கூட ஆழமாகச் சிந்திக்காமலே உங்களைப் பின்பற்றினார்கள்.\" (11:27). ஸாலிஹ் (அலை) அவர்களின் சமூகத்திலிருந்த தலைவர்கள், அவர்களில் ஈமான் கொண்ட பலவீனமான மக்களிடம் கூறினார்கள்:\n\r\n\n\r\nقَالَ الْمَلأ الَّذِينَ اسْتَكْبَرُواْ مِن قَوْمِهِ لِلَّذِينَ اسْتُضْعِفُواْ لِمَنْ ءَامَنَ مِنْهُمْ أَتَعْلَمُونَ أَنَّ صَـلِحاً مُّرْسَلٌ مِّن رَّبِّهِ قَالُواْ إِنَّا بِمَآ أُرْسِلَ بِهِ مُؤْمِنُونَ - قَالَ الَّذِينَ اسْتَكْبَرُواْ إِنَّا بِالَّذِى ءَامَنتُمْ بِهِ كَـفِرُونَ\n\r\n\n\r\n(பலவீனமானவர்களாகக் கருதப்பட்டவர்களில் ஈமான் கொண்டவர்களிடம்: \"நிச்சயமாக ஸாலிஹ் தம் இறைவனால் அனுப்பப்பட்ட தூதர் என்று நீங்கள் அறிகிறீர்களா?\" எனக் கேட்டனர். அதற்கு அவர்கள்: \"நிச்சயமாக அவர் எதைக் கொண்டு அனுப்பப்பட்டாரோ, அதையே நாங்கள் ஈமான் கொள்கிறோம்\" என்று கூறினர். அதற்குப் பெருமையடித்தவர்கள்: \"நிச்சயமாக நீங்கள் எதை ஈமான் கொள்கிறீர்களோ, அதை நாங்கள் நிராகரிக்கிறோம்\" என்று கூறினர்.) (7:75-76). மேலும் அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَكَذلِكَ فَتَنَّا بَعْضَهُمْ بِبَعْضٍ لِّيَقُولواْ أَهَـؤُلاءِ مَنَّ اللَّهُ عَلَيْهِم مِّن بَيْنِنَآ أَلَيْسَ اللَّهُ بِأَعْلَمَ بِالشَّـكِرِينَ\n\r\n\n\r\n(\"இவ்வாறே, அவர்களில் சிலரை மற்றவர்களைக் கொண்டு நாம் சோதித்தோம்; 'நமக்கு இடையில் அல்லாஹ் அருள் புரிந்தது இவர்களுக்கா (இந்த ஏழை முஃமின்களுக்கா)?' என்று அவர்கள் கேட்பதற்காக. நன்றியுள்ளவர்களை அல்லாஹ் மிக அறிந்தவன் அல்லவா?\") (6:53),\n\r\n\n\r\nوَكَذلِكَ جَعَلْنَا فِي كُلِّ قَرْيَةٍ أَكَابِرَ مُجْرِمِيهَا لِيَمْكُرُواْ فِيهَا\n\r\n\n\r\n(\"இவ்வாறே ஒவ்வொரு ஊரிலும் சதி செய்வதற்காக, அதன் குற்றவாளிகளில் பெரியவர்களை நாம் ஏற்படுத்தினோம்.\") (6:123), மேலும்\n\r\n\n\r\nوَإِذَآ أَرَدْنَآ أَن نُّهْلِكَ قَرْيَةً أَمَرْنَا مُتْرَفِيهَا فَفَسَقُواْ فِيهَا فَحَقَّ عَلَيْهَا الْقَوْلُ فَدَمَّرْنَاهَا تَدْمِيرًا\n\r\n\n\r\n(\"நாம் ஓர் ஊரை அழிக்க நாடினால், அங்கிருந்த ஆடம்பர வாழ்க்கை வாழ்ந்தவர்களுக்கு (கீழ்ப்படியுமாறு) கட்டளையிடுவோம். ஆனால் அவர்கள் அதில் வரம்பு மீறி நடப்பார்கள்; அப்போது அந்த ஊரின் மீது நமது தீர்ப்பு உறுதியாகிவிடும்; பின்னர் நாம் அதனை அடியோடு அழித்துவிடுவோம்.\") (17:16). இங்கு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَمَآ أَرْسَلْنَا فِى قَرْيَةٍ مِّن نَّذِيرٍ\n\r\n\n\r\nநாம் எந்த ஓர் ஊருக்கும் ஓர் எச்சரிக்கையாளரை அனுப்பவில்லை - அதாவது ஒரு நபியையோ அல்லது ஒரு தூதரையோ -\n\r\n\n\r\nإِلاَّ قَالَ مُتْرَفُوهَآ\n\r\n\n\r\n(அங்கிருந்த ஆடம்பர சுகபோகங்களை அனுபவித்தவர்கள் கூறாமல் இருந்ததில்லை) அதாவது, செல்வம், செல்வாக்கு மற்றும் தலைமைப் பதவிகளில் இருப்பவர்கள். கதாதா (ரஹ்) கூறினார்கள், \"அவர்கள் அந்த ஊரின் கொடுங்கோலர்களும், தலைவர்களும், தீய வழிகாட்டுதல்களை வழங்குபவர்களும் ஆவர்.\"\n\r\n\n\r\nإِنَّا بِمَآ أُرْسِلْتُمْ بِهِ كَـفِرُونَ\n\r\n\n\r\n(\"நிச்சயமாக நீங்கள் எதைக் கொண்டு அனுப்பப்பட்டீர்களோ, அதனை நாங்கள் நிராகரிக்கிறோம்.\") அதாவது, 'நாங்கள் அதனை நம்பமாட்டோம், பின்பற்றவும் மாட்டோம்.' தூதர்களை நிராகரித்த அந்த ஆடம்பரவாதிகள் இவ்வாறு கூறியதாக அல்லாஹ் நமக்குத் தெரிவிக்கிறான்:\n\r\n\n\r\nوَقَالُواْ نَحْنُ أَكْثَـرُ أَمْوَلاً وَأَوْلَـداً وَمَا نَحْنُ بِمُعَذَّبِينَ\n\r\n\n\r\n(\"மேலும் அவர்கள் கூறினார்கள்: 'நாங்கள் செல்வத்திலும் பிள்ளைகளிலும் அதிகமுடையவர்கள்; நாங்கள் தண்டிக்கப்பட மாட்டோம்.'\") அதாவது, அவர்கள் தங்களின் அதிகப்படியான செல்வத்தையும் பிள்ளைகளையும் கண்டு பெருமை கொண்டனர். இது அல்லாஹ் தங்களை நேசிப்பதற்கும் தங்கள் மீது அக்கறை கொள்வதற்குமான அடையாளம் என்று அவர்கள் நம்பினார்கள். 'இந்த உலகிலேயே அல்லாஹ் எங்களுக்கு இவற்றை வழங்கியிருக்கும்போது, அவன் எங்களை மறுமையில் தண்டிக்க மாட்டான்' என்று அவர்கள் எண்ணினர். இது மிகவும் தவறான கற்பனையாகும். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَيَحْسَبُونَ أَنَّمَا نُمِدُّهُمْ بِهِ مِن مَّالٍ وَبَنِينَ - نُسَارِعُ لَهُمْ فِى الْخَيْرَتِ بَل لاَّ يَشْعُرُونَ\n\r\n\n\r\n(\"நாம் அவர்களுக்கு வழங்கும் செல்வம் மற்றும் பிள்ளைகளால், அவர்களுக்கு நன்மைகளை விரைவுபடுத்துகிறோம் என்று அவர்கள் நினைக்கிறார்களா? இல்லை, அவர்கள் (உண்மையை) உணரவில்லை.\") (23:55-56)\n\r\n\n\r\nفَلاَ تُعْجِبْكَ أَمْوَلُهُمْ وَلاَ أَوْلَـدُهُمْ إِنَّمَا يُرِيدُ اللَّهُ لِيُعَذِّبَهُمْ بِهَا فِي الْحَيَوةِ الدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَـفِرُونَ\n\r\n\n\r\n(\"ஆகவே, அவர்களுடைய செல்வமும் அவர்களுடைய பிள்ளைகளும் உம்மை ஆச்சரியப்படுத்த வேண்டாம். உண்மையில், இவ்வுலக வாழ்க்கையிலேயே அவற்றின் மூலம் அவர்களைத் தண்டிக்கவும், அவர்கள் காஃபிர்களாக இருக்கும் நிலையிலேயே அவர்களுடைய உயிர் பிரியவுமே அல்லாஹ் நாடுகிறான்.\") (9:55), மேலும்\n\r\n\n\r\nذَرْنِى وَمَنْ خَلَقْتُ وَحِيداً - وَجَعَلْتُ لَهُ مَالاً مَّمْدُوداً - وَبَنِينَ شُهُوداً - وَمَهَّدتُّ لَهُ تَمْهِيداً - ثُمَّ يَطْمَعُ أَنْ أَزِيدَ - كَلاَّ إِنَّهُ كَانَ لِآيَاتِنَا عَنِيداً - سَأُرْهِقُهُ صَعُوداً\n\r\n\n\r\n(\"எவனை நான் தனியாகப் படைத்தேனோ, அவனுடன் என்னை விட்டுவிடுவீராக! அவனுக்கு நான் தாராளமான செல்வத்தை வழங்கினேன். எப்போதும் அவனுடன் இருக்கக்கூடிய பிள்ளைகளையும் வழங்கினேன். அவனுக்கு வாழ்க்கையை மிக வசதியாகவும் ஆக்கினேன். இவ்வளவு இருந்தும், நான் இன்னும் அதிகமாகக் கொடுக்க வேண்டும் என்று அவன் ஆசைப்படுகிறான். அவ்வாறல்ல! நிச்சயமாக அவன் நமது வசனங்களை (ஆயத்துக்களை) பிடிவாதமாக எதிர்ப்பவனாய் இருந்தான். விரைவில் அவனை நான் ஏறுவதற்கு மிகக் கடினமான ஒரு வேதனையில் ஆழ்த்துவேன்.\") (74:11-17) மேலும், அந்த இரண்டு தோட்டங்களின் உரிமையாளரைப் பற்றியும் அல்லாஹ் நமக்குக் கூறியிருக்கிறான். அவனிடம் செல்வம், பயிர்கள் மற்றும் பிள்ளைகள் இருந்தன. ஆனால், மறுமையை அடைவதற்கு முன்பே, இந்த உலகிலேயே அவனிடமிருந்து அவை அனைத்தும் பறிக்கப்பட்டபோது, அவற்றுள் எதுவும் அவனுக்குப் பலன் அளிக்கவில்லை. அல்லாஹ் இங்கு கூறுகிறான்:\n\r\n\n\r\nقُلْ إِنَّ رَبِّى يَبْسُطُ الرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ\n\r\n\n\r\n(கூறுவீராக: \"நிச்சயமாக எனது இறைவன் தான் நாடியவருக்கு வாழ்வாதாரத்தை விரிவாக்குகிறான்; (தான் நாடியவருக்கு) அதனைச் சுருக்கியும் விடுகிறான்.\") அதாவது, தான் நேசிப்பவர்களுக்கும் நேசிக்காதவர்களுக்கும் அவன் செல்வத்தை வழங்குகிறான். தான் நாடியவரை ஏழையாக்குகிறான், தான் நாடியவரைச் செல்வந்தனாக்குகிறான். அவனிடம் இது தொடர்பாக முழுமையான ஞானமும் தெளிவான அத்தாட்சியும் உள்ளன.\n\r\n\n\r\nوَلَـكِنَّ أَكْثَرَ النَّاسِ لاَ يَعْلَمُونَ\n\r\n\n\r\n(\"ஆனாலும் மனிதர்களில் பெரும்பாலானோர் இதனை அறிவதில்லை.\") பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَمَآ أَمْوَلُكُمْ وَلاَ أَوْلَـدُكُمْ بِالَّتِى تُقَرِّبُكُمْ عِندَنَا زُلْفَى\n\r\n\n\r\n(\"உங்களுடைய செல்வமோ அல்லது உங்களுடைய பிள்ளைகளோ எம்மிடம் உங்களை நெருக்கமாக்கிவிடக் கூடியவை அல்ல.\") அதாவது, 'இவை நாம் உங்களை நேசிக்கிறோம் அல்லது உங்கள் மீது அக்கறை கொள்கிறோம் என்பதற்கான அடையாளங்கள் அல்ல.' இமாம் அஹ்மத் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ اللهَ تَعَالَى لَا يَنْظُرُ إِلَى صُوَرِكُمْ وَأَمْوَالِكُمْ، وَلَكِنْ إِنَّمَا يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُم»\n\r\n\n\r\n(\"நிச்சயமாக அல்லாஹ் உங்கள் உருவங்களையோ அல்லது உங்கள் செல்வங்களையோ பார்ப்பதில்லை; மாறாக அவன் உங்கள் இதயங்களையும் உங்கள் செயல்களையுமே பார்க்கிறான்.\") முஸ்லிம் மற்றும் இப்னு மாஜா ஆகியோரும் இதனைப் பதிவு செய்துள்ளனர். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nإِلاَّ مَنْ ءَامَنَ وَعَمِلَ صَـلِحاً\n\r\n\n\r\n(\"ஈமான் கொண்டு நற்செயல்களைச் செய்தவர்களைத் தவிர.\") அதாவது, 'ஈமானும் நற்செயல்களும் மட்டுமே உங்களை எம்மிடம் நெருக்கமாக்கும்.'\n\r\n\n\r\nفَأُوْلَـئِكَ لَهُمْ جَزَآءُ الضِّعْفِ بِمَا عَمِلُواْ\n\r\n\n\r\n(\"அத்தகையவர்களுக்கு அவர்கள் செய்தவற்றிற்காகப் பலமடங்கு நற்கூலி உண்டு.\") அதாவது, அவர்களுடைய கூலியானது பத்து முதல் எழுநூறு மடங்கு வரை அதிகப்படுத்தப்படும்.\n\r\n\n\r\nوَهُمْ فِى الْغُرُفَـتِ ءَامِنُونَ\n\r\n\n\r\n(\"அவர்கள் (சுவனத்தின்) உன்னதமான அறைகளில் நிம்மதியாக வசிப்பார்கள்.\") அதாவது, சொர்க்கத்தின் உயர்ந்த மாளிகைகளில் எல்லாவிதமான துக்கங்கள், பயம், துன்பங்கள் மற்றும் தாங்கள் அஞ்சக்கூடிய அனைத்துத் தீமைகளிலிருந்தும் பாதுகாப்பாக இருப்பார்கள். இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்கள்: அலி (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ فِي الْجَنَّةِ لَغُرَفًا تُرَى ظُهُورُهَا مِنْ بُطُونِهَا، وَبُطُونُهَا مِنْ ظُهُورِهَا»\n\r\n\n\r\n(\"நிச்சயமாகச் சொர்க்கத்தில் உயர்ந்த அறைகள் உள்ளன; அவற்றின் வெளிப்புறத்தை உட்புறத்திலிருந்தும், உட்புறத்தை வெளிப்புறத்திலிருந்தும் பார்க்கலாம்.\") ஒரு கிராமவாசி, \"அல்லாஹ்வின் தூதரே! அவை யாருக்காக?\" எனக் கேட்டார். அதற்கு அவர்கள் (ஸல்) கூறினார்கள்:\n\r\n\n\r\n«لِمَنْ طَيَّبَ الْكَلَامَ، وَأَطْعَمَ الطَّعَامَ، وَأَدَامَ الصِّيَامَ، وَصَلَّى بِاللَّيْلِ وَالنَّاسُ نِيَام»\n\r\n\n\r\n(\"இனிய சொற்களைப் பேசுபவர்களுக்கும், உணவளிப்பவர்களுக்கும், தொடர்ந்து நோன்பு நோற்பவர்களுக்கும், மக்கள் உறங்கிக் கொண்டிருக்கும்போது இரவில் எழுந்து தொழுபவர்களுக்கும் (அவை உரியவை).\")\n\r\n\n\r\nوَالَّذِينَ يَسْعَوْنَ فِى ءَايَـتِنَا مُعَـجِزِينَ\n\r\n\n\r\n(\"எவர்கள் நமது வசனங்களை (ஆயத்துக்களை) முறியடிக்க முயற்சி செய்கிறார்களோ,\") அதாவது, அல்லாஹ்வின் பாதையிலிருந்தும், அவனது தூதர்களைப் பின்பற்றுவதிலிருந்தும், அவனது சான்றுகளை ஈமான் கொள்வதிலிருந்தும் மக்களைத் தடுக்க முயற்சிப்பவர்கள்,\n\r\n\n\r\nفَأُوْلَـئِكَ فِى الْعَذَابِ مُحْضَرُونَ\n\r\n\n\r\n(அவர்கள் வேதனையில் ஆஜர்படுத்தப்படுவார்கள்.) அதாவது, அவர்கள் அனைவரும் அவரவர் செயல்களுக்கு ஏற்பத் தண்டிக்கப்படுவார்கள்."},"39":{"html":"<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">رَبِّى</span> <span class=\"quran-arabic-font text-success\">يَبْسُطُ</span> <span class=\"quran-arabic-font text-success\">الرِّزْقَ</span> <span class=\"quran-arabic-font text-success\">لِمَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عِبَادِهِ</span> <span class=\"quran-arabic-font text-success\">وَيَقْدِرُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span><br />\r\n<br />\r\n(நீர் கூறுவீராக! \"நிச்சயமாக என் இறைவன், தன் அடியார்களில், தான் நாடியவர்களுக்கு வாழ்வாதாரத்தை விசாலமாக்குகிறான்; (தான் நாடியவர்களுக்குச்) சுருக்கியும் விடுகிறான்.\") இதன் கருத்து என்னவென்றால், அல்லாஹ்வின் ஞானத்தின்படியும், அவனது அடியார்களின் நலனுக்குத் தக்கவாறும் செல்வத்தை அளிப்பதிலும் தடுப்பதிலும் அவன் ஞானம் மிக்கவன் என்பதாகும். அல்லாஹ் (வேறொரு வசனத்தில்) கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">انظُرْ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">فَضَّلْنَا</span> <span class=\"quran-arabic-font text-success\">بَعْضَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">بَعْضٍ</span> <span class=\"quran-arabic-font text-success\">وَلَلْآخِرَةُ</span> <span class=\"quran-arabic-font text-success\">أَكْبَرُ</span> <span class=\"quran-arabic-font text-success\">دَرَجَاتٍ</span> <span class=\"quran-arabic-font text-success\">وَأَكْبَرُ</span> <span class=\"quran-arabic-font text-success\">تَفْضِيلاً</span><br />\r\n<br />\r\n(அவர்களில் சிலரை மற்றவர்களை விட நாம் எவ்வாறு சிறப்பித்துள்ளோம் என்பதைப் பாரும். நிச்சயமாக, மறுமை அந்தஸ்துகளில் மிகப் பெரியதாகவும், சிறப்புகளில் மிகப் பெரியதாகவும் இருக்கும்.) (<a href=\"qurandisp.php?sura=17&ayah=21\" class=\"link\">17:21</a>). இதன் பொருள் என்னவென்றால், இந்த உலகத்தில் அவர்களிடையே வேறுபாடுகள் இருப்பது போலவே - ஒருவன் ஏழையாகவும் நெருக்கடியான நிலையில் இருக்கும்போது, மற்றொருவன் செல்வந்தனாகவும் வசதியான வாழ்க்கையை அனுபவிப்பவனாகவும் இருக்கலாம் - மறுமையிலும் அவர்கள் அவ்வாறே இருப்பார்கள். அங்கே ஒருவர் சொர்க்கத்தின் மிக உயர்ந்த அடுக்குகளில் உள்ள அறைகளில் வசிப்பார், மற்றவரோ நரகத்தின் மிகக் கீழ் மட்டங்களில் இருப்பார். இந்த உலகில் சிறந்த மனிதர்களைப் பற்றி விவரித்து நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أَفْلَحَ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَسْلَمَ</span> <span class=\"quran-arabic-font text-success\">وَرُزِقَ</span> <span class=\"quran-arabic-font text-success\">كَفَافًا</span> <span class=\"quran-arabic-font text-success\">وَقَنَّعَهُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">آتَاه</span>»<br />\r\n<br />\r\n(\"யார் இஸ்லாத்தை ஏற்று, போதுமான அளவு வாழ்வாதாரம் வழங்கப்பட்டு, அல்லாஹ் தனக்கு வழங்கியதைக் கொண்டு அவனை மனநிறைவு அடையச் செய்தானோ, அவர் நிச்சயமாக வெற்றி பெற்றுவிட்டார்.\") இது முஸ்லிம் நூலில் பதிவு செய்யப்பட்டுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَنفَقْتُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">يُخْلِفُهُ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">خَيْرُ</span> <span class=\"quran-arabic-font text-success\">الرَّازِقِينَ</span><br />\r\n<br />\r\n(\"நீங்கள் எப்பொருளைச் செலவு செய்தாலும், அவன் அதற்குப் பதிலாக வேறொன்றைத் தருவான்; மேலும், அவன் உணவளிப்போரில் மிகவும் மேலானவன்.\") என்பதன் பொருள், 'அல்லாஹ் உங்களுக்குக் கட்டளையிட்ட மற்றும் அனுமதித்த வழிகளில் நீங்கள் எதைச் செலவு செய்தாலும், அதற்குப் பதிலாக இந்த உலகத்தில் வேறொன்றைத் தந்து அவன் உங்களுக்கு ஈடுசெய்வான்; மறுமையில் அதற்குரிய நற்கூலியை வழங்குவான்.' நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَقُولُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span>: <span class=\"quran-arabic-font text-success\">أَنْفِقْ،</span> <span class=\"quran-arabic-font text-success\">أُنْفِقْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْك</span>»<br />\r\n<br />\r\n(அல்லாஹ் கூறுகிறான்: \"நீ செலவு செய், நான் உனக்காகச் செலவு செய்வேன்.\") மேலும் நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">يُصْبِحُ</span> <span class=\"quran-arabic-font text-success\">الْعِبَادُ</span> <span class=\"quran-arabic-font text-success\">فِيهِ،</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">مَلَكَانِ</span> <span class=\"quran-arabic-font text-success\">يَنْزِلَانِ،</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span> <span class=\"quran-arabic-font text-success\">أَحَدُهُمَا</span>: <span class=\"quran-arabic-font text-success\">اللهُمَّ</span> <span class=\"quran-arabic-font text-success\">أَعْطِ</span> <span class=\"quran-arabic-font text-success\">مُنْفِقًا</span> <span class=\"quran-arabic-font text-success\">خَلَفًا،</span> <span class=\"quran-arabic-font text-success\">وَيَقُولُ</span> <span class=\"quran-arabic-font text-success\">الْآخَرُ</span>: <span class=\"quran-arabic-font text-success\">اللهُمَّ</span> <span class=\"quran-arabic-font text-success\">أَعْطِ</span> <span class=\"quran-arabic-font text-success\">مُمْسِكًا</span> <span class=\"quran-arabic-font text-success\">تَلَفًا</span>»<br />\r\n<br />\r\nமற்றொரு ஹதீஸில், ஒவ்வொரு காலையிலும் இரண்டு வானவர்கள் வருகின்றனர்; அவர்களில் ஒருவர், \"யா அல்லாஹ்! (செலவு செய்யாமல்) தடுத்து வைப்பவருக்கு அழிவைத் தருவாயாக!\" என்று கூறுகிறார். மற்றொருவர், \"யா அல்லாஹ்! செலவு செய்பவருக்குப் பதிலாக (வேறு ஒரு பொருளை) ஈடாக அருள்வாயாக!\" என்று கூறுகிறார் என அறிவிக்கப்பட்டுள்ளது. மேலும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَنْفِقْ</span> <span class=\"quran-arabic-font text-success\">بِلَالُ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَخْشَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">ذِي</span> <span class=\"quran-arabic-font text-success\">الْعَرْشِ</span> <span class=\"quran-arabic-font text-success\">إِقْلَالًا</span>»<br />\r\n<br />\r\n(பிலாலே! நீர் செலவு செய்வீராக! அர்ஷின் அதிபதி உமக்குக் குறைத்துவிடுவார் என்று அஞ்ச வேண்டாம்.)<br />\r\n<br />","text":"قُلْ إِنَّ رَبِّى يَبْسُطُ الرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِ وَيَقْدِرُ لَهُ\n\r\n\n\r\n(நீர் கூறுவீராக! \"நிச்சயமாக என் இறைவன், தன் அடியார்களில், தான் நாடியவர்களுக்கு வாழ்வாதாரத்தை விசாலமாக்குகிறான்; (தான் நாடியவர்களுக்குச்) சுருக்கியும் விடுகிறான்.\") இதன் கருத்து என்னவென்றால், அல்லாஹ்வின் ஞானத்தின்படியும், அவனது அடியார்களின் நலனுக்குத் தக்கவாறும் செல்வத்தை அளிப்பதிலும் தடுப்பதிலும் அவன் ஞானம் மிக்கவன் என்பதாகும். அல்லாஹ் (வேறொரு வசனத்தில்) கூறுகிறான்:\n\r\n\n\r\nانظُرْ كَيْفَ فَضَّلْنَا بَعْضَهُمْ عَلَى بَعْضٍ وَلَلْآخِرَةُ أَكْبَرُ دَرَجَاتٍ وَأَكْبَرُ تَفْضِيلاً\n\r\n\n\r\n(அவர்களில் சிலரை மற்றவர்களை விட நாம் எவ்வாறு சிறப்பித்துள்ளோம் என்பதைப் பாரும். நிச்சயமாக, மறுமை அந்தஸ்துகளில் மிகப் பெரியதாகவும், சிறப்புகளில் மிகப் பெரியதாகவும் இருக்கும்.) (17:21). இதன் பொருள் என்னவென்றால், இந்த உலகத்தில் அவர்களிடையே வேறுபாடுகள் இருப்பது போலவே - ஒருவன் ஏழையாகவும் நெருக்கடியான நிலையில் இருக்கும்போது, மற்றொருவன் செல்வந்தனாகவும் வசதியான வாழ்க்கையை அனுபவிப்பவனாகவும் இருக்கலாம் - மறுமையிலும் அவர்கள் அவ்வாறே இருப்பார்கள். அங்கே ஒருவர் சொர்க்கத்தின் மிக உயர்ந்த அடுக்குகளில் உள்ள அறைகளில் வசிப்பார், மற்றவரோ நரகத்தின் மிகக் கீழ் மட்டங்களில் இருப்பார். இந்த உலகில் சிறந்த மனிதர்களைப் பற்றி விவரித்து நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«قَدْ أَفْلَحَ مَنْ أَسْلَمَ وَرُزِقَ كَفَافًا وَقَنَّعَهُ اللهُ بِمَا آتَاه»\n\r\n\n\r\n(\"யார் இஸ்லாத்தை ஏற்று, போதுமான அளவு வாழ்வாதாரம் வழங்கப்பட்டு, அல்லாஹ் தனக்கு வழங்கியதைக் கொண்டு அவனை மனநிறைவு அடையச் செய்தானோ, அவர் நிச்சயமாக வெற்றி பெற்றுவிட்டார்.\") இது முஸ்லிம் நூலில் பதிவு செய்யப்பட்டுள்ளது.\n\r\n\n\r\nوَمَآ أَنفَقْتُمْ مِّن شَىْءٍ فَهُوَ يُخْلِفُهُ وَهُوَ خَيْرُ الرَّازِقِينَ\n\r\n\n\r\n(\"நீங்கள் எப்பொருளைச் செலவு செய்தாலும், அவன் அதற்குப் பதிலாக வேறொன்றைத் தருவான்; மேலும், அவன் உணவளிப்போரில் மிகவும் மேலானவன்.\") என்பதன் பொருள், 'அல்லாஹ் உங்களுக்குக் கட்டளையிட்ட மற்றும் அனுமதித்த வழிகளில் நீங்கள் எதைச் செலவு செய்தாலும், அதற்குப் பதிலாக இந்த உலகத்தில் வேறொன்றைத் தந்து அவன் உங்களுக்கு ஈடுசெய்வான்; மறுமையில் அதற்குரிய நற்கூலியை வழங்குவான்.' நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«يَقُولُ اللهُ تَعَالَى: أَنْفِقْ، أُنْفِقْ عَلَيْك»\n\r\n\n\r\n(அல்லாஹ் கூறுகிறான்: \"நீ செலவு செய், நான் உனக்காகச் செலவு செய்வேன்.\") மேலும் நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَا مِنْ يَوْمٍ يُصْبِحُ الْعِبَادُ فِيهِ، إِلَّا مَلَكَانِ يَنْزِلَانِ، فَيَقُولُ أَحَدُهُمَا: اللهُمَّ أَعْطِ مُنْفِقًا خَلَفًا، وَيَقُولُ الْآخَرُ: اللهُمَّ أَعْطِ مُمْسِكًا تَلَفًا»\n\r\n\n\r\nமற்றொரு ஹதீஸில், ஒவ்வொரு காலையிலும் இரண்டு வானவர்கள் வருகின்றனர்; அவர்களில் ஒருவர், \"யா அல்லாஹ்! (செலவு செய்யாமல்) தடுத்து வைப்பவருக்கு அழிவைத் தருவாயாக!\" என்று கூறுகிறார். மற்றொருவர், \"யா அல்லாஹ்! செலவு செய்பவருக்குப் பதிலாக (வேறு ஒரு பொருளை) ஈடாக அருள்வாயாக!\" என்று கூறுகிறார் என அறிவிக்கப்பட்டுள்ளது. மேலும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«أَنْفِقْ بِلَالُ، وَلَا تَخْشَ مِنْ ذِي الْعَرْشِ إِقْلَالًا»\n\r\n\n\r\n(பிலாலே! நீர் செலவு செய்வீராக! அர்ஷின் அதிபதி உமக்குக் குறைத்துவிடுவார் என்று அஞ்ச வேண்டாம்.)"},"40":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=42\" class=\"link\">34:42</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:42 ஐ பார்க்கவும்"},"41":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=42\" class=\"link\">34:42</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:42 ஐ பார்க்கவும்"},"42":{"html":"<strong>மறுமை நாளில் வானவர்கள் தங்களை வணங்கியவர்களைக் கைவிட்டுவிடுவார்கள்</strong><br />\r\n<br />\r\nமறுமை நாளில், படைப்புகள் அனைத்திற்கும் முன்னால் அல்லாஹ் இணைவைப்பாளர்களைக் கடிந்து கொள்வான் என்று நமக்குக் கூறுகிறான். இணைவைப்பாளர்கள் எவர்களை வணங்கிக் கொண்டிருந்தார்களோ அந்த வானவர்களிடம் அல்லாஹ் கேட்பான். ஏனெனில், அந்தச் சிலைகள் வானவர்களின் உருவத்தில் இருப்பதாகவும், அவை தங்களை அல்லாஹ்விடம் நெருக்கமாக்கும் என்றும் அவர்கள் வாதிட்டு வந்தனர். அல்லாஹ் வானவர்களிடம் கேட்பான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَهَؤُلَاءِ</span> <span class=\"quran-arabic-font text-success\">إِيَّاكُمْ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَعْبُدُونَ﴿</span><br />\r\n<br />\r\n(இந்த மக்கள் உங்களையா வணங்கிக் கொண்டிருந்தார்கள்?) அதாவது, 'உங்களை வணங்குமாறு நீங்கள் அவர்களுக்குக் கட்டளையிட்டீர்களா?' என்று பொருள். ஸூரத்துல் ஃபுர்கானில் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَءَنتُمْ</span> <span class=\"quran-arabic-font text-success\">أَضْلَلْتُمْ</span> <span class=\"quran-arabic-font text-success\">عِبَادِى</span> <span class=\"quran-arabic-font text-success\">هَؤُلَاءِ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">ضَلُّوا</span> <span class=\"quran-arabic-font text-success\">السَّبِيلَ﴿</span><br />\r\n<br />\r\n(என்னுடைய இந்த அடியார்களை நீங்கள் வழிதவறச் செய்தீர்களா அல்லது அவர்களே நேர்வழியை விட்டுத் தடம் புரண்டார்களா?) (<a href=\"qurandisp.php?sura=25&ayah=17\" class=\"link\">25:17</a>). மேலும், ஈஸா (அலை) அவர்களிடம் அவன் கூறுவான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَءَنتَ</span> <span class=\"quran-arabic-font text-success\">قُلتَ</span> <span class=\"quran-arabic-font text-success\">لِلنَّاسِ</span> <span class=\"quran-arabic-font text-success\">اتَّخِذُونِى</span> <span class=\"quran-arabic-font text-success\">وَأُمِّىَ</span> <span class=\"quran-arabic-font text-success\">إِلَهَيْنِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">سُبْحَانَكَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَكُونُ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">أَقُولَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">بِحَقٍّ﴿</span><br />\r\n<br />\r\n(\"அல்லாஹ்வையன்றி, என்னையும் என் தாயாரையும் இரு கடவுள்களாக எடுத்துக் கொள்ளுங்கள் என்று நீர் மக்களிடம் கூறினீரா?\" அதற்கு அவர், \"நீ மிகவும் தூய்மையானவன்! எனக்குத் தகுதியில்லாத ஒன்றைச் சொல்ல எனக்கு உரிமை இல்லை\" எனக் கூறுவார்.) (<a href=\"qurandisp.php?sura=5&ayah=116\" class=\"link\">5:116</a>). இதேபோன்று, வானவர்கள் கூறுவார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾سُبْحَانَكَ﴿</span><br />\r\n<br />\r\nநீ மிகவும் தூய்மையானவன்! அதாவது, உன்னைத் தவிர வேறு கடவுள் இருக்கக்கூடும் என்ற கருத்தை விட்டும் நீ மேலானவனாகவும் பரிசுத்தமானவனாகவும் இருக்கிறாய் என்று பொருள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَنتَ</span> <span class=\"quran-arabic-font text-success\">وَلِيُّنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِهِمْ﴿</span><br />\r\n<br />\r\nஅவர்களை விடுத்து நீயே எங்கள் பாதுகாவலன். அதாவது, நாங்கள் உன்னுடைய அடியார்கள்; இவர்களுக்கும் எங்களுக்கும் எந்தத் தொடர்புமில்லை என உன்னிடத்தில் இவர்களை நாங்கள் கைவிடுகிறோம்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾بَلْ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَعْبُدُونَ</span> <span class=\"quran-arabic-font text-success\">الْجِنَّ﴿</span><br />\r\n<br />\r\n(இல்லை, மாறாக அவர்கள் ஜின்களையே வணங்கிக் கொண்டிருந்தார்கள்;) அதாவது ஷைத்தான்களை. ஏனெனில், அவர்கள்தான் இவர்களுக்குச் சிலை வணக்கத்தை அழகாகக் காட்டினார்கள், மேலும் இவர்களை வழிதவறச் செய்தார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَكْثَرُهُم</span> <span class=\"quran-arabic-font text-success\">بِهِم</span> <span class=\"quran-arabic-font text-success\">مُّؤْمِنُونَ﴿</span><br />\r\n<br />\r\nஅவர்களில் பெரும்பாலோர் அவர்களை (ஜின்களை) விசுவாசிப்பவர்களாக இருந்தார்கள். இது இந்த வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِن</span> <span class=\"quran-arabic-font text-success\">يَدْعُونَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِهِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">إِنَاثًا</span> <span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">يَدْعُونَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">شَيْطَانًا</span> <span class=\"quran-arabic-font text-success\">مَّرِيداً</span> <span class=\"quran-arabic-font text-success\">لَّعَنَهُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ﴿</span><br />\r\n<br />\r\n(அவர்கள் அல்லாஹ்வையன்றிப் பெண் தெய்வங்களையே அழைக்கின்றனர்; மேலும் அவர்கள் வரம்பு மீறிய ஷைத்தானைத் தவிர வேறு யாரையும் அழைக்கவில்லை. அல்லாஹ் அவனைச் சபித்தான்.) (<a href=\"qurandisp.php?sura=4&ayah=117\" class=\"link\">4:117</a>-118).<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَالْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَمْلِكُ</span> <span class=\"quran-arabic-font text-success\">بَعْضُكُمْ</span> <span class=\"quran-arabic-font text-success\">لِبَعْضٍ</span> <span class=\"quran-arabic-font text-success\">نَّفْعاً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">ضَرّاً﴿</span><br />\r\n<br />\r\n(எனவே, இன்றைய தினம் உங்களில் ஒருவர் மற்றவருக்கு எந்தப் பயனோ தீங்கோ செய்ய சக்தி பெறமாட்டீர்கள்.) அதாவது, 'உங்களுக்குப் பயனளிக்கும் என்று நீங்கள் நம்பியிருந்த எந்தச் சிலைகளும், இணைகளும் இன்று உங்களுக்கு உதவப் போவதில்லை. நெருக்கடி மற்றும் துன்ப காலங்களில் உங்களுக்கு உதவுவார்கள் என்ற நம்பிக்கையில் நீங்கள் எவர்களை வணங்கினீர்களோ, இன்று உங்களுக்கு நன்மை செய்யவும் அல்லது தீங்கு செய்யவும் அவற்றுக்கு எந்த அதிகாரமும் இருக்காது.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَنَقُولُ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ظَلَمُواْ﴿</span><br />\r\n<br />\r\nஅநீதி இழைத்தவர்களிடம் (அதாவது இணைவைப்பாளர்களிடம்) நாம் கூறுவோம்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ذُوقُواْ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">كُنتُم</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">تُكَذِّبُونَ﴿</span><br />\r\n<br />\r\n(\"நீங்கள் பொய்யாக்கிக் கொண்டிருந்த நரக நெருப்பின் வேதனையைச் சுவையுங்கள்.\") அதாவது, அவர்களைக் கண்டிக்கும் விதமாக இது கூறப்படும்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"மறுமை நாளில் வானவர்கள் தங்களை வணங்கியவர்களைக் கைவிட்டுவிடுவார்கள்\n\r\n\n\r\nமறுமை நாளில், படைப்புகள் அனைத்திற்கும் முன்னால் அல்லாஹ் இணைவைப்பாளர்களைக் கடிந்து கொள்வான் என்று நமக்குக் கூறுகிறான். இணைவைப்பாளர்கள் எவர்களை வணங்கிக் கொண்டிருந்தார்களோ அந்த வானவர்களிடம் அல்லாஹ் கேட்பான். ஏனெனில், அந்தச் சிலைகள் வானவர்களின் உருவத்தில் இருப்பதாகவும், அவை தங்களை அல்லாஹ்விடம் நெருக்கமாக்கும் என்றும் அவர்கள் வாதிட்டு வந்தனர். அல்லாஹ் வானவர்களிடம் கேட்பான்:\n\r\n\n\r\n﴾أَهَؤُلَاءِ إِيَّاكُمْ كَانُواْ يَعْبُدُونَ﴿\n\r\n\n\r\n(இந்த மக்கள் உங்களையா வணங்கிக் கொண்டிருந்தார்கள்?) அதாவது, 'உங்களை வணங்குமாறு நீங்கள் அவர்களுக்குக் கட்டளையிட்டீர்களா?' என்று பொருள். ஸூரத்துல் ஃபுர்கானில் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾أَءَنتُمْ أَضْلَلْتُمْ عِبَادِى هَؤُلَاءِ أَمْ هُمْ ضَلُّوا السَّبِيلَ﴿\n\r\n\n\r\n(என்னுடைய இந்த அடியார்களை நீங்கள் வழிதவறச் செய்தீர்களா அல்லது அவர்களே நேர்வழியை விட்டுத் தடம் புரண்டார்களா?) (25:17). மேலும், ஈஸா (அலை) அவர்களிடம் அவன் கூறுவான்:\n\r\n\n\r\n﴾أَءَنتَ قُلتَ لِلنَّاسِ اتَّخِذُونِى وَأُمِّىَ إِلَهَيْنِ مِن دُونِ اللَّهِ قَالَ سُبْحَانَكَ مَا يَكُونُ لِى أَنْ أَقُولَ مَا لَيْسَ لِى بِحَقٍّ﴿\n\r\n\n\r\n(\"அல்லாஹ்வையன்றி, என்னையும் என் தாயாரையும் இரு கடவுள்களாக எடுத்துக் கொள்ளுங்கள் என்று நீர் மக்களிடம் கூறினீரா?\" அதற்கு அவர், \"நீ மிகவும் தூய்மையானவன்! எனக்குத் தகுதியில்லாத ஒன்றைச் சொல்ல எனக்கு உரிமை இல்லை\" எனக் கூறுவார்.) (5:116). இதேபோன்று, வானவர்கள் கூறுவார்கள்:\n\r\n\n\r\n﴾سُبْحَانَكَ﴿\n\r\n\n\r\nநீ மிகவும் தூய்மையானவன்! அதாவது, உன்னைத் தவிர வேறு கடவுள் இருக்கக்கூடும் என்ற கருத்தை விட்டும் நீ மேலானவனாகவும் பரிசுத்தமானவனாகவும் இருக்கிறாய் என்று பொருள்.\n\r\n\n\r\n﴾أَنتَ وَلِيُّنَا مِن دُونِهِمْ﴿\n\r\n\n\r\nஅவர்களை விடுத்து நீயே எங்கள் பாதுகாவலன். அதாவது, நாங்கள் உன்னுடைய அடியார்கள்; இவர்களுக்கும் எங்களுக்கும் எந்தத் தொடர்புமில்லை என உன்னிடத்தில் இவர்களை நாங்கள் கைவிடுகிறோம்.\n\r\n\n\r\n﴾بَلْ كَانُواْ يَعْبُدُونَ الْجِنَّ﴿\n\r\n\n\r\n(இல்லை, மாறாக அவர்கள் ஜின்களையே வணங்கிக் கொண்டிருந்தார்கள்;) அதாவது ஷைத்தான்களை. ஏனெனில், அவர்கள்தான் இவர்களுக்குச் சிலை வணக்கத்தை அழகாகக் காட்டினார்கள், மேலும் இவர்களை வழிதவறச் செய்தார்கள்.\n\r\n\n\r\n﴾أَكْثَرُهُم بِهِم مُّؤْمِنُونَ﴿\n\r\n\n\r\nஅவர்களில் பெரும்பாலோர் அவர்களை (ஜின்களை) விசுவாசிப்பவர்களாக இருந்தார்கள். இது இந்த வசனத்தைப் போன்றது:\n\r\n\n\r\n﴾إِن يَدْعُونَ مِن دُونِهِ إِلاَّ إِنَاثًا وَإِن يَدْعُونَ إِلاَّ شَيْطَانًا مَّرِيداً لَّعَنَهُ اللَّهُ﴿\n\r\n\n\r\n(அவர்கள் அல்லாஹ்வையன்றிப் பெண் தெய்வங்களையே அழைக்கின்றனர்; மேலும் அவர்கள் வரம்பு மீறிய ஷைத்தானைத் தவிர வேறு யாரையும் அழைக்கவில்லை. அல்லாஹ் அவனைச் சபித்தான்.) (4:117-118).\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾فَالْيَوْمَ لاَ يَمْلِكُ بَعْضُكُمْ لِبَعْضٍ نَّفْعاً وَلاَ ضَرّاً﴿\n\r\n\n\r\n(எனவே, இன்றைய தினம் உங்களில் ஒருவர் மற்றவருக்கு எந்தப் பயனோ தீங்கோ செய்ய சக்தி பெறமாட்டீர்கள்.) அதாவது, 'உங்களுக்குப் பயனளிக்கும் என்று நீங்கள் நம்பியிருந்த எந்தச் சிலைகளும், இணைகளும் இன்று உங்களுக்கு உதவப் போவதில்லை. நெருக்கடி மற்றும் துன்ப காலங்களில் உங்களுக்கு உதவுவார்கள் என்ற நம்பிக்கையில் நீங்கள் எவர்களை வணங்கினீர்களோ, இன்று உங்களுக்கு நன்மை செய்யவும் அல்லது தீங்கு செய்யவும் அவற்றுக்கு எந்த அதிகாரமும் இருக்காது.'\n\r\n\n\r\n﴾وَنَقُولُ لِلَّذِينَ ظَلَمُواْ﴿\n\r\n\n\r\nஅநீதி இழைத்தவர்களிடம் (அதாவது இணைவைப்பாளர்களிடம்) நாம் கூறுவோம்:\n\r\n\n\r\n﴾ذُوقُواْ عَذَابَ النَّارِ الَّتِى كُنتُم بِهَا تُكَذِّبُونَ﴿\n\r\n\n\r\n(\"நீங்கள் பொய்யாக்கிக் கொண்டிருந்த நரக நெருப்பின் வேதனையைச் சுவையுங்கள்.\") அதாவது, அவர்களைக் கண்டிக்கும் விதமாக இது கூறப்படும்."},"43":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=45\" class=\"link\">34:45</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:45 ஐ பார்க்கவும்"},"44":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=45\" class=\"link\">34:45</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:45 ஐ பார்க்கவும்"},"45":{"html":"<strong>நபிமார்களைப் பற்றி நிராகரிப்பாளர்கள் கூறிய கூற்றும், அதற்கான மறுப்பும்</strong><br />\r\n<br />\r\nஅல்லாஹ்வின் தெளிவான வசனங்கள் அவர்களுக்கு ஓதிக் காண்பிக்கப்பட்டபோது, அவனது தூதரின் நாவிலிருந்து நேரடியாகப் புதியதாக அவற்றைக் கேட்டும் அவர்கள் பின்வருமாறு கூறியதால், நிராகரிப்பாளர்கள் தன்னிடம் இருந்து கடுமையான தண்டனைக்குத் தகுதியானவர்கள் என்று அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">رَجُلٌ</span> <span class=\"quran-arabic-font text-success\">يُرِيدُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَصُدَّكُمْ</span> <span class=\"quran-arabic-font text-success\">عَمَّا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">يَعْبُدُ</span> <span class=\"quran-arabic-font text-success\">ءَابَآؤُكُمْ</span><br />\r\n<br />\r\n(அவர்கள் கூறுகிறார்கள்: “உங்கள் முன்னோர்கள் எதை வணங்கிக் கொண்டிருந்தார்களோ, அதிலிருந்து உங்களைத் தடுக்க விரும்பும் ஒரு மனிதரே அன்றி இவர் வேறில்லை.”) அதாவது, தங்கள் முன்னோர்களின் மார்க்கமே சத்தியமானது என்றும், இத்தூதர் கொண்டு வந்தது பொய்யானது என்றும் அவர்கள் கருதினர். அல்லாஹ்வும் அவனது சாபமும் அவர்கள் மீதும் அவர்களின் முன்னோர்கள் மீதும் உண்டாவதாக!<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">هَـذَآ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">إِفْكٌ</span> <span class=\"quran-arabic-font text-success\">مُّفْتَرًى</span><br />\r\n<br />\r\n(மேலும் அவர்கள் கூறுகிறார்கள்: \"இது இட்டுக்கட்டப்பட்ட ஒரு பொய்யே அன்றி வேறில்லை.\") இது குர்ஆனைக் குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">لِلْحَقِّ</span> <span class=\"quran-arabic-font text-success\">لَمَّا</span> <span class=\"quran-arabic-font text-success\">جَآءَهُمْ</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">هَـذَآ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">سِحْرٌ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٌ</span><br />\r\n<br />\r\n(மேலும் நிராகரிப்பாளர்கள் தங்களுக்குச் சத்தியம் வந்தபோது அதைப் பற்றி: “இது தெளிவான சூனியமே அன்றி வேறில்லை!” என்று கூறுகின்றனர்.) அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">ءَاتَيْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">كُتُبٍ</span> <span class=\"quran-arabic-font text-success\">يَدْرُسُونَهَا</span> <span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">قَبْلَكَ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">نَّذِيرٍ</span><br />\r\n<br />\r\n(அவர்கள் படிப்பதற்கென எந்த வேதங்களையும் நாம் அவர்களுக்கு வழங்கவில்லை; உமக்கு முன்னர் எச்சரிக்கை செய்பவர் எவரையும் நாம் அவர்களிடம் அனுப்பவுமில்லை.) அதாவது, குர்ஆனுக்கு முன்பு அரேபியர்களுக்கு அல்லாஹ் எந்த வேதத்தையும் அருளவில்லை, முஹம்மது (ஸல்) அவர்களுக்கு முன்பு எந்த ஒரு நபியையும் அவன் அனுப்பவில்லை. \"எங்களிடம் ஓர் எச்சரிக்கையாளர் வந்திருந்தால் அல்லது எங்களுக்கு ஒரு வேதம் அருளப்பட்டிருந்தால், நிச்சயமாக நாங்கள் மற்றவர்களை விட நேர்வழி பெற்றவர்களாக இருந்திருப்போம்\" என்று அவர்கள் ஆசைப்பட்டு வந்தனர். ஆனால் அல்லாஹ் அவர்களுக்கு அந்த அருளை வழங்கியபோது, அவர்கள் அவரை நிராகரித்து, பிடிவாதமாக மறுத்தனர். பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَذَّبَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبلِهِمْ</span><br />\r\n<br />\r\n(அவர்களுக்கு முன்னிருந்தவர்களும் (இவ்வாறே) மறுத்தனர்;) அதாவது, முந்தைய சமுதாயத்தினர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">بَلَغُواْ</span> <span class=\"quran-arabic-font text-success\">مِعْشَارَ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">ءَاتَيْنَـهُمْ</span><br />\r\n<br />\r\n(முந்தைய அவர்களுக்கு நாம் வழங்கியவற்றில் பத்தில் ஒரு பங்கைக்கூட இவர்கள் அடையவில்லை;) \"இவ்வுலகின் அதிகாரத்தில் (பத்தில் ஒரு பங்கைக்கூட இவர்கள் அடையவில்லை)\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள். கத்தாதா, அஸ்-ஸுத்தி மற்றும் இப்னு ஸைத் ஆகியோரின் கருத்தும் இதுவேயாகும். இது பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">مَكَّنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">فِيمَآ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">مَّكَّنَّـكُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">وَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">سَمْعاً</span> <span class=\"quran-arabic-font text-success\">وَأَبْصَـراً</span> <span class=\"quran-arabic-font text-success\">وَأَفْئِدَةً</span> <span class=\"quran-arabic-font text-success\">فَمَآ</span> <span class=\"quran-arabic-font text-success\">أَغْنَى</span> <span class=\"quran-arabic-font text-success\">عَنْهُمْ</span> <span class=\"quran-arabic-font text-success\">سَمْعُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَبْصَـرُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَفْئِدَتُهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَجْحَدُونَ</span> <span class=\"quran-arabic-font text-success\">بِـَايَـتِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَحَاقَ</span> <span class=\"quran-arabic-font text-success\">بِهم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">يَسْتَهْزِءُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக, உங்களுக்கு நாம் வழங்காத வசதி வாய்ப்புகளை அவர்களுக்கு நாம் வழங்கியிருந்தோம்! மேலும் நாம் அவர்களுக்குச் செவிப்புலனையும், பார்வைகளையும், இதயங்களையும் கொடுத்திருந்தோம்; ஆனால் அவர்கள் அல்லாஹ்வின் வசனங்களை மறுத்துக் கொண்டிருந்ததால், அவர்களுடைய செவியோ, பார்வைகளோ, இதயங்களோ அவர்களுக்கு எவ்விதப் பலனையும் அளிக்கவில்லை. மேலும் அவர்கள் எதைக் கேலி செய்து கொண்டிருந்தார்களோ, அதுவே அவர்களைச் சூழ்ந்து கொண்டது!) (<a href=\"qurandisp.php?sura=46&ayah=26\" class=\"link\">46:26</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَسِيرُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">فَيَنظُرُواْ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَـقِبَةُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِمْ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">أَكْـثَرَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَشَدَّ</span> <span class=\"quran-arabic-font text-success\">قُوَّةً</span><br />\r\n<br />\r\n(அவர்கள் பூமியில் பயணம் செய்து, தங்களுக்கு முன்னிருந்தவர்களின் முடிவு என்னவாயிற்று என்பதைப் பார்க்கவில்லையா? அவர்கள் இவர்களை விட எண்ணிக்கையில் அதிகமாகவும், வலிமையில் மிகக் கூடினவர்களாகவும் இருந்தனர்.) (<a href=\"qurandisp.php?sura=40&ayah=82\" class=\"link\">40:82</a>). இருப்பினும், அது அவர்களை அல்லாஹ்வின் தண்டனையிலிருந்து பாதுகாக்கவில்லை. அவர்கள் அவனது தூதர்களைப் பொய்ப்பித்த காரணத்தால் அல்லாஹ் அவர்களை அழித்தான். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَكَذَّبُواْ</span> <span class=\"quran-arabic-font text-success\">رُسُلِى</span> <span class=\"quran-arabic-font text-success\">فَكَيْفَ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">نَكِيرِ</span><br />\r\n<br />\r\n(ஆயினும் அவர்கள் எனது தூதர்களைப் பொய்ப்பித்தனர். எனவே, எனது மறுப்பு (தண்டனை) எவ்வாறு இருந்தது!) அதாவது, ‘எனது கோபம் எவ்வளவு கடுமையாக இருந்தது, எனது தூதர்களுக்காக நான் பழிவாங்கியது எவ்வளவு பயங்கரமாக இருந்தது’ என்பதாகும்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"நபிமார்களைப் பற்றி நிராகரிப்பாளர்கள் கூறிய கூற்றும், அதற்கான மறுப்பும்\n\r\n\n\r\nஅல்லாஹ்வின் தெளிவான வசனங்கள் அவர்களுக்கு ஓதிக் காண்பிக்கப்பட்டபோது, அவனது தூதரின் நாவிலிருந்து நேரடியாகப் புதியதாக அவற்றைக் கேட்டும் அவர்கள் பின்வருமாறு கூறியதால், நிராகரிப்பாளர்கள் தன்னிடம் இருந்து கடுமையான தண்டனைக்குத் தகுதியானவர்கள் என்று அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nقَالُواْ مَا هَـذَا إِلاَّ رَجُلٌ يُرِيدُ أَن يَصُدَّكُمْ عَمَّا كَانَ يَعْبُدُ ءَابَآؤُكُمْ\n\r\n\n\r\n(அவர்கள் கூறுகிறார்கள்: “உங்கள் முன்னோர்கள் எதை வணங்கிக் கொண்டிருந்தார்களோ, அதிலிருந்து உங்களைத் தடுக்க விரும்பும் ஒரு மனிதரே அன்றி இவர் வேறில்லை.”) அதாவது, தங்கள் முன்னோர்களின் மார்க்கமே சத்தியமானது என்றும், இத்தூதர் கொண்டு வந்தது பொய்யானது என்றும் அவர்கள் கருதினர். அல்லாஹ்வும் அவனது சாபமும் அவர்கள் மீதும் அவர்களின் முன்னோர்கள் மீதும் உண்டாவதாக!\n\r\n\n\r\nوَقَالُواْ مَا هَـذَآ إِلاَّ إِفْكٌ مُّفْتَرًى\n\r\n\n\r\n(மேலும் அவர்கள் கூறுகிறார்கள்: \"இது இட்டுக்கட்டப்பட்ட ஒரு பொய்யே அன்றி வேறில்லை.\") இது குர்ஆனைக் குறிக்கிறது.\n\r\n\n\r\nوَقَالَ الَّذِينَ كَفَرُواْ لِلْحَقِّ لَمَّا جَآءَهُمْ إِنْ هَـذَآ إِلاَّ سِحْرٌ مُّبِينٌ\n\r\n\n\r\n(மேலும் நிராகரிப்பாளர்கள் தங்களுக்குச் சத்தியம் வந்தபோது அதைப் பற்றி: “இது தெளிவான சூனியமே அன்றி வேறில்லை!” என்று கூறுகின்றனர்.) அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَمَآ ءَاتَيْنَـهُمْ مِّنْ كُتُبٍ يَدْرُسُونَهَا وَمَآ أَرْسَلْنَا إِلَيْهِمْ قَبْلَكَ مِّن نَّذِيرٍ\n\r\n\n\r\n(அவர்கள் படிப்பதற்கென எந்த வேதங்களையும் நாம் அவர்களுக்கு வழங்கவில்லை; உமக்கு முன்னர் எச்சரிக்கை செய்பவர் எவரையும் நாம் அவர்களிடம் அனுப்பவுமில்லை.) அதாவது, குர்ஆனுக்கு முன்பு அரேபியர்களுக்கு அல்லாஹ் எந்த வேதத்தையும் அருளவில்லை, முஹம்மது (ஸல்) அவர்களுக்கு முன்பு எந்த ஒரு நபியையும் அவன் அனுப்பவில்லை. \"எங்களிடம் ஓர் எச்சரிக்கையாளர் வந்திருந்தால் அல்லது எங்களுக்கு ஒரு வேதம் அருளப்பட்டிருந்தால், நிச்சயமாக நாங்கள் மற்றவர்களை விட நேர்வழி பெற்றவர்களாக இருந்திருப்போம்\" என்று அவர்கள் ஆசைப்பட்டு வந்தனர். ஆனால் அல்லாஹ் அவர்களுக்கு அந்த அருளை வழங்கியபோது, அவர்கள் அவரை நிராகரித்து, பிடிவாதமாக மறுத்தனர். பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَكَذَّبَ الَّذِينَ مِن قَبلِهِمْ\n\r\n\n\r\n(அவர்களுக்கு முன்னிருந்தவர்களும் (இவ்வாறே) மறுத்தனர்;) அதாவது, முந்தைய சமுதாயத்தினர்.\n\r\n\n\r\nوَمَا بَلَغُواْ مِعْشَارَ مَآ ءَاتَيْنَـهُمْ\n\r\n\n\r\n(முந்தைய அவர்களுக்கு நாம் வழங்கியவற்றில் பத்தில் ஒரு பங்கைக்கூட இவர்கள் அடையவில்லை;) \"இவ்வுலகின் அதிகாரத்தில் (பத்தில் ஒரு பங்கைக்கூட இவர்கள் அடையவில்லை)\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள். கத்தாதா, அஸ்-ஸுத்தி மற்றும் இப்னு ஸைத் ஆகியோரின் கருத்தும் இதுவேயாகும். இது பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\nوَلَقَدْ مَكَّنَـهُمْ فِيمَآ إِن مَّكَّنَّـكُمْ فِيهِ وَجَعَلْنَا لَهُمْ سَمْعاً وَأَبْصَـراً وَأَفْئِدَةً فَمَآ أَغْنَى عَنْهُمْ سَمْعُهُمْ وَلاَ أَبْصَـرُهُمْ وَلاَ أَفْئِدَتُهُمْ مِّن شَىْءٍ إِذْ كَانُواْ يَجْحَدُونَ بِـَايَـتِ اللَّهِ وَحَاقَ بِهم مَّا كَانُواْ بِهِ يَسْتَهْزِءُونَ\n\r\n\n\r\n(நிச்சயமாக, உங்களுக்கு நாம் வழங்காத வசதி வாய்ப்புகளை அவர்களுக்கு நாம் வழங்கியிருந்தோம்! மேலும் நாம் அவர்களுக்குச் செவிப்புலனையும், பார்வைகளையும், இதயங்களையும் கொடுத்திருந்தோம்; ஆனால் அவர்கள் அல்லாஹ்வின் வசனங்களை மறுத்துக் கொண்டிருந்ததால், அவர்களுடைய செவியோ, பார்வைகளோ, இதயங்களோ அவர்களுக்கு எவ்விதப் பலனையும் அளிக்கவில்லை. மேலும் அவர்கள் எதைக் கேலி செய்து கொண்டிருந்தார்களோ, அதுவே அவர்களைச் சூழ்ந்து கொண்டது!) (46:26)\n\r\n\n\r\nأَفَلَمْ يَسِيرُواْ فِى الْأَرْضِ فَيَنظُرُواْ كَيْفَ كَانَ عَـقِبَةُ الَّذِينَ مِن قَبْلِهِمْ كَانُواْ أَكْـثَرَ مِنْهُمْ وَأَشَدَّ قُوَّةً\n\r\n\n\r\n(அவர்கள் பூமியில் பயணம் செய்து, தங்களுக்கு முன்னிருந்தவர்களின் முடிவு என்னவாயிற்று என்பதைப் பார்க்கவில்லையா? அவர்கள் இவர்களை விட எண்ணிக்கையில் அதிகமாகவும், வலிமையில் மிகக் கூடினவர்களாகவும் இருந்தனர்.) (40:82). இருப்பினும், அது அவர்களை அல்லாஹ்வின் தண்டனையிலிருந்து பாதுகாக்கவில்லை. அவர்கள் அவனது தூதர்களைப் பொய்ப்பித்த காரணத்தால் அல்லாஹ் அவர்களை அழித்தான். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَكَذَّبُواْ رُسُلِى فَكَيْفَ كَانَ نَكِيرِ\n\r\n\n\r\n(ஆயினும் அவர்கள் எனது தூதர்களைப் பொய்ப்பித்தனர். எனவே, எனது மறுப்பு (தண்டனை) எவ்வாறு இருந்தது!) அதாவது, ‘எனது கோபம் எவ்வளவு கடுமையாக இருந்தது, எனது தூதர்களுக்காக நான் பழிவாங்கியது எவ்வளவு பயங்கரமாக இருந்தது’ என்பதாகும்."},"46":{"html":"<strong>நபி (ஸல்) அவர்கள் பைத்தியக்காரர் என்ற அவர்களின் குற்றச்சாட்டுக்கு மறுப்பு</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: \"(முஹம்மதே!) நீர் ஒரு பைத்தியக்காரர் என்று வாதிடும் இந்த நிராகரிப்பாளர்களிடம் நீர் கூறுவீராக:\" <span class=\"quran-arabic-font text-success\">﴾قُلْ</span> <span class=\"quran-arabic-font text-success\">إِنَّمَآ</span> <span class=\"quran-arabic-font text-success\">أَعِظُكُمْ</span> <span class=\"quran-arabic-font text-success\">بِوَاحِدَةٍ﴿</span><br />\r\n<br />\r\n\"நான் உங்களுக்கு ஒரே ஒரு விஷயத்தைத்தான் உபதேசிக்கிறேன். அது யாதெனில்:\" <span class=\"quran-arabic-font text-success\">﴾أَن</span> <span class=\"quran-arabic-font text-success\">تَقُومُواْ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">مَثْنَى</span> <span class=\"quran-arabic-font text-success\">وَفُرَادَى</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">تَتَفَكَّرُواْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">بِصَاحِبِكُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">جِنَّةٍ﴿</span><br />\r\n<br />\r\n\"நீங்கள் ஈர்இருவராகவும் அல்லது தனித்தனியாகவும் அல்லாஹ்விற்காக (உண்மையை அறிய) முன்வாருங்கள்; பிறகு சிந்தித்துப் பாருங்கள், உங்கள் தோழரிடம் (முஹம்மத் ஸல் அவர்களிடம்) எந்தப் பைத்தியமும் இல்லை. அதாவது, உங்கள் சொந்த ஆசைகளுக்கோ அல்லது கோத்திர உணர்வுகளுக்கோ இடம் தராமல், தூய எண்ணத்துடன் அல்லாஹ்விற்காக முன்வந்து, 'முஹம்மத் (ஸல்) அவர்களுக்குப் பைத்தியமா?' என்று ஒருவருக்கொருவர் கேட்டுக்கொள்ளுங்கள்; ஒருவருக்கொருவர் அறிவுரை கூறுங்கள்.\" <span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">تَتَفَكَّرُواْ﴿</span><br />\r\n<br />\r\nமேலும், 'சிந்தித்துப் பாருங்கள்' என்பது ஒவ்வொருவரும் முஹம்மத் (ஸல்) அவர்களின் விஷயத்தைப் பற்றித் தமக்குள்ளேயே சிந்தித்துப் பார்க்க வேண்டும் என்பதைக் குறிக்கிறது. அவருக்கு இன்னும் ஏதேனும் குழப்பம் இருந்தால், மற்றவர்களிடம் அவரைப் பற்றி வினவட்டும், பிறகு அந்த விஷயத்தைப் பற்றிச் சிந்திக்கட்டும். அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾أَن</span> <span class=\"quran-arabic-font text-success\">تَقُومُواْ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">مَثْنَى</span> <span class=\"quran-arabic-font text-success\">وَفُرَادَى</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">تَتَفَكَّرُواْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">بِصَاحِبِكُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">جِنَّةٍ﴿</span><br />\r\n<br />\r\n(நீங்கள் ஈர்இருவராகவும் அல்லது தனித்தனியாகவும் அல்லாஹ்விற்காக முன்வந்து நில்லுங்கள்; பிறகு சிந்தித்துப் பாருங்கள், உங்கள் தோழரிடம் எந்தப் பைத்தியமும் இல்லை.) இந்தக் கருத்தை முஜாஹித், முஹம்மத் பின் கஅப், அஸ்-ஸுத்தி, கதாதா மற்றும் பலர் கூறியுள்ளனர். இதுவே இந்த வசனத்தின் (ஆயத்தின்) பொருளாகும். <span class=\"quran-arabic-font text-success\">﴾إِنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">نَذِيرٌ</span> <span class=\"quran-arabic-font text-success\">لَّكُمْ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">يَدَىْ</span> <span class=\"quran-arabic-font text-success\">عَذَابٍ</span> <span class=\"quran-arabic-font text-success\">شَدِيدٍ﴿</span><br />\r\n<br />\r\n(கடுமையான வேதனைக்கு முன்னால் அவர் உங்களுக்கு எச்சரிக்கை செய்பவரே அன்றி வேறில்லை.) இப்னு அப்பாஸ் (ரழி) அவர்கள் இந்த வசனத்தைப் பற்றி இவ்வாறு கூறியதாக புகாரி பதிவு செய்துள்ளார்: \"ஒரு நாள் நபி (ஸல்) அவர்கள் ஸஃபா மலை குன்றின் மீது ஏறி, 'யா ஸபாஹா' (மக்களே!) என்று சத்தமிட்டு அழைத்தார்கள்.\" <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">صَبَاحَاه</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\nகுரைஷிகள் அவர்களைச் சூழ்ந்து கொண்டு, 'உமக்கு என்ன நேர்ந்தது?' என்று கேட்டார்கள். அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">أَرَأَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">أَخْبَرْتُكُمْ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">الْعَدُوَّ</span> <span class=\"quran-arabic-font text-success\">يُصَبِّحُكُمْ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">يُمَسِّيكُمْ</span> <span class=\"quran-arabic-font text-success\">أَمَا</span> <span class=\"quran-arabic-font text-success\">كُنْتُمْ</span> <span class=\"quran-arabic-font text-success\">تُصَدِّقُونِّي</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"பகைவர்கள் காலையிலோ அல்லது மாலையிலோ உங்கள் மீது தாக்குதல் நடத்த வருகிறார்கள் என்று நான் உங்களிடம் கூறினால், நீங்கள் என்னை நம்புவீர்களா என்று சொல்லுங்கள்?\" அதற்கு அவர்கள், \"நிச்சயமாக (நம்புவோம்)\" என்று கூறினார்கள். நபி (ஸல்) அவர்கள் கூறினார்கள்:) <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">فَإِنِّي</span> <span class=\"quran-arabic-font text-success\">نَذِيرٌ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">يَدَيْ</span> <span class=\"quran-arabic-font text-success\">عَذَابٍ</span> <span class=\"quran-arabic-font text-success\">شَدِيد</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n\"(கடுமையான வேதனைக்கு முன்னால் நான் உங்களுக்கு எச்சரிக்கை செய்பவனாக இருக்கிறேன்.)\" அப்போது அபூ லஹப், \"நீ நாசமாகப் போவாயாக! இதற்காகத்தான் எங்களை ஒன்று திரட்டினாயா?\" என்று கேட்டான். உடனே அல்லாஹ் (இவ்வசனத்தை) இறக்கினான்: <span class=\"quran-arabic-font text-success\">﴾تَبَّتْ</span> <span class=\"quran-arabic-font text-success\">يَدَآ</span> <span class=\"quran-arabic-font text-success\">أَبِى</span> <span class=\"quran-arabic-font text-success\">لَهَبٍ</span> <span class=\"quran-arabic-font text-success\">وَتَبَّ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அபூ லஹபின் இரு கைகளும் நாசமாகட்டும்! அவனும் நாசமாகட்டும்!) (<a href=\"qurandisp.php?sura=111&ayah=1\" class=\"link\">111:1</a>) பின்வரும் வசனத்திற்கான தஃப்ஸீரில் (விளக்கவுரையில்) இதனை நாம் ஏற்கனவே விவரித்துள்ளோம்: <span class=\"quran-arabic-font text-success\">﴾وَأَنذِرْ</span> <span class=\"quran-arabic-font text-success\">عَشِيرَتَكَ</span> <span class=\"quran-arabic-font text-success\">الْأَقْرَبِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும், உமது நெருங்கிய உறவினர்களை எச்சரிக்கை செய்வீராக.) (<a href=\"qurandisp.php?sura=26&ayah=214\" class=\"link\">26:214</a>).<br />\r\n<br />\r\n<br />\r\n<br />","text":"நபி (ஸல்) அவர்கள் பைத்தியக்காரர் என்ற அவர்களின் குற்றச்சாட்டுக்கு மறுப்பு\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: \"(முஹம்மதே!) நீர் ஒரு பைத்தியக்காரர் என்று வாதிடும் இந்த நிராகரிப்பாளர்களிடம் நீர் கூறுவீராக:\" ﴾قُلْ إِنَّمَآ أَعِظُكُمْ بِوَاحِدَةٍ﴿\n\r\n\n\r\n\"நான் உங்களுக்கு ஒரே ஒரு விஷயத்தைத்தான் உபதேசிக்கிறேன். அது யாதெனில்:\" ﴾أَن تَقُومُواْ لِلَّهِ مَثْنَى وَفُرَادَى ثُمَّ تَتَفَكَّرُواْ مَا بِصَاحِبِكُم مِّن جِنَّةٍ﴿\n\r\n\n\r\n\"நீங்கள் ஈர்இருவராகவும் அல்லது தனித்தனியாகவும் அல்லாஹ்விற்காக (உண்மையை அறிய) முன்வாருங்கள்; பிறகு சிந்தித்துப் பாருங்கள், உங்கள் தோழரிடம் (முஹம்மத் ஸல் அவர்களிடம்) எந்தப் பைத்தியமும் இல்லை. அதாவது, உங்கள் சொந்த ஆசைகளுக்கோ அல்லது கோத்திர உணர்வுகளுக்கோ இடம் தராமல், தூய எண்ணத்துடன் அல்லாஹ்விற்காக முன்வந்து, 'முஹம்மத் (ஸல்) அவர்களுக்குப் பைத்தியமா?' என்று ஒருவருக்கொருவர் கேட்டுக்கொள்ளுங்கள்; ஒருவருக்கொருவர் அறிவுரை கூறுங்கள்.\" ﴾ثُمَّ تَتَفَكَّرُواْ﴿\n\r\n\n\r\nமேலும், 'சிந்தித்துப் பாருங்கள்' என்பது ஒவ்வொருவரும் முஹம்மத் (ஸல்) அவர்களின் விஷயத்தைப் பற்றித் தமக்குள்ளேயே சிந்தித்துப் பார்க்க வேண்டும் என்பதைக் குறிக்கிறது. அவருக்கு இன்னும் ஏதேனும் குழப்பம் இருந்தால், மற்றவர்களிடம் அவரைப் பற்றி வினவட்டும், பிறகு அந்த விஷயத்தைப் பற்றிச் சிந்திக்கட்டும். அல்லாஹ் கூறுகிறான்: ﴾أَن تَقُومُواْ لِلَّهِ مَثْنَى وَفُرَادَى ثُمَّ تَتَفَكَّرُواْ مَا بِصَاحِبِكُم مِّن جِنَّةٍ﴿\n\r\n\n\r\n(நீங்கள் ஈர்இருவராகவும் அல்லது தனித்தனியாகவும் அல்லாஹ்விற்காக முன்வந்து நில்லுங்கள்; பிறகு சிந்தித்துப் பாருங்கள், உங்கள் தோழரிடம் எந்தப் பைத்தியமும் இல்லை.) இந்தக் கருத்தை முஜாஹித், முஹம்மத் பின் கஅப், அஸ்-ஸுத்தி, கதாதா மற்றும் பலர் கூறியுள்ளனர். இதுவே இந்த வசனத்தின் (ஆயத்தின்) பொருளாகும். ﴾إِنْ هُوَ إِلاَّ نَذِيرٌ لَّكُمْ بَيْنَ يَدَىْ عَذَابٍ شَدِيدٍ﴿\n\r\n\n\r\n(கடுமையான வேதனைக்கு முன்னால் அவர் உங்களுக்கு எச்சரிக்கை செய்பவரே அன்றி வேறில்லை.) இப்னு அப்பாஸ் (ரழி) அவர்கள் இந்த வசனத்தைப் பற்றி இவ்வாறு கூறியதாக புகாரி பதிவு செய்துள்ளார்: \"ஒரு நாள் நபி (ஸல்) அவர்கள் ஸஃபா மலை குன்றின் மீது ஏறி, 'யா ஸபாஹா' (மக்களே!) என்று சத்தமிட்டு அழைத்தார்கள்.\" ﴾«يَا صَبَاحَاه»﴿\n\r\n\n\r\nகுரைஷிகள் அவர்களைச் சூழ்ந்து கொண்டு, 'உமக்கு என்ன நேர்ந்தது?' என்று கேட்டார்கள். அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்: ﴾«أَرَأَيْتُمْ لَوْ أَخْبَرْتُكُمْ أَنَّ الْعَدُوَّ يُصَبِّحُكُمْ أَوْ يُمَسِّيكُمْ أَمَا كُنْتُمْ تُصَدِّقُونِّي»﴿\n\r\n\n\r\n(\"பகைவர்கள் காலையிலோ அல்லது மாலையிலோ உங்கள் மீது தாக்குதல் நடத்த வருகிறார்கள் என்று நான் உங்களிடம் கூறினால், நீங்கள் என்னை நம்புவீர்களா என்று சொல்லுங்கள்?\" அதற்கு அவர்கள், \"நிச்சயமாக (நம்புவோம்)\" என்று கூறினார்கள். நபி (ஸல்) அவர்கள் கூறினார்கள்:) ﴾«فَإِنِّي نَذِيرٌ لَكُمْ بَيْنَ يَدَيْ عَذَابٍ شَدِيد»﴿\n\r\n\n\r\n\"(கடுமையான வேதனைக்கு முன்னால் நான் உங்களுக்கு எச்சரிக்கை செய்பவனாக இருக்கிறேன்.)\" அப்போது அபூ லஹப், \"நீ நாசமாகப் போவாயாக! இதற்காகத்தான் எங்களை ஒன்று திரட்டினாயா?\" என்று கேட்டான். உடனே அல்லாஹ் (இவ்வசனத்தை) இறக்கினான்: ﴾تَبَّتْ يَدَآ أَبِى لَهَبٍ وَتَبَّ ﴿\n\r\n\n\r\n(அபூ லஹபின் இரு கைகளும் நாசமாகட்டும்! அவனும் நாசமாகட்டும்!) (111:1) பின்வரும் வசனத்திற்கான தஃப்ஸீரில் (விளக்கவுரையில்) இதனை நாம் ஏற்கனவே விவரித்துள்ளோம்: ﴾وَأَنذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ ﴿\n\r\n\n\r\n(மேலும், உமது நெருங்கிய உறவினர்களை எச்சரிக்கை செய்வீராக.) (26:214)."},"47":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=50\" class=\"link\">34:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:50 ஐ பார்க்கவும்"},"48":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=50\" class=\"link\">34:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:50 ஐ பார்க்கவும்"},"49":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=50\" class=\"link\">34:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:50 ஐ பார்க்கவும்"},"50":{"html":"<strong>இந்தத் தூதை எடுத்துரைப்பதற்காக நான் எந்தக் கூலியையும் கேட்கவில்லை</strong><br />\r\n<br />\r\n<br />\r\nஇணைவைப்பாளர்களிடம் கூறுமாறு அல்லாஹ் தன் தூதருக்குக் கட்டளையிடுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">سَأَلْتُكُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">أَجْرٍ</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span><br />\r\n<br />\r\n<br />\r\n(கூறுவீராக: \"நான் உங்களிடம் ஏதேனும் கூலியைக் கேட்டிருந்தால், அது உங்களுக்கே உரியது.\") அதாவது, \"அல்லாஹ்வின் தூதை உங்களிடம் சேர்ப்பதற்காகவோ, உங்களுக்கு நற்போதனை செய்வதற்காகவோ அல்லது அல்லாஹ்வை வணங்குமாறு உங்களை ஏவுவதற்காகவோ நான் உங்களிடமிருந்து எதையும் எதிர்பார்க்கவில்லை\" என்பதாகும்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">أَجْرِيَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n<br />\r\nஎனது கூலி அல்லாஹ்விடமே தவிர வேறில்லை. அதாவது, இதற்கான நற்கூலியை நான் அல்லாஹ்விடமே தேடுவேன்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">شَهِيدٌ</span><br />\r\n<br />\r\n<br />\r\nமேலும், அவன் அனைத்தின் மீதும் சாட்சியாளனாக இருக்கிறான். அதாவது, அவன் அனைத்தையும் அறிந்தவன். என்னைப் பற்றியும், இந்தத் தூதை நான் உங்களுக்கு எவ்விதம் எடுத்துரைக்கிறேன் என்பது பற்றியும் அவன் நன்கு அறிவான்; உங்களைப் பற்றியும் அவன் அனைத்தையும் அறிவான்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">رَبِّي</span> <span class=\"quran-arabic-font text-success\">يَقْذِفُ</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span> <span class=\"quran-arabic-font text-success\">عَلَّامُ</span> <span class=\"quran-arabic-font text-success\">الْغُيُوبِ</span><br />\r\n<br />\r\n<br />\r\n(கூறுவீராக: \"நிச்சயமாக, என் இறைவன் சத்தியத்தை இறக்குகிறான்; அவன் மறைவானவற்றை எல்லாம் நன்கறிந்தவன்.\") இது இந்த வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يُلْقِي</span> <span class=\"quran-arabic-font text-success\">الرُّوحَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَمْرِهِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عِبَادِهِ</span><br />\r\n<br />\r\n<br />\r\n(அவன் தனது அடியார்களில் தான் நாடியவர் மீது தனது கட்டளையினால் வஹீ (இறைச்செய்தி)யை இறக்குகிறான்) (<a href=\"qurandisp.php?sura=40&ayah=15\" class=\"link\">40:15</a>). அதாவது, பூமியில் உள்ள மனிதர்களில் தான் நாடிய தனது அடியாரிடம் அவன் வானவரை அனுப்புகிறான். அவன் மறைவானவற்றை எல்லாம் நன்கறிந்தவன்; வானங்களிலோ பூமியிலோ அவனுக்கு எதுவுமே மறைவானது அல்ல.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يُبْدِئُ</span> <span class=\"quran-arabic-font text-success\">الْبَاطِلُ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يُعِيدُ</span><br />\r\n<br />\r\n<br />\r\n(கூறுவீராக: \"சத்தியம் வந்துவிட்டது; அசத்தியம் எதையும் புதிதாக உருவாக்கவும் முடியாது, எதையும் மீண்டும் கொண்டு வரவும் முடியாது.\") அதாவது, அல்லாஹ்விடமிருந்து சத்தியமும் மாபெரும் சட்டமும் வந்துவிட்டன; அசத்தியம் அழிந்து மறைந்துவிட்டது. இது இந்த வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">نَقْذِفُ</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْبَاطِلِ</span> <span class=\"quran-arabic-font text-success\">فَيَدْمَغُهُ</span> <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">زَاهِقٌ</span><br />\r\n<br />\r\n<br />\r\n(மாறாக, நாம் சத்தியத்தை அசத்தியத்தின் மீது வீசுகிறோம்; அது அதனைத் தகர்த்துவிடுகிறது. பின்னர் அது அழிந்துவிடுகிறது) (<a href=\"qurandisp.php?sura=21&ayah=18\" class=\"link\">21:18</a>). மக்கா வெற்றியின் போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மஸ்ஜிதுல் ஹராமிற்குள் நுழைந்தபோது, கஃபாவைச் சுற்றி சிலைகள் வைக்கப்பட்டிருந்தன. அவர்கள் (ஸல்) தங்கள் வில்லால் அந்தச் சிலைகளைத் தட்டியவாறே பின்வருமாறு ஓதினார்கள்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقُلْ</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">وَزَهَقَ</span> <span class=\"quran-arabic-font text-success\">الْبَاطِلُ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْبَاطِلَ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">زَهُوقًا</span><br />\r\n<br />\r\n<br />\r\n(மேலும் கூறுவீராக: \"சத்தியம் வந்துவிட்டது, அசத்தியம் அழிந்துவிட்டது. நிச்சயமாக அசத்தியம் அழிந்து போகக் கூடியதே.\") (<a href=\"qurandisp.php?sura=17&ayah=81\" class=\"link\">17:81</a>), மற்றும்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يُبْدِئُ</span> <span class=\"quran-arabic-font text-success\">الْبَاطِلُ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يُعِيدُ</span><br />\r\n<br />\r\n<br />\r\n(கூறுவீராக: \"சத்தியம் வந்துவிட்டது; அசத்தியம் எதையும் புதிதாக உருவாக்கவும் முடியாது, எதையும் மீண்டும் கொண்டு வரவும் முடியாது.\") இதனை புகாரீ, முஸ்லிம், திர்மிதீ மற்றும் நஸயீ ஆகியோர் பதிவு செய்துள்ளனர்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">ضَلَلْتُ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّمَآ</span> <span class=\"quran-arabic-font text-success\">أَضِلُّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">وَإِنِ</span> <span class=\"quran-arabic-font text-success\">اهْتَدَيْتُ</span> <span class=\"quran-arabic-font text-success\">فَبِمَا</span> <span class=\"quran-arabic-font text-success\">يُوحِي</span> <span class=\"quran-arabic-font text-success\">إِلَيَّ</span> <span class=\"quran-arabic-font text-success\">رَبِّي</span><br />\r\n<br />\r\n<br />\r\n(கூறுவீராக: \"நான் வழிதவறினால், அது எனக்கு எதிராகவே அமையும். நான் நேர்வழி பெற்றால், அது எனது இறைவன் எனக்கு அறிவிக்கும் வஹீ (இறைச்செய்தி)யால்தான்...\") அதாவது, நன்மைகள் அனைத்தும் அல்லாஹ்விடமிருந்தே வருகின்றன. அல்லாஹ் இறக்கியருளும் வஹீ (இறைச்செய்தி)யிலும், தெளிவான சத்தியத்திலும் நேர்வழியும் ஞானமும் உண்டு. எனவே, ஒருவர் வழிதவறினால் அது அவரது சொந்தக் குறைபாடே ஆகும். ஒரு விஷயம் குறித்துக் கேட்கப்பட்ட போது அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் பின்வருமாறு கூறினார்கள்: \"நான் இதில் எனது கருத்தைச் சொல்கிறேன். அது சரியானதாக இருந்தால் அது அல்லாஹ்விடமிருந்து வந்ததாகும். அது தவறாக இருந்தால் அது என்னிடமிருந்தும் ஷைத்தானிடமிருந்தும் வந்ததாகும். அல்லாஹ்விற்கும் அவனது தூதருக்கும் இதில் எந்தப் பொறுப்பும் இல்லை.\"<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">سَمِيعٌ</span> <span class=\"quran-arabic-font text-success\">قَرِيبٌ</span><br />\r\n<br />\r\n<br />\r\nநிச்சயமாக அவன் அனைத்தையும் செவியேற்பவன், மிக நெருக்கமானவன். அதாவது, அவன் தனது அடியார்களின் அனைத்துச் சொற்களையும் செவியுறுகிறான். அவர்கள் அவனை அழைக்கும்போது அவர்களுக்குப் பதிலளிக்க அவன் மிக அருகிலேயே இருக்கிறான். நஸயீயில் அபூ மூஸா (ரழி) அவர்கள் அறிவிக்கும் ஒரு ஹதீஸ் பதிவாகியுள்ளது. அது புகாரீ, முஸ்லிம் ஆகிய இரு ஸஹீஹ்களிலும் இடம்பெற்றுள்ளது:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">لَاتَدْعُونَ</span> <span class=\"quran-arabic-font text-success\">أَصَمَّ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">غَائِبًا،</span> <span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">تَدْعُونَ</span> <span class=\"quran-arabic-font text-success\">سَمِيعًا</span> <span class=\"quran-arabic-font text-success\">قَرِيبًا</span> <span class=\"quran-arabic-font text-success\">مُجِيبًا</span>»<br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக நீங்கள் செவிடனையோ அல்லது இங்கில்லாதவரையோ அழைக்கவில்லை; மாறாக நீங்கள் அனைத்தையும் செவியேற்பவனையும், மிக நெருக்கமானவனையும், பதிலளிப்பவனையுமே அழைக்கிறீர்கள்.)<br />\r\n<br />","text":"இந்தத் தூதை எடுத்துரைப்பதற்காக நான் எந்தக் கூலியையும் கேட்கவில்லை\n\r\n\n\r\n\n\r\nஇணைவைப்பாளர்களிடம் கூறுமாறு அல்லாஹ் தன் தூதருக்குக் கட்டளையிடுகிறான்:\n\r\n\n\r\n\n\r\nقُلْ مَا سَأَلْتُكُم مِّن أَجْرٍ فَهُوَ لَكُمْ\n\r\n\n\r\n\n\r\n(கூறுவீராக: \"நான் உங்களிடம் ஏதேனும் கூலியைக் கேட்டிருந்தால், அது உங்களுக்கே உரியது.\") அதாவது, \"அல்லாஹ்வின் தூதை உங்களிடம் சேர்ப்பதற்காகவோ, உங்களுக்கு நற்போதனை செய்வதற்காகவோ அல்லது அல்லாஹ்வை வணங்குமாறு உங்களை ஏவுவதற்காகவோ நான் உங்களிடமிருந்து எதையும் எதிர்பார்க்கவில்லை\" என்பதாகும்.\n\r\n\n\r\n\n\r\nإِنْ أَجْرِيَ إِلاَّ عَلَى اللَّهِ\n\r\n\n\r\n\n\r\nஎனது கூலி அல்லாஹ்விடமே தவிர வேறில்லை. அதாவது, இதற்கான நற்கூலியை நான் அல்லாஹ்விடமே தேடுவேன்.\n\r\n\n\r\n\n\r\nوَهُوَ عَلَى كُلِّ شَىْءٍ شَهِيدٌ\n\r\n\n\r\n\n\r\nமேலும், அவன் அனைத்தின் மீதும் சாட்சியாளனாக இருக்கிறான். அதாவது, அவன் அனைத்தையும் அறிந்தவன். என்னைப் பற்றியும், இந்தத் தூதை நான் உங்களுக்கு எவ்விதம் எடுத்துரைக்கிறேன் என்பது பற்றியும் அவன் நன்கு அறிவான்; உங்களைப் பற்றியும் அவன் அனைத்தையும் அறிவான்.\n\r\n\n\r\n\n\r\nقُلْ إِنَّ رَبِّي يَقْذِفُ بِالْحَقِّ عَلَّامُ الْغُيُوبِ\n\r\n\n\r\n\n\r\n(கூறுவீராக: \"நிச்சயமாக, என் இறைவன் சத்தியத்தை இறக்குகிறான்; அவன் மறைவானவற்றை எல்லாம் நன்கறிந்தவன்.\") இது இந்த வசனத்தைப் போன்றது:\n\r\n\n\r\n\n\r\nيُلْقِي الرُّوحَ مِنْ أَمْرِهِ عَلَى مَن يَشَآءُ مِنْ عِبَادِهِ\n\r\n\n\r\n\n\r\n(அவன் தனது அடியார்களில் தான் நாடியவர் மீது தனது கட்டளையினால் வஹீ (இறைச்செய்தி)யை இறக்குகிறான்) (40:15). அதாவது, பூமியில் உள்ள மனிதர்களில் தான் நாடிய தனது அடியாரிடம் அவன் வானவரை அனுப்புகிறான். அவன் மறைவானவற்றை எல்லாம் நன்கறிந்தவன்; வானங்களிலோ பூமியிலோ அவனுக்கு எதுவுமே மறைவானது அல்ல.\n\r\n\n\r\n\n\r\nقُلْ جَآءَ الْحَقُّ وَمَا يُبْدِئُ الْبَاطِلُ وَمَا يُعِيدُ\n\r\n\n\r\n\n\r\n(கூறுவீராக: \"சத்தியம் வந்துவிட்டது; அசத்தியம் எதையும் புதிதாக உருவாக்கவும் முடியாது, எதையும் மீண்டும் கொண்டு வரவும் முடியாது.\") அதாவது, அல்லாஹ்விடமிருந்து சத்தியமும் மாபெரும் சட்டமும் வந்துவிட்டன; அசத்தியம் அழிந்து மறைந்துவிட்டது. இது இந்த வசனத்தைப் போன்றது:\n\r\n\n\r\n\n\r\nبَلْ نَقْذِفُ بِالْحَقِّ عَلَى الْبَاطِلِ فَيَدْمَغُهُ فَإِذَا هُوَ زَاهِقٌ\n\r\n\n\r\n\n\r\n(மாறாக, நாம் சத்தியத்தை அசத்தியத்தின் மீது வீசுகிறோம்; அது அதனைத் தகர்த்துவிடுகிறது. பின்னர் அது அழிந்துவிடுகிறது) (21:18). மக்கா வெற்றியின் போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மஸ்ஜிதுல் ஹராமிற்குள் நுழைந்தபோது, கஃபாவைச் சுற்றி சிலைகள் வைக்கப்பட்டிருந்தன. அவர்கள் (ஸல்) தங்கள் வில்லால் அந்தச் சிலைகளைத் தட்டியவாறே பின்வருமாறு ஓதினார்கள்:\n\r\n\n\r\n\n\r\nوَقُلْ جَآءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ إِنَّ الْبَاطِلَ كَانَ زَهُوقًا\n\r\n\n\r\n\n\r\n(மேலும் கூறுவீராக: \"சத்தியம் வந்துவிட்டது, அசத்தியம் அழிந்துவிட்டது. நிச்சயமாக அசத்தியம் அழிந்து போகக் கூடியதே.\") (17:81), மற்றும்:\n\r\n\n\r\n\n\r\nقُلْ جَآءَ الْحَقُّ وَمَا يُبْدِئُ الْبَاطِلُ وَمَا يُعِيدُ\n\r\n\n\r\n\n\r\n(கூறுவீராக: \"சத்தியம் வந்துவிட்டது; அசத்தியம் எதையும் புதிதாக உருவாக்கவும் முடியாது, எதையும் மீண்டும் கொண்டு வரவும் முடியாது.\") இதனை புகாரீ, முஸ்லிம், திர்மிதீ மற்றும் நஸயீ ஆகியோர் பதிவு செய்துள்ளனர்.\n\r\n\n\r\n\n\r\nقُلْ إِن ضَلَلْتُ فَإِنَّمَآ أَضِلُّ عَلَى نَفْسِي وَإِنِ اهْتَدَيْتُ فَبِمَا يُوحِي إِلَيَّ رَبِّي\n\r\n\n\r\n\n\r\n(கூறுவீராக: \"நான் வழிதவறினால், அது எனக்கு எதிராகவே அமையும். நான் நேர்வழி பெற்றால், அது எனது இறைவன் எனக்கு அறிவிக்கும் வஹீ (இறைச்செய்தி)யால்தான்...\") அதாவது, நன்மைகள் அனைத்தும் அல்லாஹ்விடமிருந்தே வருகின்றன. அல்லாஹ் இறக்கியருளும் வஹீ (இறைச்செய்தி)யிலும், தெளிவான சத்தியத்திலும் நேர்வழியும் ஞானமும் உண்டு. எனவே, ஒருவர் வழிதவறினால் அது அவரது சொந்தக் குறைபாடே ஆகும். ஒரு விஷயம் குறித்துக் கேட்கப்பட்ட போது அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் பின்வருமாறு கூறினார்கள்: \"நான் இதில் எனது கருத்தைச் சொல்கிறேன். அது சரியானதாக இருந்தால் அது அல்லாஹ்விடமிருந்து வந்ததாகும். அது தவறாக இருந்தால் அது என்னிடமிருந்தும் ஷைத்தானிடமிருந்தும் வந்ததாகும். அல்லாஹ்விற்கும் அவனது தூதருக்கும் இதில் எந்தப் பொறுப்பும் இல்லை.\"\n\r\n\n\r\n\n\r\nإِنَّهُ سَمِيعٌ قَرِيبٌ\n\r\n\n\r\n\n\r\nநிச்சயமாக அவன் அனைத்தையும் செவியேற்பவன், மிக நெருக்கமானவன். அதாவது, அவன் தனது அடியார்களின் அனைத்துச் சொற்களையும் செவியுறுகிறான். அவர்கள் அவனை அழைக்கும்போது அவர்களுக்குப் பதிலளிக்க அவன் மிக அருகிலேயே இருக்கிறான். நஸயீயில் அபூ மூஸா (ரழி) அவர்கள் அறிவிக்கும் ஒரு ஹதீஸ் பதிவாகியுள்ளது. அது புகாரீ, முஸ்லிம் ஆகிய இரு ஸஹீஹ்களிலும் இடம்பெற்றுள்ளது:\n\r\n\n\r\n\n\r\n«إِنَّكُمْ لَاتَدْعُونَ أَصَمَّ وَلَا غَائِبًا، إِنَّمَا تَدْعُونَ سَمِيعًا قَرِيبًا مُجِيبًا»\n\r\n\n\r\n\n\r\n(நிச்சயமாக நீங்கள் செவிடனையோ அல்லது இங்கில்லாதவரையோ அழைக்கவில்லை; மாறாக நீங்கள் அனைத்தையும் செவியேற்பவனையும், மிக நெருக்கமானவனையும், பதிலளிப்பவனையுமே அழைக்கிறீர்கள்.)"},"51":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=54\" class=\"link\">34:54</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:54 ஐ பார்க்கவும்"},"52":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=54\" class=\"link\">34:54</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:54 ஐ பார்க்கவும்"},"53":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=34&ayah=54\" class=\"link\">34:54</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 34:54 ஐ பார்க்கவும்"},"54":{"html":"<span class=\"quran-arabic-font text-success\">وَحِيلَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَشْتَهُونَ</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">فُعِلَ</span> <span class=\"quran-arabic-font text-success\">بِأَشْيَاعِهِم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ</span> <span class=\"quran-arabic-font text-success\">ۚ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">كَانُوا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">شَكٍّ</span> <span class=\"quran-arabic-font text-success\">مُّرِيبٍ</span><br />\r\n(அவர்களுக்கும், அவர்கள் விரும்பியவற்றுக்கும் இடையே திரை இடப்பட்டு விட்டது; இவர்களுக்கு முன் சென்ற இவர்களுடைய இனத்தார்களுக்குச் செய்யப்பட்டது போலவே! நிச்சயமாக அவர்களும் ஆழ்ந்த சந்தேகத்திலேயே இருந்தனர்.)<br />\r\n<br />\r\nஅதாவது, இவ்வுலகத்திற்குத் திரும்பிச் செல்ல வேண்டும் என்றும், தௌபாச் செய்து இறைநம்பிக்கை கொள்ள வேண்டும் என்றும் அவர்கள் விரும்பினார்கள். ஆனால், அதற்கான வழி அடைக்கப்பட்டுவிட்டது. இவர்களுக்கு முன் சென்று, இவர்களைப் போன்றே இறைமறுப்பில் ஈடுபட்டவர்களுக்கும் இதே நிலைதான் ஏற்பட்டது. அவர்களுக்கும் இவ்வுலகத்திற்குத் திரும்பும் வாய்ப்பு மறுக்கப்பட்டது. இறைவேதனையைக் கண்ட சமயத்தில் அவர்கள் கொண்ட நம்பிக்கை எதற்கும் பயன்படவில்லை.<br />\r\n<br />\r\n(நிச்சயமாக அவர்களும் ஆழ்ந்த சந்தேகத்திலேயே இருந்தனர்) அதாவது இறைத்தூதர்கள் கொண்டு வந்த செய்திகளை நம்பாது சந்தேகித்தனர்.<br />\r\n<br />\r\n(இத்தோடு ஸூரத்து ஸபாவுடைய தஃப்ஸீர் நிறைவுற்றது. அல்ஹம்துலில்லாஹ்!)<br />\r\n<br />","text":"وَحِيلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ كَمَا فُعِلَ بِأَشْيَاعِهِم مِّن قَبْلُ ۚ إِنَّهُمْ كَانُوا فِي شَكٍّ مُّرِيبٍ\n\r\n(அவர்களுக்கும், அவர்கள் விரும்பியவற்றுக்கும் இடையே திரை இடப்பட்டு விட்டது; இவர்களுக்கு முன் சென்ற இவர்களுடைய இனத்தார்களுக்குச் செய்யப்பட்டது போலவே! நிச்சயமாக அவர்களும் ஆழ்ந்த சந்தேகத்திலேயே இருந்தனர்.)\n\r\n\n\r\nஅதாவது, இவ்வுலகத்திற்குத் திரும்பிச் செல்ல வேண்டும் என்றும், தௌபாச் செய்து இறைநம்பிக்கை கொள்ள வேண்டும் என்றும் அவர்கள் விரும்பினார்கள். ஆனால், அதற்கான வழி அடைக்கப்பட்டுவிட்டது. இவர்களுக்கு முன் சென்று, இவர்களைப் போன்றே இறைமறுப்பில் ஈடுபட்டவர்களுக்கும் இதே நிலைதான் ஏற்பட்டது. அவர்களுக்கும் இவ்வுலகத்திற்குத் திரும்பும் வாய்ப்பு மறுக்கப்பட்டது. இறைவேதனையைக் கண்ட சமயத்தில் அவர்கள் கொண்ட நம்பிக்கை எதற்கும் பயன்படவில்லை.\n\r\n\n\r\n(நிச்சயமாக அவர்களும் ஆழ்ந்த சந்தேகத்திலேயே இருந்தனர்) அதாவது இறைத்தூதர்கள் கொண்டு வந்த செய்திகளை நம்பாது சந்தேகித்தனர்.\n\r\n\n\r\n(இத்தோடு ஸூரத்து ஸபாவுடைய தஃப்ஸீர் நிறைவுற்றது. அல்ஹம்துலில்லாஹ்!)"}}};})(self);
